                    generalVendor: "Általános beszállító", createdOn: "Létrehozva: {date}", recent: "Legutóbbi", draft: "Piszkozat",
                    orderItemsNotes: "Rendelési tételek / Megjegyzések:", restockDefault: "Készletutánpótlás szükséges.",
