                async function endPresenceSession() {
            if (!authToken) return;
            try { await fetch(`${API_URL}/presence/logout`, { method: "POST", headers: {"Content-Type":"application/json","Authorization":`Bearer ${authToken}`}, body: JSON.stringify({session_id: window.supplyPresenceSessionId || null}) }); } catch (_) {}
            window.supplyPresenceSessionId = null;
        }

        function startPresenceHeartbeat() {
            if (businessDeletionInProgress) return; // never (re)start while a deletion is underway
            if (window.supplyPresenceTimer) clearInterval(window.supplyPresenceTimer);
            const ping = async () => {
                if (businessDeletionInProgress || !authToken) return;
                try { const res=await fetch(`${API_URL}/presence/heartbeat`,{method:"POST",headers:{"Content-Type":"application/json","Authorization":`Bearer ${authToken}`},body:JSON.stringify({session_id:window.supplyPresenceSessionId||null})}); const d=await res.json(); if(res.ok) window.supplyPresenceSessionId=d.session_id; } catch(_) {}
            };
            ping(); window.supplyPresenceTimer=setInterval(ping,60000);
        }

        // Asks for confirmation before actually signing out — the sign-out
        // button in renderAuthButton() calls this, not handleSignOut()
        // directly. Reuses the app's existing shared confirm modal
        // (showCustomConfirm) rather than a second confirmation system.
        function confirmSignOut() {
            showCustomConfirm(t("common.signOutConfirmBody"), t("common.signOut"), t("common.signOut"), t("common.cancel")).then(confirmed => {
                if (confirmed) handleSignOut();
            });
        }

        // Stops every timer that periodically calls a protected/business-
        // scoped endpoint in the background — notification badge polling,
        // the presence heartbeat, the auth-refresh heartbeat — and aborts
        // whichever of those requests is currently in flight. Deliberately
        // does NOT touch auth/business state, call any server-side logout
        // endpoint, or navigate anywhere: its only job is to make the app
        // network-quiet for the current tenant so a caller (business
        // deletion, or handleSignOut() below) can do its own destructive
        // work — or its own full state teardown — without a stray poll
        // landing mid-transition. Safe to call more than once; every step
        // here is itself idempotent.
        function quiesceAuthenticatedActivity() {
            stopNotificationPolling();
            notificationPollAbortController?.abort();
            if (window.supplyPresenceTimer) { clearInterval(window.supplyPresenceTimer); window.supplyPresenceTimer = null; }
            stopAuthRefreshHeartbeat();
        }

        async function handleSignOut(options = {}) {
            // options.toastMessage/toastType let a caller whose exit reason is
            // more specific than a plain sign-out (e.g. confirmDeleteBusiness
            // Profile — the business and this session's own user row no
            // longer exist server-side) show its own message, while still
            // going through this exact same cleanup rather than re-deriving
            // a partial copy of it that would drift out of sync over time.
            // options.skipServerLogout: true when the caller already knows
            // the server-side session is gone — confirmDeleteBusinessProfile()
            // sets this because DELETE /business-profile/ already deleted
            // this session's own user and refresh-session rows, so
            // /auth/logout and /presence/logout could only ever come back
            // 401 for a row that no longer exists. Skipping them avoids that
            // guaranteed-to-fail round trip entirely, rather than merely
            // relying on their try/catch to hide it.
            // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) -----
            console.log(`[auth-diag-frontend] handleSignOut() CALLED caller=` + (new Error().stack || "").split("\n").slice(1, 6).join(" | "));
            // --- END TEMPORARY DEV DIAGNOSTIC -------------------------------
            // Blocks every background auth path (heartbeat, visibilitychange,
            // session validation) from re-establishing a session while this
            // runs — see refreshAccessToken()/validateAuthenticationSession().
            signOutInProgress = true;
            quiesceAuthenticatedActivity();

            if (!options.skipServerLogout) {
                if (authToken) {
                    try { await fetch(`${API_URL}/auth/logout`, { method: "POST", credentials: "include", headers: { "Authorization": `Bearer ${authToken}` } }); } catch (_) {}
                }
                await endPresenceSession();
            }

            authToken = "";
            currentUserProfile = null;
            businessProfile = null;
            globalProducts = [];
            inventoryViewProducts = [];
            globalSuppliers = [];
            globalPurchaseOrders = [];
            warehouseRecords = [];
            customWarehouses = [];
            businessEmployees = [];
            employeeDirectoryUsers = [];
            posCart = [];
            billingUsageCache = null;
            currentAiEntitled = true; // same default a fresh guest load starts with
            inventoryStatusCounts = { healthy: 0, low: 0, out: 0 };
            inventoryStatusFilter = null;
            selectedWarehouseFilter = "ALL";
            // A subsequent sign-in (same tab, different or same business)
            // must cold-start its own loading state, not inherit this
            // session's "already loaded" flags.
            productsSuppliersReady = false;
            warehousesReady = false;
            inventoryEverLoaded = false;
            coreDataEverLoaded = false;
            // The Business Brain holds the previous session's intelligence in
            // module state, so clear it before rendering the signed-out view.
            businessBrainData = null;
            dashboardBrainForbiddenMessage = null;
            lastFinancialIntelData = null;
            dashboardTodayProfit = null;
            dashboardSalesToday = null;
            dashboardSubscriptionWarning = null;
            dashboardPendingReopenCount = 0;
            document.getElementById("global-loading-banner")?.classList.add("hidden");

            updateCompanyHeaderDisplay();
            updateWelcomeBanner();
            updateDashboardMetrics();
            updateWarehouseUIElements();
            renderInventoryTable([]);
            renderBusinessInsights();
            renderAuthButton();
            applyRoleRestrictions();
            updateGuestHeaderState();
            // Rebuilds the mobile drawer from the now-guest sidebar directly —
            // deliberately NOT loadData(), whose very first line would attempt
            // refreshAccessToken() and could re-fetch business data before the
            // guest transition is even visible.
            renderMobileNav();
            showToast(options.toastMessage || t("common.signedOutSuccess"), options.toastType || "info");
            signOutInProgress = false;
        }

        function confirmClearInventoryData() {
            showCustomConfirm(t("settings.clearInventoryConfirmBody"), t("settings.clearInventoryConfirmTitle")).then(async confirmed => {
                if (confirmed) {
                    let failed = 0;
                    if (authToken) {
                        const headers = { "Authorization": `Bearer ${authToken}` };
                        for (const prod of [...globalProducts]) {
                            try {
                                const res = await fetch(`${API_URL}/products/${prod.id}`, { method: "DELETE", headers });
                                if (!res.ok) failed++;
                            } catch (e) { failed++; }
                        }
                    }
                    await loadData();
                    updateDashboardMetrics();
                    closeSettingsModal();
                    if (failed > 0) {
                        showToast(`${failed} item(s) could not be cleared. Please try again.`, "error");
                    } else {
                        showToast(t("settings.inventoryClearedSuccess"), "success");
                    }
                }
            });
        }

