        function switchBizAuthView(viewName) {
            const inner = document.getElementById("business-auth-modal-inner");
            if (inner) {
                inner.className = viewName === 'plan'
                    ? "bg-cardBg border border-borderCol rounded-2xl p-5 sm:p-8 max-w-6xl w-full shadow-2xl max-h-[92vh] overflow-y-auto"
                    : "bg-cardBg border border-borderCol rounded-2xl p-6 max-w-md w-full shadow-2xl max-h-[90vh] overflow-y-auto";
            }
            document.getElementById("biz-auth-view-landing").classList.add("hidden");
            document.getElementById("biz-auth-view-plan").classList.add("hidden");
            document.getElementById("biz-auth-view-payment-email").classList.add("hidden");
            document.getElementById("biz-auth-view-payment-verifying").classList.add("hidden");
            document.getElementById("biz-auth-view-register").classList.add("hidden");
            document.getElementById("biz-auth-view-signin-step1").classList.add("hidden");
            document.getElementById("biz-auth-view-signin-step2").classList.add("hidden");

            const titleEl = document.getElementById("biz-auth-modal-title");

            if (viewName === 'landing') {
                document.getElementById("biz-auth-view-landing").classList.remove("hidden");
                titleEl.innerHTML = `<i class="fa-solid fa-building-user text-primary"></i> Welcome to Cauldra`;
            } else if (viewName === 'plan') {
                document.getElementById("biz-auth-view-plan").classList.remove("hidden");
                titleEl.innerHTML = `<i class="fa-solid fa-layer-group text-primary"></i> Choose Your Plan`;
                loadPublicPlanCatalog();
            } else if (viewName === 'payment-email') {
                if (!onboardingSelectedPlan) { switchBizAuthView('plan'); return; }
                document.getElementById("biz-auth-view-payment-email").classList.remove("hidden");
                titleEl.innerHTML = `<i class="fa-solid fa-envelope-circle-check text-primary"></i> Verify Your Email`;
                renderPaymentEmailPlanBanner();
                evShowState(evVerifiedEmail ? 3 : 1);
            } else if (viewName === 'payment-verifying') {
                document.getElementById("biz-auth-view-payment-verifying").classList.remove("hidden");
                titleEl.innerHTML = `<i class="fa-solid fa-shield-halved text-primary"></i> Verifying Payment`;
            } else if (viewName === 'register') {
                if (!onboardingSelectedPlan || !verifiedOnboardingReference) {
                    // Never let a new business reach the registration form without an
                    // explicit plan AND an already-verified payment method — the
                    // backend independently rejects this too, but we shouldn't let
                    // the user get this far in the UI in the first place.
                    switchBizAuthView('plan');
                    return;
                }
                document.getElementById("biz-auth-view-register").classList.remove("hidden");
                renderRegisterPlanBanner();
                ensureCountrySelectorReady();
                ensureCountrySelectorReady();
                titleEl.innerHTML = `<i class="fa-solid fa-building-circle-arrow-right text-primary"></i> Register a Business & Admin`;
            } else if (viewName === 'signin') {
                document.getElementById("biz-auth-view-signin-step1").classList.remove("hidden");
                titleEl.innerHTML = `<i class="fa-solid fa-right-to-bracket text-primary"></i> Sign in to a Business`;
            } else if (viewName === 'signin-step2') {
                document.getElementById("biz-auth-view-signin-step2").classList.remove("hidden");
                titleEl.innerHTML = `<i class="fa-solid fa-user-check text-primary"></i> Employee Authentication`;
            }
        }

        // ---------------------------------------------------------------------
        // ONBOARDING: PLAN SELECTION (runs before business registration)
        // ---------------------------------------------------------------------
        let onboardingSelectedPlan = null;      // e.g. "starter" | "business" | "enterprise" — null until user picks one
        let onboardingSelectedInterval = "monthly"; // "monthly" | "annual" — matches backend's existing values exactly
        let publicPlanCatalog = null;           // cached response from GET /plans (server-authoritative pricing)
        let verifiedOnboardingReference = null; // set only after the backend independently confirms Paystack card verification; required to reach/submit registration
        // --- Supabase email verification (gate BEFORE Paystack) ---
        let evVerifiedEmail = null;        // the Supabase-verified email; the backend re-checks Supabase before Paystack regardless
        let evResendCooldownUntil = 0;     // epoch ms (frontend guard; Supabase enforces its own per-email cooldown too)
        let evResendTimer = null;
        let evPollTimer = null;
        let evVerifyChannel = null;        // BroadcastChannel: a verify completed in another tab updates this one

        function formatNaira(amount) {
            return "₦" + Number(amount || 0).toLocaleString("en-NG");
        }

        const PLAN_DISPLAY_META = {
            core: { icon: "fa-shop", description: "Run your business — essential tools, no AI.", theme: "slate" },
            starter: { icon: "fa-rocket", description: "Run your business smarter, with AI.", theme: "blue" },
            business: { icon: "fa-arrow-trend-up", description: "Run and grow your business at scale.", theme: "green", recommended: true },
            enterprise: { icon: "fa-crown", description: "The complete Cauldra experience.", theme: "purple" },
        };

        const PLAN_CARD_THEME = {
            slate:  { iconBg: "bg-slate-500/15 text-slate-400", border: "border-borderCol", cardBg: "bg-bgMain", button: "bg-gradient-to-r from-slate-600 to-slate-500 hover:from-slate-500 hover:to-slate-400" },
            blue:   { iconBg: "bg-blue-500/15 text-blue-400", border: "border-borderCol", cardBg: "bg-bgMain", button: "bg-gradient-to-r from-blue-600 to-blue-500 hover:from-blue-500 hover:to-blue-400" },
            green:  { iconBg: "bg-success/15 text-success", border: "border-success/60", cardBg: "bg-success/5", button: "bg-gradient-to-r from-success to-emerald-500 hover:brightness-110" },
            purple: { iconBg: "bg-purple-500/15 text-purple-400", border: "border-borderCol", cardBg: "bg-bgMain", button: "bg-gradient-to-r from-purple-600 to-purple-500 hover:from-purple-500 hover:to-purple-400" },
        };

        const AI_CREDIT_FEATURE_META = [
            ["margin_advisor", "Margin Advisor", "fa-magnifying-glass-chart", "bg-blue-500/15 text-blue-400"],
            ["inventory_insight", "Inventory Insight", "fa-lightbulb", "bg-success/15 text-success"],
            ["invoice_ocr", "Invoice OCR", "fa-file-invoice", "bg-purple-500/15 text-purple-400"],
            ["chat", "AI Chat", "fa-comment-dots", "bg-amber-500/15 text-amber-400"],
            ["predictive_analysis", "Predictive Analysis", "fa-chart-line", "bg-danger/15 text-danger"],
            ["complex_analysis", "Complex Analysis", "fa-star", "bg-orange-500/15 text-orange-400"],
        ];
        // Credit costs mirror the backend's AI_CREDIT_WEIGHTS exactly (main.py) — this
        // registration screen runs before authentication, so it can't call an
        // authenticated usage endpoint; the numbers themselves are never used for
        // billing, only for this explainer, and match the server-authoritative values.
        const AI_CREDIT_WEIGHTS_DISPLAY = { margin_advisor: 2, chat: 2, inventory_insight: 5, predictive_analysis: 8, invoice_ocr: 10, complex_analysis: 10 };

        function renderAiCreditWorkGrid() {
            const grid = document.getElementById("plan-ai-credit-grid");
            if (!grid) return;
            grid.innerHTML = AI_CREDIT_FEATURE_META.map(([key, label, icon, badgeClass]) => `
                <div class="flex items-center gap-2">
                    <div class="w-8 h-8 rounded-lg ${badgeClass} flex items-center justify-center shrink-0"><i class="fa-solid ${icon} text-[11px]"></i></div>
                    <div class="min-w-0">
                        <p class="text-textMain font-semibold leading-tight truncate">${label}</p>
                        <p class="text-textSec text-[10px] leading-tight">${AI_CREDIT_WEIGHTS_DISPLAY[key]} credits</p>
                    </div>
                </div>
            `).join("");
        }

        function buildPlanFeatureLines(limits) {
            if (!limits) return [];
            const spec = [
                ["admin", "Admin", "Admins"],
                ["manager", "Manager", "Managers"],
                ["staff", "Staff", "Staff"],
                ["branch", "Branch", "Branches"],
                ["city", "City", "Cities"],
                ["country", "Country", "Countries"],
                ["product", "Product", "Products"],
                ["supplier", "Supplier", "Suppliers"],
                ["warehouse", "Warehouse", "Warehouses"],
                ["purchase_order", "Purchase Order", "Purchase Orders"],
                ["price_monitor", "Price Monitor source", "Price Monitor sources"],
                ["storage_gb", "GB Storage", "GB Storage"],
            ];
            // A resource limit of exactly 0 means the capability isn't part of this
            // plan at all — listing "0 X" reads as a broken/crippled feature rather
            // than a deliberate tier boundary, so it's omitted from the standard
            // list entirely (never shown as "Unlimited" either). It's still
            // communicated separately via the locked-feature/upgrade UI elsewhere.
            const lines = [];
            spec.forEach(([key, singular, plural]) => {
                const v = limits[key];
                if (v === null || v === undefined) { lines.push(`Unlimited ${plural}`); return; }
                if (Number(v) === 0) return;
                if (key === "storage_gb") { lines.push(`${Number(v).toLocaleString("en-NG")} ${plural}`); return; }
                lines.push(`${Number(v).toLocaleString("en-NG")} ${v === 1 ? singular : plural}`);
            });
            const credits = limits.included_ai_credits;
            if (credits === null || credits === undefined) lines.push("Unlimited AI Credits");
            else if (Number(credits) > 0) lines.push(`${Number(credits).toLocaleString("en-NG")} AI Credits`);
            return lines;
        }

        async function loadPublicPlanCatalog(forceRetry = false) {
            renderAiCreditWorkGrid();
            if (publicPlanCatalog && !forceRetry) { renderPlanCards(); return; }
            document.getElementById("plan-cards-loading").classList.remove("hidden");
            document.getElementById("plan-cards-error").classList.add("hidden");
            document.getElementById("plan-cards-grid").classList.add("hidden");
            try {
                const res = await fetch(`${API_URL}/plans`);
                if (!res.ok) throw new Error("plans_fetch_failed");
                publicPlanCatalog = await res.json();
                renderAnnualSavingsBadge();
                renderPlanCards();
            } catch (e) {
                document.getElementById("plan-cards-loading").classList.add("hidden");
                document.getElementById("plan-cards-error").classList.remove("hidden");
            }
        }

        function renderAnnualSavingsBadge() {
            const badge = document.getElementById("plan-annual-savings-badge");
            if (!badge || !publicPlanCatalog) return;
            // Computed from the server-returned prices (never hardcoded) — the
            // largest annual-vs-monthly discount across all plans.
            let maxPct = 0;
            Object.values(publicPlanCatalog).forEach(p => {
                if (!p.monthly_price || !p.annual_price) return;
                const pct = (1 - (p.annual_price / (p.monthly_price * 12))) * 100;
                if (pct > maxPct) maxPct = pct;
            });
            if (maxPct >= 1) {
                badge.textContent = `Save up to ${Math.round(maxPct)}%`;
                badge.classList.remove("hidden");
            } else {
                badge.classList.add("hidden");
            }
        }

        function renderIntervalToggleButtons() {
            const monthlyBtn = document.getElementById("plan-interval-btn-monthly");
            const annualBtn = document.getElementById("plan-interval-btn-annual");
            monthlyBtn.className = onboardingSelectedInterval === 'monthly'
                ? "flex-1 py-2 rounded-lg font-semibold transition cursor-pointer bg-primary text-white"
                : "flex-1 py-2 rounded-lg font-semibold transition cursor-pointer text-textSec hover:text-textMain";
            annualBtn.className = onboardingSelectedInterval === 'annual'
                ? "flex-1 py-2 rounded-lg font-semibold transition cursor-pointer bg-primary text-white"
                : "flex-1 py-2 rounded-lg font-semibold transition cursor-pointer text-textSec hover:text-textMain";
        }

        function setOnboardingInterval(interval) {
            onboardingSelectedInterval = (interval === 'annual') ? 'annual' : 'monthly';
            renderIntervalToggleButtons();
            renderPlanCards();
        }

        function renderPlanCards() {
            if (!publicPlanCatalog) return;
            document.getElementById("plan-cards-loading").classList.add("hidden");
            document.getElementById("plan-cards-error").classList.add("hidden");
            const grid = document.getElementById("plan-cards-grid");
            grid.classList.remove("hidden");
            // Stable, intentional display order regardless of object key order.
            const order = ["core", "starter", "business", "enterprise"];
            const ids = order.filter(id => publicPlanCatalog[id]).concat(Object.keys(publicPlanCatalog).filter(id => !order.includes(id)));
            const intervalLabel = onboardingSelectedInterval === 'annual' ? 'year' : 'month';
            grid.innerHTML = ids.map(id => {
                const p = publicPlanCatalog[id];
                const meta = PLAN_DISPLAY_META[id] || { icon: "fa-layer-group", description: "", theme: "blue" };
                const theme = PLAN_CARD_THEME[meta.theme] || PLAN_CARD_THEME.blue;
                const price = onboardingSelectedInterval === 'annual' ? p.annual_price : p.monthly_price;
                const lines = buildPlanFeatureLines(p.limits);
                const recommended = !!meta.recommended;
                return `
                    <div class="relative flex flex-col rounded-2xl border-2 ${recommended ? theme.border : 'border-borderCol'} ${recommended ? theme.cardBg : 'bg-bgMain'} p-4 pt-5 transition hover:border-primary/50 overflow-hidden">
                        ${recommended ? `<span class="absolute top-0 right-0 bg-success text-white text-[10px] font-bold px-3 py-1 rounded-bl-lg rounded-tr-2xl shadow-md tracking-wide">RECOMMENDED</span>` : ''}
                        <div class="flex items-center gap-2.5 mb-2.5">
                            <div class="w-11 h-11 rounded-xl ${theme.iconBg} flex items-center justify-center shrink-0 text-lg"><i class="fa-solid ${meta.icon}"></i></div>
                            <div class="min-w-0">
                                <p class="font-extrabold text-textMain text-base leading-tight">${escapeHtml(p.label)}</p>
                                <p class="text-textSec text-[10.5px] leading-snug mt-0.5">${escapeHtml(meta.description)}</p>
                            </div>
                        </div>
                        <div class="border-t border-borderCol mb-3"></div>
                        <ul class="space-y-2 mb-3 flex-1">
                            ${lines.map(f => `
                                <li class="flex items-center gap-2 text-textMain text-[11.5px] font-semibold">
                                    <span class="w-4 h-4 rounded-full bg-success/20 text-success flex items-center justify-center shrink-0"><i class="fa-solid fa-check text-[9px]"></i></span>
                                    <span class="min-w-0 break-words">${escapeHtml(f)}</span>
                                    ${f.includes('AI Credit') ? `<i class="fa-solid fa-circle-info text-textSec/60 text-[10px] shrink-0" title="AI credits reset each billing period"></i>` : ''}
                                </li>
                            `).join("")}
                            ${!p.ai_included ? `
                                <li class="flex items-center gap-2 text-textSec text-[11px] italic pt-1 border-t border-borderCol/60">
                                    <span class="w-4 h-4 rounded-full bg-textSec/15 text-textSec flex items-center justify-center shrink-0"><i class="fa-solid fa-lock text-[8px]"></i></span>
                                    <span class="min-w-0 break-words">AI features not included</span>
                                </li>
                            ` : ''}
                        </ul>
                        <button type="button" onclick="selectPlanAndContinue('${id}')"
                            class="w-full ${theme.button} text-white py-3 rounded-xl font-extrabold transition shadow-md cursor-pointer flex items-center justify-between px-4">
                            <span class="text-left leading-tight">
                                <span class="block text-lg">${formatNaira(price)}</span>
                                <span class="block text-[10px] font-semibold opacity-90">/ ${intervalLabel}</span>
                            </span>
                            <i class="fa-solid fa-arrow-right"></i>
                        </button>
                        ${onboardingSelectedInterval === 'annual' && p.annual_saving > 0 ? `<p class="text-center text-success text-[10px] font-bold mt-1.5">Save ${formatNaira(p.annual_saving)}/year</p>` : ''}
                        <p class="text-center text-textSec text-[10px] mt-1">Billed ${onboardingSelectedInterval === 'annual' ? 'annually' : 'monthly'} after trial</p>
                    </div>
                `;
            }).join("");
        }

        function selectPlanAndContinue(planId) {
            onboardingSelectedPlan = planId;
            verifiedOnboardingReference = null; // changing plan always requires a fresh card verification
            evResetVerification();
            switchBizAuthView('payment-email');
        }

        function changeSelectedPlan() {
            onboardingSelectedPlan = null;
            verifiedOnboardingReference = null;
            evResetVerification();
            switchBizAuthView('plan');
        }

        function renderPaymentEmailPlanBanner() {
            const el = document.getElementById("payment-email-plan-text");
            if (!el || !publicPlanCatalog?.[onboardingSelectedPlan]) return;
            const p = publicPlanCatalog[onboardingSelectedPlan];
            const price = onboardingSelectedInterval === 'annual' ? p.annual_price : p.monthly_price;
            el.textContent = `${p.label} • ${onboardingSelectedInterval === 'annual' ? 'Annual' : 'Monthly'} • ${formatNaira(price)}/${onboardingSelectedInterval === 'annual' ? 'year' : 'month'} after trial`;
        }

        // Reached only from STATE 3 (email already verified through Supabase). The
        // backend independently re-checks Supabase before it initialises Paystack,
        // so this can never actually proceed for an unverified email.
        async function startOnboardingPaymentVerification() {
            const email = (evVerifiedEmail || '').trim();
            if (!email) { evShowState(1); return; }
            if (!onboardingSelectedPlan) { switchBizAuthView('plan'); return; }
            const btn = document.getElementById("ev-continue-paystack-btn");
            if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Starting secure payment…`; }
            try {
                const res = await fetch(`${API_URL}/onboarding/payment/init`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email, plan: onboardingSelectedPlan, billing_interval: onboardingSelectedInterval })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotStartVerification")));
                // Only the reference travels through the redirect — the backend
                // re-derives plan/interval from its own verified record when the
                // user returns, never from anything stashed client-side.
                sessionStorage.setItem('cauldra_pending_onboarding_reference', data.reference);
                window.location.href = data.authorization_url;
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotStartVerification")), "error");
                if (btn) { btn.disabled = false; btn.innerHTML = `<i class="fa-solid fa-lock"></i> Continue to Paystack`; }
            }
        }
        const continueToPaystackAfterVerify = startOnboardingPaymentVerification;

        function evShowState(n) {
            for (let i = 1; i <= 4; i++) document.getElementById('ev-state-' + i)?.classList.toggle('hidden', i !== n);
            if (evPollTimer) { clearInterval(evPollTimer); evPollTimer = null; }
            if (n === 3 && evVerifiedEmail) {
                const e = document.getElementById('ev-email-verified'); if (e) e.textContent = evVerifiedEmail;
            }
            if (n === 2) evPollTimer = setInterval(() => checkEmailVerification(false), 5000);
        }
        function evResetVerification() {
            evVerifiedEmail = null;
            evResendCooldownUntil = 0;
            if (evResendTimer) { clearInterval(evResendTimer); evResendTimer = null; }
            if (evPollTimer) { clearInterval(evPollTimer); evPollTimer = null; }
        }
        function evBackToState1(focus) {
            evResetVerification();
            evShowState(1);
            if (focus) document.getElementById('payment-email-input')?.focus();
        }
        function onPaymentEmailInputChanged() {
            // Per spec: changing the email after verifying makes it unverified again.
            if (evVerifiedEmail !== null || evResendTimer || evPollTimer) { evResetVerification(); evShowState(1); }
        }
        function evEnsureChannel() {
            if (evVerifyChannel || typeof BroadcastChannel === 'undefined') return;
            try {
                evVerifyChannel = new BroadcastChannel('cauldra-email-verify');
                evVerifyChannel.onmessage = (m) => {
                    const d = (m && m.data) || {};
                    if (!d.verified || !d.email) return;
                    const want = (document.getElementById('payment-email-input')?.value || '').trim().toLowerCase();
                    if (want && d.email.toLowerCase() !== want) return;
                    evVerifiedEmail = d.email;
                    if (d.plan && publicPlanCatalog && publicPlanCatalog[d.plan]) onboardingSelectedPlan = d.plan;
                    if (d.interval === 'annual' || d.interval === 'monthly') onboardingSelectedInterval = d.interval;
                    if (!document.getElementById('biz-auth-view-payment-email')?.classList.contains('hidden')) evShowState(3);
                };
            } catch (_) {}
        }
        function evBroadcastVerified() {
            try {
                evEnsureChannel();
                evVerifyChannel?.postMessage({ verified: true, email: evVerifiedEmail, plan: onboardingSelectedPlan, interval: onboardingSelectedInterval });
            } catch (_) {}
        }
        function evStartResendCooldown(ms) {
            evResendCooldownUntil = Date.now() + Math.max(1000, ms || 60000);
            const btn = document.getElementById('ev-resend-btn');
            const label = document.getElementById('ev-resend-label');
            if (evResendTimer) clearInterval(evResendTimer);
            const tick = () => {
                const left = Math.ceil((evResendCooldownUntil - Date.now()) / 1000);
                if (left > 0) { if (btn) btn.disabled = true; if (label) label.textContent = `Resend in ${left}s`; }
                else { clearInterval(evResendTimer); evResendTimer = null; if (btn) btn.disabled = false; if (label) label.textContent = 'Resend verification email'; }
            };
            tick();
            evResendTimer = setInterval(tick, 1000);
        }
        async function evPostVerify(email) {
            const res = await fetch(`${API_URL}/onboarding/email/verify`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, plan: onboardingSelectedPlan, billing_interval: onboardingSelectedInterval })
            });
            const data = await res.json().catch(() => ({}));
            return { res, data };
        }
        async function startEmailVerification() {
            const email = (document.getElementById('payment-email-input')?.value || '').trim();
            if (!email || !email.includes('@')) { showToast(t("common.enterValidEmail"), "error"); return; }
            if (!onboardingSelectedPlan) { switchBizAuthView('plan'); return; }
            const btn = document.getElementById('ev-verify-btn');
            if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Sending verification email…`; }
            try {
                const { res, data } = await evPostVerify(email);
                if (!res.ok) throw new Error(showApiError(res, data, "We couldn't send the verification email. Please try again."));
                if (data.status === 'verified') { evVerifiedEmail = data.email || email; evShowState(3); return; }
                const e = document.getElementById('ev-email'); if (e) e.textContent = data.email || email;
                evEnsureChannel();
                evStartResendCooldown((data.resend_after_seconds || 60) * 1000);
                evShowState(2);
                showToast("Verification email sent.", "success");
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, "We couldn't send the verification email. Please try again."), "error");
            } finally {
                if (btn) { btn.disabled = false; btn.innerHTML = `<i class="fa-solid fa-envelope-circle-check"></i> Verify Email`; }
            }
        }
        async function resendEmailVerification() {
            if (Date.now() < evResendCooldownUntil) { showToast("Please wait before requesting another verification email.", "info"); return; }
            const email = (document.getElementById('payment-email-input')?.value || '').trim();
            if (!email) { evShowState(1); return; }
            try {
                const { res, data } = await evPostVerify(email);
                if (res.status === 429) { evStartResendCooldown(60000); showToast(data.detail || "Please wait before requesting another verification email.", "info"); return; }
                if (!res.ok) throw new Error(showApiError(res, data, "We couldn't resend the verification email."));
                if (data.status === 'verified') { evVerifiedEmail = data.email || email; evShowState(3); return; }
                evStartResendCooldown((data.resend_after_seconds || 60) * 1000);
                showToast("Verification email sent.", "success");
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, "We couldn't resend the verification email."), "error");
            }
        }
        async function checkEmailVerification(manual) {
            const email = (evVerifiedEmail || document.getElementById('payment-email-input')?.value || '').trim();
            if (!email) return;
            const btn = document.getElementById('ev-check-btn');
            if (manual && btn) { btn.disabled = true; btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Checking…`; }
            try {
                const res = await fetch(`${API_URL}/onboarding/email/verify/confirm`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email })
                });
                const data = await res.json().catch(() => ({}));
                if (res.ok && data.status === 'verified') {
                    evVerifiedEmail = data.email || email;
                    evBroadcastVerified();
                    evShowState(3);
                } else if (manual) {
                    showToast(data.detail || "Not verified yet. Open the link in your email, then check again.", "info");
                }
            } catch (_) {
                if (manual) showToast("We couldn't check verification just now. Please try again.", "error");
            } finally {
                if (manual && btn) { btn.disabled = false; btn.innerHTML = `<i class="fa-solid fa-rotate-right"></i> I've verified &mdash; check now`; }
            }
        }
        // Return from the Supabase verification link: ?cauldra_email_verify=1 plus
        // the session token in the URL fragment. The token is validated WITH
        // Supabase server-side; a URL flag alone never counts as verified.
        async function handleEmailVerifyReturn() {
            const params = new URLSearchParams(window.location.search);
            const hashParams = new URLSearchParams((window.location.hash || '').replace(/^#/, ''));
            const accessToken = hashParams.get('access_token') || '';
            const evPlan = params.get('ev_plan') || '';
            const evInterval = params.get('ev_interval') || '';
            window.history.replaceState({}, document.title, window.location.pathname);
            if (!publicPlanCatalog) { try { await loadPublicPlanCatalog(); } catch (_) {} }
            if (evPlan && publicPlanCatalog && publicPlanCatalog[evPlan]) onboardingSelectedPlan = evPlan;
            if (evInterval === 'annual' || evInterval === 'monthly') onboardingSelectedInterval = evInterval;
            openBusinessAuthModal();
            if (!onboardingSelectedPlan) { switchBizAuthView('plan'); return; }
            switchBizAuthView('payment-email');
            try {
                const res = await fetch(`${API_URL}/onboarding/email/verify/confirm`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ access_token: accessToken })
                });
                const data = await res.json().catch(() => ({}));
                if (res.ok && data.status === 'verified') {
                    evVerifiedEmail = data.email;
                    const inp = document.getElementById('payment-email-input'); if (inp) inp.value = data.email;
                    evBroadcastVerified();
                    evShowState(3);
                    showToast("Email verified successfully.", "success");
                } else {
                    const msg = document.getElementById('ev-state-4-msg');
                    if (msg) msg.textContent = data.detail || "We couldn't confirm this verification link. It may have expired.";
                    evShowState(4);
                }
            } catch (_) {
                evShowState(4);
            }
        }

        function renderRegisterPlanBanner() {
            if (!onboardingSelectedPlan || !publicPlanCatalog?.[onboardingSelectedPlan]) return;
            const p = publicPlanCatalog[onboardingSelectedPlan];
            const price = onboardingSelectedInterval === 'annual' ? p.annual_price : p.monthly_price;
            const bannerText = document.getElementById("reg-selected-plan-text");
            if (bannerText) {
                bannerText.textContent = `${p.label} • ${onboardingSelectedInterval === 'annual' ? 'Annual' : 'Monthly'} • ${formatNaira(price)}/${onboardingSelectedInterval === 'annual' ? 'year' : 'month'}`;
            }
        }

        async function handleRegisterBusinessSubmit(event) {
            event.preventDefault();
            if (!onboardingSelectedPlan || !verifiedOnboardingReference) {
                // Defense in depth — the UI shouldn't let this happen (register view
                // redirects back to plan selection if either is missing), but never
                // submit a registration without an explicit plan AND an already-
                // verified payment method regardless.
                showToast(t("subscription.choosePlanVerifyPayment"), "error");
                switchBizAuthView('plan');
                return;
            }
            const company_name = document.getElementById("reg-biz-name").value.trim();
            const country_region = document.getElementById("reg-biz-country").value;
            if (!country_region) {
                showToast(t("auth.selectCountryRegion"), "error");
                toggleCountryDropdown();
                return;
            }
            const email = document.getElementById("reg-biz-email").value.trim();
            const phonePrefix = document.getElementById("reg-biz-phone-prefix").value.trim();
            const phoneNumberRaw = document.getElementById("reg-biz-phone").value.trim();
            const phone = `${phonePrefix} ${phoneNumberRaw}`;
            const address = document.getElementById("reg-biz-address").value.trim();
            const currency = document.getElementById("reg-biz-currency").value;
            const language = document.getElementById("reg-biz-language")?.value || "en";
            const tax_id = document.getElementById("reg-biz-tax").value.trim();
            
            const firstname = document.getElementById("reg-owner-firstname").value.trim();
            const lastname = document.getElementById("reg-owner-lastname").value.trim();
            const owner_email = document.getElementById("reg-owner-email").value.trim();
            const ownerPhoneRaw = document.getElementById("reg-owner-phone").value.trim();
            const owner_phone = ownerPhoneRaw ? `${phonePrefix} ${ownerPhoneRaw}` : "";
            const username = document.getElementById("reg-owner-username").value.trim();
            const password = document.getElementById("reg-owner-password").value;
            const position = document.getElementById("reg-admin-position").value.trim();

            try {
                const response = await fetch(`${API_URL}/auth/register-business`, {
                    method: "POST",
                    credentials: "include",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        company_name, country: country_region, country_code: window.selectedBusinessContext?.country_code || "", locale: buildBusinessLocale(language, window.selectedBusinessContext?.country_code), language, timezone: window.selectedBusinessContext?.timezone || "UTC", phone_country_code: phonePrefix, email, phone, address, currency, tax_id,
                        firstname, lastname, owner_email, owner_phone, username, password, position,
                        plan: onboardingSelectedPlan, billing_interval: onboardingSelectedInterval,
                        payment_reference: verifiedOnboardingReference
                    })
                });
                const data = await response.json();
                if (response.ok) {
                    authToken = data.access_token;
                    currentUserProfile = {
                        id: data.id || null,
                        username: username,
                        role: data.role,
                        firstname: data.firstname,
                        lastname: data.lastname,
                        position: data.position,
                        phone: data.phone,
                        email: data.email,
                        must_change_password: data.must_change_password
                    };
                    businessProfile = {
                        id: data.business_id || null,
                        business_id: data.business_id || null,
                        business_code: data.business_code,
                        company_name: data.company_name,
                        currency: data.currency || currency, country: country_region, country_code: window.selectedBusinessContext?.country_code || data.country_code, locale: data.locale || buildBusinessLocale(language, window.selectedBusinessContext?.country_code), language: data.language || language, timezone: window.selectedBusinessContext?.timezone || data.timezone, phone_country_code: phonePrefix
                    };

                    startAuthRefreshHeartbeat();

                    verifiedOnboardingReference = null; // consumed server-side; never reusable
                    closeBusinessAuthModal();
                    redirectAuthenticatedBusinessToDashboard();
                    updateCompanyHeaderDisplay();
                    updateWelcomeBanner();
                    renderAuthButton();
                    updateFormCurrencyLabels();
                    syncLanguageFromProfile(businessProfile);
                    applyRoleRestrictions();
                    loadData();
                    openBusinessIdSuccessModal(data.business_code, data.trial_end_at);
                } else {
                    showAuthError(showApiError(response, data, "We couldn't create your business account. Please check the form and try again."));
                }
            } catch (err) {
                showToast(t("common.connectionError"), "error");
            }
        }

        function openBusinessIdSuccessModal(code, trialEndAt) {
            document.getElementById("popup-display-business-code").innerText = code;
            const planEl = document.getElementById("popup-selected-plan-label");
            if (planEl) {
                const p = publicPlanCatalog?.[onboardingSelectedPlan];
                planEl.textContent = p ? `${p.label} · ${onboardingSelectedInterval === 'annual' ? 'Annual' : 'Monthly'}` : '—';
            }
            const trialEl = document.getElementById("popup-trial-end-label");
            if (trialEl) {
                trialEl.textContent = trialEndAt ? formatDateShort(trialEndAt) : 'in 14 days';
            }
            document.getElementById("business-id-success-modal").classList.remove("hidden");
        }

