        async function handleSecureEmployeeAuthSubmit(event) {
            event.preventDefault();
            clearAuthError();
            const username = document.getElementById("employee-login-username").value.trim();
            const password = document.getElementById("employee-login-password").value;

            if (!verifiedSignInBusiness || !selectedSignInRole) {
                showToast(t("auth.verifyBusinessFirst"), "error");
                return;
            }

            try {
                const isAdmin = selectedSignInRole === 'admin';
                const endpoint = isAdmin ? `${API_URL}/auth/admin-login` : `${API_URL}/auth/employee-login`;
                const payload = isAdmin
                    ? { business_id: verifiedSignInBusiness.business_code, username, password }
                    : { business_id: verifiedSignInBusiness.business_code, username, password, selected_role: selectedSignInRole };

                const res = await fetch(endpoint, {
                    method: "POST",
                    credentials: "include",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload)
                });
                let data = {};
                try {
                    data = await res.json();
                } catch (_) {
                    data = {};
                }
                if (!res.ok) {
                    // Never expose raw FastAPI/Pydantic objects to users.
                    // Authentication failures are intentionally generic.
                    if (res.status === 401 || res.status === 422) {
                        showAuthError("Invalid username or password.");
                    } else {
                        showAuthError(showApiError(res, data, "Unable to sign in. Please check your details and try again."));
                    }
                    return;
                }

                authToken = data.access_token;
                currentUserProfile = {
                    id: data.id || null,
                    username: data.username || username,
                    role: String(data.role || selectedSignInRole).toLowerCase(),
                    firstname: data.firstname,
                    lastname: data.lastname,
                    position: data.position,
                    phone: data.phone,
                    email: data.email,
                    must_change_password: !!data.must_change_password
                };
                businessProfile = {
                    id: data.business_id || verifiedSignInBusiness.id,
                    business_id: data.business_id || verifiedSignInBusiness.id,
                    business_code: data.business_code,
                    company_name: data.company_name,
                    currency: data.currency || verifiedSignInBusiness.currency,
                    country: data.country || verifiedSignInBusiness.country,
                    country_code: data.country_code || verifiedSignInBusiness.country_code,
                    locale: data.locale || verifiedSignInBusiness.locale,
                    language: data.language || verifiedSignInBusiness.language || "en",
                    timezone: data.timezone || verifiedSignInBusiness.timezone,
                    phone_country_code: data.phone_country_code || verifiedSignInBusiness.phone_country_code
                };

                startAuthRefreshHeartbeat();


                closeBusinessAuthModal();
                redirectAuthenticatedBusinessToDashboard();
                updateCompanyHeaderDisplay();
                updateFormCurrencyLabels();
                syncLanguageFromProfile(businessProfile);
                applyRoleRestrictions();

                if (data.must_change_password) {
                    document.getElementById("password-change-modal").classList.remove("hidden");
                    document.getElementById("password-change-modal").style.display = "flex";
                    showToast(t("auth.createNewPasswordFirst"), "warning");
                    setTimeout(() => document.getElementById("pw-change-current")?.focus(), 50);
                } else {
                    await loadData();
                    showToast(t("auth.signedInAsRole", {role: ({admin:t("team.admin"),manager:t("team.manager"),staff:t("team.staff")})[currentUserProfile.role] || currentUserProfile.role}), "success");
                }
            } catch (e) {
                showAuthError("Unable to connect right now. Please check your connection and try again.");
            }
        }

        function setMandatoryPasswordMessage(message, type = 'error') {
            const el = document.getElementById('password-change-message');
            if (!el) return;
            el.className = `rounded-xl border px-3 py-2 text-[11px] ${type === 'success' ? 'border-success/25 bg-success/10 text-emerald-200' : 'border-danger/25 bg-danger/10 text-rose-200'}`;
            el.textContent = message;
            el.classList.remove('hidden');
        }

        async function handleMandatoryPasswordChange(event) {
            event.preventDefault();
            const current_password = document.getElementById("pw-change-current").value;
            const new_password = document.getElementById("pw-change-new").value;
            const confirm_password = document.getElementById("pw-change-confirm").value;
            const msg = document.getElementById('password-change-message');
            if (msg) msg.classList.add('hidden');

            if (new_password !== confirm_password) {
                setMandatoryPasswordMessage("The new passwords do not match.");
                return;
            }

            try {
                const res = await fetch(`${API_URL}/auth/change-password`, {
                    method: "POST",
                    credentials: "include",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ current_password, new_password })
                });
                const data = await res.json().catch(() => ({}));
                if (res.ok) {
                    if (data.access_token) authToken = data.access_token;
                    if (currentUserProfile) currentUserProfile.must_change_password = false;

                    document.getElementById("password-change-modal").classList.add("hidden");
                    showToast(t("auth.passwordUpdatedSuccess"), "success");
                    await loadData();
                } else {
                    setMandatoryPasswordMessage(data.detail || t("settings.passwordUpdateFailed"));
                }
            } catch (err) {
                setMandatoryPasswordMessage("We could not reach the server. Please try again.");
            }
        }

        // The Settings sidebar group covers three independent destinations —
        // Business Profile, Subscription & Billing, and Activity History —
        // each its own modal. These helpers keep the group's expand/collapse
        // and "active" indication working the same way whether the click
        // happened on the desktop sidebar or its mobile-drawer clone.
        function toggleSettingsSubmenu(btn) {
            const group = btn.closest(".settings-nav-group");
            const submenu = group?.querySelector(".settings-submenu");
            if (!submenu) return;
            const willExpand = submenu.classList.contains("hidden");
            submenu.classList.toggle("hidden", !willExpand);
            group.querySelectorAll(".settings-caret").forEach(c => c.classList.toggle("rotate-180", willExpand));
            btn.setAttribute("aria-expanded", String(willExpand));
        }

        // Expands every Settings submenu currently in the DOM (desktop + the
        // mobile-nav clone, when mounted) and highlights the active destination.
        function expandSettingsSubmenu(activeView) {
            document.querySelectorAll(".settings-nav-group").forEach(group => {
                const submenu = group.querySelector(".settings-submenu");
                const toggleBtn = group.querySelector("#nav-btn-settings, [onclick^='toggleSettingsSubmenu']");
                submenu?.classList.remove("hidden");
                group.querySelectorAll(".settings-caret").forEach(c => c.classList.add("rotate-180"));
                toggleBtn?.setAttribute("aria-expanded", "true");
            });
            document.querySelectorAll("[data-settings-view]").forEach(btn => {
                const active = btn.getAttribute("data-settings-view") === activeView;
                btn.classList.toggle("bg-cardHover", active);
                btn.classList.toggle("text-textMain", active);
            });
        }

        function closeAllSettingsModals() {
            document.getElementById("settings-modal")?.classList.add("hidden");
            document.getElementById("billing-modal")?.classList.add("hidden");
            document.getElementById("activity-history-modal")?.classList.add("hidden");
        }

        // The Team Management sidebar group covers three existing destinations —
        // Employees, Team Presence, and Account Action Requests — mirroring the
        // Settings group's expand/collapse and active-indication pattern above,
        // so it works the same on the desktop sidebar and its mobile-drawer clone.
        function toggleTeamManagementSubmenu(btn) {
            const group = btn.closest(".team-management-nav-group");
            const submenu = group?.querySelector(".team-management-submenu");
            if (!submenu) return;
            const willExpand = submenu.classList.contains("hidden");
            submenu.classList.toggle("hidden", !willExpand);
            group.querySelectorAll(".team-management-caret").forEach(c => c.classList.toggle("rotate-180", willExpand));
            btn.setAttribute("aria-expanded", String(willExpand));
        }

        // Expands every Team Management submenu currently in the DOM (desktop +
        // the mobile-nav clone, when mounted) and highlights the active destination.
        function expandTeamManagementSubmenu(activeView) {
            document.querySelectorAll(".team-management-nav-group").forEach(group => {
                const submenu = group.querySelector(".team-management-submenu");
                const toggleBtn = group.querySelector("#nav-btn-team-management, [onclick^='toggleTeamManagementSubmenu']");
                submenu?.classList.remove("hidden");
                group.querySelectorAll(".team-management-caret").forEach(c => c.classList.add("rotate-180"));
                toggleBtn?.setAttribute("aria-expanded", "true");
            });
            document.querySelectorAll("[data-team-management-view]").forEach(btn => {
                const active = btn.getAttribute("data-team-management-view") === activeView;
                btn.classList.toggle("bg-cardHover", active);
                btn.classList.toggle("text-textMain", active);
            });
        }

