        // ---------------------------------------------------------------------
        // SETTINGS > SUBSCRIPTION & BILLING
        // ---------------------------------------------------------------------
        let billingUsageCache = null;
        let billingIntervalChoice = 'monthly';

        const SUBSCRIPTION_STATUS_BADGES = {
            pending_payment_method: { label: 'Add Payment Method', cls: 'text-warning border-warning/40 bg-warning/10' },
            trialing: { label: 'Trial', cls: 'text-primary border-primary/40 bg-primary/10' },
            active: { label: 'Active', cls: 'text-success border-success/40 bg-success/10' },
            past_due: { label: 'Past Due', cls: 'text-warning border-warning/40 bg-warning/10' },
            payment_failed: { label: 'Payment Failed', cls: 'text-danger border-danger/40 bg-danger/10' },
            expired: { label: 'Expired', cls: 'text-danger border-danger/40 bg-danger/10' },
            cancelled: { label: 'Cancelled', cls: 'text-textSec border-borderCol bg-bgMain' },
        };

        function formatDateShort(iso) {
            if (!iso) return '—';
            try { return formatBusinessDate(iso, { year: 'numeric', month: 'short', day: 'numeric' }) || '—'; }
            catch (e) { return '—'; }
        }

        async function loadBillingPanel() {
            document.getElementById("billing-panel-loading")?.classList.remove("hidden");
            document.getElementById("billing-panel-content")?.classList.add("hidden");
            try {
                const [usageRes, paymentsRes] = await Promise.all([
                    fetch(`${API_URL}/subscription/usage`, { headers: { "Authorization": `Bearer ${authToken}` } }),
                    fetch(`${API_URL}/subscription/payments`, { headers: { "Authorization": `Bearer ${authToken}` } })
                ]);
                if (!usageRes.ok) throw new Error('usage_failed');
                billingUsageCache = await usageRes.json();
                billingIntervalChoice = billingUsageCache.billing_interval === 'annual' ? 'annual' : 'monthly';
                const payments = paymentsRes.ok ? await paymentsRes.json() : [];
                document.getElementById("billing-panel-loading")?.classList.add("hidden");
                document.getElementById("billing-panel-content")?.classList.remove("hidden");
                renderBillingStatus(billingUsageCache);
                renderBillingAiUsage(billingUsageCache);
                renderBillingIntervalToggle();
                renderBillingPlanCards();
                renderPaymentHistory(payments);
            } catch (e) {
                console.error("Failed to load subscription/billing data:", e);
                document.getElementById("billing-panel-loading").innerHTML = `
                    <p class="text-danger mb-2">Couldn't load your subscription right now.</p>
                    <button type="button" onclick="loadBillingPanel()" class="text-primary underline cursor-pointer">Retry</button>`;
            }
        }

        function renderBillingStatus(usage) {
            const badge = SUBSCRIPTION_STATUS_BADGES[usage.status] || { label: usage.status, cls: 'text-textSec border-borderCol bg-bgMain' };
            document.getElementById("billing-plan-label").textContent = usage.plan_label || usage.plan;
            const statusBadgeEl = document.getElementById("billing-status-badge");
            statusBadgeEl.textContent = badge.label;
            statusBadgeEl.className = `px-2.5 py-1 rounded-lg text-[10px] font-bold border ${badge.cls}`;
            document.getElementById("billing-interval-value").textContent = usage.billing_interval === 'annual' ? 'Annual' : 'Monthly';
            document.getElementById("billing-price-value").textContent = `${formatNaira(usage.current_price_naira)}/${usage.billing_interval === 'annual' ? 'year' : 'month'}`;

            const trialBox = document.getElementById("billing-trial-dates-box");
            if (usage.status === 'trialing' && usage.trial_start_at) {
                trialBox.classList.remove("hidden");
                document.getElementById("billing-trial-dates-value").textContent = `${formatDateShort(usage.trial_start_at)} → ${formatDateShort(usage.trial_ends_at)} (${usage.trial_days_remaining} day${usage.trial_days_remaining === 1 ? '' : 's'} left)`;
            } else {
                trialBox.classList.add("hidden");
            }

            const nextBillingBox = document.getElementById("billing-next-billing-box");
            if (usage.next_billing_at && ['trialing', 'active', 'past_due'].includes(usage.status)) {
                nextBillingBox.classList.remove("hidden");
                document.getElementById("billing-next-billing-value").textContent = usage.cancel_at_period_end
                    ? `Access ends ${formatDateShort(usage.current_period_end || usage.next_billing_at)} (cancelled)`
                    : formatDateShort(usage.next_billing_at);
            } else {
                nextBillingBox.classList.add("hidden");
            }

            const cardBox = document.getElementById("billing-card-box");
            if (usage.card_verified && usage.card_last4) {
                cardBox.classList.remove("hidden");
                const brand = usage.card_type ? usage.card_type.charAt(0).toUpperCase() + usage.card_type.slice(1) : 'Card';
                document.getElementById("billing-card-value").textContent = `${brand} •••• ${usage.card_last4}`;
            } else {
                cardBox.classList.add("hidden");
            }

            const cancelRow = document.getElementById("billing-cancel-row");
            const cancelBtn = document.getElementById("billing-cancel-btn");
            const isAdmin = getCurrentRole() === 'admin';
            if (isAdmin && usage.status === 'trialing') {
                cancelRow.classList.remove("hidden");
                cancelBtn.textContent = 'Cancel Trial';
                cancelBtn.onclick = () => openCancelConfirm('trial');
            } else if (isAdmin && ['active', 'past_due'].includes(usage.status) && !usage.cancel_at_period_end) {
                cancelRow.classList.remove("hidden");
                cancelBtn.textContent = 'Cancel Subscription';
                cancelBtn.onclick = () => openCancelConfirm('subscription');
            } else {
                cancelRow.classList.add("hidden");
            }

            // Pending downgrade — server-authoritative; this box is purely a
            // display of usage.pending_downgrade, never a client-side decision.
            const pendingBox = document.getElementById("billing-pending-downgrade-box");
            if (usage.pending_downgrade) {
                pendingBox.classList.remove("hidden");
                const pd = usage.pending_downgrade;
                const effectiveText = pd.effective_at ? ` on ${formatDateShort(pd.effective_at)}` : '';
                document.getElementById("billing-pending-downgrade-text").textContent =
                    `Your plan will change from ${usage.plan_label || usage.plan} to ${pd.plan_label} (${pd.billing_interval === 'annual' ? 'Annual' : 'Monthly'}) at the end of your current billing period${effectiveText}.`;
            } else {
                pendingBox.classList.add("hidden");
            }
        }

        // AI Usage & Resources — moved here from the dashboard (see dashboard
        // decluttering). Pure render over the exact same /subscription/usage
        // payload loadBillingPanel() already fetched for the status block
        // above; never a second/duplicate fetch. Also keeps currentAiEntitled
        // in sync, same as the dashboard version did, so AI-gated features
        // still see an accurate entitlement while this modal is the one place
        // reflecting it — the lightweight dashboard warning check (see
        // checkSubscriptionWarningForDashboard()) keeps it current the rest
        // of the time.
        function renderBillingAiUsage(data) {
            currentAiEntitled = Number(data.included_ai_credits || 0) > 0;
            const used = Number(data.used_ai_credits || 0), included = Number(data.included_ai_credits || 0), percent = included ? Math.min(100, (used / included) * 100) : 0;
            document.getElementById('subscription-ai-label').textContent = t('subscription.creditsUsedOfIncluded', { used: used.toLocaleString(getBusinessLocale()), included: included.toLocaleString(getBusinessLocale()) });
            const bar = document.getElementById('subscription-ai-bar'); bar.style.width = `${percent}%`; bar.className = `h-full rounded-full ${data.ai_warning === 'overage' ? 'bg-danger' : data.ai_warning === 'warning' ? 'bg-warning' : 'bg-primary'}`;
            document.getElementById('subscription-ai-detail').textContent = data.overage_credits
                ? t('subscription.overageCreditsEstimate', { count: data.overage_credits.toLocaleString(getBusinessLocale()), amount: formatCurrency(data.estimated_overage_charge || 0) })
                : t('subscription.includedCreditsRemaining', { count: Number(data.remaining_ai_credits || 0).toLocaleString(getBusinessLocale()) });
            const warning = document.getElementById('subscription-warning');
            if (data.ai_warning) { warning.classList.remove('hidden'); warning.className = `mb-2 rounded-lg px-2.5 py-2 text-[11px] ${data.ai_warning === 'overage' ? 'bg-danger/10 text-danger border border-danger/25' : 'bg-warning/10 text-warning border border-warning/25'}`; warning.textContent = data.ai_warning === 'overage' ? t('subscription.creditsExhausted') : t('subscription.creditsWarning80'); } else warning.classList.add('hidden');
            const labels = { products: t('subscription.resourceProducts'), suppliers: t('subscription.resourceSuppliers'), warehouses: t('subscription.resourceWarehouses'), users: t('subscription.resourceUsers'), price_monitor_sources: t('subscription.resourcePriceSources'), purchase_orders: t('subscription.resourcePurchaseOrders'), storage: t('subscription.resourceStorage') };
            const formatResourceLabel = (key) => labels[key] || key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
            document.getElementById('subscription-resources').innerHTML = Object.entries(data.resources || {}).map(([key, value]) => {
                const unit = value.unit ? ` ${value.unit}` : '';
                const usedText = `${Number(value.used || 0).toLocaleString(getBusinessLocale())}${unit}`;
                const limitText = value.limit == null ? t('subscription.unlimited') : `${Number(value.limit).toLocaleString(getBusinessLocale())}${unit}`;
                return `<div class="rounded-xl bg-cardBg border border-borderCol px-2.5 py-2 min-w-0"><div class="text-[9px] uppercase tracking-wide text-textSec truncate">${formatResourceLabel(key)}</div><div class="text-xs font-bold text-textMain mt-0.5">${usedText} <span class="text-textSec font-normal">/ ${limitText}</span></div></div>`;
            }).join('');
        }

        function renderBillingIntervalToggle() {
            const monthlyBtn = document.getElementById("billing-interval-btn-monthly");
            const annualBtn = document.getElementById("billing-interval-btn-annual");
            const activeCls = "px-2.5 py-1 rounded-lg font-semibold transition cursor-pointer bg-primary text-white";
            const inactiveCls = "px-2.5 py-1 rounded-lg font-semibold transition cursor-pointer text-textSec hover:text-textMain";
            monthlyBtn.className = billingIntervalChoice === 'monthly' ? activeCls : inactiveCls;
            annualBtn.className = billingIntervalChoice === 'annual' ? activeCls : inactiveCls;
        }

        function setBillingIntervalChoice(interval) {
            billingIntervalChoice = interval === 'annual' ? 'annual' : 'monthly';
            renderBillingIntervalToggle();
            renderBillingPlanCards();
        }

        function renderBillingPlanCards() {
            if (!billingUsageCache) return;
            const usage = billingUsageCache;
            const plans = usage.plans || {};
            const isAdmin = getCurrentRole() === 'admin';
            const order = ["core", "starter", "business", "enterprise"];
            const ids = order.filter(id => plans[id]).concat(Object.keys(plans).filter(id => !order.includes(id)));
            const currentPlan = (usage.plan || '').toLowerCase();
            const intervalLabel = billingIntervalChoice === 'annual' ? 'year' : 'month';

            const pendingDowngrade = usage.pending_downgrade;

            document.getElementById("billing-plan-cards").innerHTML = ids.map(id => {
                const p = plans[id];
                const price = billingIntervalChoice === 'annual' ? p.annual_price : p.monthly_price;
                const isCurrent = id === currentPlan && billingIntervalChoice === usage.billing_interval && ['trialing', 'active', 'past_due'].includes(usage.status);
                const isPendingTarget = !!pendingDowngrade && pendingDowngrade.plan === id && pendingDowngrade.billing_interval === billingIntervalChoice;
                // A genuine plan-TIER downgrade (not a same-tier interval switch) is
                // only reachable through the scheduled-downgrade flow — the server
                // rejects an immediate one anyway, this just avoids showing an
                // action that would fail. Rank is proxied by the display order,
                // which already mirrors the server's PLAN_RANK exactly.
                const isDowngradeTarget = ['active', 'past_due'].includes(usage.status) && order.indexOf(id) < order.indexOf(currentPlan);
                const features = buildPlanFeatureLines(p.limits);
                let actionLabel = "";
                let priceButtonHtml;
                if (!isAdmin) {
                    priceButtonHtml = `<div class="w-full text-center bg-bgMain border border-borderCol text-textMain py-2.5 rounded-xl font-bold text-sm">${formatNaira(price)} <span class="font-semibold text-xs opacity-70">/ ${intervalLabel}</span></div>`;
                } else if (isCurrent) {
                    priceButtonHtml = `<button type="button" disabled class="w-full bg-bgMain text-textSec border border-borderCol py-2.5 rounded-xl font-bold text-sm cursor-not-allowed">Current Plan</button>`;
                } else if (isPendingTarget) {
                    actionLabel = "Downgrade scheduled for your next renewal";
                    priceButtonHtml = `<button type="button" disabled class="w-full bg-warning/15 text-warning border border-warning/30 py-2.5 rounded-xl font-bold text-sm cursor-not-allowed">Scheduled</button>`;
                } else {
                    let onclickFn;
                    if (usage.can_start_trial) { actionLabel = "Start your 14-day free trial"; onclickFn = `openTrialConfirm('${id}','${billingIntervalChoice}')`; }
                    else if (usage.status === 'trialing') { actionLabel = "Switch to this plan"; onclickFn = `switchPlanImmediate('${id}','${billingIntervalChoice}')`; }
                    else if (isDowngradeTarget) { actionLabel = "Takes effect at your next renewal"; onclickFn = `openDowngradeConfirm('${id}','${billingIntervalChoice}')`; }
                    else if (['active', 'past_due'].includes(usage.status)) { actionLabel = "Switch / subscribe to this plan"; onclickFn = `subscribeNow('${id}','${billingIntervalChoice}')`; }
                    else { actionLabel = "Subscribe to this plan"; onclickFn = `subscribeNow('${id}','${billingIntervalChoice}')`; }
                    const btnColor = isDowngradeTarget ? "bg-textSec/80 hover:bg-textSec text-white shadow-md" : "bg-primary hover:bg-primaryHover text-white shadow-md shadow-primary/20";
                    priceButtonHtml = `<button type="button" onclick="${onclickFn}" class="w-full ${btnColor} py-2.5 rounded-xl font-bold text-sm transition cursor-pointer">${formatNaira(price)} <span class="font-semibold text-xs opacity-90">/ ${intervalLabel}</span></button>`;
                }
                return `
                    <div class="flex flex-col rounded-xl border-2 ${isCurrent ? 'border-primary bg-primary/10' : 'border-borderCol bg-bgMain'} p-3">
                        <div class="flex items-center justify-between mb-2">
                            <span class="font-bold text-textMain">${escapeHtml(p.label)}</span>
                            ${isCurrent ? '<i class="fa-solid fa-circle-check text-primary"></i>' : ''}
                        </div>
                        <ul class="space-y-1 mb-3 flex-1">
                            ${features.map(f => `<li class="flex items-start gap-1.5 text-textSec text-[11px]"><i class="fa-solid fa-check text-primary mt-0.5 shrink-0"></i><span class="min-w-0 break-words">${escapeHtml(f)}</span></li>`).join("")}
                            ${!p.ai_included ? `<li class="flex items-start gap-1.5 text-textSec text-[11px] italic pt-1 border-t border-borderCol/60"><i class="fa-solid fa-lock mt-0.5 shrink-0"></i><span class="min-w-0 break-words">AI features not included</span></li>` : ''}
                        </ul>
                        ${actionLabel ? `<p class="text-textSec text-[10px] mb-1 text-center">${actionLabel}</p>` : ''}
                        ${priceButtonHtml}
                        ${billingIntervalChoice === 'annual' && p.annual_saving > 0 ? `<p class="text-center text-success text-[10px] font-bold mt-1.5">Save ${formatNaira(p.annual_saving)}/year</p>` : ''}
                    </div>
                `;
            }).join("");
        }

        function renderPaymentHistory(payments) {
            const el = document.getElementById("billing-payment-history");
            if (!payments || !payments.length) {
                el.innerHTML = `<p class="text-textSec text-center py-3">No payments yet.</p>`;
                return;
            }
            el.innerHTML = payments.map(p => `
                <div class="flex items-center justify-between bg-bgMain border border-borderCol rounded-lg px-2.5 py-2">
                    <div class="min-w-0">
                        <p class="text-textMain font-semibold truncate">${escapeHtml(p.plan_label || p.plan)} · ${p.billing_interval === 'annual' ? 'Annual' : 'Monthly'}</p>
                        <p class="text-textSec text-[10px]">${formatDateShort(p.paid_at || p.created_at)}</p>
                    </div>
                    <div class="text-right shrink-0 ml-2">
                        <p class="text-textMain font-semibold">${formatNaira(p.amount_naira)}</p>
                        <p class="text-[10px] ${p.status === 'success' ? 'text-success' : (p.status === 'failed' ? 'text-danger' : 'text-textSec')}">${escapeHtml(p.status)}</p>
                    </div>
                </div>
            `).join("");
        }

        // --- Start trial ---
        let pendingTrialSelection = null;

        function openTrialConfirm(plan, interval) {
            const p = billingUsageCache?.plans?.[plan];
            if (!p) return;
            pendingTrialSelection = { plan, interval };
            const price = interval === 'annual' ? p.annual_price : p.monthly_price;
            document.getElementById("trial-confirm-plan-summary").textContent = `${p.label} • ${interval === 'annual' ? 'Annual' : 'Monthly'} • ${formatNaira(price)}/${interval === 'annual' ? 'year' : 'month'} after trial`;
            document.getElementById("trial-consent-checkbox").checked = false;
            document.getElementById("trial-start-confirm-modal").classList.remove("hidden");
        }

        function closeTrialConfirmModal() {
            document.getElementById("trial-start-confirm-modal").classList.add("hidden");
            pendingTrialSelection = null;
        }

        async function confirmStartTrial() {
            if (!pendingTrialSelection) return;
            if (!document.getElementById("trial-consent-checkbox").checked) {
                showToast(t("subscription.agreeTermsFirst"), "error");
                return;
            }
            const btn = document.getElementById("trial-confirm-submit-btn");
            btn.disabled = true; btn.textContent = 'Starting…';
            try {
                const res = await fetch(`${API_URL}/subscription/trial/init`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
                    body: JSON.stringify({ plan: pendingTrialSelection.plan, billing_interval: pendingTrialSelection.interval })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotStartCardVerification")));
                sessionStorage.setItem('cauldra_pending_trial_reference', data.reference);
                window.location.href = data.authorization_url;
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotStartCardVerification")), "error");
                btn.disabled = false; btn.textContent = 'Start 14-Day Free Trial';
            }
        }

        // --- Cancel trial / subscription ---
        let pendingCancelKind = null;

        function openCancelConfirm(kind) {
            pendingCancelKind = kind;
            const title = document.getElementById("cancel-confirm-title");
            const body = document.getElementById("cancel-confirm-body");
            if (kind === 'trial') {
                title.innerHTML = `<i class="fa-solid fa-triangle-exclamation text-danger"></i> Cancel your free trial?`;
                body.textContent = "Cancelling now will prevent your trial from converting into a paid subscription. You won't be charged, and your business data will be kept.";
            } else {
                title.innerHTML = `<i class="fa-solid fa-triangle-exclamation text-danger"></i> Cancel your subscription?`;
                const until = billingUsageCache?.current_period_end ? formatDateShort(billingUsageCache.current_period_end) : 'the end of your current billing period';
                body.textContent = `Your access continues until ${until}. No further payment will be charged after that. Your business data will be kept.`;
            }
            document.getElementById("subscription-cancel-confirm-modal").classList.remove("hidden");
        }

        function closeCancelConfirmModal() {
            document.getElementById("subscription-cancel-confirm-modal").classList.add("hidden");
            pendingCancelKind = null;
        }

        async function confirmCancellation() {
            if (!pendingCancelKind) return;
            const btn = document.getElementById("cancel-confirm-submit-btn");
            btn.disabled = true; btn.textContent = 'Cancelling…';
            const endpoint = pendingCancelKind === 'trial' ? '/subscription/trial/cancel' : '/subscription/cancel';
            try {
                const res = await fetch(`${API_URL}${endpoint}`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotProcessCancellation")));
                showToast(pendingCancelKind === 'trial' ? t("subscription.trialCancelled") : t("subscription.subscriptionCancelled"), "success");
                closeCancelConfirmModal();
                loadBillingPanel();
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotProcessCancellation")), "error");
            } finally {
                btn.disabled = false; btn.textContent = 'Confirm Cancellation';
            }
        }

        // --- Direct paid checkout / free plan switch ---
        async function subscribeNow(plan, interval) {
            try {
                const res = await fetch(`${API_URL}/subscription/checkout`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
                    body: JSON.stringify({ plan, billing_interval: interval })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotStartCheckout")));
                sessionStorage.setItem('cauldra_pending_checkout_reference', data.reference || '');
                window.location.href = data.authorization_url;
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotStartCheckout")), "error");
            }
        }

        async function switchPlanImmediate(plan, interval) {
            try {
                const res = await fetch(`${API_URL}/subscription/change-plan`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
                    body: JSON.stringify({ plan, billing_interval: interval })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) {
                    if (res.status === 402) {
                        return subscribeNow(plan, interval);
                    }
                    throw new Error(showApiError(res, data, t("subscription.couldNotSwitchPlans")));
                }
                showToast(t("subscription.planUpdated"), "success");
                loadBillingPanel();
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotSwitchPlans")), "error");
            }
        }

        // --- Scheduled downgrade (takes effect at the end of the current billing
        // period — see /subscription/downgrade in main.py). The server alone
        // computes the effective date from the trusted subscription record; this
        // modal only ever displays what usage.current_period_end already says. ---
        let pendingDowngradeSelection = null;

        function openDowngradeConfirm(plan, interval) {
            const usage = billingUsageCache;
            const target = usage?.plans?.[plan];
            if (!usage || !target) return;
            pendingDowngradeSelection = { plan, interval };
            const currentLabel = escapeHtml(usage.plan_label || usage.plan);
            const targetLabel = escapeHtml(target.label);
            const targetPrice = formatNaira(interval === 'annual' ? target.annual_price : target.monthly_price);
            const intervalWord = interval === 'annual' ? 'year' : 'month';
            const effectiveDate = usage.current_period_end ? formatDateShort(usage.current_period_end) : null;
            document.getElementById("downgrade-confirm-title").innerHTML = `<i class="fa-solid fa-arrow-down text-warning shrink-0"></i> <span class="min-w-0">Downgrade to ${targetLabel}?</span>`;
            document.getElementById("downgrade-confirm-body").innerHTML =
                `You'll keep your current <strong>${currentLabel}</strong> features until the end of your current billing period${effectiveDate ? ` (<strong>${escapeHtml(effectiveDate)}</strong>)` : ''}.<br><br>` +
                `Your account will then switch to <strong>${targetLabel}</strong> at your next renewal. You'll be charged the ${targetLabel} price of <strong>${targetPrice}/${intervalWord}</strong> for that billing period.<br><br>` +
                `No refund is issued for the remainder of your current period, and you can cancel this scheduled downgrade at any time before it takes effect.`;
            document.getElementById("downgrade-confirm-modal").classList.remove("hidden");
        }

        function closeDowngradeConfirmModal() {
            document.getElementById("downgrade-confirm-modal").classList.add("hidden");
            pendingDowngradeSelection = null;
        }

        async function confirmScheduleDowngrade() {
            if (!pendingDowngradeSelection) return;
            const { plan, interval } = pendingDowngradeSelection;
            const btn = document.getElementById("downgrade-confirm-submit-btn");
            btn.disabled = true; btn.textContent = "Scheduling…";
            try {
                const res = await fetch(`${API_URL}/subscription/downgrade`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
                    body: JSON.stringify({ plan, billing_interval: interval })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotScheduleDowngrade")));
                closeDowngradeConfirmModal();
                billingUsageCache = data;
                renderBillingStatus(data);
                renderBillingPlanCards();
                showToast(t("subscription.downgradeScheduledToast"), "success");
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotScheduleDowngrade")), "error");
            } finally {
                btn.disabled = false; btn.textContent = "Confirm Downgrade";
            }
        }

        async function cancelScheduledDowngrade() {
            try {
                const res = await fetch(`${API_URL}/subscription/downgrade/cancel`, {
                    method: 'POST',
                    headers: { 'Authorization': `Bearer ${authToken}` }
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotCancelDowngrade")));
                billingUsageCache = data;
                renderBillingStatus(data);
                renderBillingPlanCards();
                showToast(t("subscription.downgradeCancelledSuccess"), "success");
            } catch (err) {
                showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotCancelDowngrade")), "error");
            }
        }

        // --- Return from Paystack (trial card verification or direct checkout) ---
        async function handlePaystackReturn() {
            const params = new URLSearchParams(window.location.search);
            const reference = params.get('reference') || params.get('trxref');
            if (!reference) return;

            // New-business onboarding references are generated server-side with
            // the cauldra_onboard_ prefix. Do not require sessionStorage to
            // survive the trip to Paystack and back.
            const pendingOnboardingRef = sessionStorage.getItem('cauldra_pending_onboarding_reference');
            const isOnboardingReturn =
                String(reference).startsWith('cauldra_onboard_') ||
                pendingOnboardingRef === reference;

            if (isOnboardingReturn) {
                if (redirectAuthenticatedBusinessToDashboard()) {
                    sessionStorage.removeItem('cauldra_pending_onboarding_reference');
                    window.history.replaceState({}, document.title, '/');
                    return;
                }
                openBusinessAuthModal();
                switchBizAuthView('payment-verifying');

                try {
                    const res = await fetch(`${API_URL}/onboarding/payment/confirm`, {
                        method: 'POST',
                        credentials: 'include',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json'
                        },
                        body: JSON.stringify({ reference })
                    });

                    const data = await res.json().catch(() => ({}));

                    if (!res.ok) {
                        throw new Error(showApiError(
                            res,
                            data,
                            "We couldn't verify your payment method. Please try again."
                        ));
                    }

                    // The backend is authoritative for the selected plan and
                    // billing interval after Paystack verification.
                    onboardingSelectedPlan = data.plan;
                    onboardingSelectedInterval = data.billing_interval;
                    verifiedOnboardingReference = reference;

                    sessionStorage.removeItem('cauldra_pending_onboarding_reference');

                    // Remove the Paystack query parameters only after the
                    // server has successfully verified the reference.
                    window.history.replaceState(
                        {},
                        document.title,
                        window.location.pathname
                    );

                    if (!publicPlanCatalog) {
                        await loadPublicPlanCatalog();
                    }

                    const refundNotice = data.refund_status === 'succeeded'
                        ? ' The verification charge refund has succeeded.'
                        : data.refund_status === 'failed'
                            ? ' The verification charge refund failed and can be retried safely.'
                            : ' The verification charge refund is pending Paystack processing.';
                    showToast(
                        "Payment method verified! Complete your business details to start your free trial." + refundNotice,
                        "success"
                    );

                    // Required new-business sequence:
                    // Paystack -> server verification -> Register Your Business
                    switchBizAuthView('register');
                } catch (err) {
                    showToast(
                        friendlyErrorMessage(
                            err?.message || err,
                            "We couldn't verify your payment method. Please try again."
                        ),
                        "error"
                    );

                    switchBizAuthView('payment-email');
                }

                return;
            }

            // Existing authenticated Paystack flows remain unchanged.
            if (!authToken) return;

            const pendingTrialRef = sessionStorage.getItem('cauldra_pending_trial_reference');
            const pendingCheckoutRef = sessionStorage.getItem('cauldra_pending_checkout_reference');
            window.history.replaceState({}, document.title, window.location.pathname);

            if (pendingTrialRef && pendingTrialRef === reference) {
                sessionStorage.removeItem('cauldra_pending_trial_reference');
                try {
                    const res = await fetch(`${API_URL}/subscription/trial/confirm`, {
                        method: 'POST',
                        credentials: 'include',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${authToken}`
                        },
                        body: JSON.stringify({ reference })
                    });
                    const data = await res.json().catch(() => ({}));
                    if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotConfirmCardVerification")));
                    showToast(t("subscription.trialStarted"), "success");
                    if (data.refund_status === 'succeeded') {
                        showToast("The verification charge refund has succeeded.", "success");
                    } else if (data.refund_status === 'failed') {
                        showToast("The trial is active, but the verification charge refund failed and can be retried safely.", "error");
                    } else {
                        showToast("The verification charge refund is pending Paystack processing.", "info");
                    }
                } catch (err) {
                    showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotConfirmCardVerification")), "error");
                }
                return;
            }

            if (pendingCheckoutRef && pendingCheckoutRef === reference) {
                sessionStorage.removeItem('cauldra_pending_checkout_reference');
                try {
                    const res = await fetch(`${API_URL}/subscription/checkout/confirm`, {
                        method: 'POST',
                        credentials: 'include',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${authToken}`
                        },
                        body: JSON.stringify({ reference })
                    });
                    const data = await res.json().catch(() => ({}));
                    if (!res.ok) throw new Error(showApiError(res, data, t("subscription.couldNotConfirmPayment")));
                    showToast(t("subscription.paymentConfirmed"), "success");
                    checkSubscriptionWarningForDashboard();
                    loadBillingPanel();
                } catch (err) {
                    showToast(friendlyErrorMessage(err?.message || err, t("subscription.couldNotConfirmPayment")), "error");
                }
            }
        }

        function populateBusinessForm(profile) {
            document.getElementById("company-name-input").value = profile.company_name || "";
            document.getElementById("company-code-input").value = profile.business_code || "";
            document.getElementById("company-email-input").value = profile.email || "";
            document.getElementById("company-phone-input").value = profile.phone || "";
            document.getElementById("company-address-input").value = profile.address || "";
            document.getElementById("company-currency-input").value = profile.currency || "USD ($)";
            populateLanguageSelects(profile.language || "en");
            const countryEl = document.getElementById("company-country-input");
            const codeEl = document.getElementById("company-phone-code-input");
            if (countryEl) countryEl.value = profile.country || "Not specified";
            if (codeEl) codeEl.value = profile.phone_country_code || "Not specified";
            document.getElementById("company-tax-input").value = profile.tax_id || "";
        }

        let employeeDirectoryUsers = [];

        function escapeEmployeeHtml(value) {
            return String(value ?? "")
                .replace(/&/g, "&amp;")
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/"/g, "&quot;")
                .replace(/'/g, "&#039;");
        }

        function updateEmployeeDirectoryCounts(users) {
            const list = Array.isArray(users) ? users : [];
            const counts = {
                all: list.length,
                admin: list.filter(u => String(u.role || "").toLowerCase() === "admin" || String(u.role || "").toLowerCase() === "owner").length,
                manager: list.filter(u => String(u.role || "").toLowerCase() === "manager").length,
                staff: list.filter(u => String(u.role || "").toLowerCase() === "staff").length
            };

            const allEl = document.getElementById("employee-count-all");
            const adminEl = document.getElementById("employee-count-admin");
            const managerEl = document.getElementById("employee-count-manager");
            const staffEl = document.getElementById("employee-count-staff");

            if (allEl) allEl.innerText = counts.all;
            if (adminEl) adminEl.innerText = counts.admin;
            if (managerEl) managerEl.innerText = counts.manager;
            if (staffEl) staffEl.innerText = counts.staff;
        }

        // Shared by the search/role filter UI and the CSV export, so
        // "export what I'm currently seeing" can never drift from what
        // filterEmployeesList() actually renders.
        function getFilteredEmployees() {
            const searchInput = document.getElementById("employee-search-input");
            const roleFilter = document.getElementById("employee-role-filter");
            const query = (searchInput?.value || "").trim().toLowerCase();
            const selectedRole = (roleFilter?.value || "all").toLowerCase();

            return employeeDirectoryUsers.filter(u => {
                const role = String(u.role || "staff").toLowerCase();
                const roleMatches = selectedRole === "all" || role === selectedRole || (selectedRole === "admin" && role === "owner");

                const fullName = `${u.firstname || ""} ${u.lastname || ""}`.trim();
                const searchable = [
                    fullName,
                    u.username,
                    u.position,
                    u.role,
                    u.email,
                    u.phone
                ].filter(Boolean).join(" ").toLowerCase();

                return roleMatches && (!query || searchable.includes(query));
            });
        }

        function filterEmployeesList() {
            const container = document.getElementById("company-employees-list");
            if (!container) return;

            const filtered = getFilteredEmployees();

            if (!filtered.length) {
                container.innerHTML = `
                    <div class="text-center py-7 text-textSec text-[11px]">
                        <div class="w-9 h-9 mx-auto mb-2 rounded-full bg-cardBg border border-borderCol flex items-center justify-center">
                            <i class="fa-solid fa-user-slash text-sm opacity-60"></i>
                        </div>
                        <div class="font-semibold text-textMain">${t("team.noMatchingEmployees")}</div>
                        <div class="mt-0.5">${t("team.tryAnotherFilter")}</div>
                    </div>`;
                return;
            }

            container.innerHTML = filtered.map(u => {
                const fullName = `${u.firstname || ""} ${u.lastname || ""}`.trim();
                const displayName = fullName || u.username || t("team.employeeFallback");
                const rawRole = String(u.role || "staff").toLowerCase();
                const roleLabel = rawRole === "owner" ? t("team.admin") : rawRole.charAt(0).toUpperCase() + rawRole.slice(1);
                const positionLabel = u.position || roleLabel;
                const contact = u.email || u.phone || t("team.noContactDetails");
                const temporaryBadge = u.must_change_password
                    ? `<span class="text-[8px] px-1.5 py-0.5 rounded-md bg-warning/15 text-warning border border-warning/20 font-semibold whitespace-nowrap">${t("team.tempPasswordBadge")}</span>`
                    : "";
                const disabledBadge = u.disabled
                    ? `<span class="text-[8px] px-1.5 py-0.5 rounded-md bg-danger/15 text-danger border border-danger/20 font-semibold whitespace-nowrap">${t("team.disabledBadge")}</span>`
                    : "";
                const initials = (displayName.match(/\b\w/g) || ["U"]).slice(0, 2).join("").toUpperCase();

                return `
                    <div class="employee-directory-card bg-cardBg border border-borderCol rounded-xl p-3 hover:border-primary/30 hover:bg-cardHover transition">
                        <div class="flex items-center gap-3">
                            <div class="w-9 h-9 rounded-full bg-primary/10 border border-primary/20 text-primary flex items-center justify-center text-[10px] font-bold shrink-0">
                                ${escapeEmployeeHtml(initials)}
                            </div>

                            <div class="min-w-0 flex-1">
                                <div class="flex items-center gap-2 flex-wrap">
                                    <span class="font-semibold text-xs text-textMain truncate">${escapeEmployeeHtml(displayName)}</span>
                                    <span class="text-[8px] px-1.5 py-0.5 rounded-md font-bold bg-primary/10 text-primary border border-primary/15">${escapeEmployeeHtml(roleLabel)}</span>
                                    ${temporaryBadge} ${disabledBadge}
                                </div>
                                <div class="text-[9px] text-textSec mt-1 flex flex-wrap gap-x-2 gap-y-0.5">
                                    <span><i class="fa-solid fa-at mr-1 opacity-60"></i>${escapeEmployeeHtml(u.username || t("team.noUsername"))}</span>
                                    <span><i class="fa-solid fa-briefcase mr-1 opacity-60"></i>${escapeEmployeeHtml(positionLabel)}</span>
                                    <span><i class="fa-solid fa-address-book mr-1 opacity-60"></i>${escapeEmployeeHtml(contact)}</span>
                                </div>
                            </div>

                            <div class="flex items-center gap-1.5 shrink-0">
                                <button type="button"
                                    onclick="promptResetEmployeePassword(${Number(u.id)}, '${String(u.username || '').replace(/'/g, "\'")}' )"
                                    class="w-8 h-8 rounded-lg bg-primary/10 hover:bg-primary/20 text-primary flex items-center justify-center transition cursor-pointer"
                                    title="${t("team.resetTempPasswordTitle")}">
                                    <i class="fa-solid fa-key text-[10px]"></i>
                                </button>
                                ${getCurrentRole()==='admin' ? `
                                <button type="button"
                                    onclick="toggleEmployeeDisabled(${Number(u.id)}, '${String(u.username || '').replace(/'/g, "\'")}', ${!!u.disabled})"
                                    class="w-8 h-8 rounded-lg ${u.disabled ? 'bg-success/10 text-success' : 'bg-warning/10 text-warning'} flex items-center justify-center transition cursor-pointer"
                                    title="${u.disabled ? t("team.enableAccount") : t("team.disableAccount")}">
                                    <i class="fa-solid ${u.disabled ? 'fa-user-check' : 'fa-user-slash'} text-[10px]"></i>
                                </button>` : `
                                <button type="button"
                                    onclick="requestOrDeleteEmployee(${Number(u.id)}, '${String(u.username || '').replace(/'/g, "\'")}', 'disable')"
                                    class="w-8 h-8 rounded-lg bg-warning/10 text-warning flex items-center justify-center transition cursor-pointer"
                                    title="${t("team.requestApprovalDisable")}">
                                    <i class="fa-solid fa-user-slash text-[10px]"></i>
                                </button>`}
                                <button type="button"
                                    onclick="requestOrDeleteEmployee(${Number(u.id)}, '${String(u.username || '').replace(/'/g, "\'")}', 'delete')"
                                    class="w-8 h-8 rounded-lg bg-danger/10 hover:bg-danger/20 text-danger flex items-center justify-center transition cursor-pointer"
                                    title="${getCurrentRole()==='admin' ? t("team.deleteEmployeeTitle") : t("team.requestApprovalDelete")}">
                                    <i class="fa-solid fa-trash text-[10px]"></i>
                                </button>
                            </div>
                        </div>
                    </div>`;
            }).join("");
        }

        // Exports exactly the filtered set getFilteredEmployees() already
        // computed (search + role filter), and only fields already shown in
        // this directory. No passwords/tokens/internal ids are exported —
        // /users itself already enforces manager-sees-staff-only, so this
        // export can never show more than the current role is authorized to see.
        function buildEmployeesExportSpec() {
            const source = getFilteredEmployees();
            if (!source.length) return null;
            const rows = source.map(u => ({
                name: `${u.firstname || ""} ${u.lastname || ""}`.trim() || u.username,
                username: u.username, role: u.role, position: u.position || "",
                email: u.email || "", phone: u.phone || "",
                status: u.disabled ? "Disabled" : "Active",
            }));
            return {
                filenameBase: `cauldra_employees_${csvDateStamp()}`,
                reportTitle: "Cauldra Employee Directory",
                metadata: [
                    ["Generated", new Date().toLocaleString()],
                    ["Role Filter", document.getElementById("employee-role-filter")?.value || "All"],
                ],
                sheets: [{
                    name: "Employees",
                    columns: [
                        { key: "name", label: "Name", type: "text" },
                        { key: "username", label: "Username", type: "text" },
                        { key: "role", label: "Role", type: "text" },
                        { key: "position", label: "Position", type: "text" },
                        { key: "email", label: "Email", type: "text" },
                        { key: "phone", label: "Phone", type: "text" },
                        { key: "status", label: "Status", type: "text" },
                    ],
                    rows,
                }],
            };
        }
        // Exports exactly the filtered set getFilteredEmployees() already
        // computed (search + role filter), and only fields already shown in
        // this directory. No passwords/tokens/internal ids are exported —
        // /users itself already enforces manager-sees-staff-only, so this
        // export can never show more than the current role is authorized to see.
        function exportEmployeesCsv() { runCsvExport(buildEmployeesExportSpec, "No employees available to export."); }
        function exportEmployeesExcel(button) { runExcelExport(button, buildEmployeesExportSpec, "No employees available to export."); }

        async function renderEmployeesList() {
            const container = document.getElementById("company-employees-list");
            if (!container) return;

            container.innerHTML = `<div class="text-center py-8 text-textSec text-[11px]"><i class="fa-solid fa-spinner fa-spin text-primary mr-1"></i> ${t("team.loadingDirectory")}</div>`;

            try {
                if (!authToken) {
                    employeeDirectoryUsers = [];
                    updateEmployeeDirectoryCounts([]);
                    container.innerHTML = `<div class="text-center py-7 text-danger text-[11px]">${t("team.signInToViewEmployees")}</div>`;
                    return;
                }

                const res = await fetch(`${API_URL}/users`, {
                    method: "GET",
                    headers: {
                        "Authorization": `Bearer ${authToken}`,
                        "Accept": "application/json"
                    }
                });

                let data = null;
                try { data = await res.json(); } catch (e) {}

                if (!res.ok) {
                    if (res.status === 401) {
                        handleAuthenticationFailure(t("team.sessionExpired"));
                        return;
                    }
                    employeeDirectoryUsers = [];
                    updateEmployeeDirectoryCounts([]);
                    const detail = data && data.detail ? data.detail : t("team.serverError", {status: res.status});
                    container.innerHTML = `<div class="text-center py-7 text-danger text-[11px] leading-relaxed"><i class="fa-solid fa-triangle-exclamation mr-1"></i>${escapeEmployeeHtml(detail)}</div>`;
                    return;
                }

                employeeDirectoryUsers = Array.isArray(data) ? data : [];
                updateEmployeeDirectoryCounts(employeeDirectoryUsers);
                renderAccountActionRequests();

                const searchInput = document.getElementById("employee-search-input");
                const roleFilter = document.getElementById("employee-role-filter");
                if (searchInput) searchInput.value = "";
                if (roleFilter) roleFilter.value = "all";

                if (!employeeDirectoryUsers.length) {
                    container.innerHTML = `
                        <div class="text-center py-8 text-textSec text-[11px]">
                            <div class="w-10 h-10 mx-auto mb-2 rounded-full bg-cardBg border border-borderCol flex items-center justify-center">
                                <i class="fa-solid fa-users-slash text-base opacity-60"></i>
                            </div>
                            <div class="font-semibold text-textMain">${t("team.noEmployeesRegistered")}</div>
                            <div class="mt-0.5">${t("team.addManagerOrStaff")}</div>
                        </div>`;
                    return;
                }

                filterEmployeesList();
            } catch (e) {
                employeeDirectoryUsers = [];
                updateEmployeeDirectoryCounts([]);
                container.innerHTML = `<div class="text-center py-7 text-danger text-[11px]"><i class="fa-solid fa-triangle-exclamation mr-1"></i>${t("team.connectionErrorLoadingEmployees")}</div>`;
            }
        }

        function openAddEmployeeModal() {
            const creatorRole = getCurrentRole();
            if (!['admin', 'manager'].includes(creatorRole)) {
                showToast(t("team.onlyAdminManagerCreate"), "error");
                return;
            }
            const roleSelect = document.getElementById("emp-role");
            if (roleSelect) {
                roleSelect.disabled = creatorRole === 'manager';
                roleSelect.value = creatorRole === 'manager' ? 'staff' : 'staff';
            }
            document.getElementById("emp-firstname").value = "";
            document.getElementById("emp-lastname").value = "";
            document.getElementById("emp-email").value = "";
            document.getElementById("emp-phone").value = "";
            document.getElementById("emp-username").value = "";
            document.getElementById("emp-password").value = "";
            document.getElementById("emp-position").value = "";
            document.getElementById("add-employee-modal").classList.remove("hidden");
        }

        function closeAddEmployeeModal() {
            document.getElementById("add-employee-modal").classList.add("hidden");
        }

        function showTemporaryCredentialModal(username, temporaryPassword) {
            document.getElementById('temp-credential-username').textContent = username || '';
            document.getElementById('temp-credential-password').value = temporaryPassword || '';
            document.getElementById('temporary-credential-modal').classList.remove('hidden');
        }
        function closeTemporaryCredentialModal() { document.getElementById('temporary-credential-modal').classList.add('hidden'); }
        async function copyTemporaryPassword() {
            const value = document.getElementById('temp-credential-password').value;
            try { await navigator.clipboard.writeText(value); showToast(t("team.tempPasswordCopied"), 'success'); } catch (_) { showToast(t("team.copyUnavailable"), 'info'); }
        }

        async function promptResetEmployeePassword(userId, username) {
            const new_password = await showCustomPrompt(t("team.resetPasswordPromptBody", {username}), t("team.resetPasswordPromptTitle"), t("team.resetPasswordPromptField"), "password", true);
            if (!new_password) return;
            try {
                const res = await fetch(`${API_URL}/users/${userId}/reset-password`, {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ new_password })
                });
                const data = await res.json().catch(() => ({}));
                if (res.ok) {
                    renderEmployeesList();
                    showTemporaryCredentialModal(username, new_password);
                    showToast(t("team.passwordResetSuccess"), "success");
                } else {
                    showToast(data.detail || t("team.resetPasswordFailed"), "error");
                }
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        async function handleCreateEmployee(event) {
            event.preventDefault();
            const creatorRole = getCurrentRole();
            if (!['admin', 'manager'].includes(creatorRole)) {
                showToast(t("team.accountNotAllowedCreate"), "error");
                return;
            }
            const role = document.getElementById("emp-role").value;
            if (creatorRole === 'manager' && role !== 'staff') {
                showToast(t("team.managersOnlyStaff"), "error");
                return;
            }
            const firstname = document.getElementById("emp-firstname").value.trim();
            const lastname = document.getElementById("emp-lastname").value.trim();
            const email = document.getElementById("emp-email").value.trim();
            const phone = normalizeBusinessPhone(document.getElementById("emp-phone").value.trim());
            const username = document.getElementById("emp-username").value.trim();
            const password = document.getElementById("emp-password").value;
            const position = document.getElementById("emp-position").value.trim();

            if (password.length < 8 || !/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password)) {
                showToast(t("team.passwordComplexityError"), "error");
                return;
            }
            if (password.toLowerCase() === username.toLowerCase()) {
                showToast(t("team.passwordSameAsUsername"), "error");
                return;
            }

            try {
                const res = await fetch(`${API_URL}/users`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ username, password, role, firstname, lastname, email, phone, position })
                });
                const data = await res.json().catch(() => ({}));
                if (res.ok) {
                    closeAddEmployeeModal();
                    renderEmployeesList();
                    showTemporaryCredentialModal(data.username || username, password);
                    showToast(t("team.employeeCreatedSuccess"), "success");
                } else {
                    showToast(data.detail || t("team.createEmployeeFailed"), "error");
                }
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        async function requestOrDeleteEmployee(userId, username, action) {
            const role = getCurrentRole();
            if (action === 'delete' && role === 'admin') {
                const confirmed = await showCustomConfirm(t("team.deleteEmployeeConfirmBody", {username}), t("team.deleteEmployeeConfirmTitle"));
                if (!confirmed) return;
                try {
                    const res = await fetch(`${API_URL}/users/${userId}`, { method: "DELETE", headers: { "Authorization": `Bearer ${authToken}` } });
                    const data = await res.json();
                    if (!res.ok) throw new Error(data.detail || t("team.deleteAccountFailed"));
                    renderEmployeesList();
                    showToast(t("team.employeeDeletedSuccess"), "success");
                } catch (e) { showToast(e.message || t("common.actionFailed"), "error"); }
                return;
            }
            if (role === 'manager') {
                const confirmed = await showCustomConfirm(t("team.requestApprovalConfirmBody", {action, username}), action === 'delete' ? t("team.requestDeletionTitle") : t("team.requestDisableTitle"));
                if (!confirmed) return;
                try {
                    const res = await fetch(`${API_URL}/account-action-requests`, { method: "POST", headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` }, body: JSON.stringify({ target_user_id: userId, action }) });
                    const data = await res.json();
                    if (!res.ok) throw new Error(data.detail || t("team.approvalRequestFailed"));
                    renderEmployeesList(); renderAccountActionRequests();
                    showToast(t("team.approvalRequestSent"), "success");
                } catch (e) { showToast(e.message || t("common.actionFailed"), "error"); }
            }
        }

        async function toggleEmployeeDisabled(userId, username, disabled) {
            if (getCurrentRole() !== 'admin') return;
            const action = disabled ? 'enable' : 'disable';
            const confirmed = await showCustomConfirm(disabled ? t("team.enableConfirmBody", {username}) : t("team.disableConfirmBody", {username}), disabled ? t("team.enableEmployeeTitle") : t("team.disableEmployeeTitle"));
            if (!confirmed) return;
            try {
                const res = await fetch(`${API_URL}/users/${userId}/${action}`, { method: "PATCH", headers: { "Authorization": `Bearer ${authToken}` } });
                const data = await res.json();
                if (!res.ok) throw new Error(data.detail || (disabled ? t("team.enableAccountFailed") : t("team.disableAccountFailed")));
                renderEmployeesList(); showToast(disabled ? t("team.employeeEnabled") : t("team.employeeDisabled"), "success");
            } catch (e) { showToast(e.message || t("common.actionFailed"), "error"); }
        }

        // Single source of truth for pending Account Action Requests: fetches the
        // current PENDING list, keeps the sidebar badge in sync, and — only when
        // the dedicated Account Action Requests modal is actually open — re-renders
        // its card list. Safe to call from anywhere data may have changed (new
        // request submitted, one resolved, employee list refreshed, app data load).
        async function renderAccountActionRequests() {
            if (!['admin','manager'].includes(getCurrentRole())) { updateAccountActionRequestsBadge(0); return []; }
            try {
                const res = await fetch(`${API_URL}/account-action-requests`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                if (!res.ok) { updateAccountActionRequestsBadge(0); return []; }
                const items = await res.json();
                updateAccountActionRequestsBadge(items.length);
                const modal = document.getElementById('account-action-requests-modal');
                if (modal && !modal.classList.contains('hidden')) renderAccountActionRequestsList(items);
                return items;
            } catch (_) {
                updateAccountActionRequestsBadge(0);
                return [];
            }
        }

        // Updates every copy of the pending-count badge currently in the DOM
        // (the desktop sidebar, and the mobile-nav clone when mounted). Hidden
        // entirely at zero rather than showing a "0" pill.
        function updateAccountActionRequestsBadge(count) {
            document.querySelectorAll('.account-action-requests-badge').forEach(el => {
                el.textContent = String(count);
                el.classList.toggle('hidden', !count);
            });
        }

        function renderAccountActionRequestsList(items) {
            const container = document.getElementById('account-action-requests-list');
            if (!container) return;
            const isAdmin = getCurrentRole() === 'admin';
            const approveAllBtn = document.getElementById('account-action-requests-approve-all-btn');
            const declineAllBtn = document.getElementById('account-action-requests-decline-all-btn');
            [approveAllBtn, declineAllBtn].forEach(btn => {
                if (!btn) return;
                btn.classList.toggle('hidden', !isAdmin);
                btn.disabled = !items.length;
                btn.classList.toggle('opacity-50', !items.length);
                btn.classList.toggle('cursor-not-allowed', !items.length);
            });

            if (!items.length) {
                container.innerHTML = `<div class="text-center py-8 text-textSec text-[11px]">
                    <div class="w-10 h-10 mx-auto mb-2 rounded-full bg-cardBg border border-borderCol flex items-center justify-center"><i class="fa-solid fa-circle-check text-base opacity-60"></i></div>
                    <div class="font-semibold text-textMain">No pending requests at the moment.</div>
                </div>`;
                return;
            }

            container.innerHTML = items.map(x => `
                <div class="p-3 rounded-xl bg-bgMain border border-borderCol space-y-2">
                    <div class="flex items-start justify-between gap-2">
                        <div class="min-w-0">
                            <div class="font-semibold text-textMain text-[11px]">${escapeEmployeeHtml(x.target_username)}${x.target_position ? ` <span class="text-textSec font-normal">· ${escapeEmployeeHtml(x.target_position)}</span>` : ''}</div>
                            <div class="text-[10px] text-textSec mt-0.5">${x.action === 'delete' ? t("team.actionDelete") : t("team.actionDisable")}</div>
                        </div>
                        <span class="shrink-0 px-2 py-0.5 rounded-md bg-warning/15 text-warning border border-warning/30 text-[9px] font-bold uppercase tracking-wide">Pending</span>
                    </div>
                    <div class="text-[10px] text-textSec space-y-0.5">
                        <div>${isAdmin ? `${t("team.requestedBy", {name: x.requested_by_name || t("team.managerFallback")})}${x.requested_by_position ? ` · ${escapeEmployeeHtml(x.requested_by_position)}` : ''}` : t("team.awaitingReview")}</div>
                        <div>${formatBusinessDateTime(x.created_at)}</div>
                    </div>
                    ${isAdmin ? `<div class="flex items-center justify-between gap-2 pt-1 border-t border-borderCol/60">
                        <button type="button" onclick="resolveAccountActionRequest(${x.id},'reject')" class="px-2 py-1 rounded-md bg-bgMain text-textSec border border-borderCol text-[10px] font-semibold hover:bg-cardHover transition cursor-pointer">Decline</button>
                        <button type="button" onclick="resolveAccountActionRequest(${x.id},'approve')" class="px-2 py-1 rounded-md bg-primary hover:bg-primaryHover text-white text-[10px] font-semibold transition cursor-pointer">Approve</button>
                    </div>` : ''}
                </div>
            `).join('');
        }

        // Resolves exactly one request — the id is captured in the onclick
        // handler at render time, so this never touches any other request.
        async function resolveAccountActionRequest(requestId, action) {
            try {
                const res = await fetch(`${API_URL}/account-action-requests/${requestId}/${action}`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } });
                const data = await res.json();
                if (!res.ok) throw new Error(data.detail || t("team.resolveRequestFailed"));
                renderEmployeesList(); renderAccountActionRequests(); showToast(data.message || t("team.requestUpdated"), 'success');
            } catch (e) { showToast(e.message || t("common.actionFailed"), 'error'); }
        }

        async function approveAllAccountActionRequests() {
            await bulkResolveAccountActionRequests('approve');
        }

        async function declineAllAccountActionRequests() {
            await bulkResolveAccountActionRequests('reject');
        }

        // Reuses the existing single-request resolve endpoint for every request
        // that is still actually pending at the moment of confirmation (re-fetched
        // fresh right before acting, so anything already approved/declined by
        // someone else in the meantime is never touched).
        async function bulkResolveAccountActionRequests(action) {
            if (getCurrentRole() !== 'admin') return;
            let items;
            try {
                const res = await fetch(`${API_URL}/account-action-requests`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                items = res.ok ? await res.json() : [];
            } catch (_) { items = []; }
            if (!items.length) { showToast("No pending requests at the moment.", "info"); return; }

            const confirmed = await showCustomConfirm(
                action === 'approve'
                    ? `Approve all ${items.length} pending request(s)? This cannot be undone.`
                    : `Decline all ${items.length} pending request(s)? This cannot be undone.`,
                action === 'approve' ? "Approve All Requests" : "Decline All Requests"
            );
            if (!confirmed) return;

            const btn = document.getElementById(action === 'approve' ? 'account-action-requests-approve-all-btn' : 'account-action-requests-decline-all-btn');
            if (btn) btn.disabled = true;
            let succeeded = 0, failed = 0;
            for (const item of items) {
                try {
                    const res = await fetch(`${API_URL}/account-action-requests/${item.id}/${action}`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } });
                    if (res.ok) succeeded++; else failed++;
                } catch (_) { failed++; }
            }
            renderEmployeesList();
            await renderAccountActionRequests();
            if (failed) {
                showToast(`${succeeded} request(s) resolved, ${failed} could not be resolved.`, succeeded ? 'info' : 'error');
            } else {
                showToast(action === 'approve' ? `${succeeded} request(s) approved.` : `${succeeded} request(s) declined.`, 'success');
            }
        }

        // Populates the Person/Action filter suggestions from whatever actors and
        // action codes actually exist in this business's Activity History — never
        // a hardcoded list, so it stays correct as new kinds of events appear.
        async function populateAuditLogFilterOptions() {
            if (!['admin','manager'].includes(getCurrentRole())) return;
            try {
                const res = await fetch(`${API_URL}/audit-logs/actions`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                if (!res.ok) return;
                const d = await res.json();
                const actorList = document.getElementById('audit-log-actor-options');
                const actionList = document.getElementById('audit-log-action-options');
                if (actorList) actorList.innerHTML = (d.actors || []).map(a => `<option value="${escapeEmployeeHtml(a)}"></option>`).join('');
                if (actionList) actionList.innerHTML = (d.actions || []).map(a => `<option value="${escapeEmployeeHtml(a)}"></option>`).join('');
            } catch (_) {}
        }

        let auditLogFilterDebounceTimer = null;
        function debouncedFilterAuditLog() {
            clearTimeout(auditLogFilterDebounceTimer);
            auditLogFilterDebounceTimer = setTimeout(renderAuditLog, 300);
        }

        function clearAuditLogFilters() {
            ['audit-log-search-input', 'audit-log-actor-input', 'audit-log-action-input', 'audit-log-date-from', 'audit-log-date-to'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });
            auditLogAppliedDateRange = { from: "", to: "" };
            hideAuditLogDateError();
            updateAuditLogActiveRangeLabel();
            markAuditLogDatePreset(null);
            renderAuditLog();
        }

        // ---- Business-timezone-aware date boundaries for the Today/Yesterday/
        // Last 7/30 days presets and for the manual custom-range inputs, so "today"
        // always means the business's own calendar day, not the browser's or the
        // server's. No hardcoded dates — everything is derived from the current
        // instant and the business's configured timezone (getBusinessTimezone()).
        function getBusinessDateParts(offsetDays, tz) {
            tz = tz || getBusinessTimezone();
            const target = new Date(Date.now() + offsetDays * 86400000);
            const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' })
                .formatToParts(target).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
            return { year: +parts.year, month: +parts.month, day: +parts.day };
        }

        // The UTC instant that reads as `year-month-day 00:00:00` when displayed in `tz`.
        function businessMidnightUtcISO(year, month, day, tz) {
            const target = Date.UTC(year, month - 1, day, 0, 0, 0);
            let guessMs = target;
            for (let i = 0; i < 2; i++) {
                const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })
                    .formatToParts(new Date(guessMs)).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
                const hour = parts.hour === '24' ? 0 : +parts.hour;
                const readAsUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, hour, +parts.minute, +parts.second);
                const diff = target - readAsUtc;
                if (diff === 0) break;
                guessMs += diff;
            }
            return new Date(guessMs).toISOString();
        }

        // Converts a bare "YYYY-MM-DD" date-input value into a precise UTC instant
        // boundary in the business timezone — the start of that day for a lower
        // bound, or the start of the *next* day (exclusive upper bound) for an
        // upper bound — so a whole business-local day is always covered correctly.
        function businessDateBoundaryISO(dateStr, isUpperBound) {
            if (!dateStr) return null;
            const [y, m, d] = dateStr.split('-').map(Number);
            if (!y || !m || !d) return null;
            const tz = getBusinessTimezone();
            if (!isUpperBound) return businessMidnightUtcISO(y, m, d, tz);
            const next = new Date(Date.UTC(y, m - 1, d + 1));
            return businessMidnightUtcISO(next.getUTCFullYear(), next.getUTCMonth() + 1, next.getUTCDate(), tz);
        }

        function toDateInputValue(parts) {
            return `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`;
        }

        function setAuditLogDatePreset(preset) {
            const tz = getBusinessTimezone();
            const fromEl = document.getElementById('audit-log-date-from');
            const toEl = document.getElementById('audit-log-date-to');
            let fromParts, toParts;
            if (preset === 'today') { fromParts = getBusinessDateParts(0, tz); toParts = fromParts; }
            else if (preset === 'yesterday') { fromParts = getBusinessDateParts(-1, tz); toParts = fromParts; }
            else if (preset === 'last7') { fromParts = getBusinessDateParts(-6, tz); toParts = getBusinessDateParts(0, tz); }
            else if (preset === 'last30') { fromParts = getBusinessDateParts(-29, tz); toParts = getBusinessDateParts(0, tz); }
            else return;
            if (fromEl) fromEl.value = toDateInputValue(fromParts);
            if (toEl) toEl.value = toDateInputValue(toParts);
            // Presets are a one-click, pre-validated range (never a manual,
            // possibly-incomplete edit), so they apply immediately — the
            // Apply-button gate exists for freehand date entry, not these.
            auditLogAppliedDateRange = { from: toDateInputValue(fromParts), to: toDateInputValue(toParts) };
            hideAuditLogDateError();
            updateAuditLogActiveRangeLabel();
            markAuditLogDatePreset(preset);
            renderAuditLog();
        }

        function markAuditLogDatePreset(preset) {
            document.querySelectorAll('.audit-log-date-preset-btn').forEach(btn => {
                const active = preset && btn.dataset.preset === preset;
                btn.className = "audit-log-date-preset-btn px-2 py-1 rounded-lg border cursor-pointer "
                    + (active ? "border-primary bg-primary/15 text-primary" : "border-borderCol text-textSec hover:text-textMain");
            });
        }

        // Every field the backend actually put on the record is shown — nothing
        // invented, and unrecognized future fields still get a readable label
        // instead of being silently dropped.
        const AUDIT_LOG_FIELD_LABELS = {
            id: 'Record ID', actor_username: 'Performed by', actor_role: 'Role',
            action: 'Action', target_username: 'Affected', description: 'Details', created_at: 'When',
        };
        function humanizeAuditLogFieldKey(key) {
            return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
        }
        function renderAuditLogDetailRows(record) {
            return Object.keys(record)
                .filter(key => record[key] !== null && record[key] !== undefined && record[key] !== '')
                .map(key => {
                    const label = AUDIT_LOG_FIELD_LABELS[key] || humanizeAuditLogFieldKey(key);
                    let value = record[key];
                    if (key === 'created_at') value = formatBusinessDateTime(value);
                    else if (key === 'actor_role') value = ({admin:t("team.admin"),manager:t("team.manager"),staff:t("team.staff")})[value] || value;
                    return `<div class="flex items-start justify-between gap-3 py-1 border-b border-borderCol/40 last:border-0"><span class="text-textSec shrink-0">${escapeEmployeeHtml(label)}</span><span class="text-textMain font-medium text-right break-words">${escapeEmployeeHtml(String(value))}</span></div>`;
                }).join('');
        }

        function toggleAuditLogDetail(index) {
            const panel = document.getElementById(`audit-log-detail-${index}`);
            const caret = document.getElementById(`audit-log-caret-${index}`);
            if (!panel) return;
            const willExpand = panel.classList.contains('hidden');
            panel.classList.toggle('hidden', !willExpand);
            caret?.classList.toggle('rotate-180', willExpand);
        }

        // Custom Date Range rule: the date boundary actually used to filter
        // and export is whatever was last explicitly APPLIED (via Apply or
        // a preset button), never whatever happens to be sitting unconfirmed
        // in the date inputs — so editing a date without clicking Apply can
        // never silently change what's shown or exported.
        let auditLogAppliedDateRange = { from: "", to: "" };

        function updateAuditLogActiveRangeLabel() {
            const el = document.getElementById('audit-log-active-range');
            if (!el) return;
            el.textContent = (auditLogAppliedDateRange.from && auditLogAppliedDateRange.to)
                ? `Showing ${formatExpenseCustomDateShort(auditLogAppliedDateRange.from)} – ${formatExpenseCustomDateShort(auditLogAppliedDateRange.to)}`
                : '';
        }

        function showAuditLogDateError(msg) {
            const el = document.getElementById('audit-log-date-error');
            if (!el) return;
            el.textContent = msg;
            el.classList.remove('hidden');
        }
        function hideAuditLogDateError() {
            document.getElementById('audit-log-date-error')?.classList.add('hidden');
        }

        // The ONE explicit commit point for a manual date range here — never
        // triggered by typing/selecting a date. Requires BOTH boundaries and
        // validates before ever reaching the backend (which independently
        // enforces the same rule — see resolve_financial_period's "custom"
        // branch and _build_audit_log_query's callers).
        function applyAuditLogDateRange() {
            const fromVal = document.getElementById('audit-log-date-from')?.value || '';
            const toVal = document.getElementById('audit-log-date-to')?.value || '';
            if (!fromVal && !toVal) { showAuditLogDateError('Select a start date and end date.'); return; }
            if (!fromVal) { showAuditLogDateError('Select a start date.'); return; }
            if (!toVal) { showAuditLogDateError('Select an end date.'); return; }
            if (toVal < fromVal) { showAuditLogDateError('End date cannot be earlier than start date.'); return; }
            hideAuditLogDateError();
            auditLogAppliedDateRange = { from: fromVal, to: toVal };
            markAuditLogDatePreset(null);
            updateAuditLogActiveRangeLabel();
            renderAuditLog();
        }

        // Shared by renderAuditLog() and exportAuditLogCsv() so the CSV can
        // never diverge from what the current filters actually show.
        function getAuditLogFilterParams() {
            const q = document.getElementById('audit-log-search-input')?.value.trim() || '';
            const actorFilter = document.getElementById('audit-log-actor-input')?.value.trim() || '';
            const actionFilter = document.getElementById('audit-log-action-input')?.value.trim() || '';
            const dateFrom = auditLogAppliedDateRange.from;
            const dateTo = auditLogAppliedDateRange.to;

            const params = new URLSearchParams();
            if (q) params.set('q', q);
            if (actorFilter) params.set('actor_username', actorFilter);
            if (actionFilter) params.set('action', actionFilter);
            const fromISO = businessDateBoundaryISO(dateFrom, false);
            const toISO = businessDateBoundaryISO(dateTo, true);
            if (fromISO) params.set('date_from', fromISO);
            if (toISO) params.set('date_to', toISO);
            return { params, hasActiveFilters: !!(q || actorFilter || actionFilter || dateFrom || dateTo) };
        }

        function exportAuditLogCsv(button) {
            const { params } = getAuditLogFilterParams();
            runBackendCsvExport(button, `${API_URL}/audit-logs/export?${params.toString()}`, `cauldra_activity_history_${csvDateStamp()}.csv`, "No activity history available to export.");
        }
        function exportAuditLogExcel(button) {
            const { params } = getAuditLogFilterParams();
            runBackendCsvExport(button, `${API_URL}/audit-logs/export/xlsx?${params.toString()}`, `cauldra_activity_history_${csvDateStamp()}.xlsx`, "No activity history available to export.");
        }

        async function renderAuditLog() {
            const section = document.getElementById('audit-log-section');
            const container = document.getElementById('audit-log-container');
            const filtersBar = document.getElementById('audit-log-filters');
            const countEl = document.getElementById('audit-log-results-count');
            if (!section || !container || !['admin','manager'].includes(getCurrentRole())) return;

            const { params, hasActiveFilters } = getAuditLogFilterParams();
            params.set('limit', '100');
            params.set('offset', '0');

            try {
                const res = await fetch(`${API_URL}/audit-logs?${params.toString()}`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                if (!res.ok) { section.classList.add('hidden'); return; }
                const data = await res.json();
                const items = Array.isArray(data.items) ? data.items : (Array.isArray(data) ? data : []);
                const total = typeof data.total === 'number' ? data.total : items.length;
                filtersBar?.classList.remove('hidden');
                section.classList.remove('hidden');
                if (countEl) {
                    if (hasActiveFilters) countEl.innerHTML = `<span class="text-primary font-semibold">Filtered</span> · ${items.length} of ${total} result${total === 1 ? '' : 's'}`;
                    else countEl.textContent = total ? `${total} activity record${total === 1 ? '' : 's'}` : '';
                }
                if (items.length) {
                    container.innerHTML = items.map((x, i) => `
                        <div class="rounded-lg bg-cardBg border border-borderCol overflow-hidden">
                            <button type="button" onclick="toggleAuditLogDetail(${i})" class="w-full text-left p-2.5 cursor-pointer hover:bg-cardHover transition">
                                <div class="flex items-start justify-between gap-2">
                                    <div class="min-w-0 flex-1">
                                        <div class="font-semibold text-textMain text-[11px]">${escapeEmployeeHtml(x.description)}</div>
                                        <div class="text-[10px] text-textSec mt-1">${escapeEmployeeHtml(x.actor_username || t("team.systemFallback"))} · ${escapeEmployeeHtml(x.action || t("team.activityFallback"))}${x.target_username ? ' · ' + escapeEmployeeHtml(x.target_username) : ''} · ${formatBusinessDateTime(x.created_at)}</div>
                                    </div>
                                    <i id="audit-log-caret-${i}" class="fa-solid fa-chevron-down text-[9px] text-textSec mt-0.5 shrink-0 transition-transform"></i>
                                </div>
                            </button>
                            <div id="audit-log-detail-${i}" class="hidden px-2.5 pb-2.5 pt-1 border-t border-borderCol/60 text-[10px]">
                                ${renderAuditLogDetailRows(x)}
                            </div>
                        </div>
                    `).join('');
                } else if (hasActiveFilters) {
                    container.innerHTML = `<div class="text-center py-8 text-textSec text-[11px]"><div class="w-10 h-10 mx-auto mb-2 rounded-full bg-cardBg border border-borderCol flex items-center justify-center"><i class="fa-solid fa-magnifying-glass text-base opacity-60"></i></div><div class="font-semibold text-textMain">No matching activity found.</div><div class="mt-0.5">Try adjusting or clearing your filters.</div></div>`;
                } else {
                    container.innerHTML = `<div class="text-[10px] text-textSec">${t("team.noRecordedActivity")}</div>`;
                }
            } catch (_) { section.classList.add('hidden'); }
        }

        async function saveCompanySettings(event) {
            event.preventDefault();
            if (getCurrentRole() !== 'admin') {
                showToast(t("settings.onlyAdminModify"), "error");
                return;
            }
            const company_name = document.getElementById("company-name-input").value.trim();
            const email = document.getElementById("company-email-input").value.trim();
            const phone = document.getElementById("company-phone-input").value.trim();
            const address = document.getElementById("company-address-input").value.trim();
            const tax_id = document.getElementById("company-tax-input").value.trim();
            const language = document.getElementById("company-language-input")?.value || businessProfile.language || "en";

            try {
                const res = await fetch(`${API_URL}/business-profile/`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ company_name, country: businessProfile.country, country_code: businessProfile.country_code, locale: buildBusinessLocale(language, businessProfile.country_code), language, timezone: businessProfile.timezone, phone_country_code: businessProfile.phone_country_code, email, phone, address, currency: businessProfile.currency, tax_id })
                });
                if (res.ok) {
                    businessProfile = await res.json();

                    syncLanguageFromProfile(businessProfile);
                    updateCompanyHeaderDisplay();
                    updateFormCurrencyLabels();
                    closeSettingsModal();
                    showToast(t("settings.profileUpdated"), "success");
                    loadData();
                } else {
                    const data = await res.json();
                    showToast(data.detail || t("settings.updateProfileDetailFailed"), "error");
                }
            } catch (e) {
                showToast(t("settings.updateProfileRetryFailed"), "error");
            }
        }

        function showStockLegendInfo(event) {
            event.stopPropagation();
            document.getElementById("stock-info-modal").classList.remove("hidden");
        }

        function closeStockInfoModal() {
            document.getElementById("stock-info-modal").classList.add("hidden");
        }

        function showCustomConfirm(message, title = "Confirm Action", confirmLabel = "Confirm", cancelLabel = "Cancel") {
            return new Promise((resolve) => {
                const modal = document.getElementById("confirm-modal");
                const titleEl = document.getElementById("confirm-modal-title");
                const messageEl = document.getElementById("confirm-modal-message");
                const okBtn = document.getElementById("confirm-modal-ok");
                const cancelBtn = document.getElementById("confirm-modal-cancel");
                const closeBtn = document.getElementById("confirm-modal-close");

                titleEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation text-warning"></i> ${title}`;
                messageEl.textContent = message;
                // Every existing caller omits these two args, so they fall back
                // to this modal's normal "Confirm"/"Cancel" wording exactly as
                // before — only a caller that opts in (e.g. sign-out, wanting
                // its buttons to literally read "Sign Out"/"Cancel") changes them.
                okBtn.textContent = confirmLabel;
                cancelBtn.textContent = cancelLabel;
                modal.classList.remove("hidden");

                function cleanup() {
                    modal.classList.add("hidden");
                    okBtn.removeEventListener("click", onConfirm);
                    cancelBtn.removeEventListener("click", onCancel);
                    closeBtn.removeEventListener("click", onCancel);
                }

                function onConfirm() { cleanup(); resolve(true); }
                function onCancel() { cleanup(); resolve(false); }

                okBtn.addEventListener("click", onConfirm);
                cancelBtn.addEventListener("click", onCancel);
                closeBtn.addEventListener("click", onCancel);
            });
        }

        function showCustomPrompt(label, title = "Enter Information", fieldLabel = "Value", inputType = "text", passwordMode = false, initialValue = "") {
            return new Promise((resolve) => {
                const modal = document.getElementById("input-modal");
                const titleEl = document.getElementById("input-modal-title");
                const labelEl = document.getElementById("input-modal-label");
                const field = document.getElementById("input-modal-field");
                const okBtn = document.getElementById("input-modal-ok");
                const cancelBtn = document.getElementById("input-modal-cancel");
                const closeBtn = document.getElementById("input-modal-close");
                const toggleBtn = document.getElementById("input-modal-toggle");
                if (!modal || !field) { resolve(null); return; }

                titleEl.innerHTML = `<i class="fa-solid ${passwordMode ? 'fa-key' : 'fa-pen-to-square'} text-primary"></i> ${title}`;
                labelEl.textContent = label || fieldLabel;
                field.type = passwordMode ? "password" : inputType;
                field.value = initialValue ?? "";
                field.placeholder = passwordMode ? "Enter temporary password" : "Enter value";
                toggleBtn.classList.toggle("hidden", !passwordMode);
                modal.classList.remove("hidden");

                function cleanup(result) {
                    modal.classList.add("hidden");
                    okBtn.removeEventListener("click", onConfirm);
                    cancelBtn.removeEventListener("click", onCancel);
                    closeBtn.removeEventListener("click", onCancel);
                    field.removeEventListener("keydown", onKeydown);
                    toggleBtn.removeEventListener("click", onToggle);
                    field.type = "text";
                    toggleBtn.classList.add("hidden");
                    resolve(result);
                }
                function onConfirm() { cleanup(field.value); }
                function onCancel() { cleanup(null); }
                function onKeydown(e) {
                    if (e.key === "Enter") { e.preventDefault(); onConfirm(); }
                    if (e.key === "Escape") { e.preventDefault(); onCancel(); }
                }
                function onToggle() {
                    const icon = toggleBtn.querySelector("i");
                    if (field.type === "password") {
                        field.type = "text";
                        if (icon) { icon.classList.remove("fa-eye"); icon.classList.add("fa-eye-slash"); }
                    } else {
                        field.type = "password";
                        if (icon) { icon.classList.remove("fa-eye-slash"); icon.classList.add("fa-eye"); }
                    }
                }
                okBtn.addEventListener("click", onConfirm);
                cancelBtn.addEventListener("click", onCancel);
                closeBtn.addEventListener("click", onCancel);
                field.addEventListener("keydown", onKeydown);
                toggleBtn.addEventListener("click", onToggle);
                setTimeout(() => field.focus(), 30);
            });
        }

        function showToast(message, type = "error") {
            message = friendlyErrorMessage(message);
            const styles = {
                error: {box:"bg-danger/10 border-danger/25 text-rose-200", icon:"fa-triangle-exclamation"},
                success: {box:"bg-success/10 border-success/25 text-emerald-200", icon:"fa-circle-check"},
                info: {box:"bg-primary/10 border-primary/25 text-indigo-200", icon:"fa-circle-info"},
                warning: {box:"bg-warning/10 border-warning/25 text-amber-200", icon:"fa-triangle-exclamation"}
            };
            const st = styles[type] || styles.error;
            const safe = String(message).replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","\'":"&#39;"}[ch]));
            let region = document.getElementById("global-status-region");
            // Only ever target an actual modal overlay (every modal in this app
            // follows the `id="...-modal"` convention) — never any other
            // position:fixed element. #toast-container and the always-visible
            // AI-chat FAB wrapper are also `.fixed` and never carry `hidden`,
            // so a bare `.fixed` selector could (and did) grab one of those
            // instead of the modal that's actually open, silently inserting
            // the status message into a hidden child and making the error
            // invisible to the user.
            const visibleModal = [...document.querySelectorAll('.fixed[id$="-modal"]')].filter(el => !el.classList.contains('hidden')).pop();
            if (visibleModal) {
                const shell = visibleModal.firstElementChild;
                if (shell) {
                    region = shell.querySelector('[data-dynamic-status]');
                    if (!region) {
                        region = document.createElement('div');
                        region.setAttribute('data-dynamic-status','true');
                        shell.insertBefore(region, shell.firstElementChild);
                    }
                }
            }
            if (!region) return;
            region.className = `flex items-center gap-2 px-3 py-2 rounded-xl border ${st.box} text-[11px] shadow-sm mb-3`;
            region.innerHTML = `<i class="fa-solid ${st.icon} text-[10px] shrink-0"></i><span class="flex-1 leading-relaxed">${safe}</span><button type="button" class="text-textSec hover:text-textMain" onclick="this.parentElement.classList.add('hidden')"><i class="fa-solid fa-xmark"></i></button>`;
            region.classList.remove('hidden');
            clearTimeout(region.__statusTimer);
            region.__statusTimer = setTimeout(() => region.classList.add('hidden'), type === 'error' ? 7000 : 4500);
        }

        // ============================================================
        // CAMERA SCANNER - ZXing only   (Scanner build: zxing-stable-v1)
        //
        // PERFORMANCE ROLLBACK of V20. Camera frame -> barcode STRING ->
        // submitProductBarcode / submitPosBarcode (downstream unchanged).
        //   - rear camera at width/height { ideal: 1920 / 1080 } only; a lower
        //     resolution from the UA is accepted. NO max-sensor request.
        //   - decode canvas capped at 1280px wide, source aspect kept; ONE
        //     reusable canvas + ONE reusable 2D context for the app lifetime.
        //   - ONE BrowserMultiFormatReader per camera session.
        //   - 350ms tick; _zxDecodeBusy lock so two decodes never overlap.
        //   - the scan loop does ONLY: draw -> decode -> route. No
        //     getSettings()/getCapabilities()/diagnostic-DOM in the hot path.
        //
        // window.ZXing is loaded by <script src="/assets/vendor/zxing.umd.js">
        // in index.html BEFORE app.js. We hand ZXing a <canvas> (not the
        // <video>) - this 0.21.3 build's decode(<video>) returns a blank frame
        // on Chrome.
        // ============================================================
        const SCANNER_BUILD = "zxing-stable-v2";
        const ZX_SCAN_INTERVAL_MS = 350;
        const ZX_DECODE_CANVAS_MAX_W = 1280;
        const ZX_DECODE_COOLDOWN_MS = 1200;   // same code re-read while still in frame is ignored this long
        const CAM_IDEAL_W = 1920, CAM_IDEAL_H = 1080;

        function _camVideoConstraints(deviceId) {
            const v = deviceId ? { deviceId: { exact: deviceId } } : { facingMode: { ideal: "environment" } };
            v.width = { ideal: CAM_IDEAL_W };     // V21: ideal only - never a min/max/exact, never higher than 1080p
            v.height = { ideal: CAM_IDEAL_H };
            return { video: v, audio: false };
        }

        let _zxReader = null;          // ONE BrowserMultiFormatReader per camera session
        let _camVideo = null;
        let _camStream = null;
        let _zxTimer = null;
        let _zxScanning = false;
        let _zxDecodeBusy = false;     // guarantees no two decode ops overlap
        let _zxStartLogged = false;
        let _zxGrab = null;            // ONE reusable decode canvas (app lifetime)
        let _zxCtx = null;             // ONE reusable 2D context
        let _frozenCanvas = null;      // V22: ONE reusable frozen-frame canvas
        let _frozenCtx = null;
        let _zxLastDecode = { code: null, at: 0 };
        // --- camera diagnostic state (read only at start / switch) ---
        let _camTrack = null;
        let _camDevices = [];
        let _camDeviceId = null;

        function _zxHints() {
            const ZX = window.ZXing, BF = ZX.BarcodeFormat, H = new Map();
            H.set(ZX.DecodeHintType.POSSIBLE_FORMATS, [
                BF.UPC_A, BF.UPC_E, BF.EAN_13, BF.EAN_8, BF.CODE_128, BF.CODE_39, BF.ITF
            ]);
            H.set(ZX.DecodeHintType.TRY_HARDER, true);
            return H;
        }

        function _scannerViewId(mode) { return mode === "product" ? "product-camera-view" : "pos-camera-view"; }

        function _setScannerLine(mode, text) {
            const host = document.getElementById(_scannerViewId(mode));
            const el = host && host.querySelector("[data-scanner-line]");
            if (el) el.textContent = text;
        }

        function _mountScannerUI(mode) {
            const host = document.getElementById(_scannerViewId(mode));
            if (!host) return;
            host.replaceChildren();
            const video = document.createElement("video");
            video.setAttribute("autoplay", ""); video.setAttribute("muted", ""); video.setAttribute("playsinline", "");
            video.muted = true; video.autoplay = true; video.playsInline = true;
            // Full-quality preview, NOT cropped. Only the decode canvas is capped.
            video.style.cssText = "width:100%;max-height:62vh;display:block;background:#000;border-radius:8px;object-fit:contain";
            const line = document.createElement("div");
            line.setAttribute("data-scanner-line", "");
            line.style.cssText = "font-size:12px;font-weight:700;line-height:1.5;color:#e0e7ff;padding:6px 2px 1px;word-break:break-all";
            line.textContent = "Camera ready";
            const build = document.createElement("div");
            build.style.cssText = "font-size:10px;color:#818cf8;opacity:.85;padding:0 2px 3px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace";
            build.textContent = "Scanner build: " + SCANNER_BUILD;
            host.appendChild(video);
            host.appendChild(line);
            host.appendChild(build);
            _camVideo = video;
        }

        // ===== CAMERA DIAGNOSTICS - run ONLY at camera start / camera switch,
        //       never inside the scan loop. =====

        async function _enumerateCameras() {
            try {
                const all = await navigator.mediaDevices.enumerateDevices();
                _camDevices = all.filter(d => d.kind === "videoinput");
            } catch (err) {
                console.warn("[camera-diag] enumerateDevices() failed:", (err && err.message) || err);
                _camDevices = [];
            }
            console.log("[camera-diag] videoinput devices (" + _camDevices.length + "):",
                _camDevices.map((d, i) => ({ i: i, deviceId: d.deviceId, label: d.label || "(no label)" })));
            console.log("[camera-diag] active deviceId:", _camDeviceId);
        }

        function _readTrackCapabilities() {
            const trk = _camTrack;
            if (!trk) return null;
            let caps = {}, settings = {};
            try { caps = (trk.getCapabilities && trk.getCapabilities()) || {}; }
            catch (err) { console.warn("[camera-diag] getCapabilities() failed:", (err && err.message) || err); }
            try { settings = (trk.getSettings && trk.getSettings()) || {}; } catch (err) {}
            const report = {
                focusMode: (caps.focusMode !== undefined) ? caps.focusMode : "(not reported)",
                zoom: caps.zoom ? { min: caps.zoom.min, max: caps.zoom.max, step: caps.zoom.step, current: settings.zoom } : "(not supported)",
                width: caps.width ? { min: caps.width.min, max: caps.width.max, current: settings.width } : "(not reported)",
                height: caps.height ? { min: caps.height.min, max: caps.height.max, current: settings.height } : "(not reported)",
            };
            console.log("[camera-diag] track.getCapabilities():", caps);
            console.log("[camera-diag] track.getSettings():", settings);
            console.log("[camera-diag] focusMode / zoom / width / height ->", report);
            return { caps: caps, settings: settings, report: report };
        }

        async function _applyContinuousFocus() {
            const trk = _camTrack;
            if (!trk || !trk.getCapabilities || !trk.applyConstraints) return;
            let modes = [];
            try { modes = (trk.getCapabilities() || {}).focusMode || []; } catch (err) { return; }
            if (Array.isArray(modes) && modes.indexOf("continuous") !== -1) {
                try {
                    await trk.applyConstraints({ advanced: [{ focusMode: "continuous" }] });
                    console.log("[camera-diag] applied focusMode: continuous");
                } catch (err) {
                    console.warn("[camera-diag] applyConstraints(focusMode:continuous) failed:", (err && err.message) || err);
                }
            } else {
                console.log("[camera-diag] continuous focus not supported (focusMode =", modes, ")");
            }
        }

        async function _applyCameraZoom(value) {
            const trk = _camTrack;
            if (!trk || !trk.applyConstraints) return;
            try { await trk.applyConstraints({ advanced: [{ zoom: value }] }); }
            catch (err) { console.warn("[camera-diag] applyConstraints(zoom) failed:", (err && err.message) || err); }
        }

        function _rearCycleList() {
            const rear = _camDevices.filter(d => /back|rear|environment|world/i.test(d.label || ""));
            return rear.length >= 2 ? rear : _camDevices;
        }

        async function _openCameraDevice(deviceId, mode) {
            if (_camStream) {
                try { _camStream.getTracks().forEach(tr => { try { tr.stop(); } catch (_) {} }); } catch (_) {}
                _camStream = null;
            }
            let stream;
            try {
                stream = await navigator.mediaDevices.getUserMedia(_camVideoConstraints(deviceId));
            } catch (err) {
                console.error("[camera-diag] switch-camera getUserMedia failed:", (err && err.name) || err);
                showToast("Could not open that camera", "error");
                return;
            }
            if (activeCameraMode !== mode) { stream.getTracks().forEach(x => { try { x.stop(); } catch (_) {} }); return; }
            _camStream = stream;
            _camTrack = (stream.getVideoTracks && stream.getVideoTracks()[0]) || null;
            _camDeviceId = (_camTrack && _camTrack.getSettings && _camTrack.getSettings().deviceId) || deviceId || null;
            if (_camVideo) {
                _camVideo.srcObject = stream;
                try { await _camVideo.play(); } catch (_) {}
            }
            await _applyContinuousFocus();
            _renderCameraDiagnostics(mode);
            _zxStartLogged = false;   // re-log decode canvas once for the new source
            console.log("[camera-diag] switched to deviceId:", _camDeviceId);
        }

        async function _switchCamera() {
            if (!activeCameraMode) return;
            const list = _rearCycleList();
            if (list.length < 2) { showToast("Only one camera available", "info"); return; }
            let idx = list.findIndex(d => d.deviceId && d.deviceId === _camDeviceId);
            if (idx < 0) idx = 0;
            const next = list[(idx + 1) % list.length];
            if (next && next.deviceId) await _openCameraDevice(next.deviceId, activeCameraMode);
        }

        function _renderCameraDiagnostics(mode) {
            const host = document.getElementById(_scannerViewId(mode));
            if (!host) return;
            let panel = host.querySelector("[data-camera-diag]");
            if (!panel) {
                panel = document.createElement("div");
                panel.setAttribute("data-camera-diag", "");
                panel.style.cssText = "font-size:11px;line-height:1.5;color:#c7d2fe;padding:4px 2px 3px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace";
                if (host.lastElementChild) host.insertBefore(panel, host.lastElementChild);
                else host.appendChild(panel);
            }
            const cap = _readTrackCapabilities();
            const rep = cap ? cap.report : { focusMode: "?", zoom: "?", width: "?", height: "?" };
            const list = _camDevices;
            const curIdx = list.findIndex(d => d.deviceId && d.deviceId === _camDeviceId);
            const esc = s => String(s).replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
            const rows = list.map((d, i) =>
                (i === curIdx ? "\u2192 " : "\u00a0\u00a0") + "[" + i + "] " +
                esc(d.label || ("camera " + (i + 1))) + " \u00b7 " +
                (d.deviceId ? esc(d.deviceId.slice(0, 10)) + "\u2026" : "(id hidden)")
            ).join("<br>");

            panel.innerHTML =
                "<div style='opacity:.8;margin-bottom:1px'>videoinput devices (" + list.length + "):</div>" +
                "<div>" + (rows || "(none)") + "</div>" +
                "<div style='margin-top:3px'>active deviceId: <b style='color:#e0e7ff'>" +
                    (_camDeviceId ? esc(_camDeviceId.slice(0, 16)) + "\u2026" : "(unknown)") + "</b></div>" +
                "<div>focusMode: <b style='color:#e0e7ff'>" + esc(JSON.stringify(rep.focusMode)) + "</b></div>" +
                "<div>zoom: <b style='color:#e0e7ff'>" + esc(JSON.stringify(rep.zoom)) + "</b></div>" +
                "<div>width: <b style='color:#e0e7ff'>" + esc(JSON.stringify(rep.width)) + "</b></div>" +
                "<div>height: <b style='color:#e0e7ff'>" + esc(JSON.stringify(rep.height)) + "</b></div>";

            if (list.length > 1) {
                const btn = document.createElement("button");
                btn.type = "button";
                btn.textContent = "Switch camera";
                btn.style.cssText = "margin-top:6px;padding:5px 12px;font-size:12px;border-radius:6px;border:1px solid #6366f1;background:#312e81;color:#e0e7ff;cursor:pointer";
                btn.onclick = function () { _switchCamera(); };
                panel.appendChild(btn);
            }

            if (cap && cap.caps && cap.caps.zoom) {
                const zc = cap.caps.zoom;
                const curZoom = (cap.settings && cap.settings.zoom != null) ? cap.settings.zoom : (zc.min != null ? zc.min : 1);
                const wrap = document.createElement("div");
                wrap.style.cssText = "margin-top:6px;display:flex;align-items:center;gap:8px";
                const lab = document.createElement("span"); lab.textContent = "Zoom";
                const rng = document.createElement("input");
                rng.type = "range";
                rng.min = (zc.min != null ? zc.min : 1);
                rng.max = (zc.max != null ? zc.max : 1);
                rng.step = (zc.step || 0.1);
                rng.value = curZoom;
                rng.style.cssText = "flex:1";
                const out = document.createElement("span"); out.textContent = Number(curZoom).toFixed(1) + "\u00d7";
                rng.oninput = function () { out.textContent = Number(rng.value).toFixed(1) + "\u00d7"; _applyCameraZoom(Number(rng.value)); };
                wrap.appendChild(lab); wrap.appendChild(rng); wrap.appendChild(out);
                panel.appendChild(wrap);
            }

            // V22: frozen-frame decoder isolation test
            const frow = document.createElement("div");
            frow.style.cssText = "margin-top:8px;border-top:1px solid #334155;padding-top:6px";
            const fbtn = document.createElement("button");
            fbtn.type = "button";
            fbtn.textContent = "\u2744 Freeze frame & test decoders";
            fbtn.style.cssText = "padding:6px 12px;font-size:12px;border-radius:6px;border:1px solid #10b981;background:#064e3b;color:#d1fae5;cursor:pointer;display:block;width:100%";
            fbtn.onclick = function () { _freezeFrameTest(mode); };
            const fout = document.createElement("div");
            fout.setAttribute("data-freeze-result", "");
            fout.style.cssText = "margin-top:5px;white-space:pre-wrap;color:#a7f3d0;font-size:11px";
            frow.appendChild(fbtn);
            frow.appendChild(fout);
            panel.appendChild(frow);
        }

        // V22: alternative 1D decoder = native BarcodeDetector (no new vendor
        // file). Runs against the exact frozen canvas. Formats include the
        // required UPC-A / UPC-E / EAN-13 / EAN-8.
        async function _altDecode(canvas) {
            if (typeof window.BarcodeDetector === "undefined") {
                return { unavailable: true, reason: "BarcodeDetector not in this browser" };
            }
            const want = ["upc_a", "upc_e", "ean_13", "ean_8", "code_128", "code_39", "itf"];
            let formats = want;
            try {
                const s = await window.BarcodeDetector.getSupportedFormats();
                formats = want.filter(f => s.indexOf(f) !== -1);
            } catch (e) { /* keep the full list */ }
            if (!formats.length) return { unavailable: true, reason: "no supported 1D formats" };
            try {
                const det = new window.BarcodeDetector({ formats: formats });
                const res = await det.detect(canvas);
                if (res && res.length && res[0] && res[0].rawValue) {
                    return { decoded: String(res[0].rawValue), format: res[0].format };
                }
                return { noResult: true };
            } catch (err) {
                return { name: (err && err.name) || "(no name)", message: (err && err.message) || String(err) };
            }
        }

        async function _freezeFrameTest(mode) {
            const host = document.getElementById(_scannerViewId(mode));
            const out = host && host.querySelector("[data-freeze-result]");
            const v = _camVideo;
            if (!v || v.readyState < 2 || !v.videoWidth) {
                if (out) out.textContent = "No live camera frame to freeze yet.";
                return;
            }

            // Freeze into a DEDICATED reusable canvas, sized exactly like the
            // live decode canvas (<=1280 wide, source aspect). The live loop
            // keeps using _zxGrab; this canvas is not overwritten until the
            // next freeze, so ZXing and the alternative decode identical
            // pixels and repeat runs are reproducible.
            const sw = v.videoWidth, sh = v.videoHeight;
            const dw = Math.min(ZX_DECODE_CANVAS_MAX_W, sw);
            const dh = Math.max(1, Math.round(dw * sh / sw));
            if (!_frozenCanvas) _frozenCanvas = document.createElement("canvas");
            if (_frozenCanvas.width !== dw || _frozenCanvas.height !== dh) { _frozenCanvas.width = dw; _frozenCanvas.height = dh; }
            _frozenCtx = _frozenCanvas.getContext("2d", { willReadFrequently: true });
            _frozenCtx.drawImage(v, 0, 0, dw, dh);

            // Show the frozen frame so its sharpness / framing is visible.
            let thumb = host.querySelector("[data-freeze-thumb]");
            if (!thumb) {
                thumb = document.createElement("img");
                thumb.setAttribute("data-freeze-thumb", "");
                thumb.style.cssText = "display:block;max-width:100%;margin-top:6px;border:1px solid #334155;border-radius:4px";
                if (out) out.parentElement.appendChild(thumb);
            }
            try { thumb.src = _frozenCanvas.toDataURL("image/jpeg", 0.85); } catch (e) {}

            // Build a fresh reader with the current hints/formats.
            const reader = new window.ZXing.BrowserMultiFormatReader(_zxHints());

            // 1a. EXACTLY what the live scan loop calls: reader.decode(<canvas>).
            //     Full exception detail - never swallowed to "".
            let zxA;
            try {
                const r = reader.decode(_frozenCanvas);
                zxA = { decoded: (r && r.getText && r.getText()) || String(r || "") };
            } catch (err) {
                zxA = { name: (err && err.name) || "(no name)", message: (err && err.message) || String(err) };
            }
            console.log("[freeze-test] frozen " + dw + "x" + dh + " | ZXing decode(canvas) ->", zxA);

            // 1b. ZXing decoder via HTMLCanvasElementLuminanceSource (the
            //     canvas-correct path in this bundle). Isolates whether ZXing's
            //     actual DECODER can read this frame, independent of 1a's
            //     canvas-input handling.
            let zxB;
            try {
                const ZX = window.ZXing;
                const src = new ZX.HTMLCanvasElementLuminanceSource(_frozenCanvas);
                const bmp = new ZX.BinaryBitmap(new ZX.HybridBinarizer(src));
                const r = reader.decodeBitmap(bmp);
                zxB = { decoded: (r && r.getText && r.getText()) || String(r || "") };
            } catch (err) {
                zxB = { name: (err && err.name) || "(no name)", message: (err && err.message) || String(err) };
            }
            console.log("[freeze-test] ZXing luminance-source ->", zxB);

            // 2. ALTERNATIVE decoder against the SAME frozen canvas.
            const alt = await _altDecode(_frozenCanvas);
            console.log("[freeze-test] Alternative (BarcodeDetector) ->", alt);

            const fmt = o => o.decoded ? ("decoded: " + o.decoded) : ("no result: " + (o.name || "?") + (o.message ? "  \u2014 " + o.message : ""));
            const L = [];
            L.push("Frozen frame: " + dw + "x" + dh);
            L.push("");
            L.push("ZXing decode(canvas)  [pre-V23 path - shows the bug]:");
            L.push("  - " + fmt(zxA));
            L.push("");
            L.push("ZXing luminance-source  [= live scan loop, V23+]:");
            L.push("  - " + fmt(zxB));
            L.push("");
            L.push("Alternative (BarcodeDetector):");
            if (alt.unavailable) L.push("  - not available" + (alt.reason ? " (" + alt.reason + ")" : ""));
            else if (alt.decoded) L.push("  - decoded: " + alt.decoded + (alt.format ? "  [" + alt.format + "]" : ""));
            else if (alt.noResult) L.push("  - no result");
            else L.push("  - error: " + (alt.name || "?") + (alt.message ? "  \u2014 " + alt.message : ""));
            if (out) out.textContent = L.join("\n");

            console.log("[freeze-test] RESULT | decode(canvas): " + (zxA.decoded || ("no result " + zxA.name)) +
                " | luminance: " + (zxB.decoded || ("no result " + zxB.name)) +
                " | BarcodeDetector: " + (alt.decoded || (alt.unavailable ? "unavailable" : (alt.noResult ? "no result" : ("error " + alt.name)))));

            // 9. feed a successful result into the existing pipeline.
            const winner = zxA.decoded || zxB.decoded || alt.decoded;
            if (winner) {
                console.log("[freeze-test] feeding into handleCameraBarcodeDecoded():", winner);
                handleCameraBarcodeDecoded(winner);
            }
        }

        // ===== end camera diagnostics =====

        // ONE camera success entry point. submitProductBarcode / submitPosBarcode
        // already emit the LOW capture beep + "Barcode captured" diagnostic and
        // carry their own de-dup, so this routes each decoded string once.
        function handleCameraBarcodeDecoded(rawCode) {
            const code = String(rawCode == null ? "" : rawCode).trim();
            if (!code) return;
            const mode = activeCameraMode;
            if (!mode) return;

            const now = Date.now();
            if (code === _zxLastDecode.code && (now - _zxLastDecode.at) < ZX_DECODE_COOLDOWN_MS) return;
            _zxLastDecode = { code: code, at: now };
            if (mode === "pos") {
                if (code === posLastCameraScan.code && (now - posLastCameraScan.at) < POS_CAMERA_SCAN_COOLDOWN_MS) return;
                posLastCameraScan = { code: code, at: now };
            }

            console.log("[barcode] ZXING DECODE SUCCESS:", code);
            _setScannerLine(mode, "Barcode read: " + code);

            if (mode === "product") {
                activeCameraMode = null;
                submitProductBarcode(code, "camera");
                stopCameraScanner();
                return;
            }
            submitPosBarcode(code, "camera");
        }

        // The ONLY hot path: video frame -> draw to reusable canvas -> decode
        // -> result/no result. Nothing else.
        function _zxScanTick() {
            _zxTimer = null;
            if (!_zxScanning) return;
            if (!_zxDecodeBusy && _zxReader && _camVideo && activeCameraMode) {
                const v = _camVideo;
                if (v.readyState >= 2 && v.videoWidth) {
                    _zxDecodeBusy = true;
                    try {
                        const sw = v.videoWidth, sh = v.videoHeight;
                        const dw = Math.min(ZX_DECODE_CANVAS_MAX_W, sw);
                        const dh = Math.max(1, Math.round(dw * sh / sw));
                        if (!_zxGrab) _zxGrab = document.createElement("canvas");
                        if (!_zxCtx || _zxGrab.width !== dw || _zxGrab.height !== dh) {
                            _zxGrab.width = dw; _zxGrab.height = dh;                       // only on a source-size change
                            _zxCtx = _zxGrab.getContext("2d", { willReadFrequently: true });
                        }
                        if (!_zxStartLogged) {
                            _zxStartLogged = true;
                            console.log("[barcode] decode canvas: " + dw + "x" + dh);
                            console.log("[barcode] decode interval: " + ZX_SCAN_INTERVAL_MS + "ms");
                        }
                        _zxCtx.drawImage(v, 0, 0, dw, dh);
                        // V23: decode via HTMLCanvasElementLuminanceSource. This
                        // ZXing 0.21.3 bundle's _zxReader.decode(<canvas>) throws
                        // IndexSizeError - createCaptureCanvas() has no
                        // HTMLCanvasElement branch, so its internal capture
                        // canvas is 0x0 - and the catch below was silently
                        // eating it on every frame. This path feeds the pixels
                        // straight in, no internal canvas.
                        const _lum = new window.ZXing.HTMLCanvasElementLuminanceSource(_zxGrab);
                        const _bmp = new window.ZXing.BinaryBitmap(new window.ZXing.HybridBinarizer(_lum));
                        const result = _zxReader.decodeBitmap(_bmp);
                        const code = (result && result.getText) ? result.getText() : "";
                        if (code) handleCameraBarcodeDecoded(code);
                    } catch (_) {
                        // NotFoundException / ChecksumException / FormatException -> normal, silent
                    } finally {
                        _zxDecodeBusy = false;
                    }
                }
            }
            if (_zxScanning) _zxTimer = setTimeout(_zxScanTick, ZX_SCAN_INTERVAL_MS);
        }

        // Preserved public name - the camera buttons call toggleInlineCamera('product'|'pos').
        async function toggleInlineCamera(mode) {
            if (activeCameraMode === mode) { await stopCameraScanner(); return; }
            await stopCameraScanner();
            _primePipelineAudio();   // runs inside the button tap -> unlocks the decode beep

            if (!window.ZXing || !window.ZXing.BrowserMultiFormatReader) {
                console.error('[barcode] window.ZXing missing - add <script src="/assets/vendor/zxing.umd.js"> before /js/app.js in index.html');
                showToast("Barcode scanner library did not load. Reload the page.", "error");
                return;
            }
            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                console.error("[barcode] getUserMedia unavailable in this browser");
                showToast(t("products.cameraAccessFailed"), "error");
                return;
            }

            const containerId = mode === "product" ? "product-camera-container" : "pos-camera-container";
            const cont = document.getElementById(containerId);
            if (cont) cont.classList.remove("hidden");
            _mountScannerUI(mode);
            activeCameraMode = mode;
            _setScannerLine(mode, "Starting camera\u2026");

            let stream;
            try {
                stream = await navigator.mediaDevices.getUserMedia(_camVideoConstraints(null));
            } catch (e1) {
                try {
                    stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment", width: { ideal: CAM_IDEAL_W }, height: { ideal: CAM_IDEAL_H } }, audio: false });
                } catch (e2) {
                    console.error("[barcode] getUserMedia failed:", (e2 && e2.name) || e2);
                    _setScannerLine(mode, "Unable to access camera");
                    showToast(t("products.cameraAccessFailed"), "error");
                    await stopCameraScanner();
                    return;
                }
            }
            if (activeCameraMode !== mode) { stream.getTracks().forEach(x => { try { x.stop(); } catch (_) {} }); return; }
            _camStream = stream;
            if (_camVideo) {
                _camVideo.srcObject = stream;
                try { await _camVideo.play(); } catch (_) { /* autoplay quirk - the tick still reads frames once ready */ }
            }

            // Camera settings are read ONCE here (start). Never in the scan loop.
            _camTrack = (stream.getVideoTracks && stream.getVideoTracks()[0]) || null;
            _camDeviceId = (_camTrack && _camTrack.getSettings && _camTrack.getSettings().deviceId) || null;
            try {
                await _enumerateCameras();
                await _applyContinuousFocus();
                _renderCameraDiagnostics(mode);
            } catch (err) {
                console.warn("[camera-diag] setup failed (decoding unaffected):", (err && err.message) || err);
            }

            try {
                _zxReader = new window.ZXing.BrowserMultiFormatReader(_zxHints(), ZX_SCAN_INTERVAL_MS);
            } catch (err) {
                console.error("[barcode] ZXing reader init failed:", (err && (err.name || err.message)) || err);
                _setScannerLine(mode, "Scanner library error");
                showToast(t("products.cameraAccessFailed"), "error");
                await stopCameraScanner();
                return;
            }
            if (!_zxGrab) _zxGrab = document.createElement("canvas");   // ONE reusable canvas (kept for the app lifetime)
            _zxScanning = true;
            _zxDecodeBusy = false;
            _zxStartLogged = false;
            _zxLastDecode = { code: null, at: 0 };
            _zxTimer = setTimeout(_zxScanTick, ZX_SCAN_INTERVAL_MS);
            _setScannerLine(mode, "Point camera at barcode");
            console.log("[barcode] " + SCANNER_BUILD + " scanner started (mode:", mode + ")");
        }

        // Preserved public name. Safe to call repeatedly / before start / after
        // stop / mid product<->POS switch.
        async function stopCameraScanner() {
            activeCameraMode = null;
            _zxScanning = false;
            _zxDecodeBusy = false;
            _zxStartLogged = false;
            if (_zxTimer) { clearTimeout(_zxTimer); _zxTimer = null; }
            if (_zxReader) { try { _zxReader.reset(); } catch (_) {} _zxReader = null; }
            if (_camStream) {
                try { _camStream.getTracks().forEach(tr => { try { tr.stop(); } catch (_) {} }); } catch (_) {}
                _camStream = null;
            }
            _camTrack = null;
            _camDevices = [];
            _camDeviceId = null;
            if (_camVideo) {
                try { _camVideo.pause(); } catch (_) {}
                try { _camVideo.srcObject = null; } catch (_) {}
                _camVideo = null;
            }
            _zxLastDecode = { code: null, at: 0 };
            // _zxGrab / _zxCtx are intentionally KEPT - one reusable canvas +
            // context for the whole app lifetime (no per-session allocation).
            const pv = document.getElementById("product-camera-view"); if (pv) pv.replaceChildren();
            const sv = document.getElementById("pos-camera-view");     if (sv) sv.replaceChildren();
            const pc = document.getElementById("product-camera-container"); if (pc) pc.classList.add("hidden");
            const sc = document.getElementById("pos-camera-container");     if (sc) sc.classList.add("hidden");
            // hand keyboard focus back so a hardware/Bluetooth scanner still works
            if (!document.getElementById("sale-modal")?.classList.contains("hidden")) {
                document.getElementById("pos-scan-input")?.focus();
            } else if (!document.getElementById("add-product-modal")?.classList.contains("hidden")) {
                document.getElementById("barcode-input")?.focus();
            }
        }

        function updateSkuPlaceholder() {
            const categoryInput = document.getElementById("p-category").value.trim();
            const skuInput = document.getElementById("p-sku");
            const barcodeVal = document.getElementById("barcode-input").value.trim();
            const last4 = barcodeVal.length >= 4 ? barcodeVal.slice(-4) : (barcodeVal || "XXXX");
            const catPrefix = categoryInput ? categoryInput.toUpperCase().slice(0, 3) : "SKU";
            skuInput.placeholder = `${catPrefix}-${last4}`;
        }

        let productAdvisorTimer = null;
        async function runProductAiMarginAdvice() {
            const cost = parseFloat(document.getElementById("p-cost").value) || 0;
            const retail = parseFloat(document.getElementById("p-retail").value) || 0;
            const category = document.getElementById("p-category")?.value.trim() || "General";
            const name = document.getElementById("p-name")?.value.trim() || "Product";
            const tipEl = document.getElementById("product-ai-advisor-tip");
            if (!tipEl) return;
            if (cost <= 0 && retail <= 0) { tipEl.textContent = t("products.enterCostRetailForAdvice"); return; }
            clearTimeout(productAdvisorTimer);
            productAdvisorTimer = setTimeout(async () => {
                tipEl.textContent = t("products.geminiEvaluating");
                try {
                    const res = await fetch(`${API_URL}/ai/suggest-margin`, {method:"POST", headers:{"Content-Type":"application/json","Authorization":`Bearer ${authToken}`}, body:JSON.stringify({product_name:name, category, cost_price:cost, retail_price:retail})});
                    const data = await res.json().catch(()=>({}));
                    if (!res.ok) { const err = new Error(data.detail || t("products.geminiUnavailable")); err.status = res.status; throw err; }
                    tipEl.textContent = `${data.advice || t("products.geminiAdviceReady")} ${t("products.suggestedPrices", {wholesale: formatCurrency(data.suggested_wholesale), retail: formatCurrency(data.suggested_retail)})}`;
                } catch (e) { tipEl.textContent = e.status === 403 ? (e.message || t("products.advisorStarterRequired")) : t("products.geminiTemporarilyUnavailable"); }
            }, 500);
        }

        let editAdvisorTimer = null;
        async function runEditAiMarginAdvice() {
            const cost = parseFloat(document.getElementById("edit-p-cost").value) || 0;
            const retail = parseFloat(document.getElementById("edit-p-retail").value) || 0;
            const category = document.getElementById("edit-p-category")?.value.trim() || "General";
            const name = document.getElementById("edit-p-name")?.value.trim() || "Product";
            const tipEl = document.getElementById("edit-ai-advisor-tip");
            if (!tipEl) return;
            if (cost <= 0 && retail <= 0) { tipEl.textContent = t("products.enterCostRetailForAdvice"); return; }
            clearTimeout(editAdvisorTimer);
            editAdvisorTimer = setTimeout(async () => {
                tipEl.textContent = t("products.geminiEvaluating");
                try {
                    const res = await fetch(`${API_URL}/ai/suggest-margin`, {method:"POST", headers:{"Content-Type":"application/json","Authorization":`Bearer ${authToken}`}, body:JSON.stringify({product_name:name, category, cost_price:cost, retail_price:retail})});
                    const data = await res.json().catch(()=>({}));
                    if (!res.ok) { const err = new Error(data.detail || t("products.geminiUnavailable")); err.status = res.status; throw err; }
                    tipEl.textContent = `${data.advice || t("products.geminiAdviceReady")} ${t("products.suggestedPrices", {wholesale: formatCurrency(data.suggested_wholesale), retail: formatCurrency(data.suggested_retail)})}`;
                } catch (e) { tipEl.textContent = e.status === 403 ? (e.message || t("products.advisorStarterRequired")) : t("products.geminiTemporarilyUnavailable"); }
            }, 500);
        }

        function syncHeaderSearch(val) {
            const inventorySearch = document.getElementById("inventory-search");
            if (inventorySearch) {
                inventorySearch.value = val;
                filterInventoryByWarehouse();
            }
        }

        function scrollToInventory() {
            document.getElementById("inventory-section")?.scrollIntoView({ behavior: 'smooth' });
        }

        function openAddProductModal() {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("add-product-modal").classList.remove("hidden");
            updateFormCurrencyLabels();
            // Give the scan field focus so a USB/Bluetooth wedge scanner can
            // type straight into it with no extra click (Part 5).
            setTimeout(() => document.getElementById("barcode-input")?.focus(), 50);
        }

        function closeAddProductModal() {
            stopCameraScanner();
            document.getElementById("add-product-modal").classList.add("hidden");
        }

        function openAICenterModal() {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("ai-center-modal").classList.remove("hidden");
        }

        function closeAICenterModal() {
            document.getElementById("ai-center-modal").classList.add("hidden");
        }

        // ===================================================================
        // BARCODE CAPTURE PIPELINE (Parts 1/3/4/6/7)
        // Camera, USB wedge, Bluetooth wedge and manual entry all converge on
        // submitProductBarcode() / submitPosBarcode(). The ONLY difference
        // between sources is how the raw string is captured; once a complete
        // barcode exists, every source runs the identical downstream business
        // flow for that screen. No source calls a different lookup.
        // ===================================================================

        // Two diagnostic tones. LOW = a complete barcode string was CAPTURED
        // (before any lookup). HIGH = it RESOLVED to a product. No beep at all
        // => nothing was ever decoded. One reused AudioContext, unlocked on the
        // camera tap / scan-field focus; entirely best-effort — a blocked or
        // missing AudioContext must never interrupt a scan.
        console.log("[barcode] app.js build 2026-09-04-v23 — decode fix: HTMLCanvasElementLuminanceSource (zxing-stable-v2)");
        let _pipelineAudioCtx = null;
        function _primePipelineAudio() {
            try {
                const AC = window.AudioContext || window.webkitAudioContext;
                if (!AC) return;
                if (!_pipelineAudioCtx) _pipelineAudioCtx = new AC();
                if (_pipelineAudioCtx.state === "suspended") _pipelineAudioCtx.resume();
            } catch (e) { /* ignore */ }
        }
        function _playPipelineBeep(frequency, seconds) {
            try {
                const AC = window.AudioContext || window.webkitAudioContext;
                if (!AC) return;
                if (!_pipelineAudioCtx) _pipelineAudioCtx = new AC();
                const ctx = _pipelineAudioCtx;
                if (ctx.state === "suspended") { try { ctx.resume(); } catch (e) {} }
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(frequency, ctx.currentTime);
                gain.gain.setValueAtTime(0.1, ctx.currentTime);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start();
                osc.stop(ctx.currentTime + seconds);
            } catch (e) { /* AudioContext unavailable/blocked — ignore */ }
        }
        function playScanDetectedBeep()    { _playPipelineBeep(540, 0.12); }  // LOW  — barcode captured
        function playProductResolvedBeep() { _playPipelineBeep(1180, 0.14); } // HIGH — product resolved

        // Barcodes are STRINGS. Never parseInt() — leading zeroes are
        // significant (012345678905 stays 012345678905). Mirrors the backend
        // normalize_barcode() contract in main.py exactly: strip every
        // non-digit; 6-14 digits is a barcode. Anything that is not 6-14
        // digits after stripping (an alphanumeric SKU in Add Product, a
        // product name typed into the POS field) passes through trimmed and
        // otherwise untouched, so SKU / name entry still works.
        function normalizeBarcodeInput(raw) {
            const trimmed = String(raw == null ? "" : raw).replace(/[\r\n\t]+/g, " ").trim();
            const digits = trimmed.replace(/\D/g, "");
            const isBarcode = digits.length >= 6 && digits.length <= 14;
            return { value: trimmed, digits, isBarcode, canonical: isBarcode ? digits : trimmed };
        }

        // Collapse a scanner that ends a barcode with more than one terminator
        // (CR+LF, or Enter then a stray Tab) into one submission. Event-noise
        // suppression only, not a business rule.
        let _lastBarcodeSubmit = { key: "", at: 0 };
        const BARCODE_SUBMIT_DEDUP_MS = 150;
        function _isDuplicateBarcodeSubmit(scope, value) {
            const now = Date.now();
            const key = scope + "|" + value;
            if (key === _lastBarcodeSubmit.key && (now - _lastBarcodeSubmit.at) < BARCODE_SUBMIT_DEDUP_MS) return true;
            _lastBarcodeSubmit = { key, at: now };
            return false;
        }

        // Diagnostic-only guess: wedge scanners emit keystrokes far faster
        // than a person types. Never a routing or security decision — both
        // paths are byte-for-byte identical.
        const _barcodeKeyCadence = {};
        function _noteBarcodeKeystroke(fieldId) {
            const now = Date.now();
            let s = _barcodeKeyCadence[fieldId];
            if (!s || (s.last && now - s.last > 1000)) s = _barcodeKeyCadence[fieldId] = { last: 0, fast: 0, n: 0 };
            if (s.last) { s.n++; if (now - s.last < 35) s.fast++; }
            s.last = now;
        }
        function _classifyBarcodeSource(fieldId) {
            const s = _barcodeKeyCadence[fieldId];
            _barcodeKeyCadence[fieldId] = { last: 0, fast: 0, n: 0 };
            return (s && s.n >= 3 && (s.fast / s.n) > 0.7) ? "hardware" : "manual";
        }

        // ADD PRODUCT submission: normalize -> LOW capture beep -> the existing
        // server-backed identity chain (own inventory -> Cauldra General
        // Catalog -> UPCitemdb, all inside POST /catalog/barcode-lookup). This
        // helper never talks to UPCitemdb or the catalog directly, and never
        // touches POS.
        function submitProductBarcode(raw, source) {
            const norm = normalizeBarcodeInput(raw);
            if (!norm.value) return;
            if (_isDuplicateBarcodeSubmit("product", norm.value)) return;
            const input = document.getElementById("barcode-input");
            if (input) input.value = norm.value;
            console.log("[barcode] captured", { source: source || "manual", mode: "product", code: norm.canonical });
            playScanDetectedBeep();            // LOW — complete barcode captured, BEFORE any lookup
            showToast("Barcode captured: " + norm.canonical, "info"); // temporary visible diagnostic
            lookupBarcode();
        }

        // POS submission: normalize -> LOW capture beep -> the existing local
        // resolver. POS matches ONLY this business's stocked inventory
        // (resolveScannedProduct) and never calls /catalog/barcode-lookup or
        // UPCitemdb — recognising a barcode is not the same as stocking it.
        function submitPosBarcode(raw, source) {
            const norm = normalizeBarcodeInput(raw);
            if (!norm.value) return;
            if (_isDuplicateBarcodeSubmit("pos", norm.value)) return;
            console.log("[barcode] captured", { source: source || "manual", mode: "pos", code: norm.canonical });
            playScanDetectedBeep();            // LOW — captured, BEFORE inventory matching
            showToast("Barcode captured: " + norm.canonical, "info"); // temporary visible diagnostic
            const input = document.getElementById("pos-scan-input");
            if (input) input.value = "";
            document.getElementById("pos-autocomplete-dropdown")?.classList.add("hidden");
            resolveAndAddScannedProduct(norm.value);
        }

        // Shared completion handling for a scan field. keydown, not keypress:
        // keypress never fires for Tab, and browsers drop keypresses under the
        // synthetic-keystroke burst a wedge scanner produces.
        //   - Enter / NumpadEnter / Tab  -> submit immediately (covers CR, LF,
        //     CRLF, Enter and Tab wedge suffixes). preventDefault keeps Tab
        //     from moving focus off the field before the value is read.
        //   - NO suffix  -> after ~110ms with no new character, if the burst
        //     arrived at scanner speed (existing _barcodeKeyCadence tracker)
        //     AND the value is a plausible barcode, submit automatically.
        //     Slow human typing never trips this; it is not used for the
        //     Enter/Tab scanners, only as an additional path.
        const BARCODE_IDLE_COMPLETE_MS = 110;
        const _barcodeIdleTimer = {};
        function _wireScanField(fieldId, submitFn) {
            const el = document.getElementById(fieldId);
            if (!el) return;
            const clearIdle = () => {
                if (_barcodeIdleTimer[fieldId]) { clearTimeout(_barcodeIdleTimer[fieldId]); _barcodeIdleTimer[fieldId] = null; }
            };
            el.addEventListener("focus", _primePipelineAudio);
            el.addEventListener("blur", clearIdle);
            el.addEventListener("keydown", (e) => {
                if (e.key === "Enter" || e.key === "Tab" || e.code === "NumpadEnter") {
                    e.preventDefault();
                    clearIdle();
                    if (!String(el.value).trim()) return;
                    submitFn(el.value, _classifyBarcodeSource(fieldId));
                    return;
                }
                // Any non-terminator key cancels a pending idle-submit so a
                // stale value is never sent. Only printable keys re-arm it
                // (Shift / Backspace / arrows must not schedule a submit).
                clearIdle();
                if (!e.key || e.key.length !== 1) return;
                // First character of a fresh entry -> start cadence clean, so
                // slow typing that was cleared out can't drag down the ratio of
                // the scan that follows it.
                if (el.value.length === 0) _barcodeKeyCadence[fieldId] = { last: 0, fast: 0, n: 0 };
                _noteBarcodeKeystroke(fieldId);
                _barcodeIdleTimer[fieldId] = setTimeout(() => {
                    _barcodeIdleTimer[fieldId] = null;
                    const c = _barcodeKeyCadence[fieldId];
                    const scannerSpeed = c && c.n >= 3 && (c.fast / c.n) > 0.7;
                    if (!scannerSpeed) return;                              // human typing — leave it
                    if (!normalizeBarcodeInput(el.value).isBarcode) return; // not a plausible barcode yet
                    console.log("[barcode] idle-completed no-suffix scan on", fieldId);
                    submitFn(el.value, _classifyBarcodeSource(fieldId));    // de-duped by _isDuplicateBarcodeSubmit if Enter also arrives
                }, BARCODE_IDLE_COMPLETE_MS);
            });
        }
        _wireScanField("barcode-input", submitProductBarcode);
        _wireScanField("pos-scan-input", submitPosBarcode);
        document.getElementById("barcode-input")?.addEventListener("input", updateSkuPlaceholder);

        // ================= SCOPED KEYBOARD-WEDGE CAPTURE (Part 9) =============
        // USB / Bluetooth scanners type like a keyboard. This listener catches
        // a scan even when focus is NOT on #barcode-input / #pos-scan-input.
        // It is SCOPED, not global: it does nothing unless #add-product-modal
        // or #sale-modal is visible, and it never touches a real editable
        // control the user is using (inputs, selects, textareas, buttons,
        // contenteditable). When a scan field itself has focus the existing
        // field path stays primary. Both paths funnel through
        // submitProductBarcode / submitPosBarcode, whose _isDuplicateBarcodeSubmit
        // guard collapses any overlap into one submission.
        const WEDGE_IDLE_MS = 100;
        const WEDGE_FAST_GAP_MS = 35;
        let _wedgeBuffer = "";
        let _wedgeLastAt = 0;
        let _wedgeTimer = null;
        let _wedgeCharCount = 0;
        let _wedgeFastCount = 0;

        function _activeScanModal() {
            if (!document.getElementById("sale-modal")?.classList.contains("hidden")) return "pos";
            if (!document.getElementById("add-product-modal")?.classList.contains("hidden")) return "product";
            return null;
        }
        function _wedgeReset() {
            _wedgeBuffer = ""; _wedgeCharCount = 0; _wedgeFastCount = 0; _wedgeLastAt = 0;
            if (_wedgeTimer) { clearTimeout(_wedgeTimer); _wedgeTimer = null; }
        }
        function _wedgeFlush(reason) {
            const buf = _wedgeBuffer;
            const looksHardware = _wedgeCharCount >= 3 && (_wedgeFastCount / _wedgeCharCount) > 0.7;
            _wedgeReset();
            if (!buf) return;
            const modal = _activeScanModal();
            if (!modal) return;
            if (reason === "idle" && (!looksHardware || !normalizeBarcodeInput(buf).isBarcode)) return;
            console.log("[barcode] wedge capture (" + reason + ", modal:", modal + "):", buf);
            if (modal === "product") submitProductBarcode(buf, "hardware");
            else submitPosBarcode(buf, "hardware");
        }

        document.addEventListener("keydown", (e) => {
            const modal = _activeScanModal();
            if (!modal) { if (_wedgeBuffer) _wedgeReset(); return; }

            const tgt = e.target;
            if (tgt && (tgt.id === "barcode-input" || tgt.id === "pos-scan-input")) {
                if (_wedgeBuffer) _wedgeReset();   // the focused-field path owns this scan
                return;
            }
            if (tgt && tgt.closest && tgt.closest("input, textarea, select, button, [contenteditable]")) {
                if (_wedgeBuffer) _wedgeReset();
                return;
            }

            if (e.key === "Enter" || e.key === "Tab" || e.code === "NumpadEnter") {
                if (_wedgeBuffer) { e.preventDefault(); _wedgeFlush("terminator"); }
                return;
            }
            if (!e.key || e.key.length !== 1) return;   // ignore Shift / Backspace / arrows / F-keys

            const now = Date.now();
            if (_wedgeLastAt && (now - _wedgeLastAt) > 1000) _wedgeReset();   // stale buffer -> new burst
            if (_wedgeLastAt) {
                _wedgeCharCount++;
                if ((now - _wedgeLastAt) < WEDGE_FAST_GAP_MS) _wedgeFastCount++;
            }
            _wedgeLastAt = now;
            _wedgeBuffer += e.key;
            if (_wedgeTimer) clearTimeout(_wedgeTimer);
            _wedgeTimer = setTimeout(() => _wedgeFlush("idle"), WEDGE_IDLE_MS);
        }, true);

        // Add Product's OWN barcode chain — completely separate from POS
        // scanning (see resolveScannedProduct/resolveAndAddScannedProduct):
        //   1. exact-barcode duplicate check against THIS business's own,
        //      already-loaded inventory (globalProducts) — never silently
        //      autofills price/cost/qty for an item already stocked; instead
        //      points the user at Stock Inventory to restock/edit it.
        //   2. Cauldra General Catalog (shared product IDENTITY only)
        //   3. UPCitemdb, only on a genuine catalog miss
        // Steps 2-3 (plus caching a UPCitemdb hit back into the General
        // Catalog) happen server-side in POST /catalog/barcode-lookup — this
        // function never talks to UPCitemdb or the General Catalog directly,
        // and never reuses this chain for POS/checkout.
        async function lookupBarcode() {
            const inputVal = document.getElementById("barcode-input").value.trim();
            if (!inputVal) { showToast(t("products.scanOrEnterSku"), "error"); return; }
            const last4 = inputVal.length >= 4 ? inputVal.slice(-4) : inputVal;
            const categoryInput = document.getElementById("p-category").value.trim();
            const catPrefix = categoryInput ? categoryInput.toUpperCase().slice(0, 3) : "SKU";
            const generatedSku = `${catPrefix}-${last4}`;

            // Cheap client-side duplicate hint using data already in memory —
            // the server repeats this exact-barcode check authoritatively
            // (business-scoped) before ever consulting the catalog/UPCitemdb,
            // so this is purely a faster response for the common case, not
            // the security boundary. Digits-only, matching backend
            // normalize_barcode() and how Product.barcode is stored.
            const normalizedInput = inputVal.replace(/\D/g, "");
            console.log("[barcode] product lookup starting:", normalizedInput || inputVal);
            const ownMatch = normalizedInput && globalProducts.find(p => p.barcode && String(p.barcode).trim() === normalizedInput);
            if (ownMatch) {
                // Already stocked. The LOW capture beep already fired; a
                // duplicate is a "you have this" notice, not a resolved-
                // identity success, so no HIGH beep (Part 11: least confusing).
                console.warn("[barcode] already in this inventory:", normalizedInput);
                showToast(t("products.barcodeAlreadyInInventory", { name: ownMatch.name }), "info");
                return;
            }

            const nameInput = document.getElementById("p-name");
            nameInput.value = "Searching database...";
            nameInput.disabled = true;
            document.getElementById("p-sku").value = generatedSku;

            try {
                const res = await fetch(`${API_URL}/catalog/barcode-lookup`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ barcode: inputVal })
                });
                const data = await res.json();
                nameInput.disabled = false;

                if (res.ok && data.found && data.duplicate) {
                    nameInput.value = "";
                    document.getElementById("p-sku").value = "";
                    console.warn("[barcode] already in this inventory:", data.product_name);
                    showToast(t("products.barcodeAlreadyInInventory", { name: data.product_name }), "info");
                } else if (res.ok && data.found) {
                    // Only IDENTITY fields the form actually supports — never
                    // category, price, cost, quantity, or SKU from an
                    // external/shared source (see spec: the business always
                    // chooses those itself).
                    document.getElementById("p-name").value = data.product_name || "";
                    if (document.getElementById("p-size") && data.size) document.getElementById("p-size").value = data.size;
                    updateSkuPlaceholder();
                    console.log("[barcode] product resolved:", data.product_name, "(source:", (data.source || "catalog") + ")");
                    playProductResolvedBeep();     // HIGH — barcode resolved to a product identity
                    showToast("Product resolved: " + (data.product_name || "(unnamed)"), "success"); // temporary visible diagnostic
                } else {
                    document.getElementById("p-name").value = "";
                    console.warn("[barcode] not found:", inputVal);
                    showToast(t("products.productNotFoundManualEntry"), "info");
                }
            } catch (err) {
                nameInput.disabled = false;
                document.getElementById("p-name").value = "";
                console.error("[barcode] product lookup failed:", (err && err.message) || err);
                showToast(t("products.lookupFailed"), "error");
            }
        }

        function openSaleModal() {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            posCart = [];
            posPricingMode = "retail";
            posLastCameraScan = { code: null, at: 0 };
            updatePricingModeUI();
            document.getElementById("sale-modal").classList.remove("hidden");
            document.getElementById("pos-scan-input").value = "";
            document.getElementById("pos-autocomplete-dropdown").classList.add("hidden");
            renderPOSCart();
            keepPOSScannerFocused();
        }

        function closeSaleModal() { stopCameraScanner(); document.getElementById("sale-modal").classList.add("hidden"); }

        function keepPOSScannerFocused(e) {
            // Skip any interactive control the cashier might be using —
            // otherwise a tap into e.g. a future select/textarea (or the
            // price-edit modal's own field, though that lives outside this
            // modal entirely) would get yanked back to the barcode input
            // mid-interaction. Editing a price itself goes through the
            // separate #input-modal overlay (see editPOSCartItemPrice), so
            // it never even reaches this click handler; this list is just
            // defensive for anything interactive inside the checkout modal.
            if (e && e.target && e.target.closest('button, input, textarea, select, [contenteditable]')) return;
            const scanInput = document.getElementById("pos-scan-input");
            if (scanInput && !document.getElementById("sale-modal").classList.contains("hidden")) scanInput.focus();
        }

        function setPOSPricingMode(mode) {
            posPricingMode = mode;
            // Re-default every cart line's transaction price to the newly
            // selected mode's catalog price — UNLESS the cashier has already
            // manually edited that specific line's price. A manual edit is a
            // deliberate transaction-only override and must survive a mode
            // switch (section 7); an un-edited line simply follows whichever
            // catalog price is currently selected, exactly as before.
            posCart.forEach(item => {
                if (!item.priceManuallyEdited) {
                    item.unitPrice = mode === "wholesale" ? item.wholesalePrice : item.retailPrice;
                    item.originalUnitPrice = item.unitPrice;
                    item.priceMode = mode;
                    item.negotiatedReason = null;
                }
            });
            updatePricingModeUI();
            renderPOSCart();
            keepPOSScannerFocused();
        }

        function updatePricingModeUI() {
            const retailBtn = document.getElementById("mode-retail-btn");
            const wholesaleBtn = document.getElementById("mode-wholesale-btn");
            if (posPricingMode === "retail") {
                retailBtn.className = "px-3 py-1 rounded-lg font-semibold bg-primary text-white transition cursor-pointer";
                wholesaleBtn.className = "px-3 py-1 rounded-lg font-semibold text-textSec hover:text-textMain transition cursor-pointer";
            } else {
                wholesaleBtn.className = "px-3 py-1 rounded-lg font-semibold bg-primary text-white transition cursor-pointer";
                retailBtn.className = "px-3 py-1 rounded-lg font-semibold text-textSec hover:text-textMain transition cursor-pointer";
            }
        }

        // #pos-scan-input terminator handling is wired by _wireScanField()
        // in the barcode capture pipeline above (keydown: Enter / NumpadEnter /
        // Tab -> submitPosBarcode). addScannedItemToPOSCart() is kept below as
        // a still-valid programmatic entry point.

        function handlePOSSearchInput() {
            const query = document.getElementById("pos-scan-input").value.toLowerCase().trim();
            const dropdown = document.getElementById("pos-autocomplete-dropdown");
            if (!query) { dropdown.classList.add("hidden"); dropdown.innerHTML = ""; return; }

            const matches = globalProducts.filter(p => p.name.toLowerCase().includes(query) || p.sku.toLowerCase().includes(query) || p.category.toLowerCase().includes(query));
            if (!matches.length) { dropdown.classList.add("hidden"); dropdown.innerHTML = ""; return; }

            dropdown.classList.remove("hidden");
            dropdown.innerHTML = matches.map(p => `
                <div onclick="selectProductFromPOSDropdown(${p.id})" class="p-2.5 hover:bg-cardHover cursor-pointer flex items-center justify-between text-xs transition">
                    <div>
                        <div class="font-medium text-textMain">${escapeHtml(p.name)} ${p.size ? `<span class="text-textSec text-[10px]">(${escapeHtml(p.size)})</span>` : ''}</div>
                        <div class="text-[10px] text-textSec font-mono">SKU: ${escapeHtml(p.sku)} | Stock: ${p.quantity}</div>
                    </div>
                    <div class="text-right font-mono"><div class="text-primary font-semibold">${formatCurrency(p.retail_price)}</div></div>
                </div>
            `).join("");
        }

        function selectProductFromPOSDropdown(productId) {
            const product = globalProducts.find(p => p.id === productId);
            if (!product) return;
            document.getElementById("pos-scan-input").value = product.sku;
            document.getElementById("pos-autocomplete-dropdown").classList.add("hidden");
            addSpecificProductToPOSCart(product);
        }

        // Exact-match product resolver — the ONE barcode/SKU resolution path
        // shared by the hardware scanner (Enter key), the camera scanner, and
        // the scan input's own Enter handler (section 19). Deliberately never
        // fuzzy-matches by product name: a scanned/typed complete identifier
        // must deterministically resolve to exactly one product or fail
        // clearly. Fuzzy name/category matching lives ONLY in the live
        // autocomplete dropdown (handlePOSSearchInput), a separate manual-
        // typing behavior that a click resolves directly, never through here.
        // Order: exact barcode match, then exact SKU match (case-insensitive)
        // — barcode and SKU are genuinely different product fields (see
        // Product.barcode in main.py) and are never assumed to be the same.
        function resolveScannedProduct(rawCode) {
            const code = String(rawCode || "").trim();
            if (!code) return null;
            const lower = code.toLowerCase();
            const digits = code.replace(/\D/g, "");
            // barcode: stored digits-only (backend normalize_barcode) — try the
            // raw scan and its digits-only form; SKU: exact, case-insensitive.
            return globalProducts.find(p => p.barcode && String(p.barcode).trim() === code)
                || (digits.length >= 6 && globalProducts.find(p => p.barcode && String(p.barcode).trim() === digits))
                || globalProducts.find(p => p.sku && String(p.sku).trim().toLowerCase() === lower)
                || null;
        }

        // Shared "a complete identifier was scanned/submitted" entry point —
        // resolves it via resolveScannedProduct() and either adds/increments
        // the matching product or shows one consistent "not found" error.
        // Both addScannedItemToPOSCart() (hardware scanner / Enter key) and
        // handleCameraBarcodeDecoded() (camera scanner, via submitPosBarcode)
        // reach this same function — one resolver, one add path, no dup logic.
        function resolveAndAddScannedProduct(rawCode) {
            const code = String(rawCode || "").trim();
            if (!code) return;
            console.log("[barcode] POS resolving:", code);
            const product = resolveScannedProduct(code);
            if (!product) {
                console.warn("[barcode] not in this inventory:", code);
                showToast(t("sales.itemNotInInventory"), "error");
                document.getElementById("pos-scan-input").value = "";
                keepPOSScannerFocused();
                return;
            }
            addSpecificProductToPOSCart(product);
        }

        function addScannedItemToPOSCart() {
            // Retained programmatic entry point — routes through the shared POS
            // submission helper so any caller still gets the capture beep and
            // terminator de-dup (the scan field's own keydown is wired
            // separately by _wireScanField).
            const code = document.getElementById("pos-scan-input").value.trim();
            if (!code) return;
            submitPosBarcode(code, "manual");
        }

        function addSpecificProductToPOSCart(product) {
            if (product.quantity < 1) {
                console.warn("[barcode] resolved but out of stock:", product.name);
                showToast(t("sales.itemOutOfStock", {name: product.name}), "error");
                document.getElementById("pos-scan-input").value = "";
                keepPOSScannerFocused();
                return;
            }
            const existing = posCart.find(i => i.id === product.id);
            if (existing) {
                if (existing.qty >= product.quantity) {
                    console.warn("[barcode] resolved but no more stock to add:", product.name);
                    showToast(t("sales.onlyUnitsLeft", {count: product.quantity}), "error");
                    document.getElementById("pos-scan-input").value = "";
                    keepPOSScannerFocused();
                    return;
                }
                existing.qty += 1;
            } else {
                const retailPrice = product.retail_price;
                const wholesalePrice = product.wholesale_price || product.retail_price;
                const unitPrice = posPricingMode === "wholesale" ? wholesalePrice : retailPrice;
                // unitPrice is the single source of truth for every cart
                // calculation and for the checkout payload (sections 3/5/6).
                // originalUnitPrice/priceManuallyEdited track whether this
                // line still follows the catalog price or was deliberately
                // overridden for this transaction only — editing unitPrice
                // NEVER writes back to product.retail_price/wholesale_price
                // or any other inventory pricing.
                posCart.push({
                    id: product.id, name: product.name, size: product.size || "", sku: product.sku, barcode: product.barcode || "",
                    retailPrice, wholesalePrice, costPrice: Number(product.cost_price || 0),
                    unitPrice, originalUnitPrice: unitPrice, priceMode: posPricingMode,
                    negotiatedReason: null, priceManuallyEdited: false,
                    qty: 1, maxStock: product.quantity
                });
            }
            console.log("[barcode] product resolved:", product.name);
            playProductResolvedBeep();          // HIGH — stocked product added/incremented in the cart
            showToast("Product resolved: " + product.name, "success"); // temporary visible diagnostic
            document.getElementById("pos-scan-input").value = "";
            renderPOSCart();
            keepPOSScannerFocused();
        }

        function updateCartItemQty(productId, change) {
            const item = posCart.find(i => i.id === productId);
            if (!item) return;
            const newQty = item.qty + change;
            if (newQty <= 0) {
                // Fully removed, not just zeroed — re-adding this product
                // later starts fresh via addSpecificProductToPOSCart (current
                // pricing mode, priceManuallyEdited=false), never resurrecting
                // a stale custom transaction price (section 15).
                posCart = posCart.filter(i => i.id !== productId);
            }
            else if (newQty > item.maxStock) { showToast(t("sales.onlyUnitsAvailable", {count: item.maxStock}), "error"); return; }
            else item.qty = newQty;
            renderPOSCart();
            keepPOSScannerFocused();
        }

        // Compact, fixed-width quantity stepper — same markup on desktop and
        // mobile so the control's width (and therefore row alignment) never
        // shifts between single- and double-digit quantities.
        function posQtyStepperHtml(item) {
            return `<div class="flex items-center border border-borderCol rounded-xl bg-bgMain overflow-hidden shrink-0">
                <button type="button" onclick="updateCartItemQty(${item.id}, -1)" class="w-8 h-8 flex items-center justify-center text-textSec hover:bg-cardHover hover:text-textMain transition cursor-pointer" aria-label="Decrease quantity">−</button>
                <span class="text-xs font-bold text-textMain px-1.5 min-w-[2rem] text-center">${item.qty}</span>
                <button type="button" onclick="updateCartItemQty(${item.id}, 1)" class="w-8 h-8 flex items-center justify-center text-textSec hover:bg-cardHover hover:text-textMain transition cursor-pointer" aria-label="Increase quantity">+</button>
            </div>`;
        }

        // Three-zone desktop layout implemented as a CSS grid on sm+ screens
        // — minmax(0,1fr) for product info (uses whatever space the other
        // two content-sized columns don't need, instead of a fixed
        // percentage that leaves dead space), auto for the quantity
        // stepper, minmax(90px,auto) for the total (room for large amounts,
        // never wraps). On narrow screens the same markup collapses to two
        // rows (product info, then quantity + total) via `display:contents`
        // on the quantity+total wrapper — no duplicated markup between
        // breakpoints. The Retail/Wholesale label is intentionally NOT
        // repeated per line — the mode selector above the cart already
        // shows it; posPricingMode itself and everything driven by it
        // (unitPrice defaults, mode-switch behavior) is untouched below.
        // unitPrice is the single source of truth for every calculation
        // here (section 5) — never recalculated from retailPrice/
        // wholesalePrice directly.
        function renderPOSCart() {
            const container = document.getElementById("pos-cart-items");
            const countEl = document.getElementById("cart-count");
            const totalEl = document.getElementById("pos-cart-total");
            countEl.innerText = `${posCart.reduce((sum, i) => sum + i.qty, 0)} items`;

            if (!posCart.length) {
                container.innerHTML = `<div class="text-center py-6 text-textSec text-xs">Cart is empty. Scan barcodes to start checkout.</div>`;
                totalEl.innerText = formatCurrency(0);
                return;
            }

            let grandTotal = 0;
            container.innerHTML = posCart.map(item => {
                const itemTotal = item.unitPrice * item.qty;
                grandTotal += itemTotal;
                return `
                    <div class="bg-cardBg border border-borderCol px-3 py-2.5 rounded-xl">
                        <div class="flex flex-col gap-2 sm:grid sm:grid-cols-[minmax(0,1fr)_auto_minmax(90px,auto)] sm:items-center sm:gap-3">
                            <div class="min-w-0 text-left">
                                <div class="font-semibold text-textMain text-xs leading-snug line-clamp-2">${escapeHtml(item.name)}${item.size ? ` <span class="text-textSec text-[10px] font-normal">(${escapeHtml(item.size)})</span>` : ''}</div>
                                ${['admin', 'manager'].includes(getCurrentRole()) ? `
                                    <button type="button" onclick="editPOSCartItemPrice(${item.id})" title="Negotiate this sale price (reason required)" class="mt-0.5 inline-flex items-center gap-1 text-[10px] text-textSec hover:text-primary transition cursor-pointer max-w-full">
                                        <span class="truncate">${formatCurrency(item.unitPrice)} each${item.priceManuallyEdited ? ` · <span class="text-warning font-medium">Negotiated</span>` : ''}</span>
                                        <i class="fa-solid fa-pen text-[9px] shrink-0"></i>
                                    </button>` : `
                                    <div class="mt-0.5 text-[10px] text-textSec">${formatCurrency(item.unitPrice)} each</div>`}
                            </div>
                            <div class="flex items-center justify-between sm:contents">
                                <div class="sm:flex sm:justify-center">${posQtyStepperHtml(item)}</div>
                                <span class="font-mono text-primary font-bold text-sm whitespace-nowrap sm:text-right">${formatCurrency(itemTotal)}</span>
                            </div>
                        </div>
                    </div>
                `;
            }).join("");
            totalEl.innerText = formatCurrency(grandTotal);
        }

        // Transaction-only price override (section 3/4) — opens the app's
        // existing reusable input-modal (showCustomPrompt) rather than a
        // bespoke inline editor or a browser prompt(). Never writes to
        // product.retail_price/wholesale_price or any other inventory data;
        // only this cart line's unitPrice changes, for this sale alone.
        async function editPOSCartItemPrice(productId) {
            const item = posCart.find(i => i.id === productId);
            if (!item) return;
            if (!['admin', 'manager'].includes(getCurrentRole())) {
                showToast("Only Admins and Managers can negotiate a sale price.", "error");
                return;
            }
            const minimumPrice = Math.max(0.01, Number(item.costPrice || 0));
            const maximumPrice = Math.max(Number(item.retailPrice || 0), Number(item.wholesalePrice || 0));
            const raw = await showCustomPrompt(
                `This sale-only price must be between ${formatCurrency(minimumPrice)} and ${formatCurrency(maximumPrice)}.`,
                "Edit Selling Price", "Selling Price", "number", false, String(item.unitPrice)
            );
            if (raw === null) { keepPOSScannerFocused(); return; } // cancelled
            const parsed = parseFloat(raw);
            if (raw === "" || !isFinite(parsed) || parsed < minimumPrice || parsed > maximumPrice) {
                showToast(`Enter a price between ${formatCurrency(minimumPrice)} and ${formatCurrency(maximumPrice)}.`, "error");
                keepPOSScannerFocused();
                return;
            }
            const reasonRaw = await showCustomPrompt(
                "Record why this negotiated price is appropriate. This reason is retained in Activity History.",
                "Negotiated Price Reason", "Reason", "text", false, item.negotiatedReason || ""
            );
            if (reasonRaw === null) { keepPOSScannerFocused(); return; }
            const reason = String(reasonRaw).trim();
            if (reason.length < 5 || reason.length > 200) {
                showToast("Enter a reason between 5 and 200 characters.", "error");
                keepPOSScannerFocused();
                return;
            }
            item.unitPrice = parsed;
            item.priceMode = "negotiated";
            item.negotiatedReason = reason;
            item.priceManuallyEdited = true;
            renderPOSCart();
            keepPOSScannerFocused();
        }

        async function completePOSCheckout() {
            if (!authToken) { showToast(t("common.signInOrRegister"), "info"); openBusinessAuthModal(); return; }
            if (!posCart.length) { showToast(t("sales.cartEmpty"), "error"); return; }
            // A product created offline (temporary negative id) doesn't exist
            // on the server yet, so it can't be referenced by a sale until its
            // own create has synced — selling it now would have nothing to
            // reconcile against. This is the one ordering dependency in this
            // system, and it's avoided by simply disallowing it up front
            // rather than attempting a fragile cross-operation sync order.
            const unsynced = posCart.find(item => item.id < 0);
            if (unsynced) { showToast(`"${unsynced.name || 'This item'}" was added offline and needs to sync before it can be sold. Try again once you're back online.`, "error"); return; }
            // unit_price is always item.unitPrice — the exact same figure
            // already shown and summed in the cart (sections 5/6). No
            // fallback/recompute here: unitPrice is guaranteed valid by
            // construction (set on add, validated on every manual edit), so
            // the displayed price and the submitted price can never disagree.
            const items=posCart.map(item=>({
                product_id:item.id,
                quantity:item.qty,
                price_mode:item.priceMode || posPricingMode,
                unit_price:item.priceMode === 'negotiated' ? item.unitPrice : undefined,
                negotiated_reason:item.priceMode === 'negotiated' ? item.negotiatedReason : undefined
            }));

            // --- Double-submit protection -----------------------------------
            // Two layers, because the UX guard alone is NOT an accounting
            // safeguard (a fast double-click can dispatch both requests
            // before the first response returns, and the button state can't
            // stop that):
            //  1. UX: disable the button + show a processing state so the
            //     ordinary double-click never fires twice in the first place.
            //  2. ACCOUNTING: reuse ONE client_ref for this cart across every
            //     attempt. The backend treats client_ref as the checkout's
            //     idempotency key, so even if two requests do reach it, the
            //     second returns the original result instead of recording a
            //     second sale. Without this the server generated a fresh key
            //     per request, so a double-submit created two real sales and
            //     one unit sold was reported as two.
            // The ref is only cleared on success, so a retry after a genuine
            // failure deliberately reuses it too.
            const btn = document.getElementById('pos-complete-sale-btn');
            if (posCheckoutInFlight) return;
            posCheckoutInFlight = true;
            const btnLabel = btn ? btn.textContent : null;
            if (btn) { btn.disabled = true; btn.textContent = 'Processing…'; }
            if (!posCheckoutClientRef) posCheckoutClientRef = `pos-${Date.now()}-${Math.random().toString(36).slice(2)}`;

            try {
                const headers={"Content-Type":"application/json","Authorization":`Bearer ${authToken}`};
                const res=await fetch(`${API_URL}/sales/checkout`,{method:'POST',headers,body:JSON.stringify({items, client_ref: posCheckoutClientRef})}); const data=await res.json();
                if(!res.ok) throw new Error(showApiError(res,data,t("sales.saleFailed")));
                posCheckoutClientRef = null;
                showToast(t("sales.saleCompletedToday", {total: formatCurrency(data.daily_total)}),"success"); posCart=[]; renderPOSCart(); closeSaleModal();
                // Targeted update — patch local product quantities from the
                // server's authoritative post-sale state and refresh only
                // the specifically affected areas (inventory, dashboard
                // metrics, Business Day status, Today's Sales if open)
                // instead of reloading the entire application (see
                // performance refactor, section 12/44). The backend already
                // marks Business Brain dirty for this sale — it recomputes
                // on its own next read, not forced here.
                (data.updated_products || []).forEach(u => {
                    const idx = globalProducts.findIndex(p => p.id === u.id);
                    if (idx !== -1) globalProducts[idx].quantity = u.quantity;
                });
                cacheProductsLocally(globalProducts);
                updateDashboardMetrics();
                refreshInventoryViewFromLocalState();
                loadBusinessDayControl();
                // Net Profit / COGS / Gross Profit move on every sale, so the
                // profit figures must be re-fetched from the backend here —
                // updateDashboardMetrics() above only refreshes inventory-
                // derived counters and would otherwise leave a stale profit.
                if (typeof loadProfitDashboardCards === 'function') loadProfitDashboardCards();
                const salesModal = document.getElementById('daily-sales-modal');
                if (salesModal && !salesModal.classList.contains('hidden')) await loadDailySales();
            }catch(err){
                if (isNetworkFailure(err)) { await completePOSCheckoutOffline(items); return; }
                showToast(friendlyErrorMessage(err.message,t("sales.saleFailed")),'error');
            } finally {
                posCheckoutInFlight = false;
                if (btn) { btn.disabled = false; btn.textContent = btnLabel; }
            }
        }

        // Offline fallback for completePOSCheckout: applies the same
        // delta-based stock decrement locally that the server performs
        // (never an absolute overwrite, so this can't clobber a quantity
        // another device changes online in the meantime), queues one outbox
        // operation for the whole cart with a single client_ref, and lets
        // /sales/checkout's own idempotency check (see main.py) guarantee a
        // retried sync can't decrement inventory or record the sale twice.
        async function completePOSCheckoutOffline(items) {
            let dailyTotal = 0;
            for (const item of items) {
                const p = globalProducts.find(pr => pr.id === item.product_id);
                if (!p) continue;
                if (item.quantity > p.quantity) {
                    showToast(`Not enough stock for ${p.name} in the locally cached inventory.`, "error");
                    return;
                }
                p.quantity -= item.quantity;
                dailyTotal += item.quantity * item.unit_price;
            }
            await cacheProductsLocally(globalProducts);
            const opId = generateOpId();
            await addOutboxOp({
                op_id: opId, business_id: currentOfflineScope(), user_id: currentUserProfile?.id || null,
                type: "sale_checkout", endpoint: "/sales/checkout", method: "POST",
                payload: { items, client_ref: opId }, meta: {},
                label: `Sale (${items.length} item${items.length === 1 ? "" : "s"})`,
                status: "pending", attempts: 0, next_retry_at: 0, created_at: Date.now(), last_error: null,
            });
            showToast(`You're offline — sale of ${formatCurrency(dailyTotal)} saved locally and will sync automatically when you're back online.`, "info");
            posCart = []; renderPOSCart(); closeSaleModal();
            updateDashboardMetrics();
            refreshInventoryViewFromLocalState();
        }

        function toggleAIChatWindow() {
            const win = document.getElementById("ai-chat-window");
            if (win.classList.contains("hidden")) {
                win.classList.remove("hidden");
                setTimeout(() => { win.classList.remove("scale-95", "opacity-0"); win.classList.add("scale-100", "opacity-100"); }, 10);
            } else {
                win.classList.remove("scale-100", "opacity-100");
                win.classList.add("scale-95", "opacity-0");
                setTimeout(() => { win.classList.add("hidden"); }, 200);
            }
        }

        async function openDailySalesModal(initialTab) {
            if (!authToken) { openBusinessAuthModal(); return; }
            document.getElementById("daily-sales-modal").classList.remove("hidden");
            const isHistoryTab = initialTab === "history" && getCurrentRole() !== "staff";
            switchSalesTab(isHistoryTab ? "history" : "current");
            await loadDailySales();
            if (getCurrentRole() !== "staff") { updateSalesHistoryPresetButtonsUI(); await Promise.all([loadSalesHistory(), loadSalesHistoryPeriodTotal()]); }
            const isStaff = getCurrentRole() === "staff";
            document.getElementById("sales-history-period-presets")?.classList.toggle("hidden", isStaff);
            // /sales/export is admin/manager only (matches /sales/history) — a
            // staff member sees the label but never the button, since the
            // history section beneath it is never even loaded for them.
            document.getElementById("sales-history-export-btn")?.classList.toggle("hidden", isStaff);
            // Sales History is not available to staff at all (same access
            // rule as above) — hide the tab itself rather than leave a tab a
            // staff member could click into and find permanently empty.
            document.getElementById("sales-tab-history-btn")?.classList.toggle("hidden", isStaff);
        }
        function closeDailySalesModal(){ document.getElementById("daily-sales-modal").classList.add("hidden"); }

        // Sales / Sales History tabs — same pattern as switchExpensesTab.
        function switchSalesTab(tab) {
            const currentBtn = document.getElementById("sales-tab-current-btn");
            const historyBtn = document.getElementById("sales-tab-history-btn");
            const activeCls = "px-2.5 py-1.5 rounded-lg text-[11px] font-semibold cursor-pointer bg-primary/15 text-primary border border-primary/30";
            const inactiveCls = "px-2.5 py-1.5 rounded-lg text-[11px] font-semibold cursor-pointer text-textSec hover:text-textMain border border-transparent";
            currentBtn.className = tab === "current" ? activeCls : inactiveCls;
            historyBtn.className = tab === "history" ? activeCls : inactiveCls;
            document.getElementById("sales-view-current").classList.toggle("hidden", tab !== "current");
            document.getElementById("sales-view-history").classList.toggle("hidden", tab !== "history");
        }

        // ---------------------------------------------------------------------
        // Business Day lifecycle (separate concept from "Today's Sales"/"Sales
        // History" below it, per the redesign): the backend is the only source
        // of truth for status/permissions — every button below just reflects
        // what the current role is actually allowed to do; the server enforces
        // it again regardless of what renders here.
        // ---------------------------------------------------------------------
        let currentBusinessDayId = null;
        let currentBusinessDayStatus = "NOT_STARTED";
        let businessDayActivityOpen = false;

        function businessDayBanner(dotClass, borderClass, bgClass, label, sub, actionsHtml) {
            return `<div class="p-3 rounded-xl ${bgClass} border ${borderClass} text-xs">
                <div class="flex items-center justify-between flex-wrap gap-2">
                    <span class="font-semibold text-textMain"><span class="inline-block w-2 h-2 rounded-full ${dotClass} mr-1.5"></span>${label}</span>
                    <span class="text-textSec">${sub}</span>
                </div>
                ${actionsHtml ? `<div class="flex items-center gap-2 flex-wrap mt-2">${actionsHtml}</div>` : ""}
            </div>`;
        }
        function bdActionBtn(onclick, label, variant, icon) {
            const styles = {
                primary: "bg-primary hover:bg-primaryHover text-white",
                warn: "bg-warning/15 hover:bg-warning/25 text-warning border border-warning/30",
                danger: "bg-danger/15 hover:bg-danger/25 text-danger border border-danger/30",
                ghost: "bg-bgMain hover:bg-cardHover text-textSec border border-borderCol",
            };
            return `<button type="button" onclick="${onclick}" class="${styles[variant] || styles.ghost} px-2.5 py-1 rounded-lg text-[11px] font-semibold cursor-pointer">${icon ? `<i class="fa-solid ${icon} mr-1"></i>` : ""}${label}</button>`;
        }
        function bdActivityToggleBtn(dayId) {
            return `<button type="button" onclick="toggleBusinessDayActivity(${dayId})" class="text-[11px] text-textSec hover:text-primary underline decoration-dotted cursor-pointer ml-auto"><i class="fa-solid fa-clock-rotate-left mr-1"></i><span id="business-day-activity-toggle-label">${businessDayActivityOpen ? "Hide" : "View"} Activity</span></button>`;
        }

        // The ONE authoritative Business Day "current state" fetch+render —
        // shared by the Dashboard header control and Today's Sales, so the
        // two can never disagree and there is no second, competing Business
        // Day system. Pure read (GET /sales/current-day): never opens/creates
        // a day as a side effect of being called — safe to call on every
        // Dashboard render, tab switch, or reload.
        async function loadBusinessDayControl() {
            const wrap = document.getElementById('business-day-header-control');
            const dot = document.getElementById('business-day-header-dot');
            const label = document.getElementById('business-day-header-label');
            const sub = document.getElementById('business-day-header-sub');
            const actionBtn = document.getElementById('business-day-header-action-btn');
            let d = { open: false, status: "NOT_STARTED", business_day: null };
            try {
                if (hasAuthenticatedBusinessContext()) {
                    const res = await fetch(`${API_URL}/sales/current-day`, { headers: { "Authorization": `Bearer ${authToken}` } });
                    if (res.ok) d = await res.json();
                }
            } catch (_) { /* keep the NOT_STARTED fallback rather than guessing */ }

            currentBusinessDayId = d.business_day ? d.business_day.id : null;
            currentBusinessDayStatus = d.status || "NOT_STARTED";

            // loadBusinessDayControl() is already the one function every
            // Business Day action (open, close, direct-reopen, reopen-
            // request submit/approve/reject, close-historical) calls when it
            // finishes — refreshing the dashboard's current-session Net
            // Profit headline here, rather than re-adding a separate call to
            // each of those handlers individually, guarantees none of them
            // can ever leave it stale. Safe/cheap to call unconditionally:
            // loadProfitDashboardCards() already no-ops for a signed-out/
            // guest state or a role without Profit access.
            if (typeof loadProfitDashboardCards === 'function') loadProfitDashboardCards();

            if (!wrap || !dot || !label || !actionBtn) return d;
            if (!hasAuthenticatedBusinessContext()) { wrap.classList.add('hidden'); wrap.classList.remove('flex'); return d; }
            wrap.classList.remove('hidden'); wrap.classList.add('flex');

            // Backend-authorized roles only (see /sales/start-business-day and
            // /sales/end-business-day) — Admin, Manager, and Staff can all
            // open/close, since Staff are often the ones physically running
            // the counter.
            const canControl = ['admin', 'manager', 'staff'].includes(getCurrentRole());
            const b = d.business_day;
            const baseBtnClass = "shrink-0 text-[11px] font-semibold px-3.5 py-2 rounded-xl transition cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed";

            // STRICTLY two states on this control, derived only from whether
            // an active Business Day SESSION currently exists (`d.open`) —
            // never from a record's lifecycle `status` (OPEN/CLOSED/
            // REOPENED), and never from `date`: a business can open, close,
            // and open a brand-new session again later the same day (see
            // the BusinessDay model docstring), so a session closed earlier
            // today is history, not something this control shows or offers
            // to "continue". /sales/current-day only ever reports the
            // active session, so business_day is always null here when
            // d.open is false. Reopening a CLOSED session is a separate,
            // more privileged, audited workflow (Admin direct-reopen /
            // Manager request) that lives exclusively in Sales History —
            // see renderSalesHistoryRow() — and must never appear as a
            // dashboard button, for any role. Pressing "Open Business Day"
            // here always creates a brand-new session (see
            // /sales/start-business-day) — the only way this can fail is if
            // another session is somehow already active, in which case
            // openBusinessDayHeaderOpen() surfaces that 409 as a toast.
            if (d.open) {
                dot.className = "inline-block w-2.5 h-2.5 rounded-full bg-success shrink-0";
                label.textContent = d.status === "REOPENED" ? "Business Day Open (Reopened)" : "Business Day Open";
                sub.textContent = b ? `${b.date}${b.opened_at ? " · Opened " + formatBusinessTime(b.opened_at) : ""}` : "";
                if (canControl) {
                    actionBtn.textContent = "Close Business Day";
                    actionBtn.className = baseBtnClass + " bg-danger/15 hover:bg-danger/25 text-danger border border-danger/30";
                    actionBtn.onclick = openBusinessDayHeaderClose;
                    actionBtn.classList.remove('hidden'); actionBtn.disabled = false;
                } else actionBtn.classList.add('hidden');
            } else {
                dot.className = "inline-block w-2.5 h-2.5 rounded-full bg-textSec shrink-0";
                label.textContent = "Business Day Closed";
                sub.textContent = "No Business Day has been started yet.";
                if (canControl) {
                    actionBtn.textContent = "Open Business Day";
                    actionBtn.className = baseBtnClass + " bg-primary hover:bg-primaryHover text-white";
                    actionBtn.onclick = openBusinessDayHeaderOpen;
                    actionBtn.classList.remove('hidden'); actionBtn.disabled = false;
                } else actionBtn.classList.add('hidden');
            }
            return d;
        }

        async function openBusinessDayHeaderOpen() {
            // Always creates a brand-new session (see /sales/start-business-
            // day) — the only way this can fail is another session already
            // being active, surfaced below as whatever 409 detail the
            // backend sends ("Another Business Day is currently open...").
            const btn = document.getElementById('business-day-header-action-btn');
            if (btn) btn.disabled = true;
            try {
                const r = await fetch(`${API_URL}/sales/start-business-day`, { method: 'POST', headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, "The Business Day could not be opened."));
                showToast("Business day started.", "success");
            } catch (e) {
                showToast(friendlyErrorMessage(e.message, e.message), 'error');
            } finally {
                await loadBusinessDayControl();
                if (document.getElementById('daily-sales-modal') && !document.getElementById('daily-sales-modal').classList.contains('hidden')) await loadDailySales();
            }
        }

        // Closing is the one action here with real consequences (finalizes
        // the sales period), so it always confirms first — reuses the exact
        // same confirmation copy as the previous Today's Sales button so the
        // wording a user has already seen doesn't change.
        async function openBusinessDayHeaderClose() {
            const ok = await showCustomConfirm(t("sales.endBusinessDayConfirmBody"), t("sales.endBusinessDayConfirmTitle"));
            if (!ok) return;
            const btn = document.getElementById('business-day-header-action-btn');
            if (btn) btn.disabled = true;
            try {
                const r = await fetch(`${API_URL}/sales/end-business-day`, { method: 'POST', headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, t("sales.businessDayCloseFailed")));
                showToast(t("sales.businessDayClosedSuccess"), 'success');
            } catch (e) {
                showToast(friendlyErrorMessage(e.message, e.message), 'error');
            } finally {
                await loadBusinessDayControl();
                if (document.getElementById('daily-sales-modal') && !document.getElementById('daily-sales-modal').classList.contains('hidden')) await loadDailySales();
                loadData(); // dashboard financial metrics move once a day closes
            }
        }

        // Today's Sales — status ONLY (see loadBusinessDayControl() above for
        // the actual Open/Close control, which lives on the Dashboard). This
        // never renders an Open/Close/Reopen button — that would let a
        // restricted role reach the action from a second place even if the
        // Dashboard control correctly hid it.
        async function loadDailySales(){
            try {
                const d = await loadBusinessDayControl();
                const box=document.getElementById("daily-sales-cards"), status=document.getElementById("daily-sales-status"), emptyState=document.getElementById("daily-sales-empty-state");
                const role = getCurrentRole();
                const b = d.business_day;
                const canViewActivity = role !== 'staff';

                // /sales/current-day only ever reports the currently ACTIVE
                // Business Day session — never a session closed earlier
                // today (that's history now, shown in Sales History, not
                // here). So "no active session" looks identical whether
                // nothing has ever been opened today or a session was
                // already opened and closed — this view has no closed/
                // Reopen state of its own, matching the Dashboard control.
                if (!d.open || !b) {
                    status.innerHTML = businessDayBanner("bg-textSec", "border-borderCol", "bg-bgMain",
                        "No Business Day is currently open",
                        "An Admin, Manager, or Staff member can open one from the Dashboard.", "");
                    box.innerHTML=''; emptyState.classList.add('hidden'); emptyState.innerHTML=''; document.getElementById('sales-chart').innerHTML='';
                    hideBusinessDayActivity();
                    return;
                }

                // OPEN or REOPENED
                const reopenedTag = d.status === "REOPENED" ? " (Reopened)" : "";
                // "Transactions" is available to every role, including
                // Staff — Staff are explicitly authorized to create refunds
                // (see /sales/transactions) and this is their entry point,
                // since the day-level Sales History aggregate stays
                // staff-restricted exactly as before (unrelated, unchanged).
                status.innerHTML = businessDayBanner("bg-success", "border-success/30", "bg-success/10",
                    `Business Day Open${reopenedTag} · ${b.date}`,
                    `Opened ${formatBusinessTime(b.opened_at)}${b.opened_by_name ? " by " + b.opened_by_name : ""}`,
                    `${canViewActivity ? bdActivityToggleBtn(b.id) : ""}<button type="button" onclick="openRefundTransactionsModal(${b.id})" class="text-[11px] text-textSec hover:text-primary underline decoration-dotted cursor-pointer${canViewActivity ? "" : " ml-auto"}"><i class="fa-solid fa-receipt mr-1"></i>Transactions</button>`);
                box.innerHTML = renderDailySalesCards(b, "Open");
                renderDailySalesEmptyState(emptyState, b);
                renderSalesChart();
                if (canViewActivity && businessDayActivityOpen) await loadBusinessDayActivity(b.id); else hideBusinessDayActivity();
            } catch(e){ showToast(t("sales.loadTodaysSalesFailed"),'error'); }
        }

        function renderDailySalesCards(b, statusLabel) {
            return [['Sales',formatCurrency(b.net_sales)],['Transactions',b.transactions],['Items Sold',b.items_sold],['Status',statusLabel]]
                .map(x=>`<div class="p-3 rounded-xl bg-bgMain border border-borderCol"><div class="text-[10px] text-textSec">${x[0]}</div><div class="text-sm font-bold text-textMain mt-1">${x[1]}</div></div>`).join('');
        }

        // Zero sales must never look broken/blank — a deliberate, explained
        // empty state instead of an unexplained gap under the cards.
        function renderDailySalesEmptyState(emptyState, b) {
            if (!emptyState) return;
            if (!b || b.transactions > 0) { emptyState.classList.add('hidden'); emptyState.innerHTML = ''; return; }
            emptyState.classList.remove('hidden');
            emptyState.innerHTML = `<div class="text-center py-8 px-4 border border-dashed border-borderCol rounded-xl bg-bgMain">
                <i class="fa-solid fa-receipt text-2xl text-textSec/50 mb-2"></i>
                <div class="text-textMain font-semibold text-xs">No sales recorded yet</div>
                <div class="text-textSec text-[11px] mt-1">Your sales will appear here once transactions are completed.</div>
                <button type="button" onclick="closeDailySalesModal(); checkFeatureAccess('new sale', openSaleModal);" class="mt-3 inline-flex items-center gap-1.5 bg-primary hover:bg-primaryHover text-white text-[11px] font-semibold px-3.5 py-2 rounded-xl transition cursor-pointer"><i class="fa-solid fa-plus text-[10px]"></i> New Sale</button>
            </div>`;
        }

        // =====================================================================
        // REFUNDS
        //
        // A refund always starts from a located completed transaction (never
        // the POS cart — see openSaleModal/completePOSCheckout, which this
        // file never touches). Two modals: refund-transactions-modal (find a
        // transaction) -> refund-modal (choose quantities/reason, confirm).
        // The backend (/sales/transactions*, POST .../refund) is the single
        // source of truth for every total shown here — this file only ever
        // displays what the API returns, it never (re)computes refund
        // arithmetic independently (section 28/12 of the refund spec).
        // =====================================================================
        let refundTransactionsDayId = null;

        async function openRefundTransactionsModal(businessDayId) {
            refundTransactionsDayId = businessDayId;
            document.getElementById('refund-transactions-modal').classList.remove('hidden');
            await loadRefundTransactionsList();
        }
        function closeRefundTransactionsModal() {
            document.getElementById('refund-transactions-modal').classList.add('hidden');
            refundTransactionsDayId = null;
        }

        async function loadRefundTransactionsList() {
            const list = document.getElementById('refund-transactions-list');
            list.innerHTML = `<div class="text-center py-6 text-textSec">Loading…</div>`;
            try {
                const res = await fetch(`${API_URL}/sales/transactions?business_day_id=${refundTransactionsDayId}`, { headers: { "Authorization": `Bearer ${authToken}` } });
                const data = await res.json().catch(() => ([]));
                if (!res.ok) throw new Error(showApiError(res, data, "Could not load transactions."));
                if (!data.length) { list.innerHTML = `<div class="text-center py-8 text-textSec">No transactions recorded for this Business Day.</div>`; return; }
                list.innerHTML = data.map(renderRefundTransactionRow).join('');
            } catch (e) {
                list.innerHTML = `<div class="text-center py-8 text-danger">${friendlyErrorMessage(e.message, "Could not load transactions.")}</div>`;
            }
        }

        const REFUND_STATUS_STYLE = {
            not_refunded: { label: "Not Refunded", cls: "text-textSec" },
            partially_refunded: { label: "Partially Refunded", cls: "text-warning" },
            fully_refunded: { label: "Fully Refunded", cls: "text-danger" },
        };

        function renderRefundTransactionRow(txn) {
            const st = REFUND_STATUS_STYLE[txn.status] || REFUND_STATUS_STYLE.not_refunded;
            const itemsLine = txn.items.map(i => escapeHtml(i.product_name) + (i.quantity > 1 ? ` ×${i.quantity}` : "")).join(", ");
            const canRefund = txn.status !== "fully_refunded";
            return `<div class="border border-borderCol rounded-xl p-3 bg-bgMain">
                <div class="flex items-center justify-between gap-2">
                    <span class="text-textSec">${formatBusinessDateTime(txn.timestamp)}</span>
                    <span class="font-semibold ${st.cls}">${st.label}</span>
                </div>
                <div class="text-textMain font-medium mt-1 truncate" title="${escapeHtml(itemsLine)}">${itemsLine}</div>
                <div class="flex items-center justify-between mt-2">
                    <div class="text-[11px] text-textSec">
                        Original: <span class="font-mono text-textMain">${formatCurrency(txn.original_total)}</span>
                        ${txn.refunded_total > 0 ? ` · Refunded: <span class="font-mono text-danger">${formatCurrency(txn.refunded_total)}</span> · Net: <span class="font-mono text-textMain">${formatCurrency(txn.net_total)}</span>` : ""}
                    </div>
                    ${canRefund
                        ? `<button type="button" onclick="openRefundModal('${txn.transaction_key}')" class="bg-danger/15 hover:bg-danger/25 text-danger border border-danger/30 px-2.5 py-1 rounded-lg text-[11px] font-semibold cursor-pointer shrink-0">Refund</button>`
                        : `<span class="text-[11px] text-textSec shrink-0">Fully Refunded</span>`}
                </div>
            </div>`;
        }

        // --- Refund modal: choose quantities per line, restock, reason ---------
        let refundModalData = null; // the transaction detail currently open for refund
        let refundLineQty = {}; // sale_id -> quantity to refund
        let refundLineRestock = {}; // sale_id -> boolean

        async function openRefundModal(transactionKey) {
            document.getElementById('refund-modal').classList.remove('hidden');
            document.getElementById('refund-modal-lines').innerHTML = `<div class="text-center py-6 text-textSec">Loading…</div>`;
            document.getElementById('refund-modal-subtitle').textContent = '';
            document.getElementById('refund-modal-total').textContent = '—';
            document.getElementById('refund-note-input').value = '';
            document.getElementById('refund-reason-select').selectedIndex = 0;
            refundSubmitClientRef = null;
            try {
                const res = await fetch(`${API_URL}/sales/transactions/${encodeURIComponent(transactionKey)}`, { headers: { "Authorization": `Bearer ${authToken}` } });
                const data = await res.json();
                if (!res.ok) throw new Error(showApiError(res, data, "Could not load this transaction."));
                refundModalData = data;
                refundLineQty = {}; refundLineRestock = {};
                data.items.forEach(i => { refundLineQty[i.sale_id] = 0; refundLineRestock[i.sale_id] = true; });
                document.getElementById('refund-modal-subtitle').textContent = `${formatBusinessDateTime(data.timestamp)} · Original ${formatCurrency(data.original_total)}`;
                renderRefundModalLines();
            } catch (e) {
                document.getElementById('refund-modal-lines').innerHTML = `<div class="text-center py-8 text-danger">${friendlyErrorMessage(e.message, "Could not load this transaction.")}</div>`;
            }
        }
        function closeRefundModal() {
            document.getElementById('refund-modal').classList.add('hidden');
            refundModalData = null; refundLineQty = {}; refundLineRestock = {};
        }

        function renderRefundModalLines() {
            const container = document.getElementById('refund-modal-lines');
            if (!refundModalData) return;
            container.innerHTML = refundModalData.items.map(item => {
                const qty = refundLineQty[item.sale_id] || 0;
                const disabled = item.available_quantity <= 0;
                const lineTotal = qty * item.unit_price;
                return `<div class="border border-borderCol rounded-xl p-3 ${disabled ? 'opacity-60' : ''}">
                    <div class="flex items-center justify-between gap-2">
                        <div class="min-w-0">
                            <div class="font-medium text-textMain truncate">${escapeHtml(item.product_name)}</div>
                            <div class="text-[10px] text-textSec mt-0.5">Sold: ${item.quantity} · Already refunded: ${item.refunded_quantity} · Available: ${item.available_quantity}</div>
                            ${item.unit_cost_known ? '' : `<div class="text-[10px] text-warning mt-0.5">Historical cost was not recorded; refund revenue is exact, but its COGS effect will remain unknown.</div>`}
                        </div>
                        <span class="font-mono text-textSec text-[11px] shrink-0">${formatCurrency(item.unit_price)} each</span>
                    </div>
                    ${disabled ? `<div class="mt-2 text-[11px] text-danger font-semibold">Fully Refunded</div>` : `
                    <div class="flex items-center justify-between mt-2">
                        <div class="flex items-center border border-borderCol rounded-xl bg-bgMain overflow-hidden shrink-0">
                            <button type="button" onclick="adjustRefundLineQty(${item.sale_id}, -1)" class="w-8 h-8 flex items-center justify-center text-textSec hover:bg-cardHover hover:text-textMain transition cursor-pointer" aria-label="Decrease refund quantity">−</button>
                            <span class="text-xs font-bold text-textMain px-2 min-w-[2rem] text-center">${qty}</span>
                            <button type="button" onclick="adjustRefundLineQty(${item.sale_id}, 1)" class="w-8 h-8 flex items-center justify-center text-textSec hover:bg-cardHover hover:text-textMain transition cursor-pointer" aria-label="Increase refund quantity">+</button>
                        </div>
                        <span class="font-mono text-danger font-semibold text-sm">${qty > 0 ? formatCurrency(lineTotal) : "—"}</span>
                    </div>
                    <label class="flex items-center gap-1.5 mt-2 text-[11px] text-textSec cursor-pointer">
                        <input type="checkbox" ${refundLineRestock[item.sale_id] ? "checked" : ""} onchange="refundLineRestock[${item.sale_id}] = this.checked" class="rounded border-borderCol">
                        Return item to inventory
                        ${!item.product_exists ? `<span class="text-warning">(product no longer exists — cannot be restocked)</span>` : ""}
                    </label>`}
                </div>`;
            }).join('');
            const grandTotal = refundModalData.items.reduce((sum, i) => sum + (refundLineQty[i.sale_id] || 0) * i.unit_price, 0);
            document.getElementById('refund-modal-total').textContent = formatCurrency(grandTotal);
        }

        function adjustRefundLineQty(saleId, delta) {
            const item = refundModalData.items.find(i => i.sale_id === saleId);
            if (!item) return;
            const next = (refundLineQty[saleId] || 0) + delta;
            if (next < 0) return;
            if (next > item.available_quantity) { showToast(`Only ${item.available_quantity} unit(s) available to refund for ${item.product_name}.`, "error"); return; }
            refundLineQty[saleId] = next;
            renderRefundModalLines();
        }

        let refundSubmitClientRef = null;
        async function submitRefund() {
            if (!refundModalData) return;
            const lines = Object.entries(refundLineQty)
                .filter(([, qty]) => qty > 0)
                .map(([saleId, qty]) => ({ sale_id: parseInt(saleId, 10), quantity: qty, restock: !!refundLineRestock[saleId] }));
            if (!lines.length) { showToast("Select at least one item and quantity to refund.", "error"); return; }

            // Double-submit protection (section 22): the button disables
            // immediately, and the SAME client_ref is reused if the user
            // somehow still fires a second request before the button
            // disables — the backend's own idempotency check/unique index
            // guarantees only one refund is ever recorded either way.
            const btn = document.getElementById('refund-confirm-btn');
            if (btn.disabled) return;
            btn.disabled = true;
            const originalLabel = btn.textContent;
            btn.textContent = 'Processing…';
            if (!refundSubmitClientRef) refundSubmitClientRef = `refund-${Date.now()}-${Math.random().toString(36).slice(2)}`;

            try {
                const reason = document.getElementById('refund-reason-select').value;
                const note = (document.getElementById('refund-note-input').value || '').trim() || null;
                const res = await fetch(`${API_URL}/sales/transactions/${encodeURIComponent(refundModalData.transaction_key)}/refund`, {
                    method: 'POST', headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ lines, reason, note, client_ref: refundSubmitClientRef }),
                });
                const data = await res.json();
                if (!res.ok) throw new Error(showApiError(res, data, "The refund could not be completed."));
                showToast(`Refund of ${formatCurrency(data.refund_total)} completed.`, "success");
                refundSubmitClientRef = null;
                closeRefundModal();

                // Live refresh (section 14) — patch inventory from the
                // authoritative response, then refresh every view that could
                // show stale figures, using the app's existing refresh
                // functions rather than a full page reload.
                (data.updated_products || []).forEach(u => {
                    const idx = globalProducts.findIndex(p => p.id === u.id);
                    if (idx !== -1) globalProducts[idx].quantity = u.quantity;
                });
                cacheProductsLocally(globalProducts);
                updateDashboardMetrics();
                refreshInventoryViewFromLocalState();
                loadBusinessDayControl();
                if (refundTransactionsDayId) await loadRefundTransactionsList();
                const salesModal = document.getElementById('daily-sales-modal');
                if (salesModal && !salesModal.classList.contains('hidden')) await loadDailySales();
                if (typeof loadSalesHistory === 'function') loadSalesHistory();
                if (typeof loadSalesHistoryPeriodTotal === 'function') loadSalesHistoryPeriodTotal();
                if (typeof loadProfitDashboardCards === 'function') loadProfitDashboardCards();
            } catch (e) {
                showToast(friendlyErrorMessage(e.message, "The refund could not be completed."), 'error');
            } finally {
                btn.disabled = false;
                btn.textContent = originalLabel;
            }
        }

        // Reopen actions belong to Sales History (per historical day), never
        // to Today's Sales or a hidden endpoint call — dayId is always the
        // specific Business Day row the user is looking at.
        async function requestBusinessDayReopen(dayId) {
            const reason = await showCustomPrompt("Why does this Business Day need to be reopened?", "Request Reopen Approval", "Reason");
            if (reason === null) return;
            if (!reason.trim()) { showToast("A reason is required.", "error"); return; }
            try {
                const r = await fetch(`${API_URL}/business-days/${dayId}/reopen-request`, { method: 'POST', headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` }, body: JSON.stringify({ reason: reason.trim() }) });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, "The reopening request could not be submitted."));
                showToast("Reopening request submitted for Admin approval.", "success");
                await loadSalesHistory();
                await loadBusinessDayControl();
            } catch (e) { showToast(friendlyErrorMessage(e.message, e.message), 'error'); }
        }

        async function directReopenBusinessDay(dayId) {
            const reason = await showCustomPrompt("Why are you reopening this Business Day directly?", "Reopen Business Day", "Reason");
            if (reason === null) return;
            if (!reason.trim()) { showToast("A reason is required.", "error"); return; }
            const ok = await showCustomConfirm("This will reopen the Business Day immediately and record your reason in its audit trail. Continue?", "Reopen Business Day", "Reopen", "Cancel");
            if (!ok) return;
            try {
                const r = await fetch(`${API_URL}/business-days/${dayId}/direct-reopen`, { method: 'POST', headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` }, body: JSON.stringify({ reason: reason.trim() }) });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, "The Business Day could not be reopened."));
                showToast("Business day reopened.", "success");
                await loadSalesHistory();
                await loadBusinessDayControl();
            } catch (e) { showToast(friendlyErrorMessage(e.message, e.message), 'error'); }
        }

        // Closes a SPECIFIC historical Business Day by id (today's or an
        // older reopened one) — distinct from /sales/end-business-day (which
        // only ever targets "today"), so a day reopened from Sales History
        // can be re-closed correctly even if the real calendar day has since
        // moved on. Same confirmation as the Dashboard header's Close action.
        async function closeHistoricalBusinessDay(dayId) {
            const ok = await showCustomConfirm(t("sales.endBusinessDayConfirmBody"), t("sales.endBusinessDayConfirmTitle"));
            if (!ok) return;
            try {
                const r = await fetch(`${API_URL}/business-days/${dayId}/close`, { method: 'POST', headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, t("sales.businessDayCloseFailed")));
                showToast(t("sales.businessDayClosedSuccess"), 'success');
                await loadSalesHistory();
                await loadBusinessDayControl();
                loadData();
            } catch (e) { showToast(friendlyErrorMessage(e.message, e.message), 'error'); }
        }

        // Fetches the pending reopen-request queue exactly once per render
        // pass. Admin gets every pending request on the business; a Manager
        // gets only their own (see the server-side scoping on this endpoint)
        // — either way, an empty/error result degrades to "no pending
        // requests" rather than throwing, since this is a secondary status
        // display, not the primary Business Day state.
        async function fetchPendingReopenRequests() {
            const role = getCurrentRole();
            if (!['admin', 'manager'].includes(role)) return [];
            try {
                const r = await fetch(`${API_URL}/business-days/reopen-requests`, { headers: { "Authorization": `Bearer ${authToken}` } });
                if (!r.ok) return [];
                return await r.json();
            } catch (_) { return []; }
        }

        async function resolveBusinessDayReopenRequestFromPanel(requestId, resolution) {
            let note = null;
            if (resolution === 'reject') {
                note = await showCustomPrompt("Optional note for this rejection", "Reject Reopening Request", "Note");
                if (note === null) note = "";
            }
            try {
                const r = await fetch(`${API_URL}/business-days/reopen-requests/${requestId}/${resolution}`, { method: 'POST', headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` }, body: JSON.stringify({ note: note || null }) });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, "That request could not be resolved."));
                showToast(resolution === 'approve' ? "Business day reopened." : "Reopening request rejected.", "success");
                await loadSalesHistory();
                await loadBusinessDayControl();
            } catch (e) { showToast(friendlyErrorMessage(e.message, e.message), 'error'); }
        }

        function hideBusinessDayActivity() {
            const panel = document.getElementById('business-day-activity-panel');
            panel.classList.add('hidden'); panel.innerHTML = '';
        }
        async function toggleBusinessDayActivity(dayId) {
            businessDayActivityOpen = !businessDayActivityOpen;
            const label = document.getElementById('business-day-activity-toggle-label');
            if (label) label.textContent = `${businessDayActivityOpen ? "Hide" : "View"} Activity`;
            if (businessDayActivityOpen) await loadBusinessDayActivity(dayId);
            else hideBusinessDayActivity();
        }
        async function loadBusinessDayActivity(dayId) {
            const panel = document.getElementById('business-day-activity-panel');
            if (getCurrentRole() === 'staff') { panel.classList.add('hidden'); panel.innerHTML = ''; return; }
            panel.classList.remove('hidden');
            panel.innerHTML = '<div class="text-textSec py-2 text-center"><i class="fa-solid fa-spinner fa-spin mr-1"></i> Loading activity…</div>';
            try {
                const r = await fetch(`${API_URL}/business-days/${dayId}/timeline`, { headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error('failed');
                if (!d.events.length) { panel.innerHTML = '<div class="text-textSec py-2 text-center">No activity recorded yet.</div>'; return; }
                const labels = {
                    BUSINESS_DAY_STARTED: ['fa-play', 'Started'], BUSINESS_DAY_CLOSED: ['fa-lock', 'Closed'],
                    BUSINESS_DAY_CLOSED_AGAIN: ['fa-lock', 'Closed again'], BUSINESS_DAY_REOPEN_REQUESTED: ['fa-rotate-left', 'Reopening requested'],
                    BUSINESS_DAY_REOPEN_APPROVED: ['fa-check', 'Reopening approved'], BUSINESS_DAY_REOPEN_REJECTED: ['fa-xmark', 'Reopening rejected'],
                    BUSINESS_DAY_REOPENED: ['fa-unlock', 'Reopened'],
                };
                panel.innerHTML = d.events.map(ev => {
                    const [icon, label] = labels[ev.action] || ['fa-circle-info', ev.action];
                    return `<div class="flex items-start gap-2 border-b border-borderCol/50 pb-1.5 last:border-0 last:pb-0">
                        <i class="fa-solid ${icon} text-primary mt-0.5"></i>
                        <div class="min-w-0 flex-1">
                            <div class="text-textMain font-medium">${label}${ev.actor_username ? ` · ${escapeHtml(ev.actor_username)}` : ''}</div>
                            <div class="text-textSec truncate">${escapeHtml(ev.description || '')}</div>
                        </div>
                        <div class="text-textSec shrink-0">${formatBusinessDateTime(ev.created_at)}</div>
                    </div>`;
                }).join('');
            } catch (_) { panel.innerHTML = '<div class="text-danger py-2 text-center">Activity could not be loaded.</div>'; }
        }

        async function renderSalesChart(){ try { const r=await fetch(`${API_URL}/sales/analytics`,{headers:{"Authorization":`Bearer ${authToken}`}}); const d=await r.json(); const rows=d.days.slice(-12); const max=Math.max(1,...rows.map(x=>x.sales)); const chart=document.getElementById('sales-chart'); if(!rows.length){chart.innerHTML='<div class="h-[170px] flex items-center justify-center text-textSec text-xs">Sales history will appear here after business days are closed.</div>';return;} chart.innerHTML=`<div class="flex items-end gap-2 h-[150px] px-2 border-b border-borderCol">${rows.map(x=>`<div class="flex-1 flex flex-col items-center justify-end h-full gap-1"><div class="w-full max-w-[42px] bg-primary/70 rounded-t" style="height:${Math.max(4,(x.sales/max)*100)}%" title="${x.date}: ${formatCurrency(x.sales)}"></div><span class="text-[8px] text-textSec rotate-[-35deg] origin-top">${x.date.slice(5)}</span></div>`).join('')}</div><div class="mt-3 flex items-center justify-between text-[10px]"><span class="font-semibold">Trend: ${d.trend}</span><span class="font-mono ${d.change_percent>=0?'text-success':'text-danger'}">${d.change_percent>=0?'+':''}${d.change_percent}%</span><span class="text-textSec">Avg ${formatCurrency(d.average_daily_sales)}</span></div>`; } catch(_){} }
        let salesHistoryActivePeriod = "all";
        let salesHistoryCustomFilters = { date_from: "", date_to: "" };

        function salesHistoryPeriodParams() {
            const params = new URLSearchParams();
            if (salesHistoryActivePeriod === "custom" && salesHistoryCustomFilters.date_from && salesHistoryCustomFilters.date_to) {
                params.set("period", "custom");
                params.set("custom_start", salesHistoryCustomFilters.date_from);
                params.set("custom_end", salesHistoryCustomFilters.date_to);
            } else {
                params.set("period", salesHistoryActivePeriod);
            }
            return params;
        }

        function setSalesHistoryPeriod(period) {
            salesHistoryActivePeriod = period;
            closeSalesHistoryCustomPanel();
            hideSalesHistoryCustomError();
            updateSalesHistoryPresetButtonsUI();
            loadSalesHistoryPeriodTotal();
            loadSalesHistory();
        }

        function updateSalesHistoryPresetButtonsUI() {
            document.querySelectorAll(".sales-period-preset-btn").forEach(btn => {
                const active = btn.dataset.preset === salesHistoryActivePeriod;
                const isCustom = btn.dataset.preset === "custom";
                btn.className = "sales-period-preset-btn text-[11px] px-2 py-1 rounded-lg border cursor-pointer "
                    + (isCustom ? "flex items-center gap-1 " : "")
                    + (active ? "border-primary bg-primary/15 text-primary" : "border-borderCol text-textSec hover:text-textMain");
            });
            const label = document.getElementById("sales-history-custom-btn-label");
            if (!label) return;
            if (salesHistoryActivePeriod === "custom" && salesHistoryCustomFilters.date_from && salesHistoryCustomFilters.date_to) {
                label.textContent = `${formatExpenseCustomDateShort(salesHistoryCustomFilters.date_from)} – ${formatExpenseCustomDateShort(salesHistoryCustomFilters.date_to)}`;
            } else {
                label.textContent = "Custom";
            }
        }

        // ---------------------------------------------------------------------
        // Shared viewport-aware positioning for every "Custom" date-range
        // popover (Sales History, Expenses, Profit). One reusable algorithm —
        // never a per-feature hard-coded direction — so the panel is always
        // fully on-screen regardless of where its trigger button happens to
        // sit. Prefers opening downward; falls back to upward if that would
        // clip; if neither side has room, opens on whichever side has more
        // space and lets the panel scroll internally instead of overflowing
        // the viewport.
        // ---------------------------------------------------------------------
        let activeDateDropdown = null; // { panel, button } for the single open Custom popover, if any

        function positionDateDropdown(buttonEl, dropdownEl) {
            if (!buttonEl || !dropdownEl) return;
            const MARGIN = 10, GAP = 4;
            // Clear any previous clamp so height is measured unconstrained.
            dropdownEl.style.maxHeight = "";
            dropdownEl.style.overflowY = "";
            const btnRect = buttonEl.getBoundingClientRect();
            const panelRect = dropdownEl.getBoundingClientRect();
            const viewportW = window.innerWidth;
            const viewportH = window.innerHeight;

            const spaceBelow = viewportH - btnRect.bottom - MARGIN;
            const spaceAbove = btnRect.top - MARGIN;
            const panelHeight = panelRect.height;

            let top;
            if (panelHeight <= spaceBelow) {
                top = btnRect.bottom + GAP;
            } else if (panelHeight <= spaceAbove) {
                top = btnRect.top - panelHeight - GAP;
            } else if (spaceBelow >= spaceAbove) {
                top = btnRect.bottom + GAP;
                dropdownEl.style.maxHeight = Math.max(120, spaceBelow) + "px";
                dropdownEl.style.overflowY = "auto";
            } else {
                dropdownEl.style.maxHeight = Math.max(120, spaceAbove - GAP) + "px";
                dropdownEl.style.overflowY = "auto";
                top = MARGIN;
            }

            let left = btnRect.left;
            const panelWidth = panelRect.width;
            if (left + panelWidth + MARGIN > viewportW) left = viewportW - panelWidth - MARGIN;
            if (left < MARGIN) left = MARGIN;

            dropdownEl.style.position = "fixed";
            dropdownEl.style.top = `${Math.round(top)}px`;
            dropdownEl.style.left = `${Math.round(left)}px`;
            dropdownEl.style.right = "auto";
            dropdownEl.style.margin = "0";
            dropdownEl.style.zIndex = "9999";
        }

        function showDateDropdown(panel, button) {
            panel.classList.remove("hidden");
            positionDateDropdown(button, panel);
            activeDateDropdown = { panel, button };
        }

        function hideDateDropdown(panel) {
            panel.classList.add("hidden");
            if (activeDateDropdown && activeDateDropdown.panel === panel) activeDateDropdown = null;
        }

        window.addEventListener("resize", function () {
            if (activeDateDropdown) positionDateDropdown(activeDateDropdown.button, activeDateDropdown.panel);
        });
        document.addEventListener("scroll", function () {
            if (activeDateDropdown) positionDateDropdown(activeDateDropdown.button, activeDateDropdown.panel);
        }, true);

        function toggleSalesHistoryCustomPanel() {
            const panel = document.getElementById("sales-history-custom-panel");
            const button = document.getElementById("sales-history-custom-btn");
            if (!panel) return;
            if (panel.classList.contains("hidden")) {
                hideSalesHistoryCustomError();
                showDateDropdown(panel, button);
                const fromInput = document.getElementById("sales-history-date-from");
                setTimeout(() => fromInput && fromInput.focus(), 0);
            } else {
                hideDateDropdown(panel);
            }
        }

        function closeSalesHistoryCustomPanel() {
            const panel = document.getElementById("sales-history-custom-panel");
            if (panel) hideDateDropdown(panel);
        }

        function handleSalesHistoryCustomRangeKeydown(event) {
            if (event.key === "Enter") {
                event.preventDefault();
                applySalesHistoryCustomRange();
            } else if (event.key === "Escape") {
                closeSalesHistoryCustomPanel();
            }
        }

        function showSalesHistoryCustomError(msg) {
            const el = document.getElementById("sales-history-custom-error");
            if (!el) return;
            el.textContent = msg;
            el.classList.remove("hidden");
        }

        function hideSalesHistoryCustomError() {
            document.getElementById("sales-history-custom-error")?.classList.add("hidden");
        }

        function applySalesHistoryCustomRange() {
            const fromVal = document.getElementById("sales-history-date-from").value;
            const toVal = document.getElementById("sales-history-date-to").value;

            if (!fromVal && !toVal) { showSalesHistoryCustomError("Select a start date and end date."); return; }
            if (!fromVal) { showSalesHistoryCustomError("Select a start date."); return; }
            if (!toVal) { showSalesHistoryCustomError("Select an end date."); return; }
            if (toVal < fromVal) { showSalesHistoryCustomError("End date cannot be earlier than start date."); return; }

            hideSalesHistoryCustomError();
            salesHistoryActivePeriod = "custom";
            salesHistoryCustomFilters.date_from = fromVal; // inclusive lower bound
            salesHistoryCustomFilters.date_to = toVal;     // inclusive upper bound
            updateSalesHistoryPresetButtonsUI();
            closeSalesHistoryCustomPanel();
            loadSalesHistoryPeriodTotal();
            loadSalesHistory();
        }

        async function loadSalesHistoryPeriodTotal() {
            const el = document.getElementById("sales-history-period-total");
            if (!el) return;
            try {
                const res = await fetch(`${API_URL}/financial-summary?${salesHistoryPeriodParams().toString()}`, { headers: { "Authorization": `Bearer ${authToken}` } });
                if (!res.ok) { el.textContent = ""; return; }
                const data = await res.json();
                el.textContent = `${formatCurrency(data.sales)} · ${data.transaction_count} sale${data.transaction_count === 1 ? "" : "s"} · ${data.units_sold} item${data.units_sold === 1 ? "" : "s"} sold`;
            } catch (e) { el.textContent = ""; }
        }

        async function loadSalesHistory(){
            const box=document.getElementById('sales-history-box');
            try{
                const r=await fetch(`${API_URL}/sales/history?${salesHistoryPeriodParams().toString()}`,{headers:{"Authorization":`Bearer ${authToken}`}});
                if(!r.ok){box.classList.add('hidden');return;}
                const rows=await r.json();
                box.classList.remove('hidden');
                if(!rows.length){box.innerHTML=`<div class="p-3 text-[10px] uppercase tracking-wider text-textSec border-b border-borderCol">Sales History</div><div class="text-center py-8 text-textSec text-xs">No sales found for this period.</div>`;return;}
                const role = getCurrentRole();
                // One fetch of the pending-request queue, cross-referenced by
                // business_day_id below — Admin sees every pending request on
                // the business, Manager only their own (server-scoped), Staff
                // gets none (this workflow doesn't involve them at all).
                const pendingRequests = await fetchPendingReopenRequests();
                box.innerHTML=`<div class="p-3 text-[10px] uppercase tracking-wider text-textSec border-b border-borderCol">Sales History</div>`
                    + rows.map(x => renderSalesHistoryRow(x, role, pendingRequests)).join('');
            }catch(_){}
        }

        // Per-SESSION Sales History row — one row per BusinessDay id, never
        // merged by date (a business can have multiple sessions on the same
        // calendar date; each gets its own row, distinguished by its own
        // opened time — see the BusinessDay model docstring in main.py).
        // Shows status + the one Business Day action (if any) this role is
        // authorized to reach for this specific session — Reopen Business
        // Day (Admin), Request Reopen Approval (Manager, only when they
        // don't already have one pending), Close Business Day (Admin/
        // Manager, only while this session is currently open/reopened), or
        // nothing at all (Staff — this workflow doesn't render for them,
        // not merely disable a control they can't use).
        function renderSalesHistoryRow(x, role, pendingRequests) {
            const isOpen = x.status === "OPEN" || x.status === "REOPENED";
            const dotClass = isOpen ? "bg-success" : "bg-textSec";
            const statusLabel = isOpen ? `Business Day Open${x.status === "REOPENED" ? " (Reopened)" : ""}` : "Business Day Closed";
            const pending = pendingRequests.find(req => req.business_day_id === x.business_day_id);

            let actionHtml = "";
            if (isOpen) {
                if (["admin", "manager"].includes(role)) {
                    actionHtml = bdActionBtn(`closeHistoricalBusinessDay(${x.business_day_id})`, "Close Business Day", "danger", "fa-lock");
                }
            } else if (role === "admin") {
                actionHtml = bdActionBtn(`directReopenBusinessDay(${x.business_day_id})`, "Reopen Business Day", "warn", "fa-unlock");
            } else if (role === "manager") {
                actionHtml = pending
                    ? `<span class="text-[11px] text-warning font-semibold"><i class="fa-solid fa-hourglass-half mr-1"></i>Awaiting Admin approval</span>`
                    : bdActionBtn(`requestBusinessDayReopen(${x.business_day_id})`, "Request Reopen Approval", "warn", "fa-rotate-left");
            }
            // Staff: actionHtml stays empty — no restricted control is rendered at all.

            let approvalHtml = "";
            if (role === "admin" && pending) {
                approvalHtml = `<div class="mt-2 flex items-center justify-between gap-2 flex-wrap bg-warning/10 border border-warning/30 rounded-lg p-2 text-[11px]">
                    <div class="min-w-0">
                        <div class="text-textMain font-medium truncate">${escapeHtml(pending.requested_by_name || "Unknown")} requests reopening</div>
                        <div class="text-textSec truncate">${escapeHtml(pending.reason)}</div>
                    </div>
                    <div class="flex items-center gap-1 shrink-0">
                        <button type="button" onclick="resolveBusinessDayReopenRequestFromPanel(${pending.id},'reject')" class="bg-danger/15 hover:bg-danger/25 text-danger border border-danger/30 px-2 py-1 rounded-lg font-semibold cursor-pointer">Reject</button>
                        <button type="button" onclick="resolveBusinessDayReopenRequestFromPanel(${pending.id},'approve')" class="bg-primary hover:bg-primaryHover text-white px-2 py-1 rounded-lg font-semibold cursor-pointer">Approve</button>
                    </div>
                </div>`;
            }

            // "View History" only appears once a day has actually been
            // reopened at least once — that's the only case where an
            // original-vs-corrected record exists to show (section 8).
            const historyToggle = (x.reopen_count > 0 && role !== "staff")
                ? `<button type="button" onclick="toggleSalesHistoryDayTimeline(${x.business_day_id})" class="text-[10px] text-textSec hover:text-primary underline decoration-dotted cursor-pointer">View History</button>`
                : "";
            // Entry point to individual completed transactions for this day
            // — the only place a refund can be started from (never the POS
            // cart itself). Available to every role, including Staff, since
            // Staff are explicitly authorized to create refunds and need a
            // way to find what they're refunding (see /sales/transactions).
            const transactionsToggle = `<button type="button" onclick="openRefundTransactionsModal(${x.business_day_id})" class="text-[10px] text-textSec hover:text-primary underline decoration-dotted cursor-pointer">Transactions</button>`;
            // Refunded-that-day indicator — only shown once there's actually
            // something to show (section 26/27), never invented for a day
            // with no refund activity.
            const refundLine = x.refund_total > 0
                ? `<div class="text-[10px] text-danger mt-0.5">Refunded ${formatCurrency(x.refund_total)}${x.refunded_units ? ` · ${x.refunded_units} unit${x.refunded_units === 1 ? "" : "s"}` : ""}</div>`
                : "";

            return `<div class="border-b border-borderCol/60 p-3 text-xs">
                <div class="flex items-center justify-between gap-2 flex-wrap">
                    <div class="min-w-0">
                        <div class="font-semibold flex items-center gap-1.5"><span class="inline-block w-1.5 h-1.5 rounded-full ${dotClass} shrink-0"></span>${escapeHtml(x.date)}${x.opened_at ? ` · ${formatBusinessTime(x.opened_at)}` : ""}</div>
                        <div class="text-[10px] text-textSec mt-0.5">${x.transactions} transaction${x.transactions === 1 ? "" : "s"} · ${x.items_sold} item${x.items_sold === 1 ? "" : "s"} sold</div>
                        <div class="text-[10px] text-textSec">${statusLabel}</div>
                        ${refundLine}
                    </div>
                    <div class="font-mono font-semibold text-success shrink-0">${formatCurrency(x.net_sales)}</div>
                </div>
                <div class="flex items-center justify-between gap-2 flex-wrap mt-2">
                    <div class="flex items-center gap-2 flex-wrap">${actionHtml}</div>
                    <div class="flex items-center gap-3">${historyToggle}${transactionsToggle}</div>
                </div>
                ${approvalHtml}
                <div id="sales-history-timeline-${x.business_day_id}" class="hidden mt-2 border border-borderCol rounded-lg bg-bgMain p-2 text-[11px] space-y-1"></div>
            </div>`;
        }

        // Expands/collapses the ORIGINAL vs CORRECTED/FINAL record for a
        // reopened historical day (section 8) — built entirely from the
        // existing immutable audit timeline, never a second/duplicated
        // record store, so the original closing snapshot can never be lost
        // or silently overwritten.
        let salesHistoryOpenTimelines = new Set();
        async function toggleSalesHistoryDayTimeline(dayId) {
            const panel = document.getElementById(`sales-history-timeline-${dayId}`);
            if (!panel) return;
            if (salesHistoryOpenTimelines.has(dayId)) {
                salesHistoryOpenTimelines.delete(dayId);
                panel.classList.add('hidden'); panel.innerHTML = '';
                return;
            }
            salesHistoryOpenTimelines.add(dayId);
            panel.classList.remove('hidden');
            panel.innerHTML = '<div class="text-textSec py-1 text-center"><i class="fa-solid fa-spinner fa-spin mr-1"></i> Loading history…</div>';
            try {
                const r = await fetch(`${API_URL}/business-days/${dayId}/timeline`, { headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error('failed');
                panel.innerHTML = renderBusinessDayOriginalVsCorrected(d.events || []);
            } catch (_) { panel.innerHTML = '<div class="text-danger py-1 text-center">History could not be loaded.</div>'; }
        }

        // Renders the ORIGINAL RECORD → REOPENED/CORRECTION → CORRECTED/FINAL
        // RECORD sequence from the ordered audit events. Never assumes
        // exactly one reopen cycle — if a day was reopened more than once,
        // every intermediate event is still shown, and only the very first
        // close and the very last close are labeled ORIGINAL / CORRECTED.
        function renderBusinessDayOriginalVsCorrected(events) {
            const closeEvents = events.filter(e => e.action === 'BUSINESS_DAY_CLOSED' || e.action === 'BUSINESS_DAY_CLOSED_AGAIN');
            if (!closeEvents.length) return '<div class="text-textSec py-1 text-center">No closing history recorded yet.</div>';
            const original = closeEvents[0];
            const finalClose = closeEvents[closeEvents.length - 1];
            const originalIdx = events.indexOf(original), finalIdx = events.indexOf(finalClose);
            const middleEvents = events.filter((e, i) => i > originalIdx && i < finalIdx && e.action !== 'BUSINESS_DAY_CLOSED' && e.action !== 'BUSINESS_DAY_CLOSED_AGAIN');
            const fmtSnap = (meta) => meta ? `${formatCurrency(meta.sales_total || 0)} · ${meta.transactions || 0} transaction${(meta.transactions || 0) === 1 ? "" : "s"}` : "—";
            const eventLabels = {
                BUSINESS_DAY_REOPEN_REQUESTED: 'Reopen requested', BUSINESS_DAY_REOPEN_APPROVED: 'Reopen approved',
                BUSINESS_DAY_REOPEN_REJECTED: 'Reopen rejected', BUSINESS_DAY_REOPENED: 'Reopened',
            };
            let html = `<div class="text-[9px] uppercase tracking-wider text-textSec font-semibold">Original Record</div>
                <div class="text-textMain font-semibold">${fmtSnap(original.metadata)}</div>
                <div class="text-textSec">Closed ${formatBusinessDateTime(original.created_at)}${original.actor_username ? " by " + escapeHtml(original.actor_username) : ""}</div>`;
            if (closeEvents.length > 1) {
                html += `<div class="text-center text-textSec/60"><i class="fa-solid fa-arrow-down text-[9px]"></i></div>`;
                middleEvents.forEach(ev => {
                    html += `<div class="text-[9px] uppercase tracking-wider text-warning font-semibold mt-1">${eventLabels[ev.action] || ev.action}</div>
                        <div class="text-textMain">${escapeHtml(ev.description || "")}</div>
                        <div class="text-textSec">${formatBusinessDateTime(ev.created_at)}</div>`;
                });
                html += `<div class="text-center text-textSec/60"><i class="fa-solid fa-arrow-down text-[9px]"></i></div>
                    <div class="text-[9px] uppercase tracking-wider text-textSec font-semibold mt-1">Corrected / Final Record</div>
                    <div class="text-textMain font-semibold">${fmtSnap(finalClose.metadata)}</div>
                    <div class="text-textSec">Closed again ${formatBusinessDateTime(finalClose.created_at)}${finalClose.actor_username ? " by " + escapeHtml(finalClose.actor_username) : ""}</div>`;
            }
            return html;
        }

        // Backend-assisted, line-item export (one row per Sale, not per
        // Business Day) — /sales/history only returns day-level aggregates,
        // so a real transaction-level CSV needs the dedicated /sales/export
        // endpoint. Respects the same period/custom-range selection as the
        // Sales History list above (salesHistoryPeriodParams()).
        function exportSalesCsv(button) {
            runBackendCsvExport(button, `${API_URL}/sales/export?${salesHistoryPeriodParams().toString()}`, `cauldra_sales_${csvDateStamp()}.csv`, "No sales available to export for this period.");
        }
        function exportSalesExcel(button) {
            runBackendCsvExport(button, `${API_URL}/sales/export/xlsx?${salesHistoryPeriodParams().toString()}`, `cauldra_sales_${csvDateStamp()}.xlsx`, "No sales available to export for this period.");
        }

        document.addEventListener("click", function (event) {
            const salesWrap = document.getElementById("sales-history-custom-combobox");
            if (salesWrap && !salesWrap.contains(event.target)) closeSalesHistoryCustomPanel();
            const profitWrap = document.getElementById("profit-custom-combobox");
            if (profitWrap && !profitWrap.contains(event.target)) closeProfitCustomPanel();
        });

        async function openTeamPresenceModal(){ if(!authToken)return; document.getElementById('team-presence-modal').classList.remove('hidden'); await loadTeamPresence(); }
        function closeTeamPresenceModal(){document.getElementById('team-presence-modal').classList.add('hidden');}
        // Team Presence shows the full employee roster (same underlying directory
        // as Employees) with each person's current/last known presence state
        // merged in. Core profile fields never disappear when someone goes
        // offline — only the presence portion re-renders.
        // Cached by loadTeamPresence() so exportTeamPresenceCsv() can export
        // exactly what's on screen without a second fetch.
        let lastTeamPresence = [];

        async function loadTeamPresence(){
            const c=document.getElementById('team-presence-container');
            c.innerHTML = `<div class="py-8 text-center text-xs text-textSec"><i class="fa-solid fa-spinner fa-spin mr-1.5"></i> Loading team presence…</div>`;
            lastTeamPresence = [];
            try{
                const r=await fetch(`${API_URL}/presence/team`,{headers:{"Authorization":`Bearer ${authToken}`}});
                const d=await r.json().catch(()=>({}));
                if(!r.ok){ c.innerHTML=`<div class="p-4 rounded-xl bg-bgMain border border-borderCol text-center"><div class="font-semibold text-textMain text-xs">Team presence is temporarily unavailable</div><div class="text-[10px] text-textSec mt-1">Please try again in a moment.</div></div>`; return; }
                const employees=Array.isArray(d.employees)?d.employees:[];
                lastTeamPresence = employees;
                if (!employees.length) { c.innerHTML = `<div class="py-8 text-center text-xs text-textSec">No other team members are registered yet.</div>`; return; }
                c.innerHTML = employees.map(x => {
                    const name = `${x.firstname||''} ${x.lastname||''}`.trim() || x.username;
                    const roleLabel = ({admin:t("team.admin"),manager:t("team.manager"),staff:t("team.staff")})[x.role] || x.role;
                    let presenceHtml;
                    if (x.online) {
                        presenceHtml = `<div class="text-success text-[10px] font-semibold">● Online</div><div class="text-[10px] text-textSec">Online since ${formatBusinessDateTime(x.online_since)}</div>`;
                    } else if (x.signed_out_at) {
                        // Session ended via an explicit sign-out.
                        presenceHtml = `<div class="text-textSec text-[10px] font-semibold">○ Offline</div><div class="text-[10px] text-textSec">Signed out ${formatBusinessDateTime(x.signed_out_at)}</div>`;
                    } else if (x.last_seen_at) {
                        // Session simply went stale (timed out / tab closed) — no explicit sign-out was recorded.
                        presenceHtml = `<div class="text-textSec text-[10px] font-semibold">○ Offline</div><div class="text-[10px] text-textSec">Last seen ${formatBusinessDateTime(x.last_seen_at)}</div>`;
                    } else {
                        presenceHtml = `<div class="text-textSec text-[10px] font-semibold">○ Offline</div><div class="text-[10px] text-textSec">No presence recorded yet</div>`;
                    }
                    return `<div class="p-3 rounded-xl bg-bgMain border border-borderCol flex items-center justify-between gap-3">
                        <div class="min-w-0">
                            <div class="font-semibold text-xs text-textMain">${escapeHtml(name)}</div>
                            <div class="text-[10px] text-textSec">${escapeHtml(roleLabel)}${x.position ? ' · ' + escapeHtml(x.position) : ''}</div>
                            ${x.email ? `<div class="text-[10px] text-textSec mt-0.5 truncate">${escapeHtml(x.email)}</div>` : ''}
                            <div class="text-[9px] text-textSec/70 mt-0.5">ID #${x.id}</div>
                        </div>
                        <div class="text-right shrink-0">${presenceHtml}</div>
                    </div>`;
                }).join('');
            }catch(_){ c.innerHTML='<div class="p-4 rounded-xl bg-bgMain border border-borderCol text-center"><div class="font-semibold text-textMain text-xs">Team presence is temporarily unavailable</div><div class="text-[10px] text-textSec mt-1">Please try again in a moment.</div></div>'; }
        }

        function buildTeamPresenceExportSpec() {
            if (!lastTeamPresence.length) return null;
            const rows = lastTeamPresence.map(x => ({
                name: `${x.firstname || ""} ${x.lastname || ""}`.trim() || x.username,
                role: x.role, position: x.position || "",
                status: x.online ? "Online" : "Offline",
                online_since: x.online_since || null, last_seen_at: x.last_seen_at || null, signed_out_at: x.signed_out_at || null,
            }));
            return {
                filenameBase: `cauldra_team_presence_${csvDateStamp()}`,
                reportTitle: "Cauldra Team Presence Report",
                metadata: [["Generated", new Date().toLocaleString()]],
                sheets: [{
                    name: "Team Presence",
                    columns: [
                        { key: "name", label: "Employee", type: "text" },
                        { key: "role", label: "Role", type: "text" },
                        { key: "position", label: "Position", type: "text" },
                        { key: "status", label: "Status", type: "text" },
                        { key: "online_since", label: "Online Since", type: "datetime" },
                        { key: "last_seen_at", label: "Last Seen", type: "datetime" },
                        { key: "signed_out_at", label: "Signed Out At", type: "datetime" },
                    ],
                    rows,
                }],
            };
        }
        function exportTeamPresenceCsv() { runCsvExport(buildTeamPresenceExportSpec, "No team presence data available to export."); }
        function exportTeamPresenceExcel(button) { runExcelExport(button, buildTeamPresenceExportSpec, "No team presence data available to export."); }

        function openPOModal() { 
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("po-modal").classList.remove("hidden"); 
            loadPurchaseOrders(); 
        }
        function closePOModal() { document.getElementById("po-modal").classList.add("hidden"); }
        
        function openSupplierModal() { 
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("supplier-modal").classList.remove("hidden"); 
            loadSuppliers(); 
        }
        function closeSupplierModal() { document.getElementById("supplier-modal").classList.add("hidden"); }
        
        function openWarehouseModal() { 
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("warehouse-modal").classList.remove("hidden"); 
            renderWarehouseModalData(); 
        }
        function closeWarehouseModal() { document.getElementById("warehouse-modal").classList.add("hidden"); }

        // =====================================================================
        // EXPENSES
        // =====================================================================
        let expenseCategoriesCache = null;
        let expenseSelectedCategory = null;
        let expenseHistoryFilters = { search: "", category: "", user_id: "", date_from: "", date_to: "" };
        let expenseHistoryActivePreset = "all";
        let expenseHistoryPage = 0;
        const EXPENSE_HISTORY_PAGE_SIZE = 20;

        function openExpensesModal() {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("expenses-modal").classList.remove("hidden");
            switchExpensesTab("record");
            showExpenseCategoryPicker();
        }
        function closeExpensesModal() { document.getElementById("expenses-modal").classList.add("hidden"); }

        function switchExpensesTab(tab) {
            const recordBtn = document.getElementById("expenses-tab-record-btn");
            const historyBtn = document.getElementById("expenses-tab-history-btn");
            const activeCls = "px-2.5 py-1.5 rounded-lg text-[11px] font-semibold cursor-pointer bg-primary/15 text-primary border border-primary/30";
            const inactiveCls = "px-2.5 py-1.5 rounded-lg text-[11px] font-semibold cursor-pointer text-textSec hover:text-textMain border border-transparent";
            recordBtn.className = tab === "record" ? activeCls : inactiveCls;
            historyBtn.className = tab === "history" ? activeCls : inactiveCls;
            document.getElementById("expenses-view-history").classList.toggle("hidden", tab !== "history");
            if (tab === "record") {
                showExpenseCategoryPicker();
            } else {
                document.getElementById("expenses-view-category-picker").classList.add("hidden");
                document.getElementById("expenses-view-entry").classList.add("hidden");
                populateExpenseHistoryCategoryFilter();
                setExpenseHistoryDateRange("all");
            }
        }

        async function ensureExpenseCategoriesLoaded() {
            if (expenseCategoriesCache) return expenseCategoriesCache;
            try {
                const r = await fetch(`${API_URL}/expenses/categories`, { headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                expenseCategoriesCache = r.ok ? (d.categories || []) : [];
            } catch (_) { expenseCategoriesCache = []; }
            return expenseCategoriesCache;
        }

        async function showExpenseCategoryPicker() {
            document.getElementById("expenses-view-entry").classList.add("hidden");
            document.getElementById("expenses-view-history").classList.add("hidden");
            document.getElementById("expenses-view-category-picker").classList.remove("hidden");
            document.getElementById("expense-category-search").value = "";
            await ensureExpenseCategoriesLoaded();
            renderExpenseCategoryList();
        }

        function renderExpenseCategoryList() {
            const query = document.getElementById("expense-category-search").value.trim().toLowerCase();
            const list = (expenseCategoriesCache || []).filter(c => c.toLowerCase().includes(query));
            const container = document.getElementById("expense-category-list");
            const rowCls = "text-left w-full px-3 py-2 rounded-lg hover:bg-cardHover text-textMain transition cursor-pointer";
            let html = list.map(c => `<button type="button" class="${rowCls}" onclick="selectExpenseCategory('${escapeHtml(c).replace(/'/g, "\\'")}')">${escapeHtml(c)}</button>`).join("");
            const customLabel = query ? `Use "${escapeHtml(document.getElementById("expense-category-search").value.trim())}" as a custom category` : "Enter a custom category";
            html += `<button type="button" class="${rowCls} border-t border-borderCol mt-1 pt-2 text-primary font-semibold" onclick="selectExpenseCategory(${query ? `'${escapeHtml(document.getElementById("expense-category-search").value.trim()).replace(/'/g, "\\'")}'` : "null"})"><i class="fa-solid fa-plus mr-1.5"></i>${customLabel}</button>`;
            if (!list.length && !query) container.innerHTML = `<div class="text-center py-4 text-textSec">Loading categories...</div>` + html;
            else container.innerHTML = html;
        }

        function selectExpenseCategory(name) {
            if (name === null) {
                const typed = document.getElementById("expense-category-search").value.trim();
                if (!typed) { showToast(t("expenses.typeCategoryFirst"), "info"); return; }
                name = typed;
            }
            expenseSelectedCategory = name;
            document.getElementById("expense-entry-category-label").textContent = name;
            document.getElementById("expense-entry-amount").value = "";
            document.getElementById("expense-entry-source").value = "";
            document.getElementById("expense-entry-note").value = "";
            document.getElementById("expenses-view-category-picker").classList.add("hidden");
            document.getElementById("expenses-view-entry").classList.remove("hidden");
            setTimeout(() => document.getElementById("expense-entry-amount").focus(), 50);
        }

        async function handleRecordExpense(event) {
            event.preventDefault();
            if (!expenseSelectedCategory) { showToast(t("expenses.chooseCategoryFirst"), "error"); return; }
            const amount = parseFloat(document.getElementById("expense-entry-amount").value);
            if (!amount || amount <= 0) { showToast(t("expenses.enterAmountGreaterThanZero"), "error"); return; }
            const btn = document.getElementById("expense-entry-save-btn");
            const payload = {
                category: expenseSelectedCategory,
                amount: amount,
                payment_source: document.getElementById("expense-entry-source").value.trim() || null,
                note: document.getElementById("expense-entry-note").value.trim() || null,
            };
            const mutationRef = generateOpId();
            const requestPayload = { ...payload, client_ref: mutationRef };
            btn.disabled = true; const originalText = btn.textContent; btn.textContent = "Saving...";
            try {
                const res = await fetch(`${API_URL}/expenses/`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify(requestPayload),
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("expenses.recordFailed")));
                showToast(t("expenses.recorded"), "success");
                expenseSelectedCategory = null;
                switchExpensesTab("history");
                // An expense immediately changes Net Profit, and (since
                // expenses now auto-open/attach to a Business Day) the
                // current Business Day's totals too — so both must be
                // re-fetched here rather than left stale until a reload.
                if (typeof loadProfitDashboardCards === 'function') loadProfitDashboardCards();
                if (typeof loadBusinessDayControl === 'function') loadBusinessDayControl();
                const dailySalesModal = document.getElementById('daily-sales-modal');
                if (dailySalesModal && !dailySalesModal.classList.contains('hidden') && typeof loadDailySales === 'function') await loadDailySales();
            } catch (e) {
                if (isNetworkFailure(e)) { await handleRecordExpenseOffline(payload, mutationRef); return; }
                showToast(friendlyErrorMessage(e.message, t("expenses.recordFailed")), "error");
            } finally {
                btn.disabled = false; btn.textContent = originalText;
            }
        }

        // Offline fallback for handleRecordExpense. The backend's /expenses/
        // POST already supports client_ref-based idempotent create (see
        // main.py) — this just needs to generate one and queue the request.
        async function handleRecordExpenseOffline(payload, opId) {
            await addOutboxOp({
                op_id: opId, business_id: currentOfflineScope(), user_id: currentUserProfile?.id || null,
                type: "expense_create", endpoint: "/expenses/", method: "POST",
                payload: { ...payload, client_ref: opId }, meta: {},
                label: `Expense: ${payload.category} (${formatCurrency(payload.amount)})`,
                status: "pending", attempts: 0, next_retry_at: 0, created_at: Date.now(), last_error: null,
            });
            showToast("You're offline — expense saved locally and will sync automatically when you're back online.", "info");
            expenseSelectedCategory = null;
            switchExpensesTab("history");
        }

        function populateExpenseHistoryCategoryFilter() {
            const select = document.getElementById("expense-history-category-filter");
            if (select.dataset.populated) return;
            ensureExpenseCategoriesLoaded().then(cats => {
                select.innerHTML = `<option value="">All categories</option>` + cats.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join("");
                select.dataset.populated = "1";
            });
        }

        async function loadExpenseHistoryFinancialTotal() {
            // Same shared calculation endpoint the Dashboard and Profit page
            // use — this view never computes its own total independently.
            const totalEl = document.getElementById("expense-history-total");
            const preset = expenseHistoryActivePreset;
            const params = new URLSearchParams();
            if (preset === "custom" && expenseHistoryFilters.date_from && expenseHistoryFilters.date_to) {
                params.set("period", "custom");
                params.set("custom_start", expenseHistoryFilters.date_from);
                params.set("custom_end", expenseHistoryFilters.date_to);
            } else if (["today", "yesterday", "week", "month", "all"].includes(preset)) {
                params.set("period", preset);
            } else {
                return; // custom range not yet fully specified — leave the count-only label as is
            }
            try {
                const res = await fetch(`${API_URL}/financial-summary?${params.toString()}`, { headers: { "Authorization": `Bearer ${authToken}` } });
                if (!res.ok) return; // non-fatal — the count label already set above still shows
                const data = await res.json();
                if (totalEl) totalEl.textContent = `${formatCurrency(data.expenses)} · ${totalEl.textContent}`;
            } catch (e) { /* non-fatal — count label remains visible */ }
        }

        // Business-local calendar date helpers. "Today" for a business must
        // be based on the BUSINESS's configured timezone, not the browser's
        // local clock and not toISOString() (which is always UTC) — a
        // device near midnight in a timezone that differs from the
        // business's own would otherwise report the wrong calendar day.
        // This is the frontend counterpart to resolve_financial_period()
        // on the backend, kept in the app's existing Monday-start week
        // convention (see resolve_financial_period()'s "week" branch).
        function getBusinessLocalDateParts(date = new Date()) {
            try {
                const parts = new Intl.DateTimeFormat("en-CA", { timeZone: getBusinessTimezone(), year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date);
                const get = t => parseInt(parts.find(p => p.type === t).value, 10);
                return { year: get("year"), month: get("month"), day: get("day") };
            } catch (_) {
                return { year: date.getUTCFullYear(), month: date.getUTCMonth() + 1, day: date.getUTCDate() };
            }
        }
        function formatDateParts(p) {
            return `${p.year}-${String(p.month).padStart(2, "0")}-${String(p.day).padStart(2, "0")}`;
        }
        function shiftDateParts(p, deltaDays) {
            // Pure calendar-day arithmetic on already-extracted Y/M/D
            // components (not an instant), so anchoring it to UTC here is
            // just a safe, DST-proof scratch calculator — it does not
            // reintroduce a timezone conversion.
            const d = new Date(Date.UTC(p.year, p.month - 1, p.day) + deltaDays * 86400000);
            return { year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate() };
        }
        function businessWeekdayMondayFirst(p) {
            // JS getUTCDay(): Sun=0..Sat=6. Convert to days-since-Monday
            // (Mon=0..Sun=6) to match resolve_financial_period()'s week
            // convention (Python weekday(): Mon=0..Sun=6).
            const sunFirst = new Date(Date.UTC(p.year, p.month - 1, p.day)).getUTCDay();
            return (sunFirst + 6) % 7;
        }

        function setExpenseHistoryDateRange(preset) {
            expenseHistoryActivePreset = preset;
            closeExpenseHistoryCustomPanel();
            hideExpenseHistoryCustomError();

            const todayParts = getBusinessLocalDateParts();
            const fmtToday = formatDateParts(todayParts);
            let from = "", to = "";
            if (preset === "today") { from = fmtToday; to = fmtToday; }
            else if (preset === "yesterday") { const y = formatDateParts(shiftDateParts(todayParts, -1)); from = y; to = y; }
            else if (preset === "week") { from = formatDateParts(shiftDateParts(todayParts, -businessWeekdayMondayFirst(todayParts))); to = fmtToday; }
            else if (preset === "month") { from = formatDateParts({ ...todayParts, day: 1 }); to = fmtToday; }
            // "all" leaves from/to empty (no lower/upper bound)
            expenseHistoryFilters.date_from = from;
            expenseHistoryFilters.date_to = to;
            updateExpenseDatePresetButtonsUI();
            loadExpenseHistory(true);
        }

        function updateExpenseDatePresetButtonsUI() {
            document.querySelectorAll(".expense-date-preset-btn").forEach(btn => {
                const active = btn.dataset.preset === expenseHistoryActivePreset;
                const isCustom = btn.dataset.preset === "custom";
                btn.className = "expense-date-preset-btn px-2 py-1 rounded-lg border cursor-pointer "
                    + (isCustom ? "flex items-center gap-1 " : "")
                    + (active ? "border-primary bg-primary/15 text-primary" : "border-borderCol text-textSec hover:text-textMain");
            });
            const label = document.getElementById("expense-history-custom-btn-label");
            if (!label) return;
            if (expenseHistoryActivePreset === "custom" && expenseHistoryFilters.date_from && expenseHistoryFilters.date_to) {
                label.textContent = `${formatExpenseCustomDateShort(expenseHistoryFilters.date_from)} \u2013 ${formatExpenseCustomDateShort(expenseHistoryFilters.date_to)}`;
            } else {
                label.textContent = "Custom";
            }
        }

        function formatExpenseCustomDateShort(iso) {
            if (!iso) return "";
            const parts = iso.split("-").map(Number);
            if (parts.length !== 3 || parts.some(n => !n && n !== 0)) return iso;
            const [y, m, d] = parts;
            return new Date(y, m - 1, d).toLocaleDateString(getBusinessLocale(), { month: "short", day: "numeric" });
        }

        function toggleExpenseHistoryCustomPanel() {
            const panel = document.getElementById("expense-history-custom-panel");
            const button = document.getElementById("expense-history-custom-btn");
            if (!panel) return;
            if (panel.classList.contains("hidden")) {
                hideExpenseHistoryCustomError();
                showDateDropdown(panel, button);
                const fromInput = document.getElementById("expense-history-date-from");
                setTimeout(() => fromInput && fromInput.focus(), 0);
            } else {
                hideDateDropdown(panel);
            }
        }

        function closeExpenseHistoryCustomPanel() {
            const panel = document.getElementById("expense-history-custom-panel");
            if (panel) hideDateDropdown(panel);
        }

        function handleExpenseCustomRangeKeydown(event) {
            if (event.key === "Enter") {
                event.preventDefault();
                applyExpenseHistoryCustomRange();
            } else if (event.key === "Escape") {
                closeExpenseHistoryCustomPanel();
            }
        }

        function showExpenseHistoryCustomError(msg) {
            const el = document.getElementById("expense-history-custom-error");
            if (!el) return;
            el.textContent = msg;
            el.classList.remove("hidden");
        }

        function hideExpenseHistoryCustomError() {
            document.getElementById("expense-history-custom-error")?.classList.add("hidden");
        }

        function applyExpenseHistoryCustomRange() {
            const fromInput = document.getElementById("expense-history-date-from");
            const toInput = document.getElementById("expense-history-date-to");
            const fromVal = fromInput.value;
            const toVal = toInput.value;

            // Graceful handling of missing dates: don't apply, just prompt.
            if (!fromVal && !toVal) { showExpenseHistoryCustomError("Select a start date and end date."); return; }
            if (!fromVal) { showExpenseHistoryCustomError("Select a start date."); return; }
            if (!toVal) { showExpenseHistoryCustomError("Select an end date."); return; }
            // Native date inputs only ever hold a valid yyyy-mm-dd value or "",
            // so a non-empty value here is guaranteed to be a real, valid date.
            if (toVal < fromVal) { showExpenseHistoryCustomError("End date cannot be earlier than start date."); return; }

            hideExpenseHistoryCustomError();
            expenseHistoryActivePreset = "custom";
            expenseHistoryFilters.date_from = fromVal; // inclusive lower bound
            expenseHistoryFilters.date_to = toVal;     // inclusive upper bound
            updateExpenseDatePresetButtonsUI();
            closeExpenseHistoryCustomPanel();
            loadExpenseHistory(true);
        }

        document.addEventListener("click", function (event) {
            const wrap = document.getElementById("expense-history-custom-combobox");
            if (wrap && !wrap.contains(event.target)) closeExpenseHistoryCustomPanel();
        });

        document.addEventListener("keydown", function (event) {
            if (event.key === "Escape") { closeExpenseHistoryCustomPanel(); closeSalesHistoryCustomPanel(); closeProfitCustomPanel(); }
        });

        function changeExpenseHistoryPage(delta) {
            expenseHistoryPage = Math.max(0, expenseHistoryPage + delta);
            loadExpenseHistory(false);
        }

        async function loadExpenseHistory(resetPage) {
            if (resetPage) expenseHistoryPage = 0;
            expenseHistoryFilters.search = document.getElementById("expense-history-search").value.trim();
            expenseHistoryFilters.category = document.getElementById("expense-history-category-filter").value;
            expenseHistoryFilters.user_id = document.getElementById("expense-history-user-filter").value;

            const params = new URLSearchParams({ limit: EXPENSE_HISTORY_PAGE_SIZE, offset: expenseHistoryPage * EXPENSE_HISTORY_PAGE_SIZE });
            if (expenseHistoryFilters.search) params.set("search", expenseHistoryFilters.search);
            if (expenseHistoryFilters.category) params.set("category", expenseHistoryFilters.category);
            if (expenseHistoryFilters.user_id) params.set("user_id", expenseHistoryFilters.user_id);
            if (expenseHistoryFilters.date_from) params.set("date_from", expenseHistoryFilters.date_from);
            if (expenseHistoryFilters.date_to) params.set("date_to", expenseHistoryFilters.date_to);

            const listEl = document.getElementById("expense-history-list");
            try {
                const r = await fetch(`${API_URL}/expenses/?${params.toString()}`, { headers: { "Authorization": `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, "Unable to load expense history."));

                document.getElementById("expense-history-total").textContent = `${d.total} expense${d.total === 1 ? "" : "s"} found`;
                loadExpenseHistoryFinancialTotal();
                if (!d.expenses.length) {
                    listEl.innerHTML = `<div class="text-center py-8 text-textSec">No expenses found for this filter.</div>`;
                } else {
                    listEl.innerHTML = d.expenses.map(e => `
                        <div class="py-2.5 flex items-center justify-between">
                            <div>
                                <div class="font-semibold text-textMain">${escapeHtml(e.category)}</div>
                                <div class="text-[10px] text-textSec">${e.payment_source ? escapeHtml(e.payment_source) + " · " : ""}Recorded by ${escapeHtml(e.recorded_by)}</div>
                                <div class="text-[10px] text-textSec">${formatBusinessDateTime(e.created_at)}</div>
                                ${e.note ? `<div class="text-[10px] text-textSec italic mt-0.5">${escapeHtml(e.note)}</div>` : ""}
                            </div>
                            <div class="font-mono font-bold text-danger shrink-0 ml-3">${formatCurrency(e.amount)}</div>
                        </div>`).join("");
                    // "User filtering where appropriate": populate from whoever
                    // actually appears in results, since there's no dedicated
                    // staff-accessible user-list endpoint this modal can call.
                    const userSelect = document.getElementById("expense-history-user-filter");
                    if (!userSelect.dataset.populated) {
                        const seen = new Map();
                        d.expenses.forEach(e => { if (e.owner_id) seen.set(e.owner_id, e.recorded_by); });
                        if (seen.size) {
                            userSelect.innerHTML = `<option value="">All users</option>` + [...seen.entries()].map(([id, name]) => `<option value="${id}">${escapeHtml(name)}</option>`).join("");
                            userSelect.dataset.populated = "1";
                        }
                    }
                }
                document.getElementById("expense-history-page-label").textContent = `Page ${expenseHistoryPage + 1}`;
                document.getElementById("expense-history-prev-btn").disabled = expenseHistoryPage === 0;
                document.getElementById("expense-history-next-btn").disabled = (expenseHistoryPage + 1) * EXPENSE_HISTORY_PAGE_SIZE >= d.total;
            } catch (e) {
                listEl.innerHTML = `<div class="text-center py-8 text-danger">${friendlyErrorMessage(e.message, "Unable to load expense history.")}</div>`;
            }
        }

        // Backend-assisted export: expenseHistoryFilters already mirrors
        // exactly what's on screen (search/category/user/date-range), and is
        // sent unchanged to /expenses/export(.xlsx) so neither format can
        // ever show a different result set than the current filtered view —
        // the frontend only ever holds one page (EXPENSE_HISTORY_PAGE_SIZE=20)
        // of results, so this re-queries the backend rather than exporting
        // just the visible page.
        function expenseExportParams() {
            const params = new URLSearchParams();
            if (expenseHistoryFilters.search) params.set("search", expenseHistoryFilters.search);
            if (expenseHistoryFilters.category) params.set("category", expenseHistoryFilters.category);
            if (expenseHistoryFilters.user_id) params.set("user_id", expenseHistoryFilters.user_id);
            if (expenseHistoryFilters.date_from) params.set("date_from", expenseHistoryFilters.date_from);
            if (expenseHistoryFilters.date_to) params.set("date_to", expenseHistoryFilters.date_to);
            return params;
        }
        function exportExpensesCsv(button) {
            runBackendCsvExport(button, `${API_URL}/expenses/export?${expenseExportParams().toString()}`, `cauldra_expenses_${csvDateStamp()}.csv`, "No expenses available to export.");
        }
        function exportExpensesExcel(button) {
            runBackendCsvExport(button, `${API_URL}/expenses/export/xlsx?${expenseExportParams().toString()}`, `cauldra_expenses_${csvDateStamp()}.xlsx`, "No expenses available to export.");
        }

        function openPredictiveModal(initialTab) {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("predictive-modal").classList.remove("hidden");
            renderPredictiveMonitor(initialTab || "at-risk");
        }
        function closePredictiveModal() { document.getElementById("predictive-modal").classList.add("hidden"); }
        
        function openAlertsModal() { document.getElementById("alerts-modal").classList.remove("hidden"); renderAlerts(); }
        function closeAlertsModal() { document.getElementById("alerts-modal").classList.add("hidden"); }
        
        function openPriceMonitorModal() { 
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("price-monitor-modal").classList.remove("hidden"); 
            loadPriceMonitor(); 
        }
        function closePriceMonitorModal() { document.getElementById("price-monitor-modal").classList.add("hidden"); }

        function updateDashboardMetrics() {
            const hasBusinessContext = hasAuthenticatedBusinessContext();

            // Guest state deliberately shows the same four cards, but with zero values.
            // Once authenticated, all figures continue to come from the existing business-scoped data.
            const totalProducts = hasBusinessContext ? globalProducts.length : 0;
            const lowStockProducts = hasBusinessContext
                ? globalProducts.filter(p => p.quantity <= p.min_stock_level).length
                : 0;
            const activeSuppliersCount = hasBusinessContext ? globalSuppliers.length : 0;
            const warehouseCount = hasBusinessContext ? customWarehouses.length : 0;

            // Only during this session's first load, before each figure's own
            // data has actually arrived, show a neutral "—" instead of "0" —
            // a real zero and "hasn't loaded yet" must never look identical.
            // Products/suppliers share one flag (they load together);
            // warehouses load separately and may resolve at a different time.
            const productsPending = hasBusinessContext && !productsSuppliersReady;
            const warehousesPending = hasBusinessContext && !warehousesReady;

            const totalSkusEl = document.getElementById("metric-total-skus");
            if (totalSkusEl) totalSkusEl.innerText = productsPending ? "—" : totalProducts;
            const totalDescEl = document.getElementById("metric-total-desc");
            if (totalDescEl) totalDescEl.innerText = productsPending ? "Loading…" : (totalProducts === 1 ? "1 product cataloged" : (totalProducts === 0 ? "No products" : `${totalProducts} products cataloged`));

            const lowSkusEl = document.getElementById("metric-low-skus");
            if (lowSkusEl) lowSkusEl.innerText = productsPending ? "—" : lowStockProducts;
            const lowDescEl = document.getElementById("metric-low-desc");
            if (lowDescEl) lowDescEl.innerText = productsPending ? "Loading…" : (lowStockProducts === 1 ? "1 item needs attention" : (lowStockProducts === 0 ? "No items" : `${lowStockProducts} items need attention`));

            const supEl = document.getElementById("metric-suppliers");
            if (supEl) supEl.innerText = productsPending ? "—" : activeSuppliersCount;
            const supDescEl = document.getElementById("metric-suppliers-desc");
            if (supDescEl) supDescEl.innerText = productsPending ? "Loading…" : (activeSuppliersCount === 1 ? "1 registered vendor" : (activeSuppliersCount === 0 ? "No suppliers" : `${activeSuppliersCount} registered vendors`));

            const metricWarehousesEl = document.getElementById("metric-warehouses");
            if (metricWarehousesEl) metricWarehousesEl.innerText = warehousesPending ? "—" : warehouseCount;
            const whDescEl = document.getElementById("metric-warehouses-desc");
            if (whDescEl) whDescEl.innerText = warehousesPending ? "Loading…" : (warehouseCount === 1 ? "1 active location" : (warehouseCount === 0 ? "No locations" : `${warehouseCount} active locations`));
        }

        async function refreshAccessToken() {
            // Never silently re-establish a session while a sign-out is in
            // progress — this is the one chokepoint every background auth
            // path (the 10-minute heartbeat, the visibilitychange listener,
            // validateAuthenticationSession()'s own 401 recovery, and
            // loadData()'s guest-reload path) funnels through, so guarding it
            // here protects all of them at once without touching each one.
            if (signOutInProgress) return false;
            // Same chokepoint, same reasoning, for a business deletion in
            // flight — see businessDeletionInProgress's declaration.
            if (businessDeletionInProgress) return false;
            // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) -----
            // Never logs tokens/cookies/passwords — only caller, timing, and
            // the true/false outcome. Logged to console AND sessionStorage
            // (the latter survives a reload in case console output is missed
            // or cleared). Search DevTools console for "auth-diag-frontend".
            // Remove once the investigation is closed.
            const __diagCallNum = (window.__refreshDiagCallCount = (window.__refreshDiagCallCount || 0) + 1);
            const __diagCaller = (new Error().stack || "").split("\n").slice(1, 4).join(" | ");
            const __diagAlreadyInFlight = !!authRefreshInFlight;
            console.log(`[auth-diag-frontend] refreshAccessToken() call #${__diagCallNum} START alreadyInFlight=${__diagAlreadyInFlight} caller=${__diagCaller}`);
            try {
                const diagLog = JSON.parse(sessionStorage.getItem("__refreshDiag") || "[]");
                diagLog.push({ n: __diagCallNum, t: Date.now(), phase: "start", alreadyInFlight: __diagAlreadyInFlight, stack: __diagCaller });
                sessionStorage.setItem("__refreshDiag", JSON.stringify(diagLog));
            } catch (_) {}
            // --- END TEMPORARY DEV DIAGNOSTIC (continues at each return below) --
            if (authRefreshInFlight) return authRefreshInFlight;
            authRefreshInFlight = (async () => {
                let __diagOutcome = "unknown";
                refreshAccessTokenWasNetworkUnreachable = false;
                try {
                    const res = await fetch(`${API_URL}/auth/refresh`, { method: "POST", credentials: "include", headers: { "Accept": "application/json" } });
                    if (res.status === 204) { __diagOutcome = "204_no_content"; return false; }
                    if (!res.ok) { __diagOutcome = `http_${res.status}`; return false; }
                    const data = await res.json();
                    if (!data.access_token) { __diagOutcome = "200_but_no_access_token_in_body"; return false; }
                    authToken = data.access_token;
                    currentUserProfile = {
                        id: data.id, username: data.username, role: String(data.role || '').toLowerCase(),
                        firstname: data.firstname, lastname: data.lastname, position: data.position,
                        phone: data.phone, email: data.email, must_change_password: !!data.must_change_password
                    };
                    businessProfile = {
                        id: data.business_id, business_id: data.business_id, business_code: data.business_code,
                        company_name: data.company_name, email: data.email, phone: data.phone, address: data.address,
                        currency: data.currency, tax_id: data.tax_id, country: data.country, country_code: data.country_code,
                        locale: data.locale, language: data.language || "en", timezone: data.timezone || "UTC",
                        phone_country_code: data.phone_country_code
                    };
                    startAuthRefreshHeartbeat();
                    applyRoleRestrictions();
                    updateCompanyHeaderDisplay();
                    syncLanguageFromProfile(businessProfile);
                    updateGuestHeaderState();
                    __diagOutcome = "success";
                    return true;
                } catch (e) {
                    // fetch() itself threw — the request never got a response
                    // from the backend at all (connection refused, DNS/reset,
                    // offline, etc.). This is a reachability problem, not the
                    // backend telling us the refresh session is invalid.
                    __diagOutcome = "exception:" + (e && e.message);
                    refreshAccessTokenWasNetworkUnreachable = true;
                    return false;
                }
                finally {
                    // --- TEMPORARY DEV DIAGNOSTIC (continued) ---
                    console.log(`[auth-diag-frontend] refreshAccessToken() call #${__diagCallNum} RESOLVED outcome=${__diagOutcome} authTokenPresentNow=${!!authToken} currentUserProfilePresentNow=${!!currentUserProfile}`);
                    try {
                        const diagLog = JSON.parse(sessionStorage.getItem("__refreshDiag") || "[]");
                        diagLog.push({ n: __diagCallNum, t: Date.now(), phase: "resolved", outcome: __diagOutcome, authTokenPresentNow: !!authToken, currentUserProfilePresentNow: !!currentUserProfile });
                        sessionStorage.setItem("__refreshDiag", JSON.stringify(diagLog));
                    } catch (_) {}
                    // --- END TEMPORARY DEV DIAGNOSTIC ---
                    authRefreshInFlight = null;
                }
            })();
            return authRefreshInFlight;
        }

        // Used only by runLoadData()'s cold-start path, when the page has no
        // in-memory authToken yet (a real reload, or the first load of a
        // tab). A single failed refreshAccessToken() call is ambiguous on its
        // own: it could mean "the backend explicitly says this session is no
        // longer valid" (genuinely unauthenticated — do not retry, do not
        // pretend otherwise) or "the backend could not be reached at all"
        // (e.g. ERR_CONNECTION_REFUSED while it's still starting up — a
        // transient condition that must NOT be treated as a logout). This
        // retries a small, bounded number of times, with a short delay, only
        // in the second case. It reuses refreshAccessToken() as-is, so the
        // existing authRefreshInFlight guard still ensures only one actual
        // request is ever in flight at a time — this never fires overlapping
        // /auth/refresh calls.
        async function refreshAccessTokenAtStartup() {
            const RETRY_DELAYS_MS = [500, 1500]; // up to 3 total attempts
            for (let attempt = 0; ; attempt++) {
                const ok = await refreshAccessToken();
                if (ok) return "success";
                if (!refreshAccessTokenWasNetworkUnreachable) {
                    // The backend WAS reached and gave an explicit answer
                    // (e.g. 204 — no valid session). Retrying would not
                    // change that, so stop immediately.
                    return "unauthenticated";
                }
                if (attempt >= RETRY_DELAYS_MS.length) return "unreachable";
                await new Promise(resolve => setTimeout(resolve, RETRY_DELAYS_MS[attempt]));
            }
        }

        // Keeps the loading UI (banner + inventory skeleton) up and swaps in a
        // connection-specific message, instead of falling through to the
        // guest/logged-out rendering, when the backend could not be reached
        // during startup after refreshAccessTokenAtStartup()'s retries.
        function showStartupConnectionIssue(loadingBanner) {
            if (loadingBanner) {
                const span = loadingBanner.querySelector("span");
                if (span) span.textContent = "Still trying to reach the server… your session will resume automatically once it's back.";
                loadingBanner.classList.remove("hidden");
            }
            if (!inventoryEverLoaded) renderInventoryLoadingSkeleton();
        }

        // Bounded self-healing retry: tries loadData() again shortly after an
        // "unreachable backend" startup outcome, so the real session is
        // restored automatically once the backend comes back — without
        // requiring the user to manually reload, and without retrying
        // forever if it never comes back.
        function scheduleStartupReconnectRetry() {
            startupReconnectAttempts++;
            if (startupReconnectAttempts > 6) return;
            setTimeout(() => { if (!authToken) loadData(); }, 4000);
        }

        function startAuthRefreshHeartbeat() {
            if (businessDeletionInProgress) return; // never (re)start while a deletion is underway
            if (authRefreshTimer) clearInterval(authRefreshTimer);
            if (!authToken) return;
            authRefreshTimer = setInterval(() => {
                if (authToken && !businessDeletionInProgress) refreshAccessToken();
            }, 10 * 60 * 1000);
        }

        function stopAuthRefreshHeartbeat() {
            if (authRefreshTimer) clearInterval(authRefreshTimer);
            authRefreshTimer = null;
        }

        document.addEventListener('visibilitychange', () => {
            // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) -----
            console.log(`[auth-diag-frontend] visibilitychange fired hidden=${document.hidden} authTokenPresent=${!!authToken}`);
            // --- END TEMPORARY DEV DIAGNOSTIC -------------------------------
            if (!document.hidden && authToken) refreshAccessToken();
        });

        function handleAuthenticationFailure(message = "") {
            // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) -----
            // This is the ONE function that forcibly clears a session client-side
            // outside of an explicit sign-out. If the logout happens without any
            // failed /auth/refresh, this line's caller= will show what actually
            // triggered it.
            console.log(`[auth-diag-frontend] handleAuthenticationFailure() CALLED message=${JSON.stringify(message)} caller=` + (new Error().stack || "").split("\n").slice(1, 6).join(" | "));
            // --- END TEMPORARY DEV DIAGNOSTIC -------------------------------
            stopAuthRefreshHeartbeat();
            authToken = "";
            currentUserProfile = null;
            businessProfile = null;
            globalProducts = [];
            inventoryViewProducts = [];
            globalSuppliers = [];
            globalPurchaseOrders = [];
            warehouseRecords = [];
            customWarehouses = [];
            inventoryStatusCounts = { healthy: 0, low: 0, out: 0 };
            inventoryStatusFilter = null;
            selectedWarehouseFilter = "ALL";
            // A fresh sign-in after this should cold-start cleanly (its own
            // "Loading your data…" banner and "—" placeholders), not silently
            // reuse whatever this session already considered "loaded".
            productsSuppliersReady = false;
            warehousesReady = false;
            inventoryEverLoaded = false;
            coreDataEverLoaded = false;
            // Clear the prior business's Brief before rendering signed-out UI.
            businessBrainData = null;
            dashboardBrainForbiddenMessage = null;
            lastFinancialIntelData = null;
            dashboardTodayProfit = null;
            dashboardSalesToday = null;
            dashboardSubscriptionWarning = null;
            dashboardPendingReopenCount = 0;
            document.getElementById("global-loading-banner")?.classList.add("hidden");
            updateWarehouseUIElements();
            applyRoleRestrictions();
            updateCompanyHeaderDisplay();
            updateWelcomeBanner();
            updateDashboardMetrics();
            renderInventoryTable([]);
            renderBusinessInsights();
            renderAuthButton();
            updateGuestHeaderState();
            if (message) {
                const authMsg = document.getElementById("auth-session-message");
                if (authMsg) { authMsg.textContent = message; authMsg.classList.remove("hidden"); }
            }
        }

        async function validateAuthenticationSession() {
            if (signOutInProgress) return false; // don't let a mid-flight validation repopulate the profile a sign-out just cleared
            if (!authToken) return false;
            try {
                const res = await fetch(`${API_URL}/auth/me`, {
                    credentials: "include",
                    headers: { "Authorization": `Bearer ${authToken}`, "Accept": "application/json" }
                });
                // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) -----
                console.log(`[auth-diag-frontend] validateAuthenticationSession() GET /auth/me status=${res.status}`);
                // --- END TEMPORARY DEV DIAGNOSTIC -------------------------------
                if (!res.ok) {
                    if (res.status === 401 && await refreshAccessToken()) return true;
                    if (res.status === 401) handleAuthenticationFailure("Your session has expired. Please sign in again.");
                    return false;
                }
                const data = await res.json();
                currentUserProfile = {
                    id: data.id, username: data.username, role: String(data.role || '').toLowerCase(),
                    firstname: data.firstname, lastname: data.lastname, position: data.position,
                    phone: data.phone, email: data.email, must_change_password: !!data.must_change_password
                };
                businessProfile = {
                    id: data.business_id, business_id: data.business_id, business_code: data.business_code,
                    company_name: data.company_name, email: data.email, phone: data.phone, address: data.address,
                    currency: data.currency, tax_id: data.tax_id, country: data.country, country_code: data.country_code,
                    locale: data.locale, language: data.language || "en", timezone: data.timezone || "UTC",
                    phone_country_code: data.phone_country_code
                };
                applyRoleRestrictions();
                updateCompanyHeaderDisplay();
                syncLanguageFromProfile(businessProfile);
                updateGuestHeaderState();
                startAuthRefreshHeartbeat();
                if (currentUserProfile.must_change_password) {
                    const lock = document.getElementById("password-change-modal");
                    if (lock) { lock.classList.remove("hidden"); lock.style.display = "flex"; setTimeout(() => document.getElementById("pw-change-current")?.focus(), 50); }
                    return false;
                }
                return true;
            } catch (e) {
                return false;
            }
        }

        async function loadWarehouses() {
            if (!authToken) {
                warehouseRecords = [];
                customWarehouses = [];
                updateWarehouseUIElements();
                return;
            }
            try {
                const res = await fetch(`${API_URL}/warehouses/`, { credentials: "include", headers: { "Authorization": `Bearer ${authToken}`, "Accept": "application/json" } });
                if (res.status === 401) { handleAuthenticationFailure(); return; }
                if (!res.ok) throw new Error("Unable to load warehouses.");
                warehouseRecords = await res.json();
                customWarehouses = warehouseRecords.filter(w => w.is_active !== false).map(w => w.name);
                warehousesReady = true;
                updateWarehouseUIElements();
                updateDashboardMetrics();
            } catch (_) {
                warehouseRecords = [];
                customWarehouses = [];
                // Resolve the "loading" placeholder to the existing empty-state
                // fallback rather than leaving the warehouse metric stuck on
                // "—" forever if this request fails.
                warehousesReady = true;
                updateWarehouseUIElements();
                updateDashboardMetrics();
            }
        }

        async function loadInventoryView() {
            if (!authToken) {
                inventoryViewProducts = [];
                inventoryStatusCounts = { healthy: 0, low: 0, out: 0 };
                renderInventoryTable([]);
                updateInventoryStatusUI();
                return;
            }
            const warehouse = selectedWarehouseFilter || "ALL";
            const params = new URLSearchParams({ limit: "500", offset: "0" });
            if (warehouse !== "ALL") params.set("warehouse", warehouse);
            if (inventoryStatusFilter) params.set("status", inventoryStatusFilter);
            const searchTerm = document.getElementById("inventory-search")?.value.trim();
            // Only on this session's first inventory fetch: a bare, empty
            // table looks identical to "you have no inventory," which is
            // exactly the wrong impression to give while data is still on
            // its way. A later manual refresh/filter change just leaves the
            // previous rows visible until the new ones replace them.
            if (!inventoryEverLoaded) renderInventoryLoadingSkeleton();
            try {
                const headers = { "Authorization": `Bearer ${authToken}`, "Accept": "application/json" };
                const res = await fetch(`${API_URL}/products/?${params.toString()}`, { credentials: "include", headers });
                if (res.status === 401) { handleAuthenticationFailure(); return; }
                if (!res.ok) throw new Error("Unable to load inventory.");
                inventoryViewProducts = await res.json();
                if (searchTerm) {
                    const term = searchTerm.toLowerCase();
                    inventoryViewProducts = inventoryViewProducts.filter(p => `${p.name || ""} ${p.sku || ""} ${p.category || ""}`.toLowerCase().includes(term));
                }
                const summaryParams = new URLSearchParams();
                if (warehouse !== "ALL") summaryParams.set("warehouse", warehouse);
                const summaryRes = await fetch(`${API_URL}/products/inventory-summary?${summaryParams.toString()}`, { credentials: "include", headers });
                if (summaryRes.ok) inventoryStatusCounts = await summaryRes.json();
                inventoryEverLoaded = true;
                renderInventoryTable(inventoryViewProducts);
                updateInventoryStatusUI();
            } catch (err) {
                // The live inventory endpoint couldn't be reached — rather than
                // showing a blank inventory table, fall back to whatever
                // products are already known locally (the in-memory list from
                // the last successful load, or the IndexedDB cache if this is
                // a fresh page load while offline) and apply the same
                // warehouse/status/search filters the user had set.
                inventoryEverLoaded = true;
                refreshInventoryViewFromLocalState();
            }
        }

        // First-load-only placeholder for the inventory table — distinct from
        // both the real rows and the "no products found" empty state, so a
        // user can never mistake "still loading" for "your inventory is gone."
        function renderInventoryLoadingSkeleton() {
            const tbody = document.getElementById("inventory-table-body");
            if (!tbody) return;
            tbody.innerHTML = `<tr><td colspan="6" class="text-center py-16">
                <div class="flex flex-col items-center gap-2.5">
                    <i class="fa-solid fa-circle-notch fa-spin text-2xl text-primary/60"></i>
                    <div class="text-textMain font-semibold text-sm">Loading your inventory…</div>
                    <div class="text-textSec text-xs max-w-xs">Your data is safe — this will only take a moment.</div>
                </div>
            </td></tr>`;
        }

        // Renders the inventory table from whatever product data is already
        // available locally (globalProducts, which includes any offline-created
        // pending-sync products) instead of a network call — used both as the
        // offline fallback for loadInventoryView() and after any offline
        // product mutation so the table updates immediately.
        function refreshInventoryViewFromLocalState() {
            const warehouse = selectedWarehouseFilter || "ALL";
            const searchTerm = (document.getElementById("inventory-search")?.value || "").trim().toLowerCase();
            let list = Array.isArray(globalProducts) ? [...globalProducts] : [];
            if (warehouse !== "ALL") list = list.filter(p => (p.warehouse || "Main Central Warehouse") === warehouse);
            if (inventoryStatusFilter === "low") list = list.filter(p => p.quantity > 0 && p.quantity <= p.min_stock_level);
            else if (inventoryStatusFilter === "out") list = list.filter(p => p.quantity === 0);
            else if (inventoryStatusFilter === "healthy") list = list.filter(p => p.quantity > p.min_stock_level);
            if (searchTerm) list = list.filter(p => `${p.name || ""} ${p.sku || ""} ${p.category || ""}`.toLowerCase().includes(searchTerm));
            inventoryViewProducts = list;
            inventoryStatusCounts = {
                healthy: list.filter(p => p.quantity > p.min_stock_level).length,
                low: list.filter(p => p.quantity > 0 && p.quantity <= p.min_stock_level).length,
                out: list.filter(p => p.quantity === 0).length,
            };
            renderInventoryTable(inventoryViewProducts);
            updateInventoryStatusUI();
        }

        // Lightweight dashboard-only check — NOT the full Subscription & AI
        // Usage card anymore (that moved to Settings → Subscription &
        // Billing; see renderBillingAiUsage()). This keeps two things
        // current without loading/showing the full usage payload as
        // dashboard content: currentAiEntitled (gates AI-powered features
        // app-wide) and a compact Needs Attention warning line for genuinely
        // urgent conditions. Admin/Manager only — Staff has no Subscription
        // access anywhere else in the app (see openBillingModal()'s own role
        // gate), so this must never surface a subscription warning to Staff.
        let dashboardSubscriptionWarning = null;
        async function checkSubscriptionWarningForDashboard() {
            dashboardSubscriptionWarning = null;
            if (!hasAuthenticatedBusinessContext() || !['admin', 'manager'].includes(getCurrentRole())) { renderNeedsAttention(); return; }
            try {
                const res = await fetch(`${API_URL}/subscription/usage`, { credentials: 'include', headers: { 'Authorization': `Bearer ${authToken}`, 'Accept': 'application/json' } });
                if (res.ok) {
                    const data = await res.json();
                    currentAiEntitled = Number(data.included_ai_credits || 0) > 0;
                    if (data.ai_warning === 'overage') dashboardSubscriptionWarning = "Your included AI credits have been used.";
                    else if (data.ai_warning === 'warning') dashboardSubscriptionWarning = "AI usage is approaching its limit.";
                    else if (data.status === 'trialing' && Number(data.trial_days_remaining) <= 3) dashboardSubscriptionWarning = `Your trial ends in ${data.trial_days_remaining} day${Number(data.trial_days_remaining) === 1 ? '' : 's'}.`;
                    else if (['past_due', 'payment_failed'].includes(data.status)) dashboardSubscriptionWarning = "There's a problem with your subscription payment.";
                }
            } catch (_) { /* no warning shown rather than a wrong one */ }
            renderNeedsAttention();
        }

        // Fetches the exact same Predictive/financial-intelligence data the
        // dedicated Predictive destination uses — only the dashboard
        // RENDERING changed (see renderBusinessInsights()): this used to
        // populate its own large "Inventory Financial Health" section with
        // four cards; now it just feeds the compact Business Insights
        // summary. Detailed figures remain fully available in Predictive.
        let lastFinancialIntelData = null;
        async function loadFinancialHealthCards() {
            lastFinancialIntelData = null;
            if (!hasAuthenticatedBusinessContext()) { renderBusinessInsights(); return; }
            try {
                const res = await fetch(`${API_URL}/products/financial-intelligence`, { credentials: 'include', headers: { 'Authorization': `Bearer ${authToken}`, 'Accept': 'application/json' } });
                if (!res.ok) {
                    const data = await res.json().catch(() => ({}));
                    const err = new Error(friendlyErrorMessage(data, 'Financial intelligence unavailable'));
                    err.status = res.status;
                    throw err;
                }
                lastFinancialIntelData = await res.json();
            } catch (err) {
                lastFinancialIntelData = err.status === 403 ? { forbidden: true, message: err.message } : null;
            }
            renderBusinessInsights();
        }

        // =====================================================================
        // PROFIT
        // =====================================================================
        const PROFIT_PREVIOUS_PERIOD = { today: "yesterday", week: "previous_week", month: "previous_month", year: "previous_year" };

        // Used to populate four separate "Today/Week/Month/Year" profit
        // cards as their own dashboard section — consolidated into a single
        // compact dashboard headline in Business Insights (see dashboard
        // decluttering). Week/Month/Year and every other calendar-period
        // breakdown remain fully available in Profit (via /financial-summary).
        //
        // Deliberately reads /business-days/current-summary, NOT
        // /financial-summary?period=today: a Business Day SESSION (see the
        // BusinessDay model) is not the same thing as a calendar day — a
        // business can close one session and open a brand-new one on the
        // SAME date, and this headline must reflect only the currently
        // active session (0 for a freshly opened one), never the total for
        // the whole calendar date or a just-closed session. financial-
        // summary's period=today keeps its own, deliberately different,
        // calendar-based meaning for historical/period reporting — see
        // main.py's financial_summary_for_period() and
        // current_business_day_summary().
        let dashboardTodayProfit = null;
        // Sales Today (Business Insights card) — the SAME /business-days/
        // current-summary response that already feeds dashboardTodayProfit,
        // just also keeping its `sales` field. This is the CURRENT BUSINESS
        // DAY SESSION's recognized sales, net of same-session refunds
        // (_business_day_financials on the backend) — never inventory
        // value, a forecast, or a calendar-day total. It is mathematically
        // identical to the "Sales" figure the Sales modal's current-day tab
        // shows (see renderDailySalesCards/serialize_business_day, which
        // shares the exact same business_day_sales_query/refund-totals
        // helpers) — the two can never disagree because they are two reads
        // of the same underlying aggregate, not two separate calculations.
        let dashboardSalesToday = null;
        async function loadProfitDashboardCards() {
            dashboardTodayProfit = null;
            dashboardSalesToday = null;
            if (!hasAuthenticatedBusinessContext() || !hasFeaturePermission('profit')) { renderBusinessInsights(); return; }
            try {
                const res = await fetch(`${API_URL}/business-days/current-summary`, { headers: { "Authorization": `Bearer ${authToken}` } });
                // `open: false` (no active session right now — e.g. between
                // closing one and opening the next) is not a fetch failure;
                // the endpoint still returns a real net_profit/sales of
                // exactly 0.0 for that case, which is exactly the neutral
                // state this headline must show rather than a stale prior
                // value.
                if (res.ok) { const d = await res.json(); dashboardTodayProfit = d.net_profit; dashboardSalesToday = d.sales; }
            } catch (_) { /* Business Insights just omits the line */ }
            renderBusinessInsights();
        }

        let profitActivePeriod = "month";
        function openProfitModal(period) {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            document.getElementById("profit-modal").classList.remove("hidden");
            switchProfitPeriod(period || profitActivePeriod || "month");
        }
        function closeProfitModal() { document.getElementById("profit-modal").classList.add("hidden"); }

        let profitCustomFilters = { date_from: "", date_to: "" };

        function switchProfitPeriod(period) {
            profitActivePeriod = period;
            closeProfitCustomPanel();
            hideProfitCustomError();
            updateProfitPeriodButtonsUI();
            loadProfitData(period);
        }

        function updateProfitPeriodButtonsUI() {
            document.querySelectorAll(".profit-period-btn").forEach(btn => {
                const active = btn.dataset.period === profitActivePeriod;
                const isCustom = btn.dataset.period === "custom";
                btn.className = "profit-period-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold cursor-pointer "
                    + (isCustom ? "flex items-center gap-1 " : "")
                    + (active ? "bg-primary/15 text-primary border border-primary/30" : "text-textSec hover:text-textMain border border-transparent");
            });
            const label = document.getElementById("profit-custom-btn-label");
            if (!label) return;
            if (profitActivePeriod === "custom" && profitCustomFilters.date_from && profitCustomFilters.date_to) {
                label.textContent = `${formatExpenseCustomDateShort(profitCustomFilters.date_from)} – ${formatExpenseCustomDateShort(profitCustomFilters.date_to)}`;
            } else {
                label.textContent = "Custom";
            }
        }

        function toggleProfitCustomPanel() {
            const panel = document.getElementById("profit-custom-panel");
            const button = document.getElementById("profit-custom-btn");
            if (!panel) return;
            if (panel.classList.contains("hidden")) {
                hideProfitCustomError();
                showDateDropdown(panel, button);
                const fromInput = document.getElementById("profit-custom-from");
                setTimeout(() => fromInput && fromInput.focus(), 0);
            } else {
                hideDateDropdown(panel);
            }
        }

        function closeProfitCustomPanel() {
            const panel = document.getElementById("profit-custom-panel");
            if (panel) hideDateDropdown(panel);
        }

        function handleProfitCustomRangeKeydown(event) {
            if (event.key === "Enter") {
                event.preventDefault();
                applyProfitCustomRange();
            } else if (event.key === "Escape") {
                closeProfitCustomPanel();
            }
        }

        function showProfitCustomError(msg) {
            const el = document.getElementById("profit-custom-error");
            if (!el) return;
            el.textContent = msg;
            el.classList.remove("hidden");
        }

        function hideProfitCustomError() {
            document.getElementById("profit-custom-error")?.classList.add("hidden");
        }

        function applyProfitCustomRange() {
            const fromVal = document.getElementById("profit-custom-from").value;
            const toVal = document.getElementById("profit-custom-to").value;

            if (!fromVal && !toVal) { showProfitCustomError("Select a start date and end date."); return; }
            if (!fromVal) { showProfitCustomError("Select a start date."); return; }
            if (!toVal) { showProfitCustomError("Select an end date."); return; }
            if (toVal < fromVal) { showProfitCustomError("End date cannot be earlier than start date."); return; }

            hideProfitCustomError();
            profitActivePeriod = "custom";
            profitCustomFilters.date_from = fromVal; // inclusive lower bound
            profitCustomFilters.date_to = toVal;     // inclusive upper bound
            updateProfitPeriodButtonsUI();
            closeProfitCustomPanel();
            loadProfitData("custom", fromVal, toVal);
        }

        function profitChangeLine(label, current, previous) {
            if (previous === null || previous === undefined || previous === 0) return "";
            const change = ((current - previous) / Math.abs(previous)) * 100;
            const arrow = change >= 0 ? "↑" : "↓";
            const cls = change >= 0 ? "text-success" : "text-danger";
            return `<span class="${cls} font-mono text-[10px]">${arrow} ${Math.abs(change).toFixed(0)}%</span>`;
        }

        // Cached by loadProfitData() purely so exportProfitCsv() can build a
        // CSV from data already on screen instead of re-fetching — cleared
        // whenever a period has nothing to show, so the export button can't
        // silently offer a stale previous period's figures.
        let lastProfitData = null;

        async function loadProfitData(period, customFrom, customTo) {
            const body = document.getElementById("profit-modal-body");
            body.innerHTML = `<div class="text-center py-10 text-textSec">Loading...</div>`;
            lastProfitData = null;
            try {
                const params = period === "custom" ? `period=custom&custom_start=${customFrom}&custom_end=${customTo}` : `period=${period}`;
                const [summaryRes, breakdownRes] = await Promise.all([
                    fetch(`${API_URL}/financial-summary?${params}`, { headers: { "Authorization": `Bearer ${authToken}` } }),
                    fetch(`${API_URL}/financial-summary/breakdown?${params}`, { headers: { "Authorization": `Bearer ${authToken}` } }),
                ]);
                if (!summaryRes.ok) { const d = await summaryRes.json().catch(() => ({})); throw new Error(showApiError(summaryRes, d, "Unable to load profit data.")); }
                const summary = await summaryRes.json();
                const breakdown = breakdownRes.ok ? await breakdownRes.json() : { expense_breakdown: [], top_products: [] };

                // Deterministic (non-AI) comparison against the previous comparable
                // period — plain arithmetic on the same shared endpoint, per the
                // "no external AI for basic arithmetic" requirement.
                let previous = null;
                const prevKey = PROFIT_PREVIOUS_PERIOD[period];
                if (prevKey) {
                    const prevRes = await fetch(`${API_URL}/financial-summary?period=${prevKey}`, { headers: { "Authorization": `Bearer ${authToken}` } });
                    if (prevRes.ok) previous = await prevRes.json();
                }

                if (summary.transaction_count === 0 && summary.expense_count === 0) {
                    body.innerHTML = `<div class="text-center py-10 text-textSec">No sales or expenses recorded yet for this period.</div>`;
                    return;
                }

                lastProfitData = { summary, breakdown, period };

                const marginLine = summary.profit_margin_percent === null
                    ? `<span class="text-textSec">${summary.cogs_complete === false ? "Unknown" : "—"}</span>`
                    : `<span class="${summary.profit_margin_percent >= 0 ? 'text-success' : 'text-danger'}">${summary.profit_margin_percent}%</span>`;

                const rows = [
                    ["Sales", summary.sales, "text-textMain", previous?.sales],
                    ["Cost of Goods", summary.cogs === null ? null : -summary.cogs, "text-textSec", previous && previous.cogs !== null ? -previous.cogs : null],
                    ["Gross Profit", summary.gross_profit, "text-textMain", previous?.gross_profit],
                    ["Expenses", -summary.expenses, "text-textSec", previous ? -previous.expenses : null],
                ];
                const unknownCostNotice = summary.cogs_complete === false ? `
                    <div class="mb-3 rounded-xl border border-warning/30 bg-warning/10 p-3 text-[11px] text-textSec">
                        <span class="font-semibold text-warning">Historical COGS is unknown.</span>
                        ${summary.unknown_cogs_sale_lines || 0} sale line(s) and ${summary.unknown_cogs_refund_lines || 0} refund line(s) lack a recorded cost snapshot. Revenue, expenses, and units remain exact; known COGS is ${formatCurrency(summary.known_cogs || 0)}, but profit is not stated.
                    </div>` : '';
                const netProfitLine = summary.net_profit === null
                    ? `<span class="font-mono font-bold text-base text-textSec">Unknown</span>`
                    : `<span class="flex items-center gap-2 font-mono font-bold text-base ${summary.net_profit >= 0 ? "text-success" : "text-danger"}">${formatCurrency(summary.net_profit)} ${profitChangeLine("Net Profit", summary.net_profit, previous?.net_profit)}</span>`;

                body.innerHTML = `
                    ${unknownCostNotice}
                    <div class="space-y-1.5 mb-4">
                        ${rows.map(([label, val, cls, prevVal]) => `
                            <div class="flex items-center justify-between py-1">
                                <span class="text-textSec">${label}</span>
                                ${val === null
                                    ? `<span class="font-mono font-semibold text-textSec">Unknown</span>`
                                    : `<span class="flex items-center gap-2 font-mono font-semibold ${cls}">${val < 0 ? "-" : ""}${formatCurrency(Math.abs(val))} ${profitChangeLine(label, val, prevVal)}</span>`}
                            </div>`).join("")}
                        <div class="border-t border-borderCol pt-2 mt-2 flex items-center justify-between">
                            <span class="font-bold text-textMain">Net Profit</span>
                            ${netProfitLine}
                        </div>
                        <div class="flex items-center justify-between pt-1">
                            <span class="text-textSec">Profit Margin</span>
                            <span class="font-mono font-semibold">${marginLine}</span>
                        </div>
                    </div>
                    ${breakdown.expense_breakdown.length ? `
                        <div class="mb-4">
                            <h4 class="text-[10px] uppercase tracking-wider text-textSec mb-1.5">Expense Breakdown</h4>
                            ${breakdown.expense_breakdown.map(e => `<div class="flex items-center justify-between py-1 text-[11px]"><span class="text-textMain">${escapeHtml(e.category)}</span><span class="font-mono text-textSec">${formatCurrency(e.amount)}</span></div>`).join("")}
                        </div>` : ""}
                    ${breakdown.top_products.length ? `
                        <div>
                            <h4 class="text-[10px] uppercase tracking-wider text-textSec mb-1.5">Best-Performing Products</h4>
                            ${breakdown.top_products.map(p => `<div class="flex items-center justify-between py-1 text-[11px]"><span class="text-textMain">${escapeHtml(p.name)}</span><span class="font-mono text-textSec">${p.units_sold} sold · ${formatCurrency(p.revenue)}</span></div>`).join("")}
                        </div>` : ""}
                `;
            } catch (e) {
                body.innerHTML = `<div class="text-center py-10 text-danger">${friendlyErrorMessage(e.message, "Unable to load profit data.")}</div>`;
            }
        }

        // Exports the P&L summary + expense breakdown + top products already
        // on screen (lastProfitData, set by loadProfitData() for whichever
        // period/custom range is currently selected) as one long-format
        // Three logical tables (Summary, Expense Breakdown, Top Products) —
        // one normalized spec, consumed differently per format: Excel gets
        // three real worksheets (rule: multiple worksheets where it
        // materially improves readability), CSV flattens each into its own
        // labeled block (see exportSpecToCsv) since plain CSV has no concept
        // of sheets. Either way it's the exact same underlying values from
        // lastProfitData — never a second, separately-computed version.
        function buildProfitExportSpec() {
            if (!lastProfitData) return null;
            const { summary, breakdown, period } = lastProfitData;
            return {
                filenameBase: `cauldra_profit_${period || "report"}_${csvDateStamp()}`,
                reportTitle: "Cauldra Profit Report",
                metadata: [["Period", period === "custom" ? "Custom Range" : (period || "All Time")], ["Generated", new Date().toLocaleString()]],
                sheets: [
                    {
                        name: "Summary",
                        columns: [{ key: "label", label: "Metric", type: "text" }, { key: "amount", label: "Amount", type: "currency" }],
                        rows: [
                            { label: "Sales", amount: summary.sales },
                            { label: "Cost of Goods", amount: summary.cogs },
                            { label: "Gross Profit", amount: summary.gross_profit },
                            { label: "Expenses", amount: summary.expenses },
                            { label: "Net Profit", amount: summary.net_profit },
                            { label: "Profit Margin %", amount: summary.profit_margin_percent ?? null },
                        ],
                    },
                    {
                        name: "Expense Breakdown",
                        columns: [{ key: "category", label: "Category", type: "text" }, { key: "amount", label: "Amount", type: "currency" }],
                        rows: (breakdown.expense_breakdown || []).map(e => ({ category: e.category, amount: e.amount })),
                    },
                    {
                        name: "Top Products",
                        columns: [{ key: "name", label: "Product", type: "text" }, { key: "units_sold", label: "Units Sold", type: "number" }, { key: "revenue", label: "Revenue", type: "currency" }],
                        rows: (breakdown.top_products || []).map(p => ({ name: p.name, units_sold: p.units_sold, revenue: p.revenue })),
                    },
                ],
            };
        }
        function exportProfitCsv() { runCsvExport(buildProfitExportSpec, "No profit data available to export."); }
        function exportProfitExcel(button) { runExcelExport(button, buildProfitExportSpec, "No profit data available to export."); }


        let businessBrainData = null;
        let businessBriefHistoryFilter = 'all';
        // Long-term History is paginated at the backend (GET /business-brain/history).
        // The browser holds only the page(s) the user has scrolled to — never years of rows.
        let businessBriefHistory = { type: 'all', range: 'all', items: [], offset: 0, hasMore: false, loading: false, loaded: false };
        const brainEsc = value => escapeEmployeeHtml(String(value ?? ''));
        const brainPriorityClass = priority => priority === 'critical'
            ? 'border-danger/35 bg-danger/10 text-danger'
            : priority === 'opportunity'
                ? 'border-success/35 bg-success/10 text-success'
                : 'border-warning/35 bg-warning/10 text-warning';

        async function fetchBusinessBrain() {
            const res = await fetch(`${API_URL}/business-brain`, {credentials:'include', headers:{'Authorization':`Bearer ${authToken}`, 'Accept':'application/json'}});
            if (!res.ok) {
                const data = await res.json().catch(() => ({}));
                const err = new Error(friendlyErrorMessage(data, t("businessBrain.unavailable")));
                err.status = res.status;
                throw err;
            }
            businessBrainData = await res.json();
            return businessBrainData;
        }

        let dashboardBrainForbiddenMessage = null;
        async function loadBusinessBrainDashboard() {
            businessBrainData = null;
            dashboardBrainForbiddenMessage = null;
            if (!hasAuthenticatedBusinessContext()) { renderBusinessBriefDashboard(); return; }
            try { await fetchBusinessBrain(); }
            catch (err) {
                if (err.status === 403) dashboardBrainForbiddenMessage = err.message || t("businessBrain.starterRequired");
            }
            renderBusinessBriefDashboard();
        }

        function businessBriefEmpty(icon, text, tone = 'text-textSec') {
            return `<div class="business-brief-empty ${tone}"><i class="fa-solid ${icon}"></i><span>${brainEsc(text)}</span></div>`;
        }

        function businessBriefCard(title, icon, tone, body, extraClass = '') {
            return `<div class="business-brief-area ${extraClass}"><h4><i class="fa-solid ${icon} ${tone}"></i>${brainEsc(title)}</h4><div class="business-brief-area-body">${body}</div></div>`;
        }

        // Dashboard-only variant of businessBriefCard: a <details> section that is
        // collapsible on phones (compact stacked list) and forced open, card-style,
        // on tablet/desktop via CSS. The modal keeps using businessBriefCard.
        function businessBriefDashCard(title, icon, tone, body, opts = {}) {
            const hint = opts.hint ? `<span class="bb-sec-hint">${brainEsc(opts.hint)}</span>` : '';
            return `<details class="business-brief-area business-brief-dash-section"${opts.open ? ' open' : ''}>`
                + `<summary><span class="bb-sec-title"><i class="fa-solid ${icon} ${tone}"></i>${brainEsc(title)}</span>${hint}<i class="fa-solid fa-chevron-down bb-sec-chevron" aria-hidden="true"></i></summary>`
                + `<div class="business-brief-area-body">${body}</div></details>`;
        }

        function businessBriefMore(total) {
            const additional = Math.max(0, Number(total || 0) - 2);
            return additional ? `<button type="button" class="business-brief-more" onclick="checkFeatureAccess('business brain', openBusinessBrainModal)">View ${additional} more <span aria-hidden="true">→</span></button>` : '';
        }

        function businessBriefSignalRow(item, compact = false) {
            const tag = item.onclick ? 'button' : 'div';
            const click = item.onclick ? ` type="button" onclick="${item.onclick}"` : '';
            const priority = item.priority || 'important';
            return `<${tag}${click} class="business-brief-signal ${item.onclick ? 'is-action' : ''} ${compact ? 'is-compact' : ''}"><span class="business-brief-signal-icon ${brainPriorityClass(priority)}"><i class="fa-solid ${item.icon || 'fa-circle'}"></i></span><span class="min-w-0"><strong>${brainEsc(item.title)}</strong>${item.summary ? `<small>${brainEsc(item.summary)}</small>` : ''}</span>${item.onclick ? '<i class="fa-solid fa-chevron-right business-brief-chevron" aria-hidden="true"></i>' : ''}</${tag}>`;
        }

        function getBusinessBriefAttentionItems(data = businessBrainData) {
            const role = getCurrentRole();
            const items = [];
            const out = inventoryStatusCounts?.out || 0;
            const low = inventoryStatusCounts?.low || 0;
            if (out > 0) items.push({ priority:'critical', icon:'fa-circle-xmark', title:`${out} out of stock`, summary:'Open the Inventory view to review the affected products.', onclick:"focusInventoryStatusFromDashboard('out')" });
            if (low > 0) items.push({ priority:'important', icon:'fa-triangle-exclamation', title:`${low} low-stock product${low === 1 ? '' : 's'}`, summary:'Review stock levels before they run out.', onclick:"focusInventoryStatusFromDashboard('low')" });
            if (['admin', 'manager'].includes(role) && dashboardPendingReopenCount > 0) items.push({ priority:'important', icon:'fa-hourglass-half', title:`${dashboardPendingReopenCount} pending reopen request${dashboardPendingReopenCount === 1 ? '' : 's'}`, summary:'Review the pending Business Day request.', onclick:"checkFeatureAccess('daily sales', () => openDailySalesModal('history'))" });
            if (['admin', 'manager'].includes(role) && dashboardSubscriptionWarning) items.push({ priority:'important', icon:'fa-credit-card', title:'Subscription needs review', summary:dashboardSubscriptionWarning, onclick:"openBillingModal()" });

            (data?.attention || []).filter(row => row.priority === 'critical').forEach(row => {
                if (row.kind === 'stock_review' && (out > 0 || low > 0)) return;
                items.push({ ...row, icon:'fa-bell', onclick:"checkFeatureAccess('business brain', openBusinessBrainModal)" });
            });
            const risk = lastFinancialIntelData?.report_ready ? lastFinancialIntelData.money_at_risk?.total : 0;
            if (risk > 0) items.push({ priority:'critical', icon:'fa-chart-line', title:`${formatCurrency(risk)} at risk from stockouts`, summary:'Open Financial Intelligence for the product-level evidence.', onclick:"checkFeatureAccess('predictive monitor', () => openPredictiveModal('at-risk'))" });
            return items;
        }

        function getBusinessBriefRecommendationItems(data = businessBrainData) {
            const rows = (data?.recommendations || []).filter(row => row.priority !== 'critical').map(row => ({ ...row, icon:'fa-lightbulb', onclick:"checkFeatureAccess('business brain', openBusinessBrainModal)" }));
            const recoverable = lastFinancialIntelData?.report_ready ? lastFinancialIntelData.potentially_recoverable?.total : 0;
            if (recoverable > 0) rows.push({ priority:'opportunity', icon:'fa-arrow-trend-up', title:`${formatCurrency(recoverable)} potentially recoverable`, summary:'Review the slow-moving stock and supported actions.', onclick:"checkFeatureAccess('predictive monitor', () => openPredictiveModal('recoverable'))" });
            return rows;
        }

        function getBusinessBriefLearningSummary(data = businessBrainData) {
            if (!data) return t("businessBrain.stillLearning");
            const days = Number(data.history_days || 0);
            if (data.learning) return data.learning_message || t("businessBrain.stillLearning");
            const patterns = (data.memory || []).length;
            const evaluated = Number(data.outcomes?.evaluated_predictions || 0);
            if (!patterns && !evaluated) return `Cauldra has ${days} completed business day${days === 1 ? '' : 's'} of evidence and will stay quiet until a pattern is supported.`;
            return `Based on ${days} completed business day${days === 1 ? '' : 's'}, Cauldra is tracking ${patterns} supported pattern${patterns === 1 ? '' : 's'} and ${evaluated} evaluated forecast${evaluated === 1 ? '' : 's'}.`;
        }

        function renderDashboardContext() {
            const salesRow = document.getElementById('dashboard-sales-today-row');
            const salesAmount = document.getElementById('dashboard-sales-today-amount');
            if (salesRow && salesAmount) {
                salesRow.classList.toggle('hidden', dashboardSalesToday === null);
                salesAmount.textContent = dashboardSalesToday === null ? '' : formatCurrency(dashboardSalesToday);
            }
            renderDashboardNetProfit();
            // Sales Today / Net Profit now live in the Business Day bar. Hide the
            // whole metrics group (and its separators) when neither value is
            // available, so the bar stays clean rather than showing an empty rail.
            const metricsWrap = document.getElementById('business-day-metrics');
            if (metricsWrap) metricsWrap.classList.toggle('hidden', dashboardSalesToday === null && dashboardTodayProfit === null);
        }

        function renderBusinessBriefDashboard() {
            const container = document.getElementById('business-brief-dashboard-content');
            if (!container) return;
            renderDashboardContext();
            if (!hasAuthenticatedBusinessContext()) {
                container.innerHTML = businessBriefEmpty('fa-lock', 'Sign in to receive a Business Brain based on your own business activity.');
                return;
            }
            if (dashboardBrainForbiddenMessage) {
                container.innerHTML = `<button type="button" onclick="openBillingModal()" class="business-brief-upgrade">${brainEsc(t("businessBrain.upgradeToUnlock"))}</button>`;
                return;
            }
            const attention = getBusinessBriefAttentionItems();
            const coming = businessBrainData?.coming || [];
            const recommendations = getBusinessBriefRecommendationItems();
            // Always the same four sections - never collapsed into one summary
            // message. An empty section shows an honest state; it is never hidden,
            // merged, or filled with fabricated data.
            const attentionBody = attention.length
                ? attention.slice(0, 2).map(row => businessBriefSignalRow(row, true)).join('') + businessBriefMore(attention.length)
                : businessBriefEmpty('fa-circle-check', t("businessBrain.dashAttentionEmpty"), 'text-success');
            const comingBody = coming.length
                ? coming.slice(0, 2).map(row => businessBriefSignalRow({ priority:'opportunity', icon:'fa-calendar-days', title:`${row.product_name}: about ${row.predicted_units} units`, summary:`By ${formatBusinessDate(row.target_at, {dateStyle:'medium'})} · ${row.confidence}` }, true)).join('') + businessBriefMore(coming.length)
                : businessBriefEmpty('fa-seedling', t("businessBrain.dashComingEmpty"), 'text-primary');
            const recommendationBody = recommendations.length
                ? recommendations.slice(0, 2).map(row => businessBriefSignalRow(row, true)).join('') + businessBriefMore(recommendations.length)
                : businessBriefEmpty('fa-circle-info', t("businessBrain.dashRecommendEmpty"));
            const learningBody = businessBriefEmpty('fa-chart-simple', getBusinessBriefLearningSummary(), businessBrainData?.learning ? 'text-primary' : 'text-textSec');
            container.innerHTML = [
                businessBriefDashCard(t("businessBrain.needsYourAttention"), 'fa-bell', attention.length ? 'text-warning' : 'text-success', attentionBody, { open: attention.length > 0, hint: attention.length ? String(attention.length) : '' }),
                businessBriefDashCard(t("businessBrain.comingUp"), 'fa-calendar-days', 'text-primary', comingBody, { hint: coming.length ? String(coming.length) : '' }),
                businessBriefDashCard(t("businessBrain.cauldraRecommends"), 'fa-lightbulb', 'text-success', recommendationBody, { hint: recommendations.length ? String(recommendations.length) : '' }),
                businessBriefDashCard(t("businessBrain.whatCauldraIsLearning"), 'fa-chart-simple', 'text-primary', learningBody, {}),
            ].join('');
        }

        // Existing data-load call sites keep these compatibility wrappers. Both
        // now refresh the one Business Brain instead of separate dashboard cards.
        function renderNeedsAttention() { renderBusinessBriefDashboard(); }
        function renderBusinessInsights() { renderBusinessBriefDashboard(); }

        function renderDashboardNetProfit() {
            const row = document.getElementById('dashboard-net-profit-row');
            const amountEl = document.getElementById('dashboard-net-profit-amount');
            if (!row || !amountEl) return;
            row.classList.toggle('hidden', dashboardTodayProfit === null);
            amountEl.className = dashboardTodayProfit > 0 ? 'text-success' : (dashboardTodayProfit < 0 ? 'text-danger' : 'text-textMain');
            amountEl.textContent = dashboardTodayProfit === null ? '' : formatCurrency(dashboardTodayProfit);
        }

        // Reuses the existing role-scoped reopen-requests endpoint (Admin
        // sees every pending request on the business, Manager only their
        // own) purely to surface a count in Needs Attention — no new
        // endpoint, no duplicate fetch logic.
        let dashboardPendingReopenCount = 0;
        async function checkPendingReopenCountForDashboard() {
            dashboardPendingReopenCount = 0;
            if (hasAuthenticatedBusinessContext() && ['admin', 'manager'].includes(getCurrentRole())) {
                try { dashboardPendingReopenCount = (await fetchPendingReopenRequests()).length; } catch (_) {}
            }
            renderNeedsAttention();
        }

        async function openBusinessBrainModal() {
            const modal = document.getElementById('business-brain-modal');
            modal.classList.remove('hidden');
            document.getElementById('business-brain-loading').classList.remove('hidden');
            document.getElementById('business-brain-body').classList.add('hidden');
            businessBriefHistoryFilter = 'all';
            businessBriefHistory = { type: 'all', range: 'all', items: [], offset: 0, hasMore: false, loading: false, loaded: false };
            try { renderBusinessBrain(await fetchBusinessBrain(), 'overview'); }
            catch (err) { document.getElementById('business-brain-loading').textContent = err.message || t("businessBrain.temporarilyUnavailable"); }
        }

        function closeBusinessBrainModal() { document.getElementById('business-brain-modal').classList.add('hidden'); }
        function switchBusinessBrainTab(tab) {
            if (!businessBrainData) return;
            if (tab === 'history' && !businessBriefHistory.loaded && !businessBriefHistory.loading) { loadBusinessBriefHistory(true); return; }
            renderBusinessBrain(businessBrainData, tab);
        }

        function businessBriefRecommendationCard(row, staff) {
            const isActed = row.status === 'acted';
            const controls = staff ? '' : `<div class="business-brief-row-actions">${isActed ? '<span class="text-success"><i class="fa-solid fa-check mr-1"></i>Action recorded</span>' : `<button type="button" onclick="updateBusinessBrainRecommendation(${Number(row.id)},'acted')">${t("businessBrain.markActionTaken")}</button>`}<button type="button" class="is-muted" onclick="updateBusinessBrainRecommendation(${Number(row.id)},'dismissed')">${t("businessBrain.dismiss")}</button></div>`;
            return `<article class="business-brief-detail-row"><div class="business-brief-detail-heading"><div><strong>${brainEsc(row.title)}</strong><p>${brainEsc(row.summary)}</p></div><span class="business-brief-priority ${brainPriorityClass(row.priority)}">${brainEsc(row.priority)}</span></div>${controls}</article>`;
        }

        function renderBusinessBriefOverview(data, staff) {
            const attentionRows = getBusinessBriefAttentionItems(data);
            const recommendationRows = getBusinessBriefRecommendationItems(data);
            const attentionBody = attentionRows.length ? attentionRows.slice(0, 4).map(row => row.id ? businessBriefRecommendationCard(row, staff) : businessBriefSignalRow(row)).join('') : businessBriefEmpty('fa-circle-check', t("businessBrain.healthyState"), 'text-success');
            const comingBody = staff ? businessBriefEmpty('fa-lock', 'Forecasts are available to Admins and Managers.') : (data.coming || []).slice(0, 4).map(row => `<article class="business-brief-detail-row"><strong>${brainEsc(row.product_name)} · about ${brainEsc(row.predicted_units)} units</strong><p>${brainEsc(row.confidence)} · target ${brainEsc(formatBusinessDate(row.target_at, {dateStyle:'medium'}))}</p></article>`).join('') || businessBriefEmpty('fa-calendar-check', t("businessBrain.noComingUp"));
            const recommendationBody = recommendationRows.length ? recommendationRows.slice(0, 4).map(row => row.id ? businessBriefRecommendationCard(row, staff) : businessBriefSignalRow(row)).join('') : businessBriefEmpty('fa-circle-check', t("businessBrain.noCurrentRecommendation"), 'text-success');
            const learningBody = businessBriefEmpty(data.learning ? 'fa-seedling' : 'fa-chart-simple', getBusinessBriefLearningSummary(data), data.learning ? 'text-primary' : 'text-textSec');
            return `<div class="business-brief-overview-grid">${businessBriefCard(t("businessBrain.needsYourAttention"), 'fa-bell', attentionRows.length ? 'text-warning' : 'text-success', attentionBody)}${businessBriefCard(t("businessBrain.comingUp"), 'fa-calendar-days', 'text-primary', comingBody)}${businessBriefCard(t("businessBrain.cauldraRecommends"), 'fa-lightbulb', 'text-success', recommendationBody)}${businessBriefCard(t("businessBrain.whatCauldraIsLearning"), 'fa-chart-simple', 'text-primary', learningBody)}</div>`;
        }

        // Durable, reusable business knowledge — never an archive of every message.
        // The engine dedupes by fingerprint (one row per pattern, reinforced in
        // place), and withdraws a memory when its evidence is withdrawn, so this
        // only has to present what is currently on file.
        function businessBriefMemoryCategory(row) {
            const evidence = row.evidence || {};
            if (evidence.product_a && evidence.product_b) return {key:'products', label:t("businessBrain.memoryProductRelationships"), icon:'fa-link'};
            if (evidence.week_of_year || evidence.cycles_observed) return {key:'seasonality', label:t("businessBrain.memorySeasonalPatterns"), icon:'fa-calendar'};
            if (evidence.average_daily_units != null || evidence.units_sold != null) return {key:'sales', label:t("businessBrain.memorySalesPatterns"), icon:'fa-chart-line'};
            return {key:'other', label:t("businessBrain.memoryOther"), icon:'fa-note-sticky'};
        }

        function renderBusinessBriefMemory(data) {
            const rows = data.memory || [];
            if (!rows.length) return businessBriefEmpty('fa-seedling', data.learning ? (data.learning_message || t("businessBrain.stillLearning")) : t("businessBrain.needMoreHistoryMemory"));
            const groups = new Map();
            rows.forEach(row => {
                const category = businessBriefMemoryCategory(row);
                if (!groups.has(category.key)) groups.set(category.key, {category, rows:[]});
                groups.get(category.key).rows.push(row);
            });
            const memRow = row => {
                const badge = row.reinforced ? `<span class="business-brief-mem-badge" title="${brainEsc(t("businessBrain.memoryUpdated"))}">${brainEsc(t("businessBrain.memoryReinforced"))}</span>` : '';
                return `<article class="business-brief-detail-row"><div class="business-brief-detail-heading"><strong>${brainEsc(row.statement)}</strong>${badge}</div><p>${brainEsc(row.confidence)} · last observed ${brainEsc(formatBusinessDate(row.last_observed_at, {dateStyle:'medium'}))}</p></article>`;
            };
            return `<div class="business-brief-memory-groups">${Array.from(groups.values()).map(group => `<section class="business-brief-memory-group"><h4><i class="fa-solid ${group.category.icon} text-primary"></i>${brainEsc(group.category.label)}</h4>${group.rows.map(memRow).join('')}</section>`).join('')}</div>`;
        }

        function renderBusinessBriefOutcomes(data) {
            const o = data.outcomes || {};
            const trendText = o.accuracy_trend === 'improving' ? t("businessBrain.accuracyImproving") : o.accuracy_trend === 'declining' ? t("businessBrain.accuracyDeclining") : '';
            const forecastText = o.accuracy == null ? (o.message || t("businessBrain.noForecastPeriods")) : tPlural("businessBrain.forecastSummary", o.evaluated_predictions, {accuracy:o.accuracy, trend:trendText ? ` · ${trendText}` : ''});
            const impact = [];
            if (o.actions_taken > 0) impact.push(tPlural("businessBrain.recommendationsActedOn", o.actions_taken));
            if (o.revenue_at_risk != null && o.revenue_at_risk > 0) impact.push(t("businessBrain.revenueAtRisk", {amount:formatCurrency(o.revenue_at_risk)}));
            return `<section class="business-brief-outcomes"><h4><i class="fa-solid fa-bullseye text-primary"></i>${brainEsc(t("businessBrain.tabOutcomes"))}</h4><p>${brainEsc(forecastText)}</p>${impact.length ? `<p>${brainEsc(impact.join(' '))}</p>` : ''}</section>`;
        }

        async function loadBusinessBriefHistory(reset) {
            if (businessBriefHistory.loading) return;
            businessBriefHistory.loading = true;
            if (reset) { businessBriefHistory.offset = 0; businessBriefHistory.items = []; businessBriefHistory.hasMore = false; }
            if (businessBrainData) renderBusinessBrain(businessBrainData, 'history');
            try {
                const p = new URLSearchParams({ type: businessBriefHistory.type, range: businessBriefHistory.range, offset: String(businessBriefHistory.offset), limit: '20' });
                const res = await fetch(`${API_URL}/business-brain/history?${p.toString()}`, { credentials:'include', headers:{ 'Authorization':`Bearer ${authToken}`, 'Accept':'application/json' } });
                if (!res.ok) throw new Error();
                const d = await res.json();
                const batch = Array.isArray(d.events) ? d.events : [];
                businessBriefHistory.items = businessBriefHistory.items.concat(batch);
                businessBriefHistory.offset += batch.length;
                businessBriefHistory.hasMore = !!d.has_more;
                businessBriefHistory.loaded = true;
            } catch (_) { showToast(t("businessBrain.historyLoadFailed"), 'error'); }
            finally { businessBriefHistory.loading = false; if (businessBrainData) renderBusinessBrain(businessBrainData, 'history'); }
        }

        function setBusinessBriefHistoryFilter(type) {
            businessBriefHistory.type = ['all','attention','recommendations','predictions'].includes(type) ? type : 'all';
            loadBusinessBriefHistory(true);
        }
        function setBusinessBriefHistoryRange(range) {
            businessBriefHistory.range = ['all','week','month','quarter','year'].includes(range) ? range : 'all';
            loadBusinessBriefHistory(true);
        }

        function businessBriefHistoryRowMarkup(row) {
            const icon = row.type === 'forecast' ? 'fa-chart-line' : 'fa-lightbulb';
            const outcome = row.outcome ? `<span class="business-brief-history-outcome outcome-${String(row.outcome).toLowerCase().replace(/[^a-z]+/g,'-')}">${brainEsc(row.outcome)}</span>` : '';
            return `<article class="business-brief-history-row"><span class="business-brief-history-icon"><i class="fa-solid ${icon}"></i></span><div><div class="business-brief-history-meta"><span>${brainEsc(row.category || row.type)}</span><time>${brainEsc(formatBusinessDate(row.occurred_at, {dateStyle:'medium'}))}</time></div><strong>${brainEsc(row.title)}</strong><p>${brainEsc(row.summary)}</p>${outcome}</div></article>`;
        }

        function renderBusinessBriefHistory(data, staff) {
            const typeFilters = [
                {id:'all', label:t("businessBrain.historyAll")},
                {id:'attention', label:t("businessBrain.historyAttention")},
                ...(staff ? [] : [{id:'recommendations', label:t("businessBrain.historyRecommendations")}, {id:'predictions', label:t("businessBrain.historyPredictions")}]),
            ];
            const ranges = [
                {id:'all', label:t("businessBrain.rangeAll")}, {id:'week', label:t("businessBrain.rangeWeek")},
                {id:'month', label:t("businessBrain.rangeMonth")}, {id:'quarter', label:t("businessBrain.rangeQuarter")},
                {id:'year', label:t("businessBrain.rangeYear")},
            ];
            const chips = `<div class="business-brief-history-filters" role="group" aria-label="Filter Business Brain history">${typeFilters.map(f => `<button type="button" class="${businessBriefHistory.type === f.id ? 'is-active' : ''}" onclick="setBusinessBriefHistoryFilter('${f.id}')">${brainEsc(f.label)}</button>`).join('')}</div>`;
            const rangeSel = `<label class="business-brief-history-range"><span>${brainEsc(t("businessBrain.historyPeriod"))}</span><select onchange="setBusinessBriefHistoryRange(this.value)">${ranges.map(r => `<option value="${r.id}"${businessBriefHistory.range === r.id ? ' selected' : ''}>${brainEsc(r.label)}</option>`).join('')}</select></label>`;
            const items = businessBriefHistory.items;
            let body;
            if (businessBriefHistory.loading && !items.length) body = businessBriefEmpty('fa-spinner fa-spin', t("businessBrain.historyLoading"));
            else if (!items.length) body = businessBriefEmpty('fa-clock-rotate-left', t("businessBrain.historyEmpty"));
            else {
                const older = businessBriefHistory.hasMore
                    ? `<button type="button" class="business-brief-more" onclick="loadBusinessBriefHistory(false)"${businessBriefHistory.loading ? ' disabled' : ''}>${brainEsc(businessBriefHistory.loading ? t("businessBrain.historyLoading") : t("businessBrain.loadOlder"))} <span aria-hidden="true">↓</span></button>`
                    : '';
                body = `<div class="business-brief-history-list">${items.map(businessBriefHistoryRowMarkup).join('')}</div>${older}`;
            }
            return `<div class="business-brief-history-controls">${chips}${rangeSel}</div>${body}${staff ? '' : renderBusinessBriefOutcomes(data)}`;
        }

        function renderBusinessBrain(data, tab = 'overview') {
            document.getElementById('business-brain-loading').classList.add('hidden');
            document.getElementById('business-brain-body').classList.remove('hidden');
            const staff = getCurrentRole() === 'staff';
            document.querySelector('#business-brain-tabs [data-tab="memory"]')?.classList.toggle('hidden', staff);
            if (staff && tab === 'memory') tab = 'overview';
            document.querySelectorAll('.brain-tab-btn').forEach(btn => {
                const active = btn.dataset.tab === tab;
                btn.classList.toggle('is-active', active);
                btn.setAttribute('aria-selected', String(active));
            });
            const content = document.getElementById('business-brain-content');
            content.innerHTML = tab === 'memory' ? renderBusinessBriefMemory(data) : tab === 'history' ? renderBusinessBriefHistory(data, staff) : renderBusinessBriefOverview(data, staff);
        }

        async function updateBusinessBrainRecommendation(id, action) {
            try {
                const res = await fetch(`${API_URL}/business-brain/recommendations/${id}/action`, {method:'POST', credentials:'include', headers:{'Authorization':`Bearer ${authToken}`, 'Content-Type':'application/json'}, body:JSON.stringify({action})});
                if (!res.ok) throw new Error();
                renderBusinessBrain(await fetchBusinessBrain(), 'overview');
                renderBusinessBriefDashboard();
            } catch (_) { showToast(t("businessBrain.updateRecommendationFailed"), 'error'); }
        }

        // loadData() is called from many places besides page load (after
        // creating/editing a product, after a sale, the sidebar Refresh
        // action, etc.) — see the many call sites throughout this
        // file. The loadDataInFlight guard below ensures two overlapping
        // calls (e.g. the initial page-load call and a mutation's post-save
        // refresh firing around the same time) share one in-flight run
        // instead of starting a second, competing one that could race the
        // first and overwrite its results with an older response.
        async function loadData(options) {
            if (loadDataInFlight) return loadDataInFlight;
            loadDataInFlight = runLoadData(options);
            try {
                return await loadDataInFlight;
            } finally {
                loadDataInFlight = null;
            }
        }

        // The sidebar Refresh action: a genuine full authenticated data
        // refresh (the same concurrent core+readiness pipeline a browser
        // reload runs), not a page reload and not a single-card refresh. It
        // deliberately reuses loadData() as-is rather than reimplementing
        // anything, so:
        //   - the loadDataInFlight guard already prevents this from ever
        //     running two overlapping refreshes, even if clicked repeatedly
        //     or while a reload-triggered load is still in flight;
        //   - authentication is untouched — authToken is already present, so
        //     this never goes anywhere near refreshAccessTokenAtStartup()'s
        //     cold-start path, the refresh-token cookie, or its rotation;
        //   - the same loading banner + inventory skeleton + "—" placeholder
        //     machinery applies, just forced visible via
        //     forceShowLoadingBanner so an explicit user-requested refresh is
        //     never silently invisible.
        async function handleManualRefreshClick() {
            document.querySelectorAll('[data-refresh-action]').forEach(btn => { btn.disabled = true; });
            try {
                await loadData({ forceShowLoadingBanner: true });
            } finally {
                document.querySelectorAll('[data-refresh-action]').forEach(btn => { btn.disabled = false; });
            }
        }

        async function runLoadData(options) {
            const forceShowLoadingBanner = !!(options && options.forceShowLoadingBanner);
            document.querySelectorAll('[data-refresh-action] i').forEach(icon => icon.classList.add('fa-spin'));
            // The reassuring "Loading your Cauldra data…" banner is shown for
            // this session's genuine first load (a real page reload, or the
            // first sign-in) — a later, purely automatic background refresh
            // (the 10-minute heartbeat, a visibilitychange-triggered check)
            // must not flash it again over data the user is already looking
            // at. An explicit user-triggered refresh (the sidebar Refresh
            // button, via forceShowLoadingBanner) is the deliberate exception:
            // the user asked for a full data refresh and must see it happen,
            // not be left wondering whether anything occurred.
            const isColdStart = !coreDataEverLoaded || forceShowLoadingBanner;
            const loadingBanner = document.getElementById("global-loading-banner");
            if (isColdStart) {
                loadingBanner?.classList.remove("hidden");
                // Restore the banner's normal reassuring text in case an
                // earlier attempt on this same page load left it showing the
                // "still trying to reach the server" message below — but only
                // when this run isn't itself one of that reconnect retry's
                // own cycles, otherwise the text would flip back to the
                // default for a moment on every retry before flipping back
                // again once refreshAccessTokenAtStartup() fails again.
                if (startupReconnectAttempts === 0) {
                    const bannerSpan = loadingBanner?.querySelector("span");
                    if (bannerSpan) {
                        if (!bannerSpan.dataset.defaultText) bannerSpan.dataset.defaultText = bannerSpan.textContent;
                        bannerSpan.textContent = bannerSpan.dataset.defaultText;
                    }
                }
            }
            // Only set true when this call deliberately stays in a
            // "reconnecting to the backend" state (see the unreachable-branch
            // return below) — otherwise the finally block's safety net must
            // still always hide the banner as before.
            let keepLoadingUIForReconnect = false;
            try {
                // Silent page-refresh recovery: the HttpOnly refresh cookie is sent to the backend.
                // The user is not asked to log in again while the backend refresh session is valid.
                if (!authToken) {
                    const startupOutcome = await refreshAccessTokenAtStartup();
                    if (startupOutcome === "unreachable") {
                        // The backend could not be reached at all (e.g.
                        // ERR_CONNECTION_REFUSED) even after retrying — this is
                        // a connectivity problem, not the backend saying the
                        // session is invalid. Do NOT fall through to the
                        // guest/logged-out rendering below: keep the loading
                        // banner + inventory skeleton up and retry again
                        // shortly, so a legitimately authenticated user is
                        // never shown a false logout just because the backend
                        // hasn't finished starting up yet.
                        keepLoadingUIForReconnect = true;
                        showStartupConnectionIssue(loadingBanner);
                        scheduleStartupReconnectRetry();
                        return;
                    }
                    startupReconnectAttempts = 0;
                }
                if (authToken && !(await validateAuthenticationSession())) {
                    if (!authToken) {
                        // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) --
                        console.log(`[auth-diag-frontend] runLoadData() EARLY RETURN: authToken empty after failed validateAuthenticationSession()`);
                        // --- END TEMPORARY DEV DIAGNOSTIC -----------------------------
                        updateDashboardMetrics();
                        renderInventoryTable([]);
                        return;
                    }
                }
                // --- TEMPORARY DEV DIAGNOSTIC (reload-logout investigation) ---------
                // The state of the world right after auth is established/checked,
                // before any business data is fetched — the key checkpoint for
                // telling "auth never succeeded" apart from "auth succeeded, then
                // something later cleared it".
                console.log(`[auth-diag-frontend] runLoadData() POST-AUTH-CHECKPOINT authTokenPresent=${!!authToken} currentUserProfilePresent=${!!currentUserProfile} username=${currentUserProfile?.username}`);
                // --- END TEMPORARY DEV DIAGNOSTIC ------------------------------------
                const headers = authToken ? { "Authorization": `Bearer ${authToken}`, "Accept": "application/json" } : {};
                if (!authToken) {
                    globalProducts = []; globalSuppliers = []; warehouseRecords = []; customWarehouses = [];
                    productsSuppliersReady = true; warehousesReady = true; inventoryEverLoaded = true; coreDataEverLoaded = true;
                    updateDashboardMetrics(); updateWarehouseUIElements(); renderInventoryTable([]);
                    renderAuthButton(); updateGuestHeaderState(); renderMobileNav();
                    return;
                }
                const [productRes, supplierRes] = await Promise.all([
                    fetch(`${API_URL}/products/?limit=500&offset=0`, { credentials: "include", headers }),
                    fetch(`${API_URL}/suppliers/?limit=500&offset=0`, { credentials: "include", headers })
                ]);
                if (productRes.status === 401 || supplierRes.status === 401) { handleAuthenticationFailure(); return; }
                globalProducts = productRes.ok ? await productRes.json() : [];
                globalSuppliers = supplierRes.ok ? await supplierRes.json() : [];
                productsSuppliersReady = true;
                // Server data is now authoritative for this business — refresh
                // the offline read cache so viewing/selling can continue from
                // this snapshot the next time the network is unavailable.
                cacheProductsLocally(globalProducts);
                cacheSuppliersLocally(globalSuppliers);
                // Re-attach any products created offline that haven't synced
                // yet — a fresh page load otherwise wouldn't know they exist,
                // even though their outbox entry (the durable record) survived.
                await restorePendingLocalProductsFromOutbox();
                // Core product/supplier counts can be shown immediately;
                // warehouse count still shows its own "—" until loadWarehouses()
                // (below, running concurrently) resolves.
                updateDashboardMetrics();

                selectedWarehouseFilter = document.getElementById("warehouse-filter")?.value || selectedWarehouseFilter || "ALL";

                // --- Core batch -------------------------------------------------
                // loadWarehouses() and loadInventoryView() are independent of
                // each other: loadInventoryView() fetches its own product and
                // summary data directly from the server rather than relying on
                // warehouseRecords/customWarehouses, so neither has to wait for
                // the other. Both are started together.
                //
                // --- Readiness batch ---------------------------------------------
                // Subscription usage, financial health, profit, Business Brain,
                // pending account-action requests, notifications, and activity
                // history (the last self-gates to admin/manager, same as the
                // modal it backs) are each independent sections — none of them
                // reads products/suppliers/warehouses/inventory state, and each
                // already renders directly into its own section/modal of the
                // page and handles its own errors internally (a failure in one
                // never throws out to here or blocks the others). They're
                // started at the same time as the core batch, not queued behind
                // it — Promise.allSettled() means one slow/failing section can't
                // hang the rest.
                //
                // These are exactly the sections a user can jump straight into
                // right after a reload (Notifications, Activity History,
                // Subscription Plan, dashboards) — so unlike a purely
                // "secondary" batch, this one IS awaited, together with the
                // core batch, before the app is allowed to report itself ready
                // (banner hidden below). Hiding the banner earlier would let
                // the user open one of these while it's still silently
                // fetching, which is the exact misleading state this is meant
                // to prevent.
                const coreBatch = Promise.all([loadWarehouses(), loadInventoryView()]);
                const readinessBatch = Promise.allSettled([
                    checkSubscriptionWarningForDashboard(),
                    checkPendingReopenCountForDashboard(),
                    loadFinancialHealthCards(),
                    loadProfitDashboardCards(),
                    loadBusinessBrainDashboard(),
                    renderAccountActionRequests(),
                    renderAlerts(),
                    populateAuditLogFilterOptions(),
                    renderAuditLog(),
                ]);

                await Promise.all([coreBatch, readinessBatch]);
                coreDataEverLoaded = true;
                loadingBanner?.classList.add("hidden");

                updateWelcomeBanner();
                updateCompanyHeaderDisplay();
                updateGuestHeaderState();
                scheduleSyncSoon();
            } catch (err) {
                // Could not reach the server for a fresh snapshot — rather than
                // wiping the screen blank, fall back to whatever was cached
                // locally from the last successful load (IndexedDB), so
                // previously-synchronized business data stays visible offline.
                try {
                    const cachedProducts = await getCachedProducts();
                    const cachedSuppliers = await getCachedSuppliers();
                    globalProducts = cachedProducts;
                    globalSuppliers = cachedSuppliers;
                } catch (_) {
                    globalProducts = Array.isArray(globalProducts) ? globalProducts : [];
                    globalSuppliers = Array.isArray(globalSuppliers) ? globalSuppliers : [];
                }
                productsSuppliersReady = true;
                warehousesReady = true;
                inventoryEverLoaded = true;
                await restorePendingLocalProductsFromOutbox();
                updateDashboardMetrics();
                updateWarehouseUIElements();
                refreshInventoryViewFromLocalState();
                setSyncStatus("offline");
            } finally {
                // Unconditional safety net: whichever way this call ends —
                // success, a guest/no-session early return, a mid-load 401,
                // or the network-failure catch above — the banner must never
                // be left stuck on screen. (coreDataEverLoaded itself is set
                // deliberately at each specific success point above rather
                // than here, so a hard failure correctly leaves it false and
                // the next attempt still gets the reassuring cold-start
                // treatment instead of silently skipping it forever.)
                // The one deliberate exception: the "backend unreachable,
                // retrying shortly" path above sets keepLoadingUIForReconnect
                // so the banner/skeleton stay visible instead of being wiped
                // right back out a moment after showStartupConnectionIssue()
                // put them up.
                if (!keepLoadingUIForReconnect) loadingBanner?.classList.add("hidden");
                setTimeout(() => {
                    document.querySelectorAll('[data-refresh-action] i').forEach(icon => icon.classList.remove('fa-spin'));
                }, 500);
            }
        }

        function updateWarehouseUIElements() {
            const selectFilter = document.getElementById("warehouse-filter");
            const selectModal = document.getElementById("p-warehouse");
            const optionsHtml = `<option value="ALL">All Warehouses</option>` + customWarehouses.map(w => `<option value="${escapeEmployeeHtml(w)}">${escapeEmployeeHtml(w)}</option>`).join("");
            const modalOptionsHtml = customWarehouses.map(w => `<option value="${escapeEmployeeHtml(w)}">${escapeEmployeeHtml(w)}</option>`).join("");
            if (selectFilter) { selectFilter.innerHTML = optionsHtml; selectFilter.value = customWarehouses.includes(selectedWarehouseFilter) ? selectedWarehouseFilter : "ALL"; }
            if (selectModal) selectModal.innerHTML = modalOptionsHtml;
        }

        async function filterInventoryByWarehouse() {
            selectedWarehouseFilter = document.getElementById("warehouse-filter")?.value || "ALL";
            await loadInventoryView();
        }

        function updateInventoryStatusUI() {
            const hc=document.getElementById('inventory-healthy-count'), lc=document.getElementById('inventory-low-count'), oc=document.getElementById('inventory-out-count');
            if(hc) hc.textContent=inventoryStatusCounts.healthy ?? 0;
            if(lc) lc.textContent=inventoryStatusCounts.low ?? 0;
            if(oc) oc.textContent=inventoryStatusCounts.out ?? 0;
            document.querySelectorAll('.inventory-status-filter').forEach(btn=>btn.classList.toggle('is-active', btn.dataset.status===inventoryStatusFilter));
            const chip=document.getElementById('inventory-status-chip');
            if(chip){
                const label={healthy:'Healthy',low:'Low Stock',out:'Out of Stock'}[inventoryStatusFilter];
                if(label){ chip.classList.add('show'); chip.innerHTML=`<span>Showing: ${label}</span><button type="button" aria-label="Clear stock filter" onclick="clearInventoryStatusFilter()">✕</button>`; }
                else { chip.classList.remove('show'); chip.innerHTML=''; }
            }
        }

        async function toggleInventoryStatusFilter(status) {
            inventoryStatusFilter = inventoryStatusFilter === status ? null : status;
            await loadInventoryView();
        }

        async function clearInventoryStatusFilter() {
            inventoryStatusFilter = null;
            await loadInventoryView();
        }

        // Used by the "Needs Attention" dashboard card to jump straight into
        // Inventory pre-filtered — sets (never toggles) the filter, since the
        // user's intent from a dashboard click is always "show me these",
        // not "flip whatever was already selected".
        async function focusInventoryStatusFromDashboard(status) {
            if (inventoryStatusFilter !== status) {
                inventoryStatusFilter = status;
                await loadInventoryView();
            }
            document.getElementById('inventory-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function renderInventoryTable(productsToRender) {
            closeRowActionMenu();
            const tbody = document.getElementById("inventory-table-body");

            // Low/out-of-stock counts are already shown by the inventory
            // status row directly below (Healthy/Low Stock/Out of Stock) and
            // by the Needs Attention card above — no separate banner here,
            // that would just be the same number a third time (see dashboard
            // decluttering: duplicate low-stock presentation). Needs
            // Attention is kept in sync from this exact point, since this is
            // the one place inventoryStatusCounts is guaranteed current.
            renderNeedsAttention();

            if (!productsToRender || !productsToRender.length) {
                if (!hasAuthenticatedBusinessContext()) {
                    tbody.innerHTML = `<tr><td colspan="6" class="text-center py-16">
                        <div class="flex flex-col items-center gap-2.5">
                            <i class="fa-solid fa-boxes-stacked text-3xl text-textSec/40"></i>
                            <div class="text-textMain font-semibold text-sm">Sign in to see your inventory</div>
                            <div class="text-textSec text-xs max-w-xs">Register your business or sign in to start tracking products, stock levels, and sales.</div>
                            <button type="button" onclick="openBusinessAuthModal()" class="mt-1 text-primary hover:underline font-semibold text-xs cursor-pointer">Get Started →</button>
                        </div>
                    </td></tr>`;
                } else {
                    tbody.innerHTML = `<tr><td colspan="6" class="text-center py-16">
                        <div class="flex flex-col items-center gap-2.5">
                            <i class="fa-solid fa-box-open text-3xl text-textSec/40"></i>
                            <div class="text-textMain font-semibold text-sm">No products found in inventory.</div>
                            <div class="text-textSec text-xs max-w-xs">Add your first product to start tracking stock levels and sales.</div>
                        </div>
                    </td></tr>`;
                }
                return;
            }

            tbody.innerHTML = productsToRender.map(product => {
                const isOut = product.quantity === 0;
                const isLow = product.quantity <= product.min_stock_level && !isOut;
                
                let dotColor = "bg-success";
                let textColor = "text-success";
                if (isOut) { dotColor = "bg-danger"; textColor = "text-danger"; }
                else if (isLow) { dotColor = "bg-warning"; textColor = "text-warning"; }

                return `
                    <tr class="hover:bg-cardHover/60 transition group">
                        <td class="py-3 px-3">
                            <div class="font-bold text-textMain">${escapeHtml(product.name)} ${product.size ? `<span class="text-textSec text-[10px]">(${escapeHtml(product.size)})</span>` : ''}</div>
                            <div class="text-[10px] font-mono text-textSec">${escapeHtml(product.sku)} | <span class="text-primary">${escapeHtml(product.category)}</span></div>
                        </td>
                        <td class="py-3 px-3">
                            <span class="px-2 py-0.5 rounded-lg bg-bgMain border border-borderCol text-[11px] font-medium text-textSec">${escapeHtml(product.warehouse) || 'Main Warehouse'}</span>
                        </td>
                        <td class="py-3 px-3">
                            <div class="flex items-center gap-2">
                                <span class="w-2 h-2 rounded-full ${dotColor}"></span>
                                <span class="font-mono font-bold ${textColor}">${product.quantity}</span>
                                <span class="text-[10px] text-textSec font-mono">/ min ${product.min_stock_level}</span>
                            </div>
                        </td>
                        <td class="py-3 px-3 font-mono font-medium text-textMain">${formatCurrency(product.wholesale_price || product.retail_price * 0.85)}</td>
                        <td class="py-3 px-3 font-mono font-semibold text-success">${formatCurrency(product.retail_price)}</td>
                        <td class="py-3 px-3 text-right">
                            <div class="flex items-center justify-end">
                                <button type="button" onclick="toggleRowActionMenu(event, ${product.id})" class="w-7 h-7 rounded-lg bg-bgMain hover:bg-cardHover border border-borderCol text-textSec hover:text-textMain transition flex items-center justify-center cursor-pointer" title="Actions">
                                    <i class="fa-solid fa-ellipsis-vertical text-[11px]"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join("");
        }

        // Exports exactly the rows currently rendered in the Inventory table
        // (inventoryViewProducts already reflects the active warehouse/status/
        // search filters — see loadInventoryView()), never a fresh unfiltered
        // fetch. Status and Stock Value are derived client-side from real
        // fields (quantity vs. min_stock_level, quantity × cost_price) rather
        // than invented — Unit and Supplier are intentionally omitted since
        // Product has no unit-of-measure or supplier relationship today.
        // Exports exactly the rows currently rendered in the Inventory table
        // (inventoryViewProducts already reflects the active warehouse/status/
        // search filters — see loadInventoryView()), never a fresh unfiltered
        // fetch. Status and Stock Value are derived client-side from real
        // fields (quantity vs. min_stock_level, quantity × cost_price) rather
        // than invented — Unit and Supplier are intentionally omitted since
        // Product has no unit-of-measure or supplier relationship today.
        function buildInventoryExportSpec() {
            const source = Array.isArray(inventoryViewProducts) ? inventoryViewProducts : [];
            if (!source.length) return null;
            const rows = source.map(p => ({
                sku: p.sku, name: p.name, category: p.category,
                warehouse: p.warehouse || "Main Central Warehouse",
                quantity: p.quantity, min_stock_level: p.min_stock_level,
                status: p.quantity === 0 ? "Out of Stock" : (p.quantity <= p.min_stock_level ? "Low Stock" : "Healthy"),
                cost_price: p.cost_price, wholesale_price: p.wholesale_price, retail_price: p.retail_price,
                stock_value: Math.round((p.quantity || 0) * (p.cost_price || 0) * 100) / 100,
                expiry_date: p.expiry_date || null,
            }));
            return {
                filenameBase: `cauldra_inventory_${csvDateStamp()}`,
                reportTitle: "Cauldra Inventory Report",
                metadata: [
                    ["Generated", new Date().toLocaleString()],
                    ["Warehouse", (selectedWarehouseFilter && selectedWarehouseFilter !== "ALL") ? selectedWarehouseFilter : "All Warehouses"],
                    ["Status Filter", inventoryStatusFilter || "All"],
                ],
                sheets: [{
                    name: "Inventory",
                    columns: [
                        { key: "sku", label: "SKU", type: "text" },
                        { key: "name", label: "Product", type: "text" },
                        { key: "category", label: "Category", type: "text" },
                        { key: "warehouse", label: "Warehouse", type: "text" },
                        { key: "quantity", label: "Quantity", type: "number" },
                        { key: "min_stock_level", label: "Min Stock Level", type: "number" },
                        { key: "status", label: "Status", type: "text" },
                        { key: "cost_price", label: "Cost Price", type: "currency" },
                        { key: "wholesale_price", label: "Wholesale Price", type: "currency" },
                        { key: "retail_price", label: "Retail Price", type: "currency" },
                        { key: "stock_value", label: "Stock Value", type: "currency" },
                        { key: "expiry_date", label: "Expiry Date", type: "date" },
                    ],
                    rows,
                }],
            };
        }
        function exportInventoryCsv() { runCsvExport(buildInventoryExportSpec, "No inventory data available to export."); }
        function exportInventoryExcel(button) { runExcelExport(button, buildInventoryExportSpec, "No inventory data available to export."); }

        // --- Row action menu (kebab): one shared floating menu, positioned per
        // click, used for the inventory table row actions on every screen size ---
        let openRowActionMenuProductId = null;

        function toggleRowActionMenu(event, productId) {
            event.stopPropagation();
            const menu = document.getElementById("row-action-menu");
            if (openRowActionMenuProductId === productId && !menu.classList.contains("hidden")) {
                closeRowActionMenu();
                return;
            }
            const product = globalProducts.find(p => p.id === productId);
            if (!product) return;
            const canEdit = getCurrentRole() !== 'staff';
            const isManager = getCurrentRole() === 'manager';
            menu.innerHTML = `
                <button type="button" onclick="closeRowActionMenu(); adjustQuickStock(${productId}, -1);" class="w-full text-left px-3 py-2 hover:bg-cardHover text-textMain flex items-center gap-2.5 cursor-pointer">
                    <i class="fa-solid fa-minus w-3.5 text-center text-textSec"></i> Decrease Stock
                </button>
                <button type="button" onclick="closeRowActionMenu(); adjustQuickStock(${productId}, 1);" class="w-full text-left px-3 py-2 hover:bg-cardHover text-textMain flex items-center gap-2.5 cursor-pointer">
                    <i class="fa-solid fa-plus w-3.5 text-center text-textSec"></i> Increase Stock
                </button>
                ${canEdit ? `
                <div class="border-t border-borderCol my-1"></div>
                <button type="button" onclick="closeRowActionMenu(); openEditProductModalFromData(${productId});" class="w-full text-left px-3 py-2 hover:bg-cardHover text-primary flex items-center gap-2.5 cursor-pointer">
                    <i class="fa-solid fa-pen-to-square w-3.5 text-center"></i> Edit Item
                </button>
                <button type="button" onclick="closeRowActionMenu(); deleteProduct(${productId});" class="w-full text-left px-3 py-2 hover:bg-cardHover text-danger flex items-center gap-2.5 cursor-pointer">
                    <i class="fa-solid ${isManager ? 'fa-paper-plane' : 'fa-trash-can'} w-3.5 text-center"></i> ${isManager ? 'Request Admin Approval' : 'Delete Item'}
                </button>` : ''}
            `;

            const btn = event.currentTarget;
            const rect = btn.getBoundingClientRect();
            menu.style.top = '-9999px'; menu.style.left = '-9999px';
            menu.classList.remove("hidden");
            const menuRect = menu.getBoundingClientRect();

            let top = rect.bottom + 4;
            let left = rect.right - menuRect.width;
            if (left < 4) left = 4;
            if (left + menuRect.width > window.innerWidth - 4) left = window.innerWidth - menuRect.width - 4;
            if (top + menuRect.height > window.innerHeight - 4) top = rect.top - menuRect.height - 4;
            if (top < 4) top = 4;

            menu.style.top = `${top}px`;
            menu.style.left = `${left}px`;
            openRowActionMenuProductId = productId;
        }

        function closeRowActionMenu() {
            const menu = document.getElementById("row-action-menu");
            if (!menu) return;
            menu.classList.add("hidden");
            menu.innerHTML = "";
            openRowActionMenuProductId = null;
        }

        document.addEventListener("click", (event) => {
            const menu = document.getElementById("row-action-menu");
            if (menu && !menu.classList.contains("hidden") && !menu.contains(event.target)) closeRowActionMenu();
        });
        document.addEventListener("scroll", () => closeRowActionMenu(), true);
        window.addEventListener("resize", () => closeRowActionMenu());
        document.addEventListener("keydown", (event) => { if (event.key === "Escape") closeRowActionMenu(); });

        async function adjustQuickStock(productId, change) {
            if (!authToken) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            try {
                const res = await fetch(`${API_URL}/products/${productId}/stock`, {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ quantity_change: change, action_type: change > 0 ? "RESTOCK" : "ADJUSTMENT" })
                });
                if (res.ok) {
                    playSuccessBeep();
                    loadData();
                } else {
                    const data = await res.json();
                    showToast(data.detail || t("products.updateStockDetailFailed"), "error");
                }
            } catch (err) {
                showToast(t("products.updateStockFailed"), "error");
            }
        }

        async function handleCreateProduct(event) {
            event.preventDefault();
            if (!authToken) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            const name = document.getElementById("p-name").value.trim();
            const category = document.getElementById("p-category").value.trim();
            const size = document.getElementById("p-size") ? document.getElementById("p-size").value.trim() : "";
            const sku = document.getElementById("p-sku").value.trim() || `SKU-${Math.floor(1000 + Math.random() * 9000)}`;
            const barcode = document.getElementById("barcode-input").value.trim() || null;
            const quantity = parseInt(document.getElementById("p-qty").value) || 0;
            const min_stock_level = parseInt(document.getElementById("p-min").value) || 0;
            const cost_price = parseFloat(document.getElementById("p-cost").value) || 0.0;
            const retail_price = parseFloat(document.getElementById("p-retail").value) || 0.0;
            const wholesale_price = parseFloat(document.getElementById("p-wholesale").value) || retail_price * 0.85;
            const warehouse = document.getElementById("p-warehouse").value;
            const expiry_date = document.getElementById("p-expiry")?.value || null;

            const payload = { name, category, size, sku, barcode, quantity, min_stock_level, cost_price, retail_price, wholesale_price, warehouse, expiry_date };
            const mutationRef = generateOpId();
            const requestPayload = { ...payload, client_ref: mutationRef };
            try {
                const res = await fetch(`${API_URL}/products/`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify(requestPayload)
                });
                if (res.ok) {
                    const data = await res.json().catch(() => null);
                    closeAddProductModal();
                    document.getElementById("product-form").reset();
                    document.getElementById("barcode-input").value = "";
                    showToast(t("products.addedSuccess"), "success");
                    // Targeted update — append the new product to local state
                    // using the server-confirmed id/sku/barcode plus the form
                    // payload already known client-side, instead of reloading
                    // the entire application (see performance refactor,
                    // section 12).
                    if (data && !data.duplicate) {
                        globalProducts.push({ ...payload, id: data.id, sku: data.sku, barcode: data.barcode, name: data.name });
                        cacheProductsLocally(globalProducts);
                    }
                    updateDashboardMetrics();
                    refreshInventoryViewFromLocalState();
                } else {
                    const data = await res.json();
                    showToast(data.detail || t("products.addDetailFailed"), "error");
                }
            } catch (err) {
                if (isNetworkFailure(err)) { await handleCreateProductOffline(payload, mutationRef); return; }
                showToast(t("products.addFailed"), "error");
            }
        }

        // Offline fallback for handleCreateProduct: the product is created in
        // local state immediately (with a temporary negative id, since a real
        // one doesn't exist until the server confirms it), persisted to
        // IndexedDB, and queued in the durable outbox with a client_ref the
        // backend uses to make a retried sync idempotent (see /products/ POST).
        async function handleCreateProductOffline(payload, opId) {
            const localId = -Date.now();
            const localProduct = {
                id: localId, sku: payload.sku, barcode: payload.barcode || null, name: payload.name, category: payload.category,
                size: payload.size || null, quantity: payload.quantity, min_stock_level: payload.min_stock_level,
                cost_price: payload.cost_price, wholesale_price: payload.wholesale_price, retail_price: payload.retail_price,
                warehouse: payload.warehouse, initial_stock: payload.quantity, expiry_date: payload.expiry_date,
                created_at: new Date().toISOString(), _pendingSync: true,
            };
            globalProducts.push(localProduct);
            await cacheProductsLocally(globalProducts);
            await addOutboxOp({
                op_id: opId, business_id: currentOfflineScope(), user_id: currentUserProfile?.id || null,
                type: "product_create", endpoint: "/products/", method: "POST",
                payload: { ...payload, client_ref: opId }, meta: { local_id: localId },
                label: `Add product "${payload.name}"`, status: "pending", attempts: 0, next_retry_at: 0,
                created_at: Date.now(), last_error: null,
            });
            closeAddProductModal();
            document.getElementById("product-form").reset();
            document.getElementById("barcode-input").value = "";
            showToast("You're offline — product saved locally and will sync automatically when you're back online.", "info");
            updateDashboardMetrics();
            refreshInventoryViewFromLocalState();
        }

        function openEditProductModalFromData(productId) {
            const product = globalProducts.find(p => p.id === productId);
            if (!product) return;

            document.getElementById("edit-p-id").value = product.id;
            document.getElementById("edit-p-name").value = product.name;
            document.getElementById("edit-p-sku").value = product.sku;
            document.getElementById("edit-p-category").value = product.category;
            if (document.getElementById("edit-p-size")) document.getElementById("edit-p-size").value = product.size || "";
            document.getElementById("edit-p-qty").value = product.quantity;
            document.getElementById("edit-p-min").value = product.min_stock_level;
            document.getElementById("edit-p-cost").value = product.cost_price;
            document.getElementById("edit-p-retail").value = product.retail_price;
            document.getElementById("edit-p-wholesale").value = product.wholesale_price || "";
            if (document.getElementById("edit-p-expiry")) document.getElementById("edit-p-expiry").value = product.expiry_date || "";

            const sym = getCurrencySymbol();
            document.getElementById("label-edit-p-cost").innerText = `${t("products.costPrice")} (${sym})`;
            document.getElementById("label-edit-p-wholesale").innerText = `${t("dashboard.wholesalePrice")} (${sym})`;
            document.getElementById("label-edit-p-retail").innerText = `${t("dashboard.retailPrice")} (${sym})`;

            runEditAiMarginAdvice();
            document.getElementById("edit-product-modal").classList.remove("hidden");
        }

        function closeEditProductModal() {
            document.getElementById("edit-product-modal").classList.add("hidden");
        }

        async function handleUpdateProductCombined(event) {
            event.preventDefault();
            if (!authToken) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            const id = parseInt(document.getElementById("edit-p-id").value);
            const name = document.getElementById("edit-p-name").value.trim();
            const sku = document.getElementById("edit-p-sku").value.trim();
            const category = document.getElementById("edit-p-category").value.trim();
            const size = document.getElementById("edit-p-size") ? document.getElementById("edit-p-size").value.trim() : "";
            const quantity = parseInt(document.getElementById("edit-p-qty").value) || 0;
            const min_stock_level = parseInt(document.getElementById("edit-p-min").value) || 0;
            const cost_price = parseFloat(document.getElementById("edit-p-cost").value) || 0;
            const retail_price = parseFloat(document.getElementById("edit-p-retail").value) || 0;
            const wholesale_price = parseFloat(document.getElementById("edit-p-wholesale").value) || 0;
            const payload = { name, sku, category, size, quantity, min_stock_level, cost_price, retail_price, wholesale_price, expiry_date: document.getElementById("edit-p-expiry")?.value || null };

            // Editing a product that was itself created offline and hasn't
            // synced yet (negative temp id): there is no server record for
            // /products/{id} to PATCH. Fold the edit into the still-pending
            // create instead of queuing a doomed update against an id the
            // server has never heard of.
            if (id < 0) {
                await applyOfflineEditToPendingProductCreate(id, payload);
                return;
            }

            const mutationRef = generateOpId();
            const requestPayload = { ...payload, client_ref: mutationRef };

            try {
                const res = await fetch(`${API_URL}/products/${id}`, {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify(requestPayload)
                });
                if (res.ok) {
                    const data = await res.json().catch(() => null);
                    closeEditProductModal();
                    showToast(t("products.updatedSuccess"), "success");
                    // Targeted update — patch local state from the server's
                    // authoritative returned product instead of reloading the
                    // entire application (see performance refactor, section
                    // 12/13): a single product edit must not re-fetch
                    // products/suppliers/warehouses/financial intelligence/
                    // profit/Business Brain/subscription/audit/everything.
                    const updated = data?.product;
                    if (updated) {
                        const idx = globalProducts.findIndex(p => p.id === id);
                        if (idx !== -1) { globalProducts[idx] = { ...globalProducts[idx], ...updated }; cacheProductsLocally(globalProducts); }
                    }
                    updateDashboardMetrics();
                    refreshInventoryViewFromLocalState();
                } else {
                    const data = await res.json();
                    showToast(data.detail || t("products.updateDetailFailed"), "error");
                }
            } catch (err) {
                if (isNetworkFailure(err)) { await handleUpdateProductOffline(id, payload, mutationRef); return; }
                showToast(t("products.updateFailed"), "error");
            }
        }

        async function applyOfflineEditToPendingProductCreate(localId, payload) {
            const rows = await getOutboxForCurrentBusiness();
            const pendingCreate = rows.find((op) => op.type === "product_create" && op.meta?.local_id === localId);
            if (pendingCreate) {
                const merged = { ...pendingCreate.payload, ...payload, client_ref: pendingCreate.payload.client_ref };
                await updateOutboxOp(pendingCreate.op_id, { payload: merged });
            }
            const idx = globalProducts.findIndex((p) => p.id === localId);
            if (idx !== -1) globalProducts[idx] = { ...globalProducts[idx], ...payload };
            closeEditProductModal();
            showToast("You're offline — change saved locally and will sync automatically.", "info");
            updateDashboardMetrics();
            refreshInventoryViewFromLocalState();
        }

        async function handleUpdateProductOffline(id, payload, opId) {
            const idx = globalProducts.findIndex((p) => p.id === id);
            if (idx !== -1) { globalProducts[idx] = { ...globalProducts[idx], ...payload, _pendingSync: true }; }
            await cacheProductsLocally(globalProducts);
            await addOutboxOp({
                op_id: opId, business_id: currentOfflineScope(), user_id: currentUserProfile?.id || null,
                type: "product_update", endpoint: `/products/${id}`, method: "PATCH",
                payload: { ...payload, client_ref: opId }, meta: { local_id: id },
                label: `Update product "${payload.name}"`, status: "pending", attempts: 0, next_retry_at: 0,
                created_at: Date.now(), last_error: null,
            });
            closeEditProductModal();
            showToast("You're offline — change saved locally and will sync automatically when you're back online.", "info");
            updateDashboardMetrics();
            refreshInventoryViewFromLocalState();
        }

        async function deleteProduct(productId) {
            const role = getCurrentRole();
            if (role === 'staff') {
                showToast(t("products.staffCannotDelete"), "error");
                return;
            }
            const isManager = role === 'manager';
            const confirmed = await showCustomConfirm(isManager ? t("products.deleteRequestConfirmBody") : t("products.deleteConfirmBody"), isManager ? t("products.requestDeletionTitle") : t("products.deleteConfirmTitle"));
            if (!confirmed) return;

            // Deleting a product that was created offline and never reached
            // the server yet: there is nothing to delete server-side. Cancel
            // its pending create and drop it from local state instead.
            if (productId < 0) {
                const rows = await getOutboxForCurrentBusiness();
                const pendingCreate = rows.find((op) => op.type === "product_create" && op.meta?.local_id === productId);
                if (pendingCreate) await removeOutboxOp(pendingCreate.op_id);
                globalProducts = globalProducts.filter((p) => p.id !== productId);
                await cacheProductsLocally(globalProducts);
                showToast(t("products.deletedSuccess"), "success");
                updateDashboardMetrics();
                refreshInventoryViewFromLocalState();
                updateSyncStatusUI();
                return;
            }

            try {
                const res = await fetch(`${API_URL}/products/${productId}`, {
                    method: "DELETE",
                    headers: { "Authorization": `Bearer ${authToken}` }
                });
                const data = await res.json();
                if (!res.ok) { showToast(data.detail || t("products.deleteActionFailed"), "error"); return; }
                showToast(data.message || (isManager ? t("products.deletionRequestSent") : t("products.deletedSuccess")), "success");
                // Targeted update — a Manager's delete is only a pending
                // approval REQUEST (nothing actually changed yet, so nothing
                // to update); an Admin's delete really did remove the
                // product, so drop it from local state directly instead of
                // reloading the entire application (see performance
                // refactor, section 12).
                if (!isManager) {
                    globalProducts = globalProducts.filter(p => p.id !== productId);
                    cacheProductsLocally(globalProducts);
                    updateDashboardMetrics();
                    refreshInventoryViewFromLocalState();
                }
                if (getCurrentRole() === 'admin') renderAlerts();
            } catch (e) {
                if (isNetworkFailure(e)) { await handleDeleteProductOffline(productId, isManager); return; }
                showToast(t("common.actionFailed"), "error");
            }
        }

        async function handleDeleteProductOffline(productId, isManager) {
            const idx = globalProducts.findIndex((p) => p.id === productId);
            const name = idx !== -1 ? globalProducts[idx].name : "";
            if (idx !== -1) globalProducts.splice(idx, 1);
            await cacheProductsLocally(globalProducts);
            const opId = generateOpId();
            await addOutboxOp({
                op_id: opId, business_id: currentOfflineScope(), user_id: currentUserProfile?.id || null,
                type: "product_delete", endpoint: `/products/${productId}`, method: "DELETE",
                payload: null, meta: {},
                label: `Delete product "${name}"`, status: "pending", attempts: 0, next_retry_at: 0,
                created_at: Date.now(), last_error: null,
            });
            showToast("You're offline — deletion saved locally and will sync automatically when you're back online.", "info");
            updateDashboardMetrics();
            refreshInventoryViewFromLocalState();
        }

        async function loadSuppliers() {
            const tbody = document.getElementById("supplier-table-body");
            try {
                const headers = authToken ? { "Authorization": `Bearer ${authToken}` } : {};
                const res = await fetch(`${API_URL}/suppliers/`, { headers });
                if (res.ok) {
                    globalSuppliers = await res.json();
                    if (!globalSuppliers.length) {
                        tbody.innerHTML = `<tr><td colspan="5" class="text-center py-4 text-textSec text-xs">${t('suppliers.noneRegistered')}</td></tr>`;
                        return;
                    }
                    tbody.innerHTML = globalSuppliers.map(s => `
                        <tr class="hover:bg-cardHover/50 transition">
                            <td class="py-2.5 px-2 font-bold text-textMain">${escapeHtml(s.name)}</td>
                            <td class="py-2.5 px-2 text-textSec">${escapeHtml(s.contact_email) || t('common.notApplicable')}</td>
                            <td class="py-2.5 px-2 font-mono text-success">${escapeHtml(s.phone) || t('common.notApplicable')}</td>
                            <td class="py-2.5 px-2 text-right">
                                <div class="flex items-center justify-end gap-1.5">
                                    <button type="button" onclick="dispatchWhatsAppOrder('${escapeHtml(s.name)}', '${escapeHtml(s.phone || '')}')" class="bg-success/15 hover:bg-success/25 text-success border border-success/30 px-2.5 py-1 rounded-lg font-semibold transition flex items-center gap-1 cursor-pointer" title="${t('suppliers.whatsappOrderTitle')}">
                                        <i class="fa-brands fa-whatsapp text-xs"></i> ${t('suppliers.order')}
                                    </button>
                                    <button type="button" onclick="deleteSupplier(${s.id})" class="w-6 h-6 rounded-lg bg-danger/15 hover:bg-danger/25 text-danger flex items-center justify-center cursor-pointer" title="${t('common.delete')}">
                                        <i class="fa-solid fa-trash-can text-[10px]"></i>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    `).join("");
                }
            } catch (e) {
                tbody.innerHTML = `<tr><td colspan="4" class="text-center py-4 text-danger text-xs">${t('suppliers.loadFailed')}</td></tr>`;
            }
        }

        // Exports globalSuppliers (already the full authorized, business-
        // scoped list loaded by loadSuppliers()). No search/filter exists on
        // this screen today, so there is no filter state to respect.
        function buildSuppliersExportSpec() {
            if (!Array.isArray(globalSuppliers) || !globalSuppliers.length) return null;
            return {
                filenameBase: `cauldra_suppliers_${csvDateStamp()}`,
                reportTitle: "Cauldra Suppliers Report",
                metadata: [["Generated", new Date().toLocaleString()]],
                sheets: [{
                    name: "Suppliers",
                    columns: [
                        { key: "name", label: "Supplier Name", type: "text" },
                        { key: "contact_email", label: "Email", type: "text" },
                        { key: "phone", label: "Phone", type: "text" },
                        { key: "lead_time_days", label: "Lead Time (Days)", type: "number" },
                    ],
                    rows: globalSuppliers,
                }],
            };
        }
        function exportSuppliersCsv() { runCsvExport(buildSuppliersExportSpec, "No suppliers available to export."); }
        function exportSuppliersExcel(button) { runExcelExport(button, buildSuppliersExportSpec, "No suppliers available to export."); }

        async function handleCreateSupplier(event) {
            event.preventDefault();
            if (!authToken) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            const name = document.getElementById("s-name").value.trim();
            const contact_email = document.getElementById("s-contact").value.trim();
            const phone = document.getElementById("s-phone").value.trim();

            if (!name) { showToast(t("suppliers.vendorNameRequired"), "error"); return; }
            try {
                const res = await fetch(`${API_URL}/suppliers/`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ name, contact_email, phone })
                });
                if (res.ok) {
                    document.getElementById("supplier-form").reset();
                    loadSuppliers();
                    loadData();
                    showToast(t("suppliers.addedSuccess"), "success");
                } else {
                    const data = await res.json().catch(() => ({}));
                    showToast(showApiError(res, data, t("suppliers.addFailed")), "error");
                }
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        async function deleteSupplier(supplierId) {
            if (!authToken) return;
            const confirmed = await showCustomConfirm(t("suppliers.deleteConfirmBody"), t("suppliers.deleteConfirmTitle"));
            if (!confirmed) return;
            try {
                const res = await fetch(`${API_URL}/suppliers/${supplierId}`, {
                    method: "DELETE",
                    headers: { "Authorization": `Bearer ${authToken}` }
                });
                const data = await res.json().catch(() => ({}));
                if (res.ok) {
                    loadSuppliers();
                    loadData();
                    showToast(t("suppliers.deletedSuccess"), "success");
                } else {
                    showToast(showApiError(res, data, t("suppliers.deleteFailed")), "error");
                }
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        function dispatchWhatsAppOrder(vendorName, phone) {
            const lowStockItems = globalProducts.filter(p => p.quantity <= p.min_stock_level);
            if (!lowStockItems.length) {
                showToast(t("suppliers.noLowStockItems"), "info");
                return;
            }
            let message = t("suppliers.whatsappGreeting", {vendor: vendorName});
            lowStockItems.forEach(i => {
                const deficit = Math.max(5, (i.min_stock_level * 2) - i.quantity);
                message += t("suppliers.whatsappLineItem", {name: i.name, sku: i.sku, deficit});
            });
            message += t("suppliers.whatsappClosing");

            const encoded = encodeURIComponent(message);
            const cleanPhone = phone.replace(/[^0-9+]/g, '');
            const url = cleanPhone ? `https://wa.me/${cleanPhone}?text=${encoded}` : `https://wa.me/?text=${encoded}`;
            window.open(url, '_blank');
            showToast(t("suppliers.dispatchOrderGenerated"), "success");
        }

        async function generatePOs() {
            if (!hasAuthenticatedBusinessContext()) {
                showToast(t("common.signInOrRegister"), "info");
                openBusinessAuthModal();
                return;
            }
            const lowStockItems = globalProducts.filter(p => p.quantity <= p.min_stock_level);
            if (!lowStockItems.length) {
                showToast(t("purchaseOrders.allHealthy"), "info");
                return;
            }

            try {
                const res = await fetch(`${API_URL}/purchase-orders/generate`, {
                    method: "POST", headers: { "Authorization": `Bearer ${authToken}` }
                });
                if (res.ok) {
                    const data = await res.json();
                    showToast(t("purchaseOrders.generatedSuccess", {id: data.id || ''}), "success");
                    openPOModal();
                } else {
                    const data = await res.json();
                    showToast(data.detail || t("purchaseOrders.generateFailed"), "error");
                }
            } catch (e) {
                showToast(t("purchaseOrders.generateUnableRetry"), "error");
            }
        }

        async function loadPurchaseOrders() {
            const container = document.getElementById("po-container");
            try {
                const headers = authToken ? { "Authorization": `Bearer ${authToken}` } : {};
                const res = await fetch(`${API_URL}/purchase-orders/`, { headers });
                if (res.ok) {
                    globalPurchaseOrders = await res.json();
                    renderPurchaseOrdersList(globalPurchaseOrders);
                } else {
                    container.innerHTML = `<div class="text-center py-6 text-textSec text-xs">${t("purchaseOrders.noneFound")}</div>`;
                }
            } catch (e) {
                container.innerHTML = `<div class="text-center py-6 text-danger text-xs">${t("purchaseOrders.loadFailed")}</div>`;
            }
        }

        // Shared by the search box and the CSV export, so "export what I'm
        // currently seeing" can never drift from what filterPurchaseOrders()
        // actually renders.
        function getFilteredPurchaseOrders() {
            const query = (document.getElementById("po-search-input")?.value || "").toLowerCase().trim();
            if (!query) return globalPurchaseOrders;
            return globalPurchaseOrders.filter(po =>
                (po.vendor_name && po.vendor_name.toLowerCase().includes(query)) ||
                (po.status && po.status.toLowerCase().includes(query)) ||
                String(po.id).includes(query)
            );
        }

        function filterPurchaseOrders() {
            renderPurchaseOrdersList(getFilteredPurchaseOrders());
        }

        // Exports whatever the search box currently filters to (all of
        // globalPurchaseOrders when the box is empty) — /purchase-orders/
        // loads every PO for the business at once, so there is no pagination
        // gap to worry about.
        function buildPurchaseOrdersExportSpec() {
            const rows = getFilteredPurchaseOrders();
            if (!rows.length) return null;
            return {
                filenameBase: `cauldra_purchase_orders_${csvDateStamp()}`,
                reportTitle: "Cauldra Purchase Orders Report",
                metadata: [
                    ["Generated", new Date().toLocaleString()],
                    ["Search", document.getElementById("po-search-input")?.value || "None"],
                ],
                sheets: [{
                    name: "Purchase Orders",
                    columns: [
                        { key: "id", label: "PO Number", type: "number" },
                        { key: "created_at", label: "Date", type: "datetime", format: v => v ? formatBusinessDate(v) : "" },
                        { key: "vendor_name", label: "Supplier", type: "text" },
                        { key: "status", label: "Status", type: "text" },
                        { key: "total_estimated_cost", label: "Total Estimated Cost", type: "currency" },
                        { key: "created_by", label: "Created By", type: "text", format: v => v || "" },
                        { key: "items_summary", label: "Order Items / Notes", type: "text" },
                    ],
                    rows,
                }],
            };
        }
        function exportPurchaseOrdersCsv() { runCsvExport(buildPurchaseOrdersExportSpec, "No purchase orders available to export."); }
        function exportPurchaseOrdersExcel(button) { runExcelExport(button, buildPurchaseOrdersExportSpec, "No purchase orders available to export."); }

        function renderPurchaseOrdersList(pos) {
            const container = document.getElementById("po-container");
            if (!pos.length) {
                container.innerHTML = `<div class="text-center py-6 text-textSec text-xs">${t("purchaseOrders.noneMatchSearch")}</div>`;
                return;
            }

            container.innerHTML = pos.map(po => {
                const isApproved = po.status === 'Approved' || po.status === 'Dispatched';
                return `
                    <div class="bg-bgMain border border-borderCol rounded-xl p-4 space-y-2.5">
                        <div class="flex items-center justify-between">
                            <div>
                                <span class="font-bold text-textMain text-xs">${t("purchaseOrders.poHeader", {id: po.id})} — <span class="text-primary">${escapeHtml(po.vendor_name) || t("purchaseOrders.generalVendor")}</span></span>
                                <div class="text-[10px] text-textSec">${po.created_at ? t("purchaseOrders.createdOn", {date: formatBusinessDate(po.created_at)}) : t("purchaseOrders.recent")}</div>
                            </div>
                            <span class="px-2.5 py-1 rounded-lg text-[10px] font-bold ${isApproved ? 'bg-success/15 text-success border border-success/30' : 'bg-warning/15 text-warning border border-warning/30'}">${escapeHtml(po.status) || t("purchaseOrders.draft")}</span>
                        </div>
                        <div class="text-[11px] text-textSec bg-cardBg p-2.5 rounded-lg border border-borderCol/60">
                            <strong>${t("purchaseOrders.orderItemsNotes")}</strong> <span class="text-textMain">${escapeHtml(po.items_summary) || t("purchaseOrders.restockDefault")}</span>
                        </div>
                        <div class="flex justify-end gap-2 pt-1">
                            <button type="button" onclick="editPurchaseOrder(${po.id}, '${escapeHtml(po.items_summary || '')}')" class="bg-cardBg hover:bg-cardHover text-textSec px-3 py-1 rounded-lg text-xs font-semibold border border-borderCol cursor-pointer">
                                <i class="fa-solid fa-pen-to-square mr-1"></i> ${t("purchaseOrders.editDraft")}
                            </button>
                            <button type="button" onclick="dispatchWhatsAppOrder('${escapeHtml(po.vendor_name || t("purchaseOrders.vendorFallback"))}', '')" class="bg-success/15 hover:bg-success/25 text-success border border-success/30 px-3 py-1 rounded-lg text-xs font-semibold transition flex items-center gap-1 cursor-pointer">
                                <i class="fa-brands fa-whatsapp"></i> ${t("purchaseOrders.whatsappOrder")}
                            </button>
                            <button type="button" onclick="deletePurchaseOrder(${po.id})" class="bg-danger/15 hover:bg-danger/25 text-danger border border-danger/30 px-3 py-1 rounded-lg text-xs font-semibold cursor-pointer">
                                <i class="fa-solid fa-trash"></i> ${t("common.delete")}
                            </button>
                        </div>
                    </div>
                `;
            }).join("");
        }

        async function editPurchaseOrder(poId, currentSummary) {
            const updated = await showCustomPrompt(t("purchaseOrders.editPromptBody"), t("purchaseOrders.editPromptTitle"), t("purchaseOrders.itemsSummaryField"), "text", false, currentSummary);
            if (updated === null) return;
            try {
                const res = await fetch(`${API_URL}/purchase-orders/${poId}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ items_summary: updated })
                });
                if (res.ok) {
                    loadPurchaseOrders();
                    showToast(t("purchaseOrders.updatedSuccess"), "success");
                } else {
                    showToast(t("purchaseOrders.updateFailed"), "error");
                }
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        async function deletePurchaseOrder(poId) {
            const confirmed = await showCustomConfirm(t("purchaseOrders.deleteConfirmBody"), t("purchaseOrders.deleteConfirmTitle"));
            if (!confirmed) return;
            try {
                const res = await fetch(`${API_URL}/purchase-orders/${poId}`, {
                    method: "DELETE", headers: { "Authorization": `Bearer ${authToken}` }
                });
                if (res.ok) {
                    loadPurchaseOrders();
                    showToast(t("purchaseOrders.deletedSuccess"), "success");
                }
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        async function confirmDeleteAllPurchaseOrders() {
            const confirmed = await showCustomConfirm(t("purchaseOrders.deleteAllConfirmBody"), t("purchaseOrders.deleteAllConfirmTitle"));
            if (!confirmed) return;
            try {
                for (const po of globalPurchaseOrders) {
                    await fetch(`${API_URL}/purchase-orders/${po.id}`, { method: "DELETE", headers: { "Authorization": `Bearer ${authToken}` } });
                }
                loadPurchaseOrders();
                showToast(t("purchaseOrders.allDeletedSuccess"), "success");
            } catch (e) {
                showToast(t("common.actionFailed"), "error");
            }
        }

        // Cached by loadPriceMonitor() so exportPriceMonitorCsv() can export
        // exactly the sources currently displayed without a second fetch.
        let lastPriceMonitorSources = [];

        async function loadPriceMonitor() {
            const container=document.getElementById('price-monitor-container');
            try{
                const res=await fetch(`${API_URL}/price-monitor`,{headers:{"Authorization":`Bearer ${authToken}`}}); const data=await res.json();
                if(!res.ok) throw new Error(showApiError(res,data,t("priceMonitor.loadFailed")));
                const sources=data.sources||[]; lastPriceMonitorSources=sources; document.getElementById('price-monitor-status').innerText=tPlural("priceMonitor.sourcesMonitored", sources.length);
                const allHistory=sources.flatMap(s=>s.history||[]).sort((a,b)=>new Date(a.recorded_at)-new Date(b.recorded_at));
                const summary=document.getElementById('price-monitor-summary'); summary.innerHTML=[[t("priceMonitor.monitoring"),sources.length],[t("priceMonitor.priceChanges"),sources.filter(s=>s.change_percent!==null&&Math.abs(s.change_percent)>0.01).length],[t("priceMonitor.websiteSources"),sources.filter(s=>s.source_type==='website').length],[t("priceMonitor.manualList"),sources.filter(s=>s.source_type!=='website').length]].map(x=>`<div class="p-2.5 rounded-xl bg-cardBg border border-borderCol"><div class="text-[9px] text-textSec">${x[0]}</div><div class="font-bold text-sm mt-0.5">${x[1]}</div></div>`).join('');
                if(allHistory.length){ const max=Math.max(...allHistory.map(x=>x.price),1), min=Math.min(...allHistory.map(x=>x.price)); document.getElementById('price-monitor-chart').innerHTML=`<div class="flex items-end gap-1 h-[140px] px-2">${allHistory.slice(-20).map(x=>`<div class="flex-1 bg-primary/65 rounded-t" style="height:${Math.max(5,((x.price-min)/Math.max(1,max-min))*100)}%" title="${formatCurrency(x.price)} · ${formatBusinessDate(x.recorded_at)}"></div>`).join('')}</div><div class="flex justify-between text-[9px] text-textSec mt-2"><span>${formatCurrency(min)}</span><span>${t("priceMonitor.recordedSupplierPrices")}</span><span>${formatCurrency(max)}</span></div>`; } else document.getElementById('price-monitor-chart').innerText=t("priceMonitor.noHistoryAddSource");
                container.innerHTML=`<div class="flex justify-end mb-2"><button type="button" onclick="openPriceSourceModal()" class="bg-primary hover:bg-primaryHover text-white px-3 py-2 rounded-xl text-[11px] font-semibold"><i class="fa-solid fa-plus mr-1"></i>${t("priceMonitor.addPriceSource")}</button></div>`+(sources.length?sources.map(s=>`<div class="bg-bgMain border border-borderCol rounded-xl p-3"><div class="flex items-start justify-between gap-3"><div><div class="font-bold text-xs">${escapeHtml(s.product_name)} <span class="text-textSec font-mono text-[10px]">(${escapeHtml(s.sku)})</span></div><div class="text-[10px] text-textSec mt-0.5">${escapeHtml(s.supplier_name)} · ${s.source_type==='website'?t("priceMonitor.sourceTypeWebsite"):s.source_type==='price_list'?t("priceMonitor.sourceTypePriceList"):t("priceMonitor.sourceTypeManual")}</div></div><div class="text-right"><div class="font-mono font-semibold text-textMain">${s.last_price!==null?formatCurrency(s.last_price):t("priceMonitor.noPriceYet")}</div>${s.change_percent!==null?`<div class="text-[10px] ${s.change_percent>0?'text-danger':'text-success'}">${s.change_percent>0?'+':''}${s.change_percent}%</div>`:''}</div></div><div class="flex justify-end gap-2 mt-2">${s.source_type==='website'?`<button type="button" onclick="checkPriceSource(${s.id})" class="text-[10px] bg-primary/10 text-primary border border-primary/25 px-2.5 py-1.5 rounded-lg">${t("common.checkNow")}</button>`:''}<button type="button" onclick="manualPriceUpdate(${s.id})" class="text-[10px] bg-bgMain text-textSec border border-borderCol px-2.5 py-1.5 rounded-lg">${t("priceMonitor.updatePrice")}</button></div></div>`).join(''):`<div class="text-center py-8 text-xs text-textSec">${t("priceMonitor.noSourcesYet")}</div>`);
            }catch(e){lastPriceMonitorSources=[];const msg=String(e.message||''); const professional=msg.toLowerCase().includes('not found')||msg.includes('404')?t("priceMonitor.noSourcesSetup"):friendlyErrorMessage(msg,t("priceMonitor.monitoringUnavailable")); container.innerHTML=`<div class="p-4 rounded-xl bg-bgMain border border-borderCol text-center text-xs text-textSec"><div class="font-semibold text-textMain mb-1">${t("priceMonitor.monitoringReady")}</div><div>${professional}</div></div>`;}
        }

        function buildPriceMonitorExportSpec() {
            if (!lastPriceMonitorSources.length) return null;
            return {
                filenameBase: `cauldra_price_monitor_${csvDateStamp()}`,
                reportTitle: "Cauldra Price Monitor Report",
                metadata: [["Generated", new Date().toLocaleString()]],
                sheets: [{
                    name: "Price Monitor",
                    columns: [
                        { key: "product_name", label: "Product", type: "text" },
                        { key: "sku", label: "SKU", type: "text" },
                        { key: "supplier_name", label: "Supplier", type: "text" },
                        { key: "source_type", label: "Source Type", type: "text" },
                        { key: "last_price", label: "Current Price", type: "currency" },
                        { key: "change_percent", label: "Change %", type: "decimal" },
                    ],
                    rows: lastPriceMonitorSources,
                }],
            };
        }
        function exportPriceMonitorCsv() { runCsvExport(buildPriceMonitorExportSpec, "No price monitor data available to export."); }
        function exportPriceMonitorExcel(button) { runExcelExport(button, buildPriceMonitorExportSpec, "No price monitor data available to export."); }
        function openPriceSourceModal(){ document.getElementById('price-source-modal').classList.remove('hidden'); document.querySelector('input[name="price-source-type"][value="website"]').checked=true; togglePriceListUpload(); document.getElementById('price-source-file').value=''; document.getElementById('price-source-supplier').innerHTML=`<option value="">${t("priceMonitor.selectSupplierPlaceholder")}</option>`+globalSuppliers.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join(''); document.getElementById('price-source-product').innerHTML=`<option value="">${t("priceMonitor.selectProductPlaceholder")}</option>`+globalProducts.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} (${escapeHtml(p.sku)})</option>`).join(''); }
        function closePriceSourceModal(){document.getElementById('price-source-modal').classList.add('hidden');}
        function togglePriceListUpload(){ const type=document.querySelector('input[name="price-source-type"]:checked')?.value; document.getElementById('price-list-file-wrap')?.classList.toggle('hidden',type!=='price_list'); }
        async function uploadSelectedPriceList(file,supplierId,productId){ return new Promise((resolve,reject)=>{ const reader=new FileReader(); reader.onload=async ev=>{ try{ const r=await fetch(`${API_URL}/price-monitor/upload-price-list`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${authToken}`},body:JSON.stringify({supplier_id:+supplierId,product_id:productId?+productId:null,file_name:file.name,file_data:ev.target.result})}); const d=await r.json(); if(!r.ok) throw new Error(showApiError(r,d,t("priceMonitor.priceListProcessFailed"))); resolve(d);}catch(err){reject(err);} }; reader.onerror=()=>reject(new Error(t("priceMonitor.priceListReadFailed"))); reader.readAsDataURL(file); }); }
        async function createPriceSource(e){e.preventDefault();const supplierId=document.getElementById('price-source-supplier').value,productId=document.getElementById('price-source-product').value,type=document.querySelector('input[name="price-source-type"]:checked').value,file=document.getElementById('price-source-file')?.files?.[0]||null;try{if(type==='price_list'&&file){const d=await uploadSelectedPriceList(file,supplierId,productId);closePriceSourceModal();showToast(tPlural("priceMonitor.priceListParsed", d.count||0),'success');loadPriceMonitor();renderAlerts();return;}const body={supplier_id:+supplierId,product_id:+productId,source_type:type,source_url:document.getElementById('price-source-url').value.trim()||null,initial_price:parseFloat(document.getElementById('price-source-initial').value)||null};const r=await fetch(`${API_URL}/price-monitor/sources`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${authToken}`},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(showApiError(r,d,t("priceMonitor.sourceAddFailed")));closePriceSourceModal();showToast(t("priceMonitor.sourceAdded"),'success');loadPriceMonitor();}catch(err){showToast(friendlyErrorMessage(err.message,t("priceMonitor.sourceAddFailed")),'error');}}
        async function checkPriceSource(id){try{const r=await fetch(`${API_URL}/price-monitor/${id}/check`,{method:'POST',headers:{'Authorization':`Bearer ${authToken}`}});const d=await r.json();if(!r.ok)throw new Error(showApiError(r,d,t("priceMonitor.priceCheckFailed")));showToast(d.message||t("priceMonitor.priceChecked"),'success');loadPriceMonitor();renderAlerts();}catch(e){showToast(friendlyErrorMessage(e.message,t("priceMonitor.priceCheckFailed")),'error');}}
        async function manualPriceUpdate(id){const value=await showCustomPrompt(t("priceMonitor.updatePricePrompt"), t("priceMonitor.updatePriceTitle"), t("priceMonitor.updatePriceField"), 'number', false, '');if(value===null)return;const price=parseFloat(value);if(!Number.isFinite(price)||price<0){showToast(t("priceMonitor.invalidPrice"),'error');return;}try{const r=await fetch(`${API_URL}/price-monitor/${id}/price`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${authToken}`},body:JSON.stringify({price})});const d=await r.json();if(!r.ok)throw new Error(showApiError(r,d,t("priceMonitor.priceUpdateFailed")));showToast(t("priceMonitor.priceRecorded"),'success');loadPriceMonitor();renderAlerts();}catch(e){showToast(friendlyErrorMessage(e.message,t("priceMonitor.priceUpdateFailed")),'error');}}

        function openDirectCameraSnapModal() {
            document.getElementById("direct-camera-snap-box").classList.remove("hidden");
            const videoEl = document.getElementById("snap-video-stream");
            navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } }).then(stream => {
                snapMediaStream = stream;
                videoEl.srcObject = stream;
            }).catch(() => {
                showToast(t("priceMonitor.cameraAccessFailed"), "error");
                closeDirectCameraSnap();
            });
        }

        function closeDirectCameraSnap() {
            if (snapMediaStream) {
                snapMediaStream.getTracks().forEach(track => track.stop());
                snapMediaStream = null;
            }
            document.getElementById("direct-camera-snap-box").classList.add("hidden");
        }

        async function captureSnapshotAndAnalyze() {
            const videoEl = document.getElementById("snap-video-stream");
            const canvasEl = document.getElementById("snap-canvas-output");
            canvasEl.width = videoEl.videoWidth || 640;
            canvasEl.height = videoEl.videoHeight || 480;
            const ctx = canvasEl.getContext("2d");
            ctx.drawImage(videoEl, 0, 0, canvasEl.width, canvasEl.height);
            
            const dataUrl = canvasEl.toDataURL("image/jpeg");
            closeDirectCameraSnap();
            playSuccessBeep();

            const resultsBox = document.getElementById("global-invoice-results-box");
            const resultsText = document.getElementById("global-invoice-results-text");
            resultsBox.classList.remove("hidden");
            setScanResultsState(resultsBox, resultsText, "loading", `<span class="italic animate-pulse">${t("priceMonitor.analyzingSnapshot")}</span>`);

            try {
                const res = await fetch(`${API_URL}/ai/scan-invoice`, {
                    method: "POST", headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ image_data: dataUrl, file_name: `invoice-snapshot-${new Date().toISOString().replace(/[:.]/g, '-')}.jpg` })
                });
                const data = await res.json();
                if (res.ok) {
                    setScanResultsState(resultsBox, resultsText, "success", `
                        <div><strong>${t("priceMonitor.supplierLabel")}</strong> ${escapeHtml(data.supplier_name) || t("priceMonitor.detectedVendor")}</div>
                        <div><strong>${t("priceMonitor.itemsExtractedLabel")}</strong> ${tPlural("priceMonitor.lineItemsParsed", data.items_count || 1)}</div>
                        <div><strong>${t("priceMonitor.statusLabel")}</strong> ${t("priceMonitor.detailsExtracted")}</div>
                    `);
                    showToast(t("priceMonitor.invoiceAnalyzedSnap"), "success");
                    loadData();
                } else {
                    setScanResultsState(resultsBox, resultsText, "error", escapeHtml(scanResultsErrorMessage(data)));
                }
            } catch (err) {
                setScanResultsState(resultsBox, resultsText, "error", t("priceMonitor.snapProcessFailed"));
            }
        }

        async function handleGlobalBulkInvoiceUpload(event) {
            const file = event.target.files[0];
            if (!file) return;

            const resultsBox = document.getElementById("global-invoice-results-box");
            const resultsText = document.getElementById("global-invoice-results-text");
            resultsBox.classList.remove("hidden");
            setScanResultsState(resultsBox, resultsText, "loading", `<span class="italic animate-pulse">${t("priceMonitor.parsingInvoice")}</span>`);

            const reader = new FileReader();
            reader.onload = async function(e) {
                const base64Data = e.target.result;
                try {
                    const res = await fetch(`${API_URL}/ai/scan-invoice`, {
                        method: "POST", headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                        body: JSON.stringify({ image_data: base64Data, file_name: file.name })
                    });
                    const data = await res.json();
                    if (res.ok) {
                        setScanResultsState(resultsBox, resultsText, "success", `
                            <div><strong>${t("priceMonitor.supplierLabel")}</strong> ${escapeHtml(data.supplier_name) || t("priceMonitor.invoiceVendor")}</div>
                            <div><strong>${t("priceMonitor.itemsExtractedLabel")}</strong> ${tPlural("priceMonitor.itemsParsed", data.items_count || 1)}</div>
                            <div><strong>${t("priceMonitor.statusLabel")}</strong> ${t("priceMonitor.detailsExtracted")}</div>
                        `);
                        showToast(t("priceMonitor.invoiceAnalyzedUpload"), "success");
                        loadData();
                    } else {
                        setScanResultsState(resultsBox, resultsText, "error", escapeHtml(scanResultsErrorMessage(data)));
                    }
                } catch (err) {
                    setScanResultsState(resultsBox, resultsText, "error", t("priceMonitor.uploadProcessFailed"));
                }
            };
            reader.readAsDataURL(file);
        }

        let finIntelActiveTab = 'at-risk';
        function getFinIntelTabConfig() {
            return {
                'at-risk': {
                    label: t("predictive.salesAtRisk"),
                    desc: t("predictive.salesAtRiskDesc"),
                    dataKey: 'money_at_risk', color: 'text-danger',
                    columns: [t("predictive.colProduct"), t("predictive.colCurrentStock"), t("predictive.colEstDaysLeft"), t("predictive.colSalesAtRisk")],
                    row: p => [`${escapeHtml(p.name)} <span class="text-textSec font-mono text-[10px]">(${escapeHtml(p.sku)})</span>`, p.quantity, p.days_to_stockout === null ? '—' : t("predictive.daysUnit", {count: p.days_to_stockout}), formatCurrency(p.potential_sales_at_risk)],
                },
                'tied-up': {
                    label: t("predictive.capitalTitle"),
                    desc: t("predictive.capitalDesc"),
                    dataKey: 'money_tied_up', color: 'text-warning',
                    columns: [t("predictive.colProduct"), t("predictive.colUnits"), t("predictive.colCostPerUnit"), t("predictive.colCapitalTiedUp"), t("predictive.colLastSale")],
                    row: p => [`${escapeHtml(p.name)} <span class="text-textSec font-mono text-[10px]">(${escapeHtml(p.sku)})</span>`, p.quantity, formatCurrency(p.cost_per_unit), formatCurrency(p.capital_tied_up), p.last_sale ? formatBusinessDate(p.last_sale) : t("common.never")],
                },
                'margin': {
                    label: t("predictive.marginTitle"),
                    desc: t("predictive.marginDesc"),
                    dataKey: 'margin_pressure', color: 'text-orange-400',
                    columns: [t("predictive.colProduct"), t("predictive.colListedMargin"), t("predictive.colRealizedMargin"), t("predictive.colMonthlyImpact")],
                    row: p => [`${escapeHtml(p.name)} <span class="text-textSec font-mono text-[10px]">(${escapeHtml(p.sku)})</span>`, `${p.previous_margin_pct}%`, `${p.current_margin_pct}%`, formatCurrency(p.estimated_monthly_impact)],
                },
                'recoverable': {
                    label: t("predictive.recoverableTitle"),
                    desc: t("predictive.recoverableDesc"),
                    dataKey: 'potentially_recoverable', color: 'text-success',
                    columns: [t("predictive.colProduct"), t("predictive.colQuantity"), t("predictive.colCostValue"), t("predictive.colLastSale"), t("predictive.colRecommendedAction"), t("predictive.colPotentialValue")],
                    row: p => [`${escapeHtml(p.name)} <span class="text-textSec font-mono text-[10px]">(${escapeHtml(p.sku)})</span>`, p.quantity, formatCurrency(p.cost_value), p.last_sale ? formatBusinessDate(p.last_sale) : t("common.never"), escapeHtml(p.recommended_action), formatCurrency(p.potential_value)],
                },
            };
        }

        // Raw (non-HTML, non-currency-formatted) column definitions for CSV,
        // kept separate from getFinIntelTabConfig()'s HTML-rendering row()
        // functions above — a CSV cell should hold the actual number/date,
        // not a formatted display string or embedded markup.
        function getFinIntelCsvSpec(tab, data) {
            const specs = {
                "at-risk": { dataKey: "money_at_risk", columns: [
                    { key: "name", label: "Product", type: "text" }, { key: "sku", label: "SKU", type: "text" }, { key: "quantity", label: "Current Stock", type: "number" },
                    { key: "days_to_stockout", label: "Est. Days Left", type: "number" }, { key: "potential_sales_at_risk", label: "Sales At Risk", type: "currency" },
                ] },
                "tied-up": { dataKey: "money_tied_up", columns: [
                    { key: "name", label: "Product", type: "text" }, { key: "sku", label: "SKU", type: "text" }, { key: "quantity", label: "Units", type: "number" },
                    { key: "cost_per_unit", label: "Cost Per Unit", type: "currency" }, { key: "capital_tied_up", label: "Capital Tied Up", type: "currency" },
                    { key: "last_sale", label: "Last Sale", type: "date", format: v => v ? formatBusinessDate(v) : "" },
                ] },
                "margin": { dataKey: "margin_pressure", columns: [
                    { key: "name", label: "Product", type: "text" }, { key: "sku", label: "SKU", type: "text" },
                    { key: "previous_margin_pct", label: "Listed Margin %", type: "decimal" }, { key: "current_margin_pct", label: "Realized Margin %", type: "decimal" },
                    { key: "estimated_monthly_impact", label: "Monthly Impact", type: "currency" },
                ] },
                "recoverable": { dataKey: "potentially_recoverable", columns: [
                    { key: "name", label: "Product", type: "text" }, { key: "sku", label: "SKU", type: "text" }, { key: "quantity", label: "Quantity", type: "number" },
                    { key: "cost_value", label: "Cost Value", type: "currency" }, { key: "last_sale", label: "Last Sale", type: "date", format: v => v ? formatBusinessDate(v) : "" },
                    { key: "recommended_action", label: "Recommended Action", type: "text" }, { key: "potential_value", label: "Potential Value", type: "currency" },
                ] },
            };
            if (tab === "efficiency") {
                const cats = [
                    ["Stockout Exposure", data.money_at_risk], ["Slow-Moving Stock", data.money_tied_up],
                    ["Declining Margins", data.margin_pressure], ["Recovery Opportunities", data.potentially_recoverable],
                ].filter(([, cat]) => cat.products.length > 0);
                return {
                    columns: [{ key: "category", label: "Category", type: "text" }, { key: "count", label: "Products Flagged", type: "number" }, { key: "amount", label: "Amount", type: "currency" }],
                    rows: cats.map(([label, cat]) => [label, cat.products.length, cat.total]),
                };
            }
            const spec = specs[tab];
            if (!spec) return null;
            return { columns: spec.columns, rows: data[spec.dataKey].products };
        }

        function buildPredictiveExportSpec() {
            if (!lastFinancialIntelData || !lastFinancialIntelData.report_ready) return null;
            const spec = getFinIntelCsvSpec(finIntelActiveTab, lastFinancialIntelData);
            if (!spec || !spec.rows.length) return null;
            const tabLabels = { "at-risk": "Money at Risk", "tied-up": "Tied-Up Capital", "margin": "Margin Pressure", "recoverable": "Recoverable", "efficiency": "Efficiency Overview" };
            return {
                filenameBase: `cauldra_predictive_${finIntelActiveTab}_${csvDateStamp()}`,
                reportTitle: "Cauldra Predictive Analysis",
                metadata: [["View", tabLabels[finIntelActiveTab] || finIntelActiveTab], ["Generated", new Date().toLocaleString()]],
                sheets: [{ name: tabLabels[finIntelActiveTab] || "Predictive", columns: spec.columns, rows: spec.rows }],
            };
        }
        function exportPredictiveCsv() { runCsvExport(buildPredictiveExportSpec, "No predictive data available to export for this tab."); }
        function exportPredictiveExcel(button) { runExcelExport(button, buildPredictiveExportSpec, "No predictive data available to export for this tab."); }

        async function renderPredictiveMonitor(initialTab) {
            finIntelActiveTab = initialTab || 'at-risk';
            document.getElementById('fin-intel-modal-loading').classList.remove('hidden');
            document.getElementById('fin-intel-modal-insufficient').classList.add('hidden');
            document.getElementById('fin-intel-modal-body').classList.add('hidden');
            document.getElementById('fin-intel-detail-panel').classList.add('hidden');
            try {
                const r = await fetch(`${API_URL}/products/financial-intelligence`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) throw new Error(showApiError(r, d, t("predictive.loadFailed")));
                lastFinancialIntelData = d;
                document.getElementById('fin-intel-modal-loading').classList.add('hidden');
                if (!d.report_ready) {
                    document.getElementById('fin-intel-modal-insufficient').classList.remove('hidden');
                    document.getElementById('fin-intel-modal-insufficient').textContent = d.insufficient_data_message || t("predictive.insufficientData");
                    return;
                }
                document.getElementById('fin-intel-modal-body').classList.remove('hidden');
                document.getElementById('fin-intel-summary-risk').textContent = formatCurrency(d.money_at_risk.total);
                document.getElementById('fin-intel-summary-tiedup').textContent = formatCurrency(d.money_tied_up.total);
                document.getElementById('fin-intel-summary-margin').textContent = formatCurrency(d.margin_pressure.total);
                document.getElementById('fin-intel-summary-recoverable').textContent = formatCurrency(d.potentially_recoverable.total);
                const notesEl = document.getElementById('fin-intel-notes');
                if (d.notes && d.notes.length) { notesEl.classList.remove('hidden'); notesEl.innerHTML = d.notes.map(n => `<div><i class="fa-solid fa-circle-info mr-1"></i>${escapeHtml(n)}</div>`).join(''); }
                else notesEl.classList.add('hidden');
                switchFinIntelTab(finIntelActiveTab);
            } catch (e) {
                document.getElementById('fin-intel-modal-loading').classList.add('hidden');
                document.getElementById('fin-intel-modal-insufficient').classList.remove('hidden');
                document.getElementById('fin-intel-modal-insufficient').textContent = friendlyErrorMessage(e.message, t("predictive.loadFailed"));
            }
        }

        function switchFinIntelTab(tab) {
            finIntelActiveTab = tab;
            document.getElementById('fin-intel-detail-panel').classList.add('hidden');
            document.querySelectorAll('.fin-intel-tab-btn').forEach(btn => {
                const active = btn.dataset.tab === tab;
                btn.className = `fin-intel-tab-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold cursor-pointer ${active ? 'bg-primary/15 text-primary border border-primary/30' : 'text-textSec hover:text-textMain border border-transparent'}`;
            });
            const d = lastFinancialIntelData;
            if (!d) return;

            if (tab === 'efficiency') {
                document.getElementById('fin-intel-tab-value').textContent = t("predictive.efficiencyTitle");
                document.getElementById('fin-intel-tab-value').className = 'text-sm font-bold text-textMain';
                document.getElementById('fin-intel-tab-label').textContent = t("predictive.efficiencySubtitle");
                document.getElementById('fin-intel-tab-desc').textContent = '';
                document.getElementById('fin-intel-table-head').innerHTML = `<th class="py-2.5 px-3">${t("predictive.colCategory")}</th><th class="py-2.5 px-3">${t("predictive.colProductsFlagged")}</th><th class="py-2.5 px-3">${t("predictive.colAmount")}</th>`;
                const cats = [
                    [t("predictive.catStockoutExposure"), d.money_at_risk, 'text-danger'],
                    [t("predictive.catSlowMoving"), d.money_tied_up, 'text-warning'],
                    [t("predictive.catDecliningMargins"), d.margin_pressure, 'text-orange-400'],
                    [t("predictive.catRecoveryOpportunities"), d.potentially_recoverable, 'text-success'],
                ].filter(([, cat]) => cat.products.length > 0);
                document.getElementById('fin-intel-table-body').innerHTML = cats.length
                    ? cats.map(([label, cat, color]) => `<tr><td class="py-2.5 px-3 font-medium">${label}</td><td class="py-2.5 px-3 font-mono">${cat.products.length}</td><td class="py-2.5 px-3 font-mono ${color}">${formatCurrency(cat.total)}</td></tr>`).join('')
                    : `<tr><td colspan="3" class="text-center py-6 text-textSec">${t("predictive.noInefficiency")}</td></tr>`;
                return;
            }

            const cfg = getFinIntelTabConfig()[tab];
            const cat = d[cfg.dataKey];
            document.getElementById('fin-intel-tab-value').textContent = formatCurrency(cat.total);
            document.getElementById('fin-intel-tab-value').className = `text-sm font-bold ${cfg.color}`;
            document.getElementById('fin-intel-tab-label').textContent = cfg.label;
            document.getElementById('fin-intel-tab-desc').textContent = cfg.desc;
            document.getElementById('fin-intel-table-head').innerHTML = cfg.columns.map(c => `<th class="py-2.5 px-3">${c}</th>`).join('');
            document.getElementById('fin-intel-table-body').innerHTML = cat.products.length
                ? cat.products.map(p => `<tr class="hover:bg-cardHover/50 cursor-pointer" onclick="showFinIntelProductDetail(${p.product_id})">${cfg.row(p).map(v => `<td class="py-2.5 px-3">${v}</td>`).join('')}</tr>`).join('')
                : `<tr><td colspan="${cfg.columns.length}" class="text-center py-6 text-textSec">${t("predictive.noProductsFlagged")}</td></tr>`;
        }

        function showFinIntelProductDetail(productId) {
            const d = lastFinancialIntelData;
            if (!d) return;
            const p = (d.products || []).find(x => x.product_id === productId);
            if (!p) return;
            const panel = document.getElementById('fin-intel-detail-panel');
            panel.classList.remove('hidden');
            document.getElementById('fin-intel-detail-name').textContent = `${p.name} (${p.sku})`;
            const cell = (label, value) => `<div class="bg-bgMain border border-borderCol rounded-lg p-2"><div class="text-[9px] uppercase tracking-wide text-textSec">${label}</div><div class="text-xs font-bold text-textMain mt-0.5">${value}</div></div>`;
            document.getElementById('fin-intel-detail-grid').innerHTML = [
                cell(t("predictive.detailCurrentInventory"), p.quantity),
                cell(t("predictive.detailSalesVelocity"), t("predictive.perDay", {count: p.daily_velocity.toFixed(2)})),
                cell(t("predictive.detailEstDaysRemaining"), p.days_to_stockout === null ? t("common.unknown") : t("predictive.daysUnit", {count: p.days_to_stockout})),
                cell(t("predictive.detailSalesAtRisk"), formatCurrency(p.potential_sales_at_risk)),
                cell(t("predictive.detailCostValueTiedUp"), formatCurrency(p.capital_tied_up)),
                cell(t("predictive.detailMargin"), p.current_margin_pct === null ? t("predictive.notEnoughData") : t("predictive.marginWithListed", {realized: p.current_margin_pct, listed: p.previous_margin_pct})),
                cell(t("predictive.detailRecentSales"), p.last_sale ? t("predictive.lastSaleOn", {date: formatBusinessDate(p.last_sale)}) : t("predictive.noSalesRecorded")),
                cell(t("predictive.slowMoving"), p.is_slow_moving ? t("predictive.yes") : t("predictive.no")),
            ].join('');
            document.getElementById('fin-intel-detail-why').innerHTML = p.why_flagged && p.why_flagged.length
                ? `<strong class="text-textMain">${t("predictive.whyFlagged")}</strong> ${p.why_flagged.map(escapeHtml).join(' ')}`
                : `<strong class="text-textMain">${t("predictive.whyFlagged")}</strong> ${t("predictive.notFlagged")}`;
        }

        function renderWarehouseModalData() {
            const listContainer = document.getElementById("warehouse-list-container");
            const selectFrom = document.getElementById("transfer-from");
            const selectTo = document.getElementById("transfer-to");
            const selectProduct = document.getElementById("transfer-product");

            listContainer.innerHTML = warehouseRecords.map(w => `
                <div class="flex items-center justify-between bg-cardBg px-3 py-1.5 rounded-xl border border-borderCol text-xs text-textMain">
                    <span class="font-medium min-w-0 truncate"><i class="fa-solid fa-warehouse text-primary mr-1.5"></i> ${escapeEmployeeHtml(w.name)}</span>
                    <span class="flex items-center gap-2 shrink-0">
                        <span class="text-[10px] text-textSec font-mono">${t('warehouses.skuCount', { count: w.sku_count ?? 0 })}</span>
                        <button type="button" onclick="handleDeleteWarehouse(${w.id}, '${escapeEmployeeHtml(w.name).replace(/'/g, "\\'")}')" class="text-textSec hover:text-danger transition cursor-pointer" title="${t('warehouses.deleteWarehouse')}"><i class="fa-solid fa-trash-can text-[11px]"></i></button>
                    </span>
                </div>
            `).join("") || `<div class="text-[10px] text-textSec text-center py-2">${t('warehouses.noneAvailable')}</div>`;

            const whOptions = customWarehouses.map(w => `<option value="${escapeEmployeeHtml(w)}">${escapeEmployeeHtml(w)}</option>`).join("");
            if (selectFrom) selectFrom.innerHTML = whOptions;
            if (selectTo) selectTo.innerHTML = whOptions;
            if (selectProduct) selectProduct.innerHTML = globalProducts.map(p => `<option value="${p.id}">${escapeEmployeeHtml(p.name)} (${escapeEmployeeHtml(p.sku)} - ${t('warehouses.qty', { qty: p.quantity })})</option>`).join("");
        }

        // Warehouse registry summary (not a second copy of Inventory — the
        // per-product breakdown for one warehouse is already available via
        // Inventory's own warehouse filter). Stock Value is derived from
        // globalProducts (quantity × cost_price per product in that
        // warehouse) since Warehouse itself carries no value field.
        function buildWarehousesExportSpec() {
            if (!Array.isArray(warehouseRecords) || !warehouseRecords.length) return null;
            const products = Array.isArray(globalProducts) ? globalProducts : [];
            const rows = warehouseRecords.map(w => {
                const stockValue = products
                    .filter(p => (p.warehouse || "Main Central Warehouse") === w.name)
                    .reduce((sum, p) => sum + (p.quantity || 0) * (p.cost_price || 0), 0);
                return { name: w.name, sku_count: w.sku_count, stock_value: Math.round(stockValue * 100) / 100, status: w.is_active === false ? "Inactive" : "Active", created_at: w.created_at || null };
            });
            return {
                filenameBase: `cauldra_warehouses_${csvDateStamp()}`,
                reportTitle: "Cauldra Warehouses Report",
                metadata: [["Generated", new Date().toLocaleString()]],
                sheets: [{
                    name: "Warehouses",
                    columns: [
                        { key: "name", label: "Warehouse", type: "text" },
                        { key: "sku_count", label: "SKU Count", type: "number" },
                        { key: "stock_value", label: "Stock Value", type: "currency" },
                        { key: "status", label: "Status", type: "text" },
                        { key: "created_at", label: "Created At", type: "date" },
                    ],
                    rows,
                }],
            };
        }
        function exportWarehousesCsv() { runCsvExport(buildWarehousesExportSpec, "No warehouses available to export."); }
        function exportWarehousesExcel(button) { runExcelExport(button, buildWarehousesExportSpec, "No warehouses available to export."); }

        async function handleCreateWarehouse(event) {
            event.preventDefault();
            if (!authToken) return;
            const nameInput = document.getElementById("new-warehouse-name");
            const name = nameInput.value.trim();
            if (!name) return;
            try {
                const res = await fetch(`${API_URL}/warehouses/`, {
                    method: "POST", credentials: "include",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ name })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t('warehouses.createFailed')));
                nameInput.value = "";
                await loadWarehouses();
                renderWarehouseModalData();
                updateDashboardMetrics();
                showToast(t('warehouses.addedSuccess'), "success");
            } catch (e) {
                showToast(friendlyErrorMessage(e.message, t('warehouses.createFailed')), "error");
            }
        }

        async function handleDeleteWarehouse(id, name) {
            if (!authToken) return;
            const confirmed = await showCustomConfirm(t('warehouses.deleteWarning', { name }), t('warehouses.deleteConfirmTitle', { name }));
            if (!confirmed) return;
            try {
                const res = await fetch(`${API_URL}/warehouses/${id}`, {
                    method: "DELETE", credentials: "include",
                    headers: { "Authorization": `Bearer ${authToken}` }
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("warehouses.deleteFailed")));
                await loadWarehouses();
                renderWarehouseModalData();
                updateDashboardMetrics();
                showToast(data.message || t("warehouses.deletedSuccess"), "success");
            } catch (e) {
                showToast(friendlyErrorMessage(e.message, t("warehouses.deleteFailed")), "error");
            }
        }

        async function handleStockTransfer(event) {
            event.preventDefault();
            const productId = parseInt(document.getElementById("transfer-product").value);
            const fromWh = document.getElementById("transfer-from").value;
            const toWh = document.getElementById("transfer-to").value;
            const qty = parseInt(document.getElementById("transfer-qty").value) || 0;
            if (fromWh === toWh) { showToast(t("warehouses.transferDifferentRequired"), "error"); return; }
            if (!productId || qty < 1) { showToast(t("warehouses.selectProductPositiveQty"), "error"); return; }
            try {
                const res = await fetch(`${API_URL}/products/${productId}/transfer`, {
                    method: "PATCH", credentials: "include",
                    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ from_warehouse: fromWh, to_warehouse: toWh, quantity: qty })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok) throw new Error(showApiError(res, data, t("warehouses.transferFailed")));
                closeWarehouseModal();
                showToast(data.message || t("warehouses.transferCompletedSuccess"), "success");
                await loadData();
            } catch (e) {
                showToast(friendlyErrorMessage(e.message, t("warehouses.transferFailed")), "error");
            }
        }

        async function renderProductDeletionRequests() {
            if (getCurrentRole() !== 'admin') return '';
            try {
                const r = await fetch(`${API_URL}/product-deletion-requests`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                if (!r.ok) return '';
                const items = await r.json();
                if (!items.length) return '';
                return `<div class="mb-3 p-3 rounded-xl bg-warning/10 border border-warning/30">
                    <div class="font-bold text-textMain text-xs mb-2"><i class="fa-solid fa-clock text-warning mr-1"></i> ${t("alerts.deletionRequests")}</div>
                    ${items.map(x => `<div class="p-2.5 mb-2 last:mb-0 rounded-lg bg-cardBg border border-borderCol flex items-center justify-between gap-3">
                        <div class="min-w-0"><div class="font-semibold text-textMain text-[11px]">${escapeEmployeeHtml(x.product_name)} <span class="text-textSec">(${escapeEmployeeHtml(x.sku || '')})</span></div><div class="text-[10px] text-textSec">${t("team.requestedBy", {name: escapeEmployeeHtml(x.requested_by_name || x.requested_by || t("team.managerFallback"))})}</div></div>
                        <div class="flex gap-1.5 shrink-0"><button type="button" onclick="resolveProductDeletion(${x.id},'approve')" class="px-2 py-1 rounded-md bg-danger/15 text-danger border border-danger/25 text-[10px] font-semibold">${t("alerts.approveAndDelete")}</button><button type="button" onclick="resolveProductDeletion(${x.id},'reject')" class="px-2 py-1 rounded-md bg-bgMain text-textSec border border-borderCol text-[10px] font-semibold">${t("alerts.reject")}</button></div>
                    </div>`).join('')}
                </div>`;
            } catch (_) { return ''; }
        }
        async function resolveProductDeletion(requestId, action) {
            try {
                const r = await fetch(`${API_URL}/product-deletion-requests/${requestId}/${action}`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } });
                const d = await r.json();
                if (!r.ok) { showToast(d.detail || t("team.resolveRequestFailed"), 'error'); return; }
                showToast(d.message || t("team.requestUpdated"), 'success');
                renderAlerts(); loadData();
            } catch (_) { showToast(t("common.actionFailed"), 'error'); }
        }
        // ---- Notification badge background polling --------------------------
        // Keeps #notification-badge / #mobile-notification-badge current
        // without requiring the user to open the Notifications panel.
        // Deliberately lightweight: this ONLY re-fetches the server-authoritative
        // unread count and updates the two badge counts — it never touches
        // #notifications-container and never calls renderAlerts() (that stays
        // exactly as-is, reserved for when the panel is actually opened).
        // Started/stopped from updateGuestHeaderState() below — the existing
        // single place that already tracks "signed in with an active business
        // profile" across login, logout, session refresh, and auth failure —
        // rather than a separate auth mechanism of its own.
        // (notificationPollTimer / notificationPollInFlight are declared with
        // the other top-level app state near the top of this script — see
        // there — since updateGuestHeaderState() is defined earlier in the
        // file and calls into these functions from the very first sign-in.)
        async function refreshNotificationBadge() {
            // Deletion-lifecycle guard: a tick that was already queued when
            // quiesceAuthenticatedActivity() cleared the interval must still
            // no-op here — clearInterval() cannot cancel a callback already
            // scheduled on the event loop.
            if (businessDeletionInProgress) return;
            if (!hasAuthenticatedBusinessContext()) return;
            if (notificationPollInFlight) return; // a previous poll hasn't finished yet — never overlap
            notificationPollInFlight = true;
            notificationPollAbortController = new AbortController();
            try {
                const res = await fetch(`${API_URL}/notifications/unread-count`, {
                    headers: { "Authorization": `Bearer ${authToken}` },
                    cache: "no-store",
                    signal: notificationPollAbortController.signal,
                });
                if (!res.ok) return; // transient failure — leave the badge showing its last known count
                const data = await res.json();
                const total = data.unread_count || 0;
                const desktopBadge = document.getElementById('notification-badge');
                const mobileBadge = document.getElementById('mobile-notification-badge');
                if (desktopBadge) desktopBadge.innerText = total;
                if (mobileBadge) mobileBadge.innerText = total;
            } catch (err) {
                // An intentional abort (quiesceAuthenticatedActivity(), fired
                // right before a business deletion) is not a failure — no
                // toast, no console noise, no retry.
                if (err && err.name === "AbortError") return;
                // Offline / network error — stay silent, keep the last known
                // count on screen; the next 5s tick (or the visibility/online
                // triggers below) retries naturally.
            } finally {
                notificationPollInFlight = false;
            }
        }

        function startNotificationPolling() {
            if (businessDeletionInProgress) return; // never (re)start while a deletion is underway
            if (notificationPollTimer) return; // already running — never create a second interval
            refreshNotificationBadge(); // immediate first check, don't wait 5s
            notificationPollTimer = setInterval(refreshNotificationBadge, 5000);
            // Section 15 — ask for push permission a few seconds after the
            // user is actually signed in and looking at their dashboard,
            // never on the very first paint.
            setTimeout(maybeShowPushPermissionPrompt, 4000);
        }

        function stopNotificationPolling() {
            if (notificationPollTimer) { clearInterval(notificationPollTimer); notificationPollTimer = null; }
        }

        // Coming back to the tab shouldn't wait up to 5s for a stale badge to catch up.
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') refreshNotificationBadge();
        });

        // The last-rendered notification rows, keyed by id — lets
        // openNotification(id) (a plain numeric-arg onclick, same pattern as
        // every other handler in this file) look up a row's deep_link/read
        // state without re-fetching or embedding an escaped JSON blob into
        // an inline onclick attribute.
        let notificationCenterItems = [];

        async function renderAlerts() {
            const container=document.getElementById('notifications-container'); const badge=document.getElementById('notification-badge');
            const mobileBadge=document.getElementById('mobile-notification-badge');
            const deletionRequests = getCurrentRole() === 'admin' ? await renderProductDeletionRequests() : '';
            try {
                const r = await fetch(`${API_URL}/notifications?limit=50`, { headers: { 'Authorization': `Bearer ${authToken}` } });
                if (!r.ok) throw new Error("notifications fetch failed");
                const data = await r.json();
                notificationCenterItems = Array.isArray(data.notifications) ? data.notifications : [];
                const unread = data.unread_count || 0;
                if (badge) badge.innerText = unread;
                if (mobileBadge) mobileBadge.innerText = unread;
                if (!notificationCenterItems.length && !deletionRequests) {
                    container.innerHTML = `<div class="p-3 rounded-xl bg-bgMain border border-borderCol text-center text-textSec">${t("alerts.noActiveAlerts")}</div>`;
                    return;
                }
                container.innerHTML = deletionRequests + notificationCenterItems.map(n => {
                    const sevClass = n.severity === 'critical' ? 'bg-danger/10 border-danger/30' : n.severity === 'important' ? 'bg-warning/10 border-warning/30' : 'bg-primary/10 border-primary/30';
                    const unreadDot = !n.is_read ? '<span class="inline-block w-1.5 h-1.5 rounded-full bg-primary mr-1 align-middle"></span>' : '';
                    return `<div class="p-3 rounded-xl ${sevClass} border flex items-start justify-between gap-3 text-xs cursor-pointer" onclick="openNotification(${n.id})">
                        <div>
                            <div class="font-bold text-textMain">${unreadDot}${escapeHtml(n.title)}</div>
                            <div class="text-[11px] text-textSec mt-0.5">${escapeHtml(n.message)}</div>
                            ${n.created_at ? `<div class="text-[9px] text-textSec mt-1">${formatBusinessDateTime(n.created_at)}</div>` : ''}
                        </div>
                    </div>`;
                }).join('');
            } catch (_) {
                container.innerHTML = `<div class="p-3 text-center text-textSec">${t("alerts.noActiveAlerts")}</div>`;
            }
        }

        // Retained for any older reference — repointed to the notification
        // center's own mark-read endpoint rather than the retired /alerts one.
        async function markAlertRead(id){try{await fetch(`${API_URL}/notifications/${id}/read`,{method:'POST',headers:{'Authorization':`Bearer ${authToken}`}});renderAlerts();}catch(_){} }

        // Opening a notification (section 12): marks it read, closes the
        // panel, and deep-links straight to the relevant Cauldra screen —
        // never just the dashboard (section 13).
        async function openNotification(id) {
            const n = notificationCenterItems.find(x => x.id === id);
            closeAlertsModal();
            if (n && !n.is_read) {
                try { await fetch(`${API_URL}/notifications/${id}/read`, { method: 'POST', headers: { 'Authorization': `Bearer ${authToken}` } }); } catch (_) {}
                refreshNotificationBadge();
            }
            if (n) navigateToDeepLink(n.deep_link);
        }

        // Routes a notification's deep_link (see main.py's create_notification()
        // callers — "inventory:123", "subscription", "ai_center",
        // "purchase_order:45", "supplier:12", "account_security") to the
        // actual Cauldra screen, reusing the exact same functions the sidebar
        // nav already calls rather than a second navigation system.
        function navigateToDeepLink(deepLink) {
            if (!deepLink) return;
            const [kind, idPart] = String(deepLink).split(':');
            const id = idPart ? parseInt(idPart, 10) : null;
            switch (kind) {
                case 'inventory':
                    scrollToInventory();
                    if (id && Array.isArray(globalProducts) && globalProducts.some(p => p.id === id)) openEditProductModalFromData(id);
                    break;
                case 'subscription': openBillingModal(); break;
                case 'ai_center': openAICenterModal(); break;
                case 'purchase_order': openPOModal(); break;
                case 'supplier': openSupplierModal(); break;
                case 'account_security': openSettingsModal(); break;
                default: break; // unrecognized/absent deep link — nothing further to navigate to
            }
        }

