        // -----------------------------------------------------------------------
        // EXTERNAL PUSH NOTIFICATIONS (sections 14/15)
        //
        // Service worker registration for push already happens above (the
        // SAME /sw.js registration the offline-first shell cache uses — see
        // its own push/notificationclick handlers) — this is only the
        // subscribe/unsubscribe/permission-prompt half. Every decision about
        // WHETHER and WHO to notify lives entirely server-side in main.py's
        // notification engine; this code only ever decides whether THIS
        // browser/device is registered to receive one at all.
        // -----------------------------------------------------------------------
        function pushNotificationsSupported() {
            return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window && typeof isNativeAppShell === "function" && !isNativeAppShell();
        }

        function urlBase64ToUint8Array(base64String) {
            const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
            const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
            const rawData = atob(base64);
            const outputArray = new Uint8Array(rawData.length);
            for (let i = 0; i < rawData.length; i++) outputArray[i] = rawData.charCodeAt(i);
            return outputArray;
        }

        async function subscribeToPushNotifications() {
            if (!pushNotificationsSupported()) { showToast(t("alerts.pushUnsupported"), "info"); return false; }
            try {
                let permission = Notification.permission;
                if (permission === "default") permission = await Notification.requestPermission();
                if (permission !== "granted") {
                    if (permission === "denied") showToast(t("alerts.pushBlocked"), "info");
                    return false; // gracefully continue without push — in-app notifications are unaffected
                }
                const keyRes = await fetch(`${API_URL}/push/vapid-public-key`);
                if (!keyRes.ok) return false; // push not configured on this server — fail silently
                const { public_key } = await keyRes.json();
                const registration = await navigator.serviceWorker.ready;
                let subscription = await registration.pushManager.getSubscription();
                if (!subscription) {
                    subscription = await registration.pushManager.subscribe({
                        userVisibleOnly: true,
                        applicationServerKey: urlBase64ToUint8Array(public_key),
                    });
                }
                const json = subscription.toJSON();
                await fetch(`${API_URL}/push/subscribe`, {
                    method: "POST", headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                    body: JSON.stringify({ endpoint: json.endpoint, keys: json.keys, user_agent: navigator.userAgent }),
                });
                showToast(t("alerts.pushEnabled"), "success");
                return true;
            } catch (_) {
                return false; // a push-setup failure must never disrupt normal app use
            }
        }

        async function unsubscribeFromPushNotifications() {
            try {
                const registration = await navigator.serviceWorker.ready;
                const subscription = await registration.pushManager.getSubscription();
                if (subscription) {
                    const endpoint = subscription.endpoint;
                    await subscription.unsubscribe();
                    if (authToken) {
                        try {
                            await fetch(`${API_URL}/push/unsubscribe`, {
                                method: "POST", headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                                body: JSON.stringify({ endpoint }),
                            });
                        } catch (_) {}
                    }
                }
            } catch (_) {}
            showToast(t("alerts.pushDisabled"), "info");
        }

        // Section 15 — never bombards a new user with the permission dialog
        // immediately. Shows an explanatory custom prompt (reusing the app's
        // existing confirm modal, not a second dialog system) at most ONCE
        // per browser — tracked in localStorage, not per-session — and only
        // once the user is actually signed in with an active business.
        function maybeShowPushPermissionPrompt() {
            if (!pushNotificationsSupported()) return;
            if (typeof Notification === "undefined" || Notification.permission !== "default") return; // already decided — never re-prompt with our own UI on top of the browser's
            if (localStorage.getItem("cauldra_push_prompt_dismissed") === "true") return;
            if (!hasAuthenticatedBusinessContext()) return;
            showCustomConfirm(t("alerts.enablePushBody"), t("alerts.enablePushTitle"), t("alerts.enablePushConfirm"), t("alerts.enablePushDismiss")).then((confirmed) => {
                localStorage.setItem("cauldra_push_prompt_dismissed", "true"); // asked once — never nag again regardless of the answer
                if (confirmed) subscribeToPushNotifications();
            });
        }

        async function fetchAIInsights() {
            const chatMessages = document.getElementById("chat-messages");
            const win = document.getElementById("ai-chat-window");
            if (win.classList.contains("hidden")) toggleAIChatWindow();

            chatMessages.innerHTML += `
                <div class="bg-primary/15 border border-primary/30 p-2.5 rounded-xl shadow-sm my-1">
                    <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                    <p class="text-textMain leading-relaxed text-[11px] italic animate-pulse">${t("aiCenter.analyzingTelemetry")}</p>
                </div>
            `;
            chatMessages.scrollTop = chatMessages.scrollHeight;

            try {
                const headers = authToken ? { "Authorization": `Bearer ${authToken}` } : {};
                const res = await fetch(`${API_URL}/ai/insights`, { headers });
                const data = await res.json();

                if (!res.ok) throw new Error(showApiError(res, data, t("aiCenter.insightsUnavailable")));

                chatMessages.lastElementChild.remove();
                chatMessages.innerHTML += `
                    <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1">
                        <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Insights</p>
                        <p class="text-textMain leading-relaxed text-[11px]">${escapeHtml(data.insight) || t("aiCenter.defaultInsight")}</p>
                    </div>
                `;
                chatMessages.scrollTop = chatMessages.scrollHeight;
            } catch (err) {
                chatMessages.lastElementChild.remove();
                chatMessages.innerHTML += `
                    <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1">
                        <p class="font-semibold text-danger mb-0.5 text-[11px]">Cauldra Assistant</p>
                        <p class="text-textMain leading-relaxed text-[11px]">${escapeHtml(friendlyErrorMessage(err.message, t("aiCenter.insightsTemporarilyUnavailable")))}</p>
                    </div>
                `;
                chatMessages.scrollTop = chatMessages.scrollHeight;
            }
        }

        async function sendAIChat(event) {
            event.preventDefault();
            const input = document.getElementById("chat-input");
            const query = input.value.trim();
            if (!query) return;

            const chatMessages = document.getElementById("chat-messages");
            chatMessages.innerHTML += `
                <div class="bg-cardHover border border-borderCol p-2.5 rounded-xl shadow-sm my-1 ml-4">
                    <p class="font-semibold text-textSec mb-0.5 text-[10px]">You</p>
                    <p class="text-textMain leading-relaxed text-[11px]">${escapeHtml(query)}</p>
                </div>
            `;
            input.value = "";
            chatMessages.scrollTop = chatMessages.scrollHeight;

            const lowerQuery = query.toLowerCase();

            // Grounded Local/API-driven evaluation based on real database state
            if (/\b(hello|hi|hey)\b/.test(lowerQuery)) {
                setTimeout(() => {
                    chatMessages.innerHTML += `
                        <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                            <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                            <p class="text-textMain leading-relaxed text-[11px]">Hello! How can I assist you with your inventory today?</p>
                        </div>
                    `;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }, 300);
                return;
            }

            if (lowerQuery.includes("low stock") || lowerQuery.includes("low item") || lowerQuery.includes("any low") || lowerQuery.includes("low inventory")) {
                const lowStockItems = globalProducts.filter(p => p.quantity <= p.min_stock_level);
                setTimeout(() => {
                    let replyText = "";
                    if (lowStockItems.length === 0) {
                        replyText = "You currently have no low-stock products in your inventory.";
                    } else {
                        replyText = `${lowStockItems.length} product(s) are currently low on stock:\n` + 
                            lowStockItems.map(i => `• ${escapeHtml(i.name)} (SKU: ${escapeHtml(i.sku)}): ${i.quantity} units remaining (Min Level: ${i.min_stock_level})`).join("<br>");
                    }
                    chatMessages.innerHTML += `
                        <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                            <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                            <p class="text-textMain leading-relaxed text-[11px]">${replyText}</p>
                        </div>
                    `;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }, 300);
                return;
            }

            if (lowerQuery.includes("how many products") || lowerQuery.includes("total products") || lowerQuery.includes("how many inventory")) {
                setTimeout(() => {
                    let replyText = "";
                    if (globalProducts.length === 0) {
                        replyText = "You currently have no products recorded in your inventory.";
                    } else {
                        replyText = `You currently have ${globalProducts.length} product record(s) in your inventory database.`;
                    }
                    chatMessages.innerHTML += `
                        <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                            <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                            <p class="text-textMain leading-relaxed text-[11px]">${replyText}</p>
                        </div>
                    `;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }, 300);
                return;
            }

            if (lowerQuery.includes("how many units") || lowerQuery.includes("total units") || lowerQuery.includes("total stock")) {
                const totalUnits = globalProducts.reduce((sum, p) => sum + p.quantity, 0);
                setTimeout(() => {
                    chatMessages.innerHTML += `
                        <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                            <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                            <p class="text-textMain leading-relaxed text-[11px]">You currently have a total of ${totalUnits} physical unit(s) across all products in your inventory.</p>
                        </div>
                    `;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }, 300);
                return;
            }

            if (lowerQuery.includes("out of stock") || lowerQuery.includes("depleted")) {
                const outOfStockItems = globalProducts.filter(p => p.quantity === 0);
                setTimeout(() => {
                    let replyText = "";
                    if (outOfStockItems.length === 0) {
                        replyText = "You currently have no out-of-stock products.";
                    } else {
                        replyText = `The following product(s) are out of stock:\n` + 
                            outOfStockItems.map(i => `• ${escapeHtml(i.name)} (SKU: ${escapeHtml(i.sku)})`).join("<br>");
                    }
                    chatMessages.innerHTML += `
                        <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                            <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                            <p class="text-textMain leading-relaxed text-[11px]">${replyText}</p>
                        </div>
                    `;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }, 300);
                return;
            }

            if (!authToken) {
                setTimeout(() => {
                    chatMessages.innerHTML += `
                        <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                            <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                            <p class="text-textMain leading-relaxed text-[11px]">Please sign in to your business account so I can look up your inventory and answer that.</p>
                        </div>
                    `;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }, 300);
                return;
            }

            try {
                const headers = { "Content-Type": "application/json" };
                if (authToken) headers["Authorization"] = `Bearer ${authToken}`;
                
                const res = await fetch(`${API_URL}/ai/chat`, {
                    method: "POST", headers, body: JSON.stringify({ message: query })
                });
                const data = await res.json();

                if (!res.ok) throw new Error(showApiError(res, data, "The AI assistant couldn't process that request right now."));

                chatMessages.innerHTML += `
                    <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                        <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                        <p class="text-textMain leading-relaxed text-[11px]">${escapeHtml(data.reply) || "I am analyzing your inventory data."}</p>
                    </div>
                `;
                chatMessages.scrollTop = chatMessages.scrollHeight;
            } catch (err) {
                chatMessages.innerHTML += `
                    <div class="bg-bgMain border border-borderCol p-2.5 rounded-xl shadow-sm my-1 mr-4">
                        <p class="font-semibold text-primary mb-0.5 text-[11px]">Cauldra Assistant</p>
                        <p class="text-textMain leading-relaxed text-[11px]">${escapeHtml(friendlyErrorMessage(err.message, "I couldn't process that request right now. Please try again."))}</p>
                    </div>
                `;
                chatMessages.scrollTop = chatMessages.scrollHeight;
            }
        }

        function playSuccessBeep() {
            try {
                const ctx = new (window.AudioContext || window.webkitAudioContext)();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(800, ctx.currentTime);
                gain.gain.setValueAtTime(0.1, ctx.currentTime);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start();
                osc.stop(ctx.currentTime + 0.1);
            } catch (e) {}
        }

        function closeAllActionDropdowns(e) {}

        window.addEventListener('resize', () => updateInventoryStatusUI());

        // Initial Data Fetch on Page Load. Authentication restoration must
        // finish before deciding whether a direct Hub/onboarding URL may open.
        loadData().then(async () => {
            const params = new URLSearchParams(window.location.search);
            if (params.get('cauldra_email_verify') === '1') {
                await handleEmailVerifyReturn();
                return;
            }
            const hasPaymentReturn = !!(params.get('reference') || params.get('trxref'));
            if (hasPaymentReturn) {
                await handlePaystackReturn();
                return;
            }
            handleHubOnboardingRoute();
        });
